/** Russo: Guida e Novita' (testi senza nome, chiave `t.<impronta del testo inglese>`). Generato da `scripts/importa-ru.mjs` dal foglio `docs/traduzione-russa.csv`: non si modifica a mano. */
export const RU_TEXTS: Record<string, string> = {
  "t.100829qiojv": "Режекторные фильтры не сохраняются: они удаляются автоматически при смене диапазона или частоты радио и исчезают после перезапуска, потому что помеха принадлежит только этой частоте.",
  "t.100j34gwrwx": "[[ca.phone]]: «[[ca.phone.ok]]», когда сеть и брандмауэр в порядке; «[[ca.phone.warn]]» при «Общедоступной» сети или отсутствии домашнего адреса; «[[ca.phone.bad]]», если брандмауэр Windows блокирует Aurora. «[[diag.fix]]» ведёт на страницу [[sw.tab.phone]].",
  "t.100yncnvyr7": "Фильтры по позывному, префиксу и уже проведённым связям",
  "t.1021xy6y559": "Во время передачи водопад останавливается (звук с радио не поступает), а жёлтая линия отмечает паузу; по окончании передачи он запускается снова.",
  "t.104ebzp7fgn": "Выход: карта, которая подаёт звук на радио для передачи (обычно «Speakers (USB Audio Device)»).",
  "t.105xdqfiwl1": "[[agent.popup]] · [[agent.preview]] с «[[agent.try.update]]» и «[[agent.try.dx]]»: две кнопки, которые сразу показывают образец карточки (пример обновления и пример DX-экспедиции, с выдуманными текстами) с длительностью, выбранной выше, чтобы увидеть, как она выглядит. Кнопки карточки («[[agent.try.updMain]]», «[[agent.try.later]]», «[[agent.try.dxMain]]», «[[agent.try.ignore]]») настоящие, но здесь карточка ничего настоящего не сообщает.",
  "t.1087fxhywsw": "Шестерёнка («[[sstv.set.title]]»): открывает Настройки страниц SSTV в отдельном окне, так что страница и приём сохраняются. На телефонах и планшетах её нет (Настройки можно менять только с ПК).",
  "t.10aopz83ig5": "заново открывает прослушивание на звуковой карте (останавливает и перезапускает приём)",
  "t.10arsvkq0ry": "Контест: TX остаётся включённым",
  "t.10bilnwf2wt": "Ниже «[[bands.far3]]»: самые дальние станции, принявшие Ваш сигнал (PSK Reporter), по одной в строке, с флагом, позывным, страной, диапазоном, расстоянием и сигналом в dB. Показываются три; четвёртая и пятая — только если хватает места. Если приёмов нет, в строке написано «[[bands.noPsk]]».",
  "t.10ep3rviz90": "Заводские значения в десятичном виде (и в шестнадцатеричном, как их пишет руководство): IC-7300 = 148 (94h), IC-7610 = 152 (98h), IC-705 = 164 (A4h), IC-9700 = 162 (A2h). Если Вы ничего не меняли в меню трансивера, 0 или это число равнозначны.",
  "t.10fapqkch4b": "Если Вы передаёте, а радиостанция не переходит на передачу, вверху появляется уведомление с причиной. В [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] проверьте, что способ PTT тот же, что Вы используете в WSJT-X (CAT или RTS/DTR на том же порту), и попробуйте «Test PTT» внизу Настроек. Aurora пробует PTT, даже если чтение радиостанции пропущено; если радиостанция не отвечает, ошибка сообщает об этом. При PTT по RTS/DTR, если порт удерживает другая программа, сообщение указывает, какая именно: закройте её и перезапустите Aurora (порт PTT открывается при запуске, «Connect» недостаточно).",
  "t.10gy1luejlj": "Команды, возвращающиеся в Aurora: на тот же порт получателей с «[[int.wsjtx]]» приходят ответ станции, остановка передачи, свободный текст, цвета позывных, очистка списка, смена локатора и конфигурация. Они применяются только при включённом «[[ens.k.AcceptUDPRequests]]» (в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]); если выключено, получатель может только читать.",
  "t.10h47ydv4fc": "[[cop.spots]] · [[cop.expire]]: выпадающий список с [[cop.never]] (заводской: они остаются, пока кластер их хранит) или 5, 10, 15, 20, 30, 60 либо 120 минут. Выберите короткое время, если список заполняется старыми спотами.",
  "t.10h6betrvbn": "Log4OM записывает QSO Aurora так же, как QSO JTDX. Радиостанция подключается отдельно (пункт «Log4OM: радиостанция через Aurora»).",
  "t.10hac8tqcfh": "На карте: колёсико или кнопки + и − для масштаба, удерживайте и перетаскивайте для перемещения. Щелчок по точке показывает квадрат, расстояние, страну и зоны CQ и ITU. Щелчок по станции в эфире или по её позывному вызывает её: Aurora оставляет текущее QSO и отвечает ей, как при работе с очередью.",
  "t.10jpr9n4wzw": "текст, выделенный в окне RX, становится QTH",
  "t.10jxym9lci5": "В Log4OM: Settings → Program configuration → CAT interface. CAT Engine: Hamlib.",
  "t.10lqea4i0nt": "Чтобы попробовать без ротора: «[[rot.set.launch]]», модель «Hamlib Dummy», без порта, затем включите «[[rot.set.enabled]]». Чтобы действительно повернуть антенну, см. пункт «Поворотное устройство антенны» и страницу [[nav.rotator]].",
  "t.10m903hhe8o": "Это не CQ? Aurora сообщит об этом отдельным уведомлением: по умолчанию она сама отвечает только на CQ. Чтобы отвечать на любое сообщение: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]].",
  "t.10peldpbs4r": "Если Вы уже перемещали карточки, сохраняется Ваше собственное расположение; [[sat.dash.reset]] возвращает стандартное. Расстояние между карточками составляет 6 px, а строки заголовков и рамки такие же, как у окон страницы FT8. [[ssbc.enter]] имеет высоту по содержимому (она растёт, когда появляются предупреждения) и показывает название контеста справа от своего заголовка.",
  "t.10pklmh7q3z": "В PSK каждый бит поступает со своей вероятностью, а варикод читается целыми словами: сомнительный бит не ломает символ, а шум печатается очень мало (ниже определённой вероятности символ не печатается). В окне приёма двойной щелчок по позывному вносит его в текущий QSO и ищет имя, QTH, локатор и страну; правый щелчок по слову вносит его в выбранное поле журнала, а «[[digi.word.copy]]» и «[[digi.mi.clearRx]]» доступны всегда.",
  "t.10rjki42jl5": "Если вместо ползунка появляется «[[aud.vol.off]]», у этого устройства нет громкости, регулируемой отсюда (например, TCI или сетевой звук): задайте уровень в программе SDR или в Cat4OM, либо в системном микшере.",
  "t.10rtqf4rioa": "Чтобы остановить: STOP TX или клавиша Esc (см. «Остановка передачи»). В контестах повторяющийся CQ — это «[[contest.autoCq]]» (F1); в Автоматизации есть «[[auto.autoCqOn]]».",
  "t.10shfsupxop": "Что отсюда изменить нельзя: репозиторий, из которого читаются версии, параметр тестовых версий (pre-release) и токен чтения для закрытого репозитория не имеют видимых полей. Они остаются на значениях по умолчанию (стабильные версии Aurora на GitHub) и важны только тем, кто занимается разработкой.",
  "t.10t7v5c87wa": "[[cat.grp.ptt]] · [[cat.ptt.port]]: появляется только при PTT по DTR или RTS. Пусто = тот же порт, что и для CAT. Впишите его, только если PTT на другом COM: например, у Yaesu FTdx101, FT-991A и FT-710 два порта — «Enhanced COM Port» для CAT и «Standard COM Port» для PTT.",
  "t.10ts8yjf0fc": "[[not2.grpColors]]",
  "t.10u8x7oepe0": "Только для OmniRig: [[cat.omnirig.rig]] (Rig 1 или Rig 2): каким из двух трансиверов OmniRig управляет Aurora. Порт, скорость и модель задаются в программе OmniRig, а не здесь.",
  "t.10ufnvi1wp": "Чтобы вызвать экспедицию UltraFOX или SuperFox: включите Hound в FT8. Aurora декодирует и широкий сигнал и отвечает, как при классическом Fox.",
  "t.10usxfuxtqi": "«[[qmap.period]]» и «[[qmap.submodes]]»: период и подрежимы для поиска. «[[qmap.fading]]»: модель замираний для EME. «[[qmap.also30]]» (при периоде 60 s также ищет Q65-30). «[[qmap.average]]» складывает периоды для более слабых сигналов; «[[qmap.clearAverage]]» очищает среднее. «[[qmap.save]]» применяет всё.",
  "t.10v5xe31tcv": "[[aud.output]] · [[aud.vol.out]] = ползунок TX Lvl (в [[sw.tab.audio]] и на панели передачи страницы Station, где он называется «[[out.label]]»): это уровень звука на трансивер. По умолчанию он уменьшает генерируемый сигнал (как в WSJT-X и JTDX), а Aurora никогда не пишет громкость Windows. С опцией «[[out.mode]]» (под ползунком) сигнал остаётся полным, а ползунок задаёт громкость Windows выхода: 100 % на ползунке = 100 % в микшере Windows, записывается только когда вы двигаете ползунок. Он служит для уменьшения исходящего сигнала, а НЕ для выбора мощности: мощность задаётся ручкой трансивера. Передавайте, следите за мощностью и КСВ на дисплее и уменьшайте TX Lvl, пока мощность не станет нужной, а КСВ останется низким; чтобы избежать перегрузки, держите ALC на нуле или около нуля на собственном приборе трансивера (Aurora его не показывает). В Linux он всегда уменьшает сигнал.",
  "t.10w7l68xqp3": "только заглавные буквы в окне передачи (OFF отключает)",
  "t.10xa6lxqho4": "Это два места вне настроек, где Aurora сообщает, что вышла новая версия. Полей для настройки в них нет: это кнопки.",
  "t.10y4vcktxzj": "Вызов CQ со страницы «Станция»",
  "t.10zi27ezrie": "«[[stats.missing]]»: открывается щелчком и показывает страны, с которыми Вы ещё не проводили связь, по одной метке на страну.",
  "t.1108re41lyh": "Жёлтая карточка сообщает, сколько секунд заняло декодирование, и, если известна используемая глубина, предлагает шаг ниже (Deep → Normal → Fast): при глубине Deep предлагает перейти на Normal, при Normal — на Fast. При Fast убирать больше нечего, поэтому карточка даёт только общие советы (выключить SWL, a7/a8 и тяжёлые программы).",
  "t.114ay4x5tb8": "очищает данные QSO",
  "t.114cw827bib": "После пролёта: выберите «[[sat.trk.afterStay]]», «[[sat.trk.afterPark]]» (с «[[sat.trk.parkAz]]» и «[[sat.trk.parkEl]]») или «[[sat.trk.afterNext]]», а в «[[sat.trk.delay]]» — сколько секунд ждать. Команда отправляется только один раз и отменяется, если начинается новый пролёт.",
  "t.114eszr12n0": "«[[int.name]]»: название, чтобы узнавать его в списке (не более 40 символов). Нужно только Вам.",
  "t.116bhi9fa5k": "Ряд кнопок: «[[contest.rules]]» (правила вкратце и официальная ссылка), «[[contest.calendar]]», «[[contest.export]]» (файл для организатора, см. ниже), «[[contest.settings]]» (настройки контеста, редактируемые и сохраняемые для каждого контеста), «[[contest.training]]», «[[contest.analysis]]» и «[[contest.end]]» (выключает контест и возвращает прежние настройки).",
  "t.116he6owt59": "Как читать строку сообщения",
  "t.116mp77pl7b": "Таблицы со столбцами (окно RX, DX Cluster): перетащите заголовок, чтобы переместить столбец (или Alt + стрелки), перетащите правый край, чтобы изменить ширину (или Alt + Shift + стрелки), щёлкните заголовок правой кнопкой для сброса.",
  "t.1186eqb7vcp": "Hound вызывают выше 1000 Hz, никогда не ниже: нижняя часть принадлежит Fox.",
  "t.11899vyx9i2": "Частота радио в MHz: Вы видите её, только если дисплей радио скрыт (иначе Вы и так читаете её там).",
  "t.119yfnb60dq": "Fox и Hound: что это такое",
  "t.11d0mpkrw3q": "«[[ca.close]]» закрывает карточку (Enter тоже). После исправления чего-либо откройте «[[ca.run]]» снова, чтобы увидеть, как меняется отметка.",
  "t.11fgtosqin8": "Проверка: проведите QSO; строка появится в журнале Log4OM.",
  "t.11fto49ogvm": "[[auto.b2]] (три кнопки выбора): при нескольких интересных CQ в одном цикле Aurora выбирает только один. [[auto.prefer.rarity]] (по умолчанию): сначала нужные, затем новая страна, новое на диапазоне или режиме, зона, квадрат; при равенстве решает самый сильный сигнал. [[auto.prefer.snr]]: самый сильный среди интересных. [[auto.prefer.score]]: балл, учитывающий новизну (10 очков за уровень) и сигнал (до 18 очков, от −24 до +12 dB).",
  "t.11gnage677": "Расстояние указывается в км или милях согласно предпочтениям. Блок обновляется сам каждые 10 секунд; условия берутся у N0NBH (hamqsl.com).",
  "t.11jht7i8a3d": "запрашивает значение, если оно пусто (также <RSTS?>, <RSTR?>, <NRS?>, <NRR?>)",
  "t.11kgxlb724f": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.tab.macros]] Вы храните список готовых текстов для свободной части сообщения, с символами, которые Aurora заменяет на месте. Список сохраняется сразу и остаётся на этом устройстве (не на ПК, если Вы на телефоне, и наоборот).",
  "t.11nu597jam1": "«[[sstv.rx.tx]]»: сразу передаёт изображение, подготовленное на вкладке «[[sstv.view.tx]]», и переводит Вас туда. Серая, если передавать нельзя, если Вы принимаете ([[sstv.rx.txWait]]) или если Вы уже передаёте.",
  "t.11pm9ffshzw": "Откроется Проводник с уже выбранным файлом Aurora-assistenza-….zip: отправьте его по электронной почте, через WhatsApp или Telegram.",
  "t.11rm4otni1b": "Частые проблемы",
  "t.11rod7g1nng": "Для самых распространённых радиостанций Aurora показывает «[[cat.preset.title]]» в разделе [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] с кнопкой, которая записывает нужные значения.",
  "t.11vj835o6ht": "Споты: список тот же, что и в DX Cluster Aurora, со столбцами [[cluster.col.by]], [[cluster.col.freq]], [[cluster.col.call]], [[cluster.col.country]], [[cluster.col.mode]], [[cluster.col.comment]] и [[cluster.col.time]]. Щелчок (или двойной щелчок, в зависимости от «[[cop.choose]]») перестраивает радио так, чтобы сигнал попал на тон приёма, помещает позывной в текущее QSO и, если режим спота — RTTY, CW или PSK, а режим страницы другой, также меняет режим страницы.",
  "t.11vq8vots64": "Над полем, как только начинается передача, появляется список уже переданного («[[digi.tx.sentTitle]]»); он очищается с помощью «[[digi.mi.clearTx]]».",
  "t.11w502na6lr": "Правый щелчок по клавише панели макросов или команда <EDITMACRO:nome> внутри другого макроса. Открывается окно «[[digi.edit.title]]»; с «[[digi.edit.ok]]» макрос сохраняется, с «[[digi.edit.cancel]]» ничего не меняется.",
  "t.11xn126efhl": "Как настроиться на сигнал SSTV",
  "t.11y33iu2afy": "Две вертикальные полосы — это Rx (зелёная) и Tx (красная), частота которых написана вверху («Rx 1500»). Их перетаскивают мышью; либо переводят на них фокус клавишей Tab и используют стрелки влево и вправо: по 10 Hz, по 50 Hz при удержании Shift.",
  "t.11yhdwc0vl6": "Последняя часть страницы [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]: как выделяются сообщения о Вас и метки («маркеры») на краю строк. Всё применяется сразу, кроме оговорённых случаев.",
  "t.11yppo1n200": "На курсоре: зелёный флажок (красный при передаче) в точке приёма и ромб (PSK, CW) или пара треугольников, соединённых линией (RTTY: два тона, на расстоянии, равном сдвигу), для приёма — тёмно-фиолетовым, а для передачи — красным. Когда Lock выключен, две пары совпадают и образуют один ромб.",
  "t.1201ueihhc3": "У режимов, кроме FT8 и VHF (PSK, RTTY, CW, SSTV, спутники), есть своя страница и своя панель: страниц [[nav.fox]], [[nav.contest]] и [[nav.stats]] там нет.",
  "t.120m8bxhfou": "Сопряжение телефона или планшета",
  "t.120y1x40a25": "поле заметок",
  "t.122rab7a7gb": "[[rep.title]] · минимальный сигнал: не отключается. Даже при снятом флажке [[rep.active]], пока Aurora открыта, примерно каждые 40 минут уходит анонимный сигнал только со случайным кодом установки, версией Aurora и уровнем использования (простой, приём, передача). В нём нет позывного, нет полученного из него кода и нет данных о компьютере. Он нужен, чтобы считать живые установки. Подробности — в политике конфиденциальности (docs/privacy.md).",
  "t.122wsdtnhzh": "[[sw.digi.perMode]] · RTTY, «[[digi.rtty.reverse]]» (по умолчанию выключено) и «[[digi.rtty.uos]]» (по умолчанию включено): Rev меняет местами метку и паузу, для станции, передающей наоборот; при трансивере в LSB Aurora уже сама их инвертирует. UOS возвращается к буквам после пробела, так что потерянный переход на буквы не превращает текст в цифры: оставьте включённым.",
  "t.123kpcb1nt7": "Delete или Backspace: удаляют выбранный слой (не во время набора в поле).",
  "t.124dev7bxmf": "[[nav.log]]",
  "t.1258lm894p8": "Страницы и панели",
  "t.125y1db1954": "[[agent.title]] · таблица уведомлений: одна строка на тип, столбцы «[[agent.kind]]», «[[agent.show.popup]]», «[[agent.show.icon]]», «[[agent.show.off]]»; в каждой строке выбирается только один столбец. «[[agent.show.popup]]» = карточка появляется на рабочем столе; «[[agent.show.icon]]» = карточки нет, только отметка на значке в области уведомлений; «[[agent.show.off]]» = ничего. Строки с выбором по умолчанию: «[[agent.kind.news]]» ([[agent.kind.news.tip]]; всплывающая карточка), «[[agent.kind.prop]]» ([[agent.kind.prop.tip]]; только значок), «[[agent.kind.dxped]]» ([[agent.kind.dxped.tip]]; всплывающая карточка), «[[agent.kind.daily]]» ([[agent.kind.daily.tip]]; выключено). Когда менять: устанавливайте «[[agent.show.popup]]» только для того, что хотите видеть сразу.",
  "t.126m4h6db1z": "Отдельные окна и раскладка",
  "t.1274sqtfaqs": "[[lay.settings]] · [[sch.use]] (флажок, по умолчанию выключен): включает или выключает всё расписание. При выключенном флажке строки остаются записанными, но не срабатывают. Смена происходит в указанную минуту, требует управления трансивером (CAT) и не действует во время передачи.",
  "t.127aqvg013u": "Не знаете порт и скорость? Попробуйте «[[cat.detect]]»: он найдёт их за вас. Если вы пользовались OmniRig, они указаны в его окне настроек.",
  "t.127g8quequ8": "[[digi.log.save]] (значок дискеты, внизу): записывает QSO в журнал Aurora с диапазоном, реальной частотой сигнала, режимом, рапортами, локатором, именем, QTH и заметками. Без позывного появляется «[[digi.run.noCall]]». Макрос <SAVEQSO> делает то же самое. При активном соревновании QSO, сохранённое с этой страницы, попадает и в журнал соревнования, с отправленным и принятым обменом.",
  "t.129cled0m8i": "[[set.add]] · поле «[[macro.new]]» (текст, до 30 символов): введите макрос. Используйте @ для позывного DX, & для Вашего и # для рапорта. Получившийся свободный текст — в верхнем регистре и не длиннее 13 символов; всё, чего не хватает (например, рапорта), опускается.",
  "t.12a4od0uloq": "«[[onl.grpSolar]]» · «[[onl.solar]]» (по умолчанию включено): каждые полчаса Aurora загружает с hamqsl.com солнечный поток, индексы A и K и условия, рассчитанные по диапазонам, и показывает их в [[nav.propagation]]. Сайт видит только Ваш IP-адрес. «[[ens.test]]» один раз загружает данные и проверяет, что их можно прочитать.",
  "t.12a9hrsp22u": "[[lay.lists]] · [[fil.countries]]: текстовое поле, названия стран для скрытия через запятую (например, Italy, Germany). По умолчанию пусто.",
  "t.12aagjh20nj": "[[gen.screen]] · [[gen.clearOnChange]]: флажок, по умолчанию включён. Когда трансивер переходит на другой диапазон или режим (FT8, FT4, JT), [[panel.all]] очищается: сообщения предыдущего диапазона больше не нужны. Применяется и к изменениям, сделанным в движке. Если выключен, список остаётся как есть, и Вы очищаете его вручную кнопкой Clear.",
  "t.12e2f62z27b": "Синхро находится далеко от линии 1200 Hz: радио настроено неточно или звуковая карта сдвинута по частоте. Исправьте это с помощью «[[sstv.set.rxOffset]]» в Настройках SSTV.",
  "t.12eyx27vm7c": "Включите [[gen2.waitFeatures]] ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]): по умолчанию оно выключено, поэтому Wait and Reply и Wait and Call ничего не делают, пока Вы его не включите.",
  "t.12f1e7pdkoh": "[[tab.windows]] · [[win.reset]]: возвращает всё, как в начале: порядок, высоту и разделитель панелей главной страницы, ничего не скрыто, а все отдельные окна возвращаются в главное окно. По завершении появляется «[[win.done]]». Используйте, если главная страница стала неуправляемой.",
  "t.12idz191nw6": "передаёт тоны DTMF (0-9, *, #, A-D; запятая — пауза)",
  "t.12jjldr4iw": "«[[dxs.look]]» · «[[dxs.captions]]» (включено): три мелкие строки (страна, диапазон и вид связи с позывным) под шестью метками. «[[dxs.total]]» (включено): число отработанных стран, вверху слева в сетке. «[[dxs.tryField]]» (включено): поле, в которое Вы вводите позывной, чтобы увидеть, как карточка его оценивает. «[[dxs.compact]]» (выключено): более мелкие ячейки, метки и интервалы, чтобы оставить больше места журналу; включайте на маленьких экранах.",
  "t.12lsj0keuss": "останавливает прокрутку окна RX (OFF возобновляет)",
  "t.12o9rw7ues9": "Код сообщает «[[pair.expired]]»: сгенерируйте на ПК новый и сразу введите его.",
  "t.12r0y1a2jfs": "Icom IC-7300, IC-705, IC-9700: один USB COM-порт (CI-V идёт по USB-кабелю) плюс звуковая карта «USB Audio CODEC». В [[cat.rig]] выберите модель по названию радио; скорость должна быть той, что задана в меню радио (пункт CI-V, см. руководство); адрес CI-V ([[cat.civ]]) оставьте равным 0 для заводского значения, а если вы изменили его в меню, он записывается в ДЕСЯТИЧНОМ виде (IC-7300 = 148, а не 94h): см. «Адрес CI-V радио Icom (в десятичном виде)».",
  "t.12vlj2nchgk": "[[toast.grp]] · [[toast.test]]: сразу показывает три примерных сообщения (успех, информация, ошибка) с текущими настройками. [[set.reset]]: возвращает к значениям по умолчанию только этот блок.",
  "t.12wfiwu11u0": "[[digi.menu.edit]] › [[digi.mi.clearTx]]: очищает окно передачи, а также список уже переданного текста над полем.",
  "t.12xt3121nuv": "Часто задаваемые вопросы",
  "t.12yb8biwyo9": "при начале передачи",
  "t.12ym175c24d": "Откройте журнал: примерно через 15 секунд, времени, нужного для завершения запуска, QSO приходят сами в том порядке, в котором Вы их проводили.",
  "t.12zfbsaidex": "[[ens.g.wsprnet]] · индикатор, «?» и [[ens.st.title]]: индикатор перед заголовком показывает, как всё прошло ([[ens.led.off]], [[ens.led.untested]], [[ens.led.ok]], [[ens.led.err]]); «?» объясняет, что отправляется; ниже «[[ens.st.title]]» даёт результат ([[ens.st.ok]] или [[ens.st.err]]) со временем и числом отправок, всё ещё ожидающих в очереди. Если WSPRnet не отвечает, повторные попытки идут не более одного часа. Кнопки проверки нет: тестовый спот оказался бы в публичной базе.",
  "t.130bywhe401": "записывает текст, выделенный в окне RX",
  "t.130ehgvk7vl": "Ничего не приходит: порт 2237 уже удерживает другая программа (GridTracker, JTAlert, другой журнал). Используйте другой свободный порт (например, 2239) и в Aurora, и в LogHX.",
  "t.13202u8yqvm": "[[not2.grpTable]] · [[not2.alsoSound]]: помимо цвета, воспроизводит звук, выбранный для этого типа (выбирается ниже, в «[[not2.grpColors]]»). Заблокирован, если подсветка строки выключена. Чтобы действительно услышать звук, должен быть включён «[[alert.button]]» (см. страницу «[[sw.pg.alerts]]»).",
  "t.132sl67alkh": "«повторите, пожалуйста, ваш номер» на языке другой станции",
  "t.134f56zi51": "В Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › «[[int.title]]» › «+ [[int.p.loghx]]». Оставьте 127.0.0.1, порт 2237, «[[int.wsjtx]]» и «[[int.loggedAdif]]» включёнными.",
  "t.134vty509pa": "AFC ограничена: она не отклоняется более чем на ±15 Hz от выбранной частоты в PSK31 (±30 в PSK63), на половину сдвига в RTTY, на ±50 Hz в CW; она не заходит в режекторные фильтры, остаётся внутри полосового фильтра и, когда сигнал пропадает, останавливается там, где есть, вместо того чтобы гнаться за соседней станцией.",
  "t.135fe0e0jla": "выполняет текст файла как макрос (внешние программы — никогда)",
  "t.135v7u6ma2a": "На телефоне кнопка [[stop.button]] находится внизу экрана.",
  "t.137q52gni7k": "Новый DXCC и разыскиваемая станция: выделенные оповещения",
  "t.137wqutopko": "Только для RTTY: «[[digi.rtty.shift]]» (23, 85, 160, 170, 182, 200, 240, 350, 425, 450 или 850 Hz; по умолчанию 170) и «[[digi.rtty.baud]]» (45, 45.45, 50, 56, 75, 100, 110, 150, 200 или 300; по умолчанию 45.45), которые сохраняются сразу, как выпадающие списки в строке состояния; затем [[digi.rtty.reverse]] ([[digi.rtty.reverseTip]]) и [[digi.rtty.uos]] (включено по умолчанию).",
  "t.13aodqg4x69": "Только приём, и автор пока не проверял её на реальных сигналах. Автоматическая фазировка не распознаёт 240 строк в минуту: в этом случае нужен ручной режим.",
  "t.13bi81xoayt": "[[gen.screen]] · [[gen.log4omCount]]: числовое поле от 1 до 200, заводское значение 20. Сколько последних QSO журнала Log4OM2 показывается в окне «Журнал»; журнал только читается, Aurora никогда его не меняет.",
  "t.13gmyyr9cb1": "[[wfs.colors]] · [[wfs.scale]] (по умолчанию включено): делит каждую строку на её медианное значение, так что фоновый шум всегда имеет один и тот же цвет независимо от уровня звука, а видны остаются только сигналы над ним. [[wfs.flatten]] (по умолчанию включено): убирает кривую фонового шума по диапазону; полезно, когда фильтр трансивера наклоняет пол шума. Выключите, если хотите «сырой» водопад.",
  "t.13gt2x7hxmu": "QSO и журнал: сохранить, очистить, подсчитать обмен, напечатать QSL, отправить спот в кластер. Пример окончания QSO в соревновании: TU <SAVESHAUTO> или <SAVEQSO><SENDSPOT:TNX QSO>.",
  "t.13hkzy551no": "Настройтесь на частоту SSTV (например, 14,230 MHz USB) и откройте [[nav.sstv]]: прослушивание начнётся само и будет идти, пока Вы не нажмёте «[[sstv.rx.stop]]», даже когда Вы готовите изображение в «[[sstv.view.tx]]». Режим определяется по VIS или, если VIS пропущен, по ритму строк синхронизации; после захвата он сохраняется до конца изображения.",
  "t.13i9mp0ma4o": "[[fil.decode]] · [[dec.ftolQ65]]: выпадающий список с допуском по частоте вокруг Rx, от 1 до 1000 Hz (1, 2, 5, 10, 20, 50, 100… до 1000); заводское значение 50 Hz. Это окно, в котором Q65 всегда пробует лучший сигнал, список QSO и среднее. Расширьте для EME с большим доплеровским дрейфом.",
  "t.13j2e3v0i4n": "[[lotw.grp]] · [[lotw.color]] (по умолчанию светло-зелёный) и [[lotw.months]]: сколько месяцев назад учитывается последняя выгрузка, выберите из «[[lotw.m3]]», «[[lotw.m6]]», «[[lotw.m12]]» (по умолчанию), «[[lotw.m24]]» или «[[lotw.m0]]» (отмечает и тех, кто не выгружал годами). Заблокированы, если «[[lotw.enable]]» выключено.",
  "t.13j7zbykb1i": "[[gen2.wsjtx3]] · [[gen2.waitFeatures]] (по умолчанию выключено): при заданном DX и выключенном [[ctl.enable_tx]], если DX вызывает Вас, QSO возобновляется само (Wait and Reply); при взведённой кнопке Wait and Call, когда DX вызывает CQ или завершает своё QSO, Вы сами вызываете его, до трёх раз. Внимание: передача может начаться без Ваших действий; держите выключенным, если не хотите сюрпризов.",
  "t.13lkddo7xzs": "«+ [[int.p.wsjtx]]»: название GridTracker, 127.0.0.1, порт 2237, включено только «[[int.wsjtx]]». Получает поток WSJT-X: Heartbeat (при запуске и каждые 15 секунд), Status при каждом изменении (частота, режим, текущий DX, отправляемое сообщение), Decode для каждого декодированного сообщения, Clear, QSO Logged в конце QSO и Close, когда Вы закрываете Aurora. Для GridTracker, JTAlert, QLog, CQRLOG, MacLoggerDX и других программ, читающих поток WSJT-X. При включённом «[[ens.k.AcceptUDPRequests]]» эти программы могут также отвечать станции, останавливать передачу или раскрашивать позывные.",
  "t.13mhultrdat": "Секунды периода («07/15»: текущая секунда и длина периода) и, под панелью, тонкая полоса хода периода.",
  "t.13mizugmr7m": "У карточки есть полоса с вращающимся логотипом, метка типа уведомления (Update, Propagation, DXpedition, Summary или имя автора), заголовок и короткий текст. При появлении звучит короткая мелодия; у праздничных сообщений тёплые цвета, а у тематических (Рождество, Новый год, Пасха, обновление, служебное) свой собственный вид.",
  "t.13mr7c3vmbl": "Откройте [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].",
  "t.13n9qlt82l4": "[[nav.sat]]: три страницы, [[sw.pg.orbits]], [[sat.set.catMap]] и [[sw.pg.doppler]]. Каждое изменение сохраняется сразу. Сюда также попадают через шестерёнку на странице «Спутники» и, для SSTV, через значок ⚙ на странице SSTV.",
  "t.13o9qeuerjm": "Чтобы не начинать заново каждый раз, добавьте исключение: «Защита от вирусов и угроз» › «Управление настройками» › «Добавление или удаление исключений» › «Добавить исключение» › «Папка». Выберите папку, где находится Aurora: обычно C:\\Users\\YOURNAME\\AppData\\Local\\Aurora (%LOCALAPPDATA%\\Aurora, куда её помещает установщик; если вы установили её в другое место, то эту папку). Затем добавьте также C:\\Users\\YOURNAME\\AppData\\Roaming\\Aurora (%APPDATA%\\Aurora, где Aurora хранит настройки и данные). YOURNAME — ваше имя пользователя Windows.",
  "t.13qd88sl2gi": "[[digi.mi.anticlick]] (вкл.): убирает с водопада горизонтальные линии от щелчков манипуляции, не затрагивая сигналы; действует, пока страница слушает, в том числе для водопада других страниц. Эта отметка хранится в движке, а не только на этой странице.",
  "t.13tmcm11q2m": "В панели [[panel.tx]] щёлкните шестую строку («[[tx.step.6]]»): точка показывает, что Aurora начинает с этого сообщения. Текст можно писать прямо на месте (например, «CQ DX» или «CQ EU»); в Hound CQ не передаётся.",
  "t.13xm5v8a9fu": "[[aud.input]] (поле и список): звуковая карта, принимающая звук от трансивера. Для трансиверов с внутренним USB-звуком это «Microphone (USB Audio CODEC)» или подобное; для остальных — карта интерфейса, подключённого к трансиверу. Каждая запись показывает моно или стерео и «[[aud.inUse]]», если она открыта. «[[aud.defaultPlain]]» следует выбору Windows; «[[aud.unset]]» появляется, если Вы никогда не выбирали вход; запись с пометкой «(not found)» — это устройство, выбранное в прошлом и теперь отключённое. В Linux входы называются «alsa_input…» (PulseAudio или PipeWire).",
  "t.13ytjdun3qi": "Шесть сообщений Tx1-Tx6 (название каждого: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): подсвеченная точка — то сообщение, которое Aurora передаёт или будет передавать в следующем периоде. Щелчок по строке выбирает, с какого сообщения начинает движок. Текст можно писать прямо на месте (до 37 символов): Enter или выход из поля подтверждает, Esc отменяет, а если очистить поле, вернётся стандартное сообщение.",
  "t.13yz22r6dsv": "Режим, подрежим и частота",
  "t.13z0ywh2fvi": "[[radio.sharing]] · [[radio.control]]: строка только для чтения. «[[radio.on]]» означает, что Aurora может менять диапазон и частоту трансивера со страницы «Станция»; включается при подключении трансивера в верхней части этой страницы. Здесь менять нечего.",
  "t.141rxbvqp1x": "[[wfs.spectrum]] · [[wfs.specPct]]: какую часть высоты занимает график спектра под водопадом, от 0 (скрыт) до 100; по умолчанию 30. Водопад никогда не исчезает полностью. [[wfs.specMode]]: «[[wfs.current]]» (по умолчанию) показывает последний спектр; «[[wfs.cumulative]]» — среднее за весь период, оно выделяет постоянные сигналы и начинается заново в каждом периоде.",
  "t.142aloo356f": "Aurora может ждать, пока DX освободится, вместо того чтобы передавать поверх него.",
  "t.142h4cihhyg": "Режим Q65",
  "t.142rvw1d54i": "Шесть сообщений, пронумерованных от 1 до 6, с меткой того, чем они являются, ниже ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], [[phone.kind.rr73]], [[phone.kind.73]], [[phone.kind.cq]]): касание выбирает, какое уйдёт в следующем периоде. Уже переданные приглушены; текущее подсвечено; пустое сообщение коснуться нельзя.",
  "t.142z8c0bdpc": "по Enter в поле передачи",
  "t.144pyc9l29m": "Ответ на CQ",
  "t.147zpak6kbr": "Приём и передача CW",
  "t.1489px2pfwo": "Диагностические оповещения внизу справа",
  "t.149c1jo47se": "Если установка не начинается, появляется сообщение с причиной и ссылкой для ручной загрузки установщика.",
  "t.14aspo1cyvr": "Полная статья: «Журнал закрыт: QSO придут позже»; «Потерянные QSO при закрытом журнале: где включить»; «QSO отсутствует во внешнем журнале».",
  "t.14bqwznhyu3": "[[acc.preview]]: два живых окна, «[[acc.previewPhone]]» (390×844) и «[[acc.previewTablet]]» (1180×820). Внутри настоящая Aurora с настоящими данными, как её увидело бы это устройство; элементы управления действительно работают (передача тоже, если она открыта). Настраивать нечего. Когда: чтобы увидеть, как это выглядит на телефоне, не беря телефон в руки.",
  "t.14bu1ac4aam": "Страница [[nav.log]] (заголовок «[[exp.title]]») показывает все QSO внутреннего журнала Aurora. Она нужна, чтобы искать их, исправлять, удалять, добавлять одно вручную и сохранять в файл ADIF или Cabrillo. Вверху справа: «＋ [[exp.add]]» и «[[exp.back]]» (возврат на Станцию).",
  "t.14ex3w000de": "Выбранная звуковая карта или аудиовыход для передачи пропали (радио выключено, USB-кабель отключён): включите радио, Aurora подхватит его снова сама.",
  "t.14g5iqm4hu6": "Log4OM: радио через Aurora",
  "t.14gexx04zz1": "DX-сплит из DX Cluster",
  "t.14ipskpq8yz": "Кнопки «Clear» здесь больше нет: чтобы очистить списки, используйте «[[list.clear]]» в строке заголовка Band activity и окна RX.",
  "t.14jojqljaom": "«Quit the agent»: закрывает значок до следующего запуска Windows; автоматический запуск не удаляется. Чтобы удалить его по-настоящему, выключите «[[agent.enabled]]» в [[nav.settings]] › [[sw.sec.access]] › [[agent.tab]].",
  "t.14o69xxku2o": "[[gen.screen]] · [[gen.confirmUnseen]]: флажок, по умолчанию включён. Перед вызовом станции, которой нет среди сообщений, принятых за последние 15 минут (например, из «CQ и новости» или от DX-экспедиций), Aurora запрашивает подтверждение с [[callUnseen.call]] или [[confirm.cancel]]. Для уже прочитанных станций и для ответов тому, кто вызывает вас, она не спрашивает. Двойной щелчок по спискам декодирования (Активность в диапазоне, окно RX) подтверждения не запрашивает, если не включить [[gen.confirmList]].",
  "t.14o794wvwf7": "Если Aurora недоступна, появляются «[[app.noCore]]» и кнопка «[[app.retry]]». Если телефон знал другой адрес и тот отвечает, страница предлагает «[[app.moved]]» со ссылкой «Open», за которой следует адрес: осторожно, адрес, отличный от aurora.local, может снова запросить сопряжение.",
  "t.14otr2gfiki": "[[sat.dash.lock]] фиксирует расположение (кнопка становится [[sat.dash.unlock]]); [[sat.dash.reset]] возвращает стандартное расположение (см. ниже). Расположение сохраняется само: отдельное для каждого контеста и для каждого вида (SSB, текстовые режимы).",
  "t.14p1pkgfa4c": "«+ [[int.p.multicast]]»: название Multicast, адрес 239.255.0.1, порт 2237, включены «[[int.wsjtx]]» и «[[int.multicast]]», «[[int.ttl]]» 1, «[[int.iface]]» 127.0.0.1. Получает тот же поток WSJT-X, но отправленный группе: все программы, подписанные на группу 239.255.0.1 на порту 2237, получают его одновременно (например, GridTracker 2 и QLog), не споря за порт. Каждая программа должна быть настроена на ту же группу и тот же порт. Для программы на другом компьютере укажите в интерфейсе адрес этого ПК в домашней сети.",
  "t.14q6ldb4ltf": "Внизу каждой страницы настроек (не только «Трансивер») есть четыре кнопки и строка состояния. Первые две проверяют трансивер, не покидая настроек.",
  "t.14qqrhoh122": "Ничего не доходит до программы: адрес и порт должны совпадать в обеих программах; нажмите «[[ens.test]]» и проверьте, что программа слушает. Если сообщается «порт уже используется», его занимает другая программа: закройте её или смените порт.",
  "t.14va2a74wja": "Нажмите «[[newdx.off]]» под карточками или снимите флажок «[[not2.popNew]]» (и «[[not2.popNewBand]]») в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], блок «[[not2.grpAlerts]]».",
  "t.14wsjmfo02y": "Многие пункты сохраняются сами через мгновение и при выходе со страницы (предпочтения Aurora и страницы вроде [[tab.radio]] и [[sw.tab.rotator]]). Пункты движка (режимы, службы, журнал), Автоматизации и настройки SSTV остаются «ожидающими»: внизу окно сообщает, сколько их, а «[[sw.save]]» сохраняет их (окно остаётся открытым, «[[sw.close]]» закрывает его). Если закрыть окно с несохранёнными изменениями, Aurora спросит, отбросить ли их.",
  "t.14wu3ep0mo5": "Это уведомления, которые остаются на несколько секунд (например, «Answering …»). Они появляются сразу по щелчку; если затем команда не удаётся, они превращаются в ошибку.",
  "t.14xlacgzpmy": "[[digi.edit.text]]: сценарий. Обычный текст — это то, что передаётся; слова между < > — команды или подстановки. Если сценарий содержит <TX>, текст начинает передаваться сразу; без <TX> текст лишь записывается в поле передачи, после того, что там уже есть. Одинокий <TX> передаёт то, что уже в поле. Среди команд: <RX> и <RXE> (в конце текста) возвращают на приём после отправки текста; <RXANDCLEAR> (или <RXC>) делает то же и очищает окно передачи. С <TX> и без <RX> передача остаётся открытой после текста и заканчивается кнопкой приёма. <TXE> ждёт, пока сигнал на частоте приёма пропадёт, и затем передаёт; через 30 s передаёт в любом случае, Esc отменяет ожидание.",
  "t.14yu1n0m0le": "как <MODE:mode>",
  "t.1509ogmh9gl": "Щёлкните значок: откроется окно с надписью «Новая версия Aurora: X (используется Y)». Кнопка «[[upd.install]]» скачивает (если нужно) и устанавливает: Aurora закрывается и открывается сама. «[[upd.open]]» открывает заметки и загрузку на сайте. «[[upd.later]]» скрывает уведомление до следующей версии.",
  "t.153yc7c0c79": "«[[ens.g.clublog]]» · «[[ens.k.ClublogSend]]» (по умолчанию выключено): отправляет каждую QSO в ClubLog в реальном времени, по одной. «[[ens.k.ClublogEmail]]» — адрес электронной почты учётной записи. «[[ens.k.ClublogPasswd]]»: лучше «Application Password», созданный в настройках ClubLog, чем пароль учётной записи. «[[ens.k.ClublogCall]]»: пусто = Ваш позывной из личных данных; впишите его только для другого журнала (например, для специального позывного). «[[ens.k.ClublogApiKey]]»: ключ, который ClubLog выдаёт авторам программ по запросу в поддержку ClubLog; в Aurora его нет, его нужно вписать здесь. Здесь «[[ens.test]]» не может проверять без отправки: он лишь проверяет наличие данных. При неверных учётных данных выгрузка останавливается сама (ClubLog блокирует тех, кто упорствует) и возобновляется, когда Вы их исправите.",
  "t.156d0m7co0l": "Неподтверждённые страны",
  "t.158x1rit5ou": "У записанного QSO тоже есть свой звук: «[[snd.ev.qso_logged]]» (по умолчанию фанфара). Можно выбрать другой звук, голос, собственный файл WAV/MP3 или вообще без звука.",
  "t.1590q3vofta": "[[sat.map.pick]]: выпадающий список с «[[sat.set.mapAuto]]» (по умолчанию: Aurora сама выбирает лучшую из доступных), «[[sat.map.builtin]]» (встроенная карта) и Вашими изображениями из папки «maps». Выбирайте конкретную карту, только если Вам не нравится «[[sat.set.mapAuto]]».",
  "t.15af9isucn1": "Кнопка «[[sstv.tx.send]]» серая: нужны собственный движок Aurora и звуковой выход на радио ([[nav.settings]] › [[sw.sec.station]] › «Звук»).",
  "t.15aii2c343s": "[[bfl.title]] · [[bfl.tags]]: метки новостей для показа в [[panel.all]]: [[bfl.all]] (без фильтра, заводское значение), [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]]. Строка показывается, если у неё есть хотя бы один из выбранных видов. Это тот же выбор, что и маленькая кнопка «Фильтр» панели, и он действует также на автоматизации: меняйте его, когда хотите видеть только нужное (например, только новые DXCC).",
  "t.15bj0b329qo": "Время UTC с секундами, а справа название и версия Aurora. Если программа не отвечает, вместо версии показывается текст об этом.",
  "t.15cisjgw5ri": "ON: вы остаётесь на передаче, даже если в макросе есть <RX>, пока не нажмёте RX; OFF возвращает обычный режим",
  "t.15dk2wkrb4c": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › «[[int.title]]». Другие программы, получающие данные от Aurora, по одной в строке, до 16. Знак «?» в заголовке объясняет всё и предупреждает о дубликатах. Список сохраняется кнопкой «[[sw.save]]», только если все значения верны; пока одно из них помечено как ошибка, список не сохраняется.",
  "t.15ezj5mfb7": "Не переходит на передачу: проблема в CAT (порт, скорость, PTT, меню CI-V/CAT).",
  "t.15fvdl920ha": "синхронизация радиостанции: при каждом макросе сигнал возвращается в центр (<CATDISABLEVFOSYNC> выключает)",
  "t.15h4io4p7bg": "[[ap.theme]] · [[gen.language]]: откройте меню с флагом и выберите язык; весь интерфейс, включая Справку, сразу изменится. Это первая строка страницы. Измените, если Aurora открылась на языке, который не Ваш.",
  "t.15k80yb690r": "Только для CW: «[[digi.cw.bandwidth]]» (50, 100, 150, 250, 500 или 1000 Hz, последнее — «wide» для обзора; по умолчанию 150) и «TX at received speed»: пункт серый, пока нет CW-сигнала, по которому можно измерить скорость. Полное объяснение — в разделе «Приём и передача CW».",
  "t.15kals6h8ln": "«Tx» (200-3000 Hz) и «Rx» (100-3000 Hz): звуковые частоты. Введите значение и нажмите Enter либо покиньте поле, чтобы применить; поля также следуют за водопадом. Поле Tx становится красным, если частота вне диапазона 200-2700 Hz: многие радио урезают там мощность (см. «Частота Tx вне 200-2700 Hz»).",
  "t.15kswseyy75": "Карточка «Проверить всё»",
  "t.15lsvtn93xb": "Красное предупреждение появляется и при начале передачи. Верните Tx в диапазон или сдвиньте частоту радиостанции.",
  "t.15lvekyffkj": "В Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › «[[int.title]]» › «+ [[int.p.bblogger]]». Оставьте 127.0.0.1, порт 2237 и включите «[[int.wsjtx]]» и «[[int.loggedAdif]]».",
  "t.15s3r973b0y": "Нет звука во время передачи: «[[not2.muteTx]]» в [[sw.pg.alerts]] (по умолчанию включено). Громкость всех звуков — ползунок «[[snd.volume]]» (по умолчанию 50%) в блоке «[[snd.title]]», без изменения громкости Windows.",
  "t.15tagb0nofa": "Звуковая карта",
  "t.15tcpygupka": "Из DX Cluster: щелчок по спотам RTTY или PSK, в том числе с главной страницы, открывает эту страницу уже в нужном режиме и на нужной станции (сначала учитывается план диапазонов, затем режим, указанный в споте). Вращение ручки радио никогда не меняет режим.",
  "t.15tl8qu7h86": "Меню [[digi.menu.view]]",
  "t.15txkt2lw6v": "выделенное слово становится принятым обменом",
  "t.15u5eiluwbi": "«[[digi.rtty.title]]» · [[digi.rtty.profiles]]: четыре профиля, точки Set 1-4. Профиль содержит [[digi.rtty.reverse]], [[digi.mi.afc]], [[digi.mi.snap]], [[digi.mi.squelch]], [[digi.rtty.uos]], порог шумоподавителя (вертикальный ползунок), «[[digi.rtty.txHz]]» и «[[digi.rtty.rxHz]]», «[[digi.rtty.receiver]]», «[[digi.rtty.shift]]» (также 22 и 30 Hz), «[[digi.rtty.baud]]» (также 10) и «[[digi.rtty.charset]]» ([[digi.rtty.cs.ita2]], [[digi.rtty.cs.lower]], [[digi.rtty.cs.cyrillic]], [[digi.rtty.cs.swedish]]).",
  "t.15umjj0q7fs": "[[sw.sub.ft8]] · [[sw.pg.messages]]",
  "t.15vax6652gn": "«[[panel.all]]»: сообщения диапазона. Одно касание строки — ответ этой станции. Ниже два блока, которые открываются и закрываются касанием заголовка: «[[panel.cluster]]» (споты диапазона; касание настраивает на спот; блока нет, если кластер выключен) и «[[phone.log]]» (последние 3 QSO).",
  "t.15vpdft8iko": "[[nav.contest]]: в обеих группах, для проведения контестов в FT8, FT4, MSK144 и Q65 (см. «Контест: панель и вкладки»).",
  "t.15w53tldfc8": "Сочетания клавиш и жесты",
  "t.15zcqc6mjsm": "Полная статья: «Сопряжение телефона или планшета»; «Удалённый вид»; «Телефон не обновляется».",
  "t.160zm79yi2j": "[[auto.b4]] · [[auto.filterCallers]] (флажок, по умолчанию выключен): даже когда Вы вызываете CQ вручную, Aurora не отвечает тем, кто скрыт фильтрами [[panel.all]] (континенты, страны, позывные) или исключён ниже. Если выключено, это действует только при включённых автоматизациях в боевом режиме.",
  "t.161vyx19yt9": "Pause (или пункт [[digi.mi.tx]] меню [[digi.menu.options]], или кнопка RX/TX внизу слева): если Вы не передаёте, она открывает передачу и удерживает её, отправляя текст из поля и то, что Вы пишете потом; если Вы передаёте, она закрывает её, и Вы возвращаетесь на приём, как только уже написанный текст закончится. В RTTY без текста передаётся холостой сигнал.",
  "t.1625kn4ir7z": "в RTTY и PSK добавляет в конце DE и ваш позывной (<CWID:text> — другой текст)",
  "t.163wr8t80gy": "Вкладка «[[sstv.layers]]»: «[[sstv.add.text]]», «[[sstv.add.rect]]», «[[sstv.add.ellipse]]», «[[sstv.add.frame]]» и «[[sstv.add.bars]]» добавляют слой. В списке для каждого слоя: «[[sstv.layer.up]]», «[[sstv.layer.down]]», «[[sstv.layer.hide]]» (или «[[sstv.layer.show]]»), «[[sstv.layer.dup]]» и «[[sstv.layer.del]]»; щелчок по названию выбирает слой (ещё один щелчок по выбранному названию снимает выбор). Когда список пуст, в нём написано «[[sstv.layers.empty]]». Если выбран слой с текстом или фигурой, его свойства появляются под списком, на той же вкладке.",
  "t.164hg10igd5": "Двойной щелчок отвечает, только если в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] включено «[[gen.dblReply]]». Если [[ctl.enable_tx]] не включается, появляется ошибка.",
  "t.167b06y0snc": "[[txcheck.title]] · [[txcheck.run]]: проверяет CAT, режим трансивера, PTT, аудиовыход и уровень TX Lvl по тому, что Aurora и трансивер уже сообщают, ни разу не включая PTT и не посылая звук (при VOX звук включил бы передачу). Каждый пункт зелёный, красный или серый, рядом указана причина.",
  "t.169xckn6oxn": "Карточки можно перемещать и изменять в размерах, как на панели приборов, на сетке из 12 столбцов. Возьмите карточку за заголовок и перетащите, чтобы переместить; потяните правый нижний угол, чтобы изменить ширину и высоту, или ручку на правом краю, чтобы изменить только ширину (двойной щелчок — восстановить). Карта всегда сохраняет пропорции 2/1: её размер меняется за собственный угловой маркер, а высота следует за шириной. Исходное расположение упорядочено: карта слева, под ней рядом два списка пролётов, основные карточки, небольшие, справа. В заголовке «[[sat.dash.lock]]» блокирует расположение (кнопка становится «[[sat.dash.unlock]]»), а «[[sat.dash.reset]]» возвращает всё к исходному расположению.",
  "t.16c7ljyklpf": "LogHX: QSO и «Active calls» по сети (UDP)",
  "t.16eq7feuf8f": "[[ctest.editActive]] открывает окно редактирования, разделённое на группы: [[ctest.g.general]], [[ctest.g.serial]], [[ctest.g.validity]], [[ctest.g.points]], [[ctest.g.mult]], [[ctest.g.macros]], [[ctest.g.grab]], [[ctest.g.suggest]], [[ctest.g.dupes]]. При наведении на поле показывается его объяснение.",
  "t.16ggvygxen4": "Зачёркнутая строка: связь с этой станцией уже проведена.",
  "t.16iqwqoa3vz": "Блоки [[ens.g.log]] и [[ens.g.alltxt]] появляются только с собственным движком Aurora (используемым по умолчанию). Кнопка для внесения текущего QSO в журнал вручную — это другое: она включается в [[sw.sub.ft8]] › [[sw.pg.messages]] флажком «[[pref.cmdLogQso]]».",
  "t.16j122ss1dx": "[[not2.grpAlerts]] · меню звука подсвеченного оповещения (рядом с положением, название «[[snd.ev.new_dx_popup]]») и меню «[[snd.ev.qso_logged]]»: звук карточки новой DXCC и звук записи QSO в журнал. У них есть звук по умолчанию (сигнал тревоги и фанфары). Выберите «[[snd.none]]», чтобы убрать его, ▶ — чтобы послушать. Звук карточки слышен только при включённом «[[alert.button]]».",
  "t.16jl6b68agw": "Откройте Настройки › SSTV › [[sstv.set.grpClock]].",
  "t.16lit8smebg": "Это относится к «[[int.adif]]» и «[[int.n1mm]]», но не к потоку WSJT-X (GridTracker, JTAlert), который нужен во время работы в эфире.",
  "t.16m2v3c2kc": "[[sw.sub.vhf]] · [[sw.pg.contest]]",
  "t.16mruwpynbm": "На водопаде позывной каждой станции того же цвета, что и её точка в списке, и расположен под курсором приёма; станции, вызывающие CQ, также имеют белую рамку. «[[wfm.calls]]» в контекстном меню показывает или скрывает их.",
  "t.16n8howvnoh": "Вижу сигналы, но ничего не декодируется",
  "t.16o7m239k76": "Пока Вы вводите позывной, Aurora показывает прежние QSO с этой станцией по диапазонам (режим, время, NR), а поле «Worked prefix / multipliers» сообщает, какие множители этой станции уже получены.",
  "t.16oidu07w67": "отмечает время и частоту в окне RX (как <MARK>)",
  "t.16q5mj0q13s": "«[[sat.data.title]]»: положение (долгота, широта, высота), угол места, азимут, расстояние, скорость и радиальная скорость, «[[sat.d.approaching]]» или «[[sat.d.receding]]», «[[sat.d.visible]]» или «[[sat.d.hidden]]»; ниже «[[sat.orbit.title]]» (наклонение, эксцентриситет, период, число витков в сутки, дата данных). «[[sat.info.title]]»: транспондер, аплинк и даунлинк, инвертирующий ли он; частоты нужно проверять на AMSAT.",
  "t.16rrzf0bot0": "Проверка: проведите QSO в Aurora (или добавьте одно вручную со страницы Log): оно должно появиться в журнале LogHX.",
  "t.16srk3yd7vb": "Случайные символы на шуме: включите [[digi.mi.squelch]] и увеличьте порог режима. Слабые сигналы, которые не появляются: уменьшите его или выключите шумоподавитель.",
  "t.16sy8cbxnrk": "Без Вашего локатора или без DX-станции линия станции под розой не появляется, а кнопки направлений на DX остаются выключенными.",
  "t.16t8sh4mve": "Для будущих QSO включите «[[int.resend]]» в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]: QSO, проведённые при закрытом журнале, отправятся сами, когда вы его откроете. Для уже потерянных: [[nav.log]], фильтр по дате, сохраните как ADIF и импортируйте файл в программу.",
  "t.16tzi8uytsr": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[cop.title]]. Это те же параметры, что и у шестерёнки DX Cluster на странице PSK · RTTY · CW: как выбирается спот, как долго он хранится и какие столбцы показываются. Каждое изменение применяется сразу и остаётся на этом устройстве.",
  "t.16v1x8lxse0": "Тильда перед значением (~S3) означает оценку по звуку: радиостанция не передаёт S-метр (например, с OmniRig).",
  "t.16vwyz4tik3": "Изменённый макрос не действует: проверьте «[[digi.edit.scope]]» (макрос «Only this mode» имеет приоритет над базовым) и отметку «[[digi.mi.macrosMerge]]» в меню [[digi.menu.file]].",
  "t.16x6ytqcf4h": "Команды макросов разделены на семейства. Для каждого из них ниже указано, для чего оно служит, и приведён готовый пример для копирования.",
  "t.16ycxayoyfr": "Текст нечитаем при выбранном цвете: в «[[ap.color]]» нажмите «[[ap.colorTheme]]» или включите «[[ap.contrast]]».",
  "t.170wz7d5f4l": "После сбоя (при включённом «[[rep.ask]]»): при перезапуске окно «[[rep.crashTitle]]» с «[[rep.crashSend]]» (отправляет отчёт, затем показывает код, который нужно сообщить тому, кто помогает, и «[[rep.close]]»), «[[rep.show]]» (показывает точный текст) и «[[rep.no]]» (ничего не отправляет и больше не спрашивает об этом сбое). «[[rep.crashSend]]» серая, если в этой версии не задан адрес сервиса.",
  "t.1712meraz6x": "Водопад показывает звук от 0 до 5 kHz (0-3,5 kHz, если выключить [[digi.mi.wideWaterfall]]); чем светлее цвет, тем сильнее сигнал. Он служит для выбора сигнала, который нужно слушать.",
  "t.171zsnk6sl9": "«[[digi.band.history]]»: весь текст за последние 60 секунд этого сигнала, обновляется, пока окно открыто. «[[digi.band.tune]]» переводит приём на сигнал, «[[digi.band.toQso]]» помещает позывной в текущее QSO (и запрашивает имя, QTH и страну), «[[digi.band.close]]» закрывает (также Esc). Если сигнал пропал 45 секунд назад, окно сообщает об этом.",
  "t.1737fh9mufn": "позывной другой станции",
  "t.173up6aw9jd": "Как экспедиция: в [[nav.fox]] отметьте «UltraFOX». В каждый чётный период один сигнал от 750 до 2260 Hz несёт все станции из очереди (RR73 и рапорты) или CQ.",
  "t.174f5df1bu4": "Текст макроса (до любого <RX>) уходит в эфир. Без <RX> передача остаётся открытой после текста, и то, что Вы набираете, уходит сразу; с <RX> происходит возврат на приём. <TX> одна отправляет то, что находится в поле. Если Вы уже передаёте, текст ставится в очередь. Aurora никогда не открывает пустую передачу.",
  "t.175cl5vk68h": "«[[rep.sendBundle]]»: загружает пакет без личных данных (очищенный журнал, отчёты о сбоях, версия, антивирус, трансивер, PTT, звук) и показывает код, который нужно сообщить тому, кто Вам помогает, чтобы он мог его найти. Кнопка есть, только если в этой версии задан адрес службы отчётов; иначе Вы видите «[[rep.notConfigured]]», и ничего не отправляется. Во время отправки показывается «[[rep.sending]]».",
  "t.176jlgscc71": "Tx и Rx: звуковые частоты в Hz. Введите значение и нажмите Enter; ▲ копирует Rx в Tx, ▼ — Tx в Rx.",
  "t.1771is19llf": "в Aurora нет Hell: параметр пропущен",
  "t.177p19t303g": "в Aurora нет соответствующего события: его можно открыть через <EDITMACRO:Hello> для редактирования, но сам он не запускается",
  "t.178wpoe9jh1": "Между двумя соседними окнами есть разделитель (фиолетовая полоса): перетащите его, чтобы сузить одно окно и расширить другое.",
  "t.17ayye2bhqe": "Настройка меняется в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.pg.qso]].",
  "t.17bfg2r6h06": "перевод строки (LF)",
  "t.17c7fixo27v": "Если файл всё ещё отсутствует: для Hamlib нажмите «[[cat.restore]]» (в полосе или в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]); для остальных файлов переустановите Aurora последним установщиком со страницы Releases на GitHub: ваши настройки сохранятся.",
  "t.17cv1xuhd8s": "Папка, в которой хранятся изображения, выбирается в «[[sstv.set.folder]]» в Настройках SSTV (отсюда её изменить нельзя). Если Вы не хотите хранить принятые изображения, выключите «[[sstv.set.autoSave]]».",
  "t.17deu1u4ms5": "останавливает и сохраняет запись",
  "t.17e66ly4206": "«[[bands.title]]» показывает дневное и ночное прохождение по группам диапазонов (тот, на котором Вы находитесь, подсвечен) и три самые дальние станции, которые Вас слышали. Нужны онлайн-сервисы: в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] включите прохождение и PSK Reporter; приёмы поступают в реальном времени, а страница обновляется каждые 10 секунд.",
  "t.17g4o9h5ptr": "отправляет в WinKeyer командные байты в hex",
  "t.17guhaxd9mk": "Уменьшайте TX Lvl, пока мощность передачи не станет нужной, КСВ останется низким, а ALC трансивера будет на нуле или около нуля. Мощность выбирайте ручкой трансивера, а не TX Lvl.",
  "t.17hw81lk6bj": "[[lay.notes]]: сворачиваемый блок внизу страницы с общими пояснениями: как работает связь, совместное использование и что делать, когда порт COM уже занят другой программой.",
  "t.17n1hnwnle0": "«[[int.wsjtx]]»: двоичный поток протокола WSJT-X (Heartbeat, Status, Decode, Clear, QSO Logged, Close); команды возвращаются на тот же порт, если Вы разрешили их в «[[ens.k.AcceptUDPRequests]]». Включайте для GridTracker, JTAlert, QLog и подобных.",
  "t.17ngl9tvu5d": "Для передачи перейдите в «[[sstv.view.tx]]», выберите «[[sstv.tx.mode]]» (разрешение и длительность указаны рядом с названием) и загрузите фото кнопкой «[[sstv.bg.load]]», перетащив его или вставив через Ctrl+V; кадрируйте перетаскиванием и колёсиком.",
  "t.17no68o6io0": "[[seq2.switches]] · [[seq2.prioCq]] (по умолчанию выключено): заставляет Aurora при выборе, кого вызывать, смотреть также среди CQ других станций и отдаёт предпочтение тем, кто вызывает CQ, перед теми, кто вызывает Вас. Вступает в силу после [[sw.save]].",
  "t.17s3rxgxe8i": "Двойной щелчок в GridTracker ничего не делает в Aurora: включите «[[ens.k.AcceptUDPRequests]]» и выберите в «[[ens.k.AcceptUDPReplyMessages]]», какие сообщения принимать.",
  "t.17sasthmcl4": "Под выбором режима находится панель из сегментов: каждый сегмент — переключатель (вкл. = зелёный) или кнопка. Наведите курсор на элемент, чтобы прочитать его пояснение. Если органы управления Aurora недоступны, сегменты серые.",
  "t.17slp3qn0hx": "Рядом очередь станций, до 4, по одной в строке с точкой места: щелчок по позывному сразу оставляет текущее QSO и отвечает этой станции (см. «Переход к станции из очереди»). Стрелка «Следующая в очереди» вызывает первую.",
  "t.17tj84bx90h": "Кнопка «[[bfl.all]]» убирает фильтр (видно всё). Остальные — типы сообщений с теми же названиями, что у цветных меток: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] и [[kind.new_state_band]] (штаты США). Несколько подсвеченных кнопок = сообщение проходит, если у него есть хотя бы одна из этих новостей (логика «или»).",
  "t.17uydns0tgf": "[[nav.settings]] › [[sw.fam.modes]] содержит настройки каждого режима. Здесь объяснены три ветви: [[sw.sub.digi]], [[sw.sec.sstv]] и [[nav.sat]]; FT8, JT, VHF, WSPR и Contest объяснены в других местах. Если Вы не находите параметр, используйте поиск вверху окна настроек.",
  "t.17v8dvi8x4m": "В [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]: модель, порт и скорость такие же, как в меню CAT радио, затем «[[cat.connect]]». На радио Icom адрес CI-V вводится в десятичном виде.",
  "t.17xhfuaqqpx": "Правый щелчок по водопаду: «[[wfm.calls]]», «[[wfm.wide]]», добавить режекторный фильтр (notch) в этой точке или удалить все, открыть новое окно RX в этой точке, закрыть ближайшее окно RX или поменять его с главным приёмом.",
  "t.17y75m402sn": "Фразы на языке другой станции: фразы INT пишутся на языке страны позывного (итальянский, английский, немецкий, французский, испанский, португальский, нидерландский). Пример: <INTGA> <NAME> <INTQSL> 73 с F5ABC превращается в «Bonjour Jean QSL, merci 73».",
  "t.18056clciqk": "DX Cluster: режим «DIGI» в участках цифровых видов связи",
  "t.1822v71ovvi": "Счёт: засчитываются QSO, сохранённые со страницы в окне дат и в допустимых категориях; дубли стоят ноль. Очки за QSO из [[ctest.f.pointsMyDxcc]], [[ctest.f.pointsMyCont]] и [[ctest.f.pointsDx]] (все нули = одно очко). Множители: [[ctest.f.multipliers]] и [[ctest.f.multOption]] суммируются ([[ctest.m.1]], [[ctest.m.2]], [[ctest.m.3]], [[ctest.m.4]], [[ctest.m.5]]); при [[ctest.f.bandMult]] они считаются на каждом диапазоне, с весом диапазона. Счёт = очки × множители.",
  "t.183kqdzbm5l": "сохраняет QSO в журнал (ставьте перед любой командой очистки)",
  "t.185agunzkr7": "Карточки множителей — это сетка из ячеек, по одной на значение, с цветной точкой для каждого диапазона, на котором оно отработано (160 красная, 80 зелёная, 40 синяя, 20 жёлтая, 15 пурпурная, 10 голубая). Нужное значение, которого ещё нет, затемнено, у последнего нового есть контур, а значение, которое принесёт вводимый Вами позывной, пульсирует. В заголовке показано «отработано из всего»; если значений много, сетка прокручивается внутри карточки.",
  "t.187ik44dwjt": "[[ens.g.log]] · [[ens.k.dBtoComments]] и [[ens.k.distanceToComments]] (по умолчанию выключены): добавляют рапорты в dB и расстояние в поле комментария каждого занесённого QSO. Отметьте, если хотите иметь эти данные в журнале без ручного ввода.",
  "t.1896iow9y2o": "При включённом «[[wefax.sql.label]]» справа от спектра появляется полоса: это уровень сигнала (0-100, то же число, что и порог), а красная пунктирная линия — порог. Изображение начинается, когда полоса поднимается выше линии. У полосы своя шкала, не такая, как у кривой спектра (кривая подстраивается под сигнал, а уровень — это отношение в полосе к шуму по бокам), поэтому порог нарисован на полосе, а не на кривой; уровень обновляется раз в секунду.",
  "t.18amb73fb2z": "«[[cmd.report]]» (от -50 до +49 dB): рапорт, который Вы отправляете (Tx2 и Tx3). Aurora выставляет его по сигналу станции; введённый вручную, он применяется сразу и действует, пока движок не выдаст другой рапорт.",
  "t.18anw1chi37": "Загрузка по умолчанию выключена, как «Upload spots» в WSJT-X: пока она выключена, ничего не отправляется. Споты становятся публичными на wsprnet.org; что именно отправляется, перечислено в уведомлении о конфиденциальности.",
  "t.18b30qa93dl": "[[acc.pair]] · [[acc.alt.title]]: если у ПК несколько адресов, ниже появляется QR-код для каждого из остальных, с типом сети ([[acc.kind.wifi]], [[acc.kind.cable]], [[acc.kind.mdns]], [[acc.kind.virtual]], [[acc.kind.other]]). Когда: если первый QR-код не открывается на телефоне, попробуйте следующий.",
  "t.18btpbips95": "Передача SSTV длится от получаса до почти пяти минут: держите TX Lvl низким и остановите автоматику FT8 перед передачей. Если числовое поле вне допустимого диапазона, появляется уведомление, и «[[sw.save]]» не сохраняет, пока вы не исправите.",
  "t.18cjj6filbk": "Страница «Что нового»",
  "t.18d9k1ofp6d": "Вверху находится панель фильтров, которая меняет только то, что Вы видите (споты остаются в памяти): «[[cluster.filter.band]]» («[[cluster.filter.bandNow]]» = диапазон, на котором находится радио, или один либо несколько диапазонов), «[[cluster.filter.mode]]», «[[cluster.filter.spotter]]» («[[cluster.filter.spotterMine]]» или выбранные континенты), кнопка «[[cluster.filter.newOnly]]» (только споты, новые для Вашего списка желаемых: страна, квадрат, диапазон), поле «[[cluster.filter.search]]».",
  "t.18da09v510f": "С Hamlib новый флажок «При передаче читать также ALC» (Настройки › Трансивер, по умолчанию выключен) заставляет Aurora читать уровень ALC трансивера во время передачи: он появляется в поле ALC дисплея, рядом с мощностью и КСВ, и показывает, не слишком ли сильный звук. Раньше поле всегда оставалось «—». Пока не проверено на настоящем трансивере.",
  "t.18dbxa3vv3j": "Если Вы находитесь на странице, не относящейся к режимам (например, [[nav.log]] или [[nav.dxmap]]), ни одна кнопка не подсвечена; щелчок по «FT8» или «VHF» возвращает на Станцию.",
  "t.18ek7gn9br7": "В «[[rd.layout]]» выберите расположение индикатора вверху справа: [[rd.layout.single]], один экран с крупным VFO A слева и VFO B справа, или [[rd.layout.pair]].",
  "t.18fskoz3xrt": "Olivia и Contestia — блочные режимы MFSK с коррекцией ошибок: текст приходит с небольшой задержкой, но читается даже при сигналах ниже шума, при замираниях и помехах. Contestia — родственник Olivia с более короткими блоками и всего 64 символами (без строчных букв): при тех же тонах и полосе он быстрее. Они выбираются в меню [[digi.menu.mode]] или по названию режима в строке состояния, как PSK31, RTTY и CW.",
  "t.18h3i48p9fb": "выводит окно Aurora на передний план",
  "t.18k8wqxop4z": "Если ПК слишком загружен и не успевает за звуком, под показаниями элементов управления появляется «Потеряно аудиоблоков: N»: каждый потерянный блок сдвигает время и наклоняет карту, поэтому закройте другие тяжёлые программы.",
  "t.18ly7v9rjcn": "[[cat.catmode]]: режим, который Aurora заново записывает в трансивер при каждой смене частоты, потому что некоторые трансиверы вызывают режим, сохранённый для диапазона. «[[cat.catmode.none]]» (заводской) не трогает заданный на трансивере; для FT8 со звуком по USB трансивера выберите «[[cat.catmode.data]]» (DATA-USB); «[[cat.catmode.usb]]» — для обычного USB.",
  "t.18np4trrlt0": "[[fil.decode]] · [[dec.jt65Ap]]: флажок, по умолчанию выключен. В JT65 декодирует также априорно с Вашим позывным, позывным DX и стадией QSO (только при включённом [[ctl.enable_tx]]). Включите, чтобы слышать слабые сигналы станции, которую Вы вызываете. Рядом с режимом есть и кнопка «AP».",
  "t.18o0yxassw7": "[[sstv.log.clear]]: очищает все поля.",
  "t.18o73rsn9tr": "Откройте [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]].",
  "t.18oqlsndsu3": "Откройте страницу [[nav.wefax]] из группы PSK · RTTY · CW · SSTV вверху или из меню «Режим».",
  "t.18polm8cyd0": "Ответ станции двойным щелчком.",
  "t.18qy5e38129": "PSK31, PSK63, RTTY, CW: используемый режим отмечен. Щелчок меняет его и сохраняет. Выбор RTTY не открывает «[[digi.rtty.title]]»: это окно открывается щелчком по названию режима в строке состояния.",
  "t.18rh5v425l9": "Фильтры скрывают или подсвечивают строки в списках, не влияя на декодирование. Они сохраняются сами.",
  "t.18u8miqvfdx": "[[rd.title]] · [[rd.hide]]: убирает дисплей из шапки (выбранный стиль запоминается). Включите, если Вам нужно больше места или Вы не используете CAT. Без CAT (система управления «[[cat.backend.none]]») дисплей в любом случае не появляется.",
  "t.18ulis2elr6": "Logger32: UDP BandMap и автоматическая запись в журнал",
  "t.18w155fg99t": "[[ap.preview]]: образец с обычным текстом, второстепенным текстом, строкой данных и четырьмя цветами состояния («[[ap.stOk]]», «[[ap.stWarn]]», «[[ap.stDanger]]», «[[ap.stAccent]]»): сразу показывает эффект сделанных изменений. Кнопка «[[ap.reset]]» возвращает контраст, шрифты, размер журнала, цвет текста и размер текста (100%) к значениям по умолчанию и снова включает тёмную тему; язык не меняется.",
  "t.18whm5nnwh4": "Выключите [[ctl.filter]]: во включённом состоянии в FT8 он декодирует только ±60 Hz вокруг частоты Rx (±290 Hz в Hound). Когда он включён, водопад по краям тёмный.",
  "t.18wjuebginy": "Во время контеста декодированные сообщения сортируются по ценности: очки и новые множители сверху (★ = рекомендуется), дубли зачёркнуты, жёлтым — те, кто не участвует в контесте. Двойной щелчок — вызвать, или «[[contest.cq]]».",
  "t.18wyy6yo8ns": "один раз перестраивает радиостанцию так, чтобы сигнал оказался в центре (1500 Гц или на частоте <CATVFOSYNCSHIFT:Hz>)",
  "t.18xq28mphhu": "Если Вы не хотите видеть сообщения своего QSO в Band activity (они уже здесь), включите «[[rxw.exclusive]]» в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; по умолчанию они появляются в обоих списках.",
  "t.18y41lwcg3m": "Ctrl+V: вставляет фото как фон (если в буфере обмена есть изображение и Вы не печатаете в поле).",
  "t.18yr6ppa32r": "[[sw.pg.personal]]",
  "t.191oofqdltx": "Подходящие радиостанции: SDR с TCI, передающие поток I/Q, например SunSDR2 (Pro, DX, QS) и ColibriNANO с ExpertSDR2/3, ANAN и Hermes-Lite 2 с Thetis. Или записанный файл I/Q WAV. Радиостанций только с аудиовыходом недостаточно.",
  "t.192m67s99ie": "Фильтр тех, кто отвечает на Ваш CQ",
  "t.192s3hzez1z": "Проверка PTT: «[[sw.testPtt]]» внизу заставляет трансивер передавать одну секунду (см. раздел о кнопках внизу): используйте эквивалент антенны или подходящую антенну.",
  "t.194x3bykp1v": "Цифры о приёме: сколько станций приняли Вас за последние часы, самая дальняя, лучший рапорт и полоски «[[prop.stat.byBand]]» с цветом каждого диапазона.",
  "t.194y9hsmjdi": "В открытой на весь экран карте кнопки «[[wefax.rotate.left]]» и «[[wefax.rotate.right]]» (изогнутые стрелки) поворачивают её на 90 градусов при каждом щелчке и сразу сохраняют вместо оригинала, без подтверждения; удобно для карт, переданных боком.",
  "t.196dmhw6fxh": "Радио переходит на TX, но мощности нет: до радио не доходит звук.",
  "t.196pyntgc9a": "[[sw.sub.jt]]",
  "t.19765yrr7rw": "[[bar.profile]]: название используемого профиля радио, если у Вас больше одного профиля ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).",
  "t.198d5haz1id": "В панели 4 ряда по 12 клавиш, группами по 4, все видны. В первом ряду клавиши F1-F12, во втором Ctrl+F1-F12, в третьем Shift+F1-F12 и в четвёртом Ctrl+Shift+F1-F12. Шестерёнка справа от первого ряда переключает на «[[digi.bar.single]]» (только один ряд, F1-F12) или «[[digi.bar.extended]]» (все четыре ряда); «[[digi.mi.macroRows]]» в меню [[digi.menu.view]] выбирает, сколько рядов показывать, а «[[digi.bar.font]]» открывает диалог выбора семейства, начертания и размера шрифта кнопок с предварительным просмотром. У каждой кнопки цвет её макроса; кнопки без названия пусты.",
  "t.19aolicvvwz": "Карточка новой DXCC не показывается: проверьте, что включён «[[not2.popNew]]» (а для стран, с которыми уже работали на других диапазонах, — «[[not2.popNewBand]]»), что карточка ещё не закрыта значком × (она не возвращается до перезапуска) и что станция ещё не показывалась (один раз на станцию). В таблице цветов должен быть включён и «[[not2.dxcc]]», иначе Aurora не распознаёт новую страну.",
  "t.19bq2gs77um": "[[digi.scan.title]] · [[digi.scan.once]] (по умолчанию выключено): сканирование останавливается на первой найденной станции, а не продолжается. Включите, если хотите только найти сигнал и затем следить за ним.",
  "t.19c0bubk8uq": "Позывной, локатор, регион и type 2 — параметры движка: счётчик «изменений для применения» внизу растёт, и они вступают в силу после «[[sw.save]]». Имя, фамилия, QTH и email сохраняются сразу.",
  "t.19dk9sadpvz": "«[[logio.import]]»: выберите файл ADIF (.adi, .adif или .txt) с Вашей историей, например экспортированный из прежней программы ведения журнала. QSO, которые там уже есть, не добавляются дважды. В конце сообщение показывает, сколько QSO импортировано, сколько уже было, сколько отброшено и сколько записей прочитано; карточка DXCC и статистика пересчитываются. Во время импорта кнопка неактивна («Импорт…»). Когда использовать: в первый раз, чтобы метки «работал раньше» и «новая DXCC» были верными.",
  "t.19egtaxfypf": "[[gen.screen]] · [[gen.dblReply]]: флажок, по умолчанию включён. Двойной щелчок по сообщению назначает эту станцию DX, и в нужный момент Aurora вызывает её сама (передача должна быть открыта). Если выключен, двойной щелчок только выделяет.",
  "t.19f1h14zcp3": "[[sat.map.pick]] · как добавить карту: строка под выпадающим списком («[[sat.map.addHint]]») указывает формат — изображение в равнопромежуточной проекции 360° × 180°. Скопируйте файл в папку «maps» в данных Aurora и снова откройте страницу: карта появится в списке. Кнопки для добавления отсюда нет.",
  "t.19fixrjj2fi": "скорость в словах в минуту (относительно — с + или -)",
  "t.19h3d8rm5vz": "[[nav.propagation]]",
  "t.19hi4hovua8": "[[lay.status]] · строка состояния: «[[upd.uptodate]]» зелёным, когда у Вас последняя версия; когда вышла новая, сообщает, какая, со ссылкой «[[upd.open]]» (открывает в браузере страницу релиза с примечаниями и загрузками). Если проверка не удалась (нет интернета, сайт недоступен), причина появляется красным.",
  "t.19hk7f2p1o0": "«[[ens.g.clublog]]» · «[[ens.k.ClublogToken]]»: самый простой способ. В Club Log откройте Settings › API, создайте токен (он начинается с cl_ и показывается только один раз, скопируйте его сразу) и вставьте сюда; затем включите «[[ens.k.ClublogSend]]». С токеном не нужны ни адрес электронной почты, ни пароль, ни ключ API, а «[[ens.test]]» действительно проверяет токен без выгрузки QSO. Если токен задан, Aurora использует его, даже если Вы заполнили поля старого способа ниже.",
  "t.19i3e1rhlnq": "[[sstv.log.save]]: записывает QSO в журнал Aurora с режимом SSTV, диапазоном и частотой радио. Без позывного появляется «[[sstv.log.needCall]]»; при успехе панель очищается.",
  "t.19jhgw8gsk9": "[[gen2.wsjtx3]] · [[gen2.fullDuplex]] (по умолчанию выключено): для спутников и полнодуплексных трансиверов. Если включено, период, в котором Вы передаёте, тоже декодируется (Вы видите собственный возвращённый сигнал); эти сообщения показываются, но не заставляют последовательность отвечать. Если выключено, период передачи не декодируется.",
  "t.19kz0hx34ex": "Введите модель в поиск (например, FT-2000) и щёлкните её в появившемся списке.",
  "t.19l3y7afl38": "Страница [[nav.textModes]] принимает и передаёт текст в PSK31, PSK63, RTTY и CW (и ведёт на страницу SSTV) с той же звуковой картой и тем же PTT, что и FT8, не мешая ему. Режим выбирается в меню [[digi.menu.mode]] страницы (см. «Страница [[nav.textModes]]: как она устроена»).",
  "t.19lcmh5iwrf": "[[wfs.preview.title]]: кнопка «[[wfs.preview.show]]» (затем «[[wfs.preview.hide]]») открывает настоящий водопад и спектр, как на странице «Станция», чтобы Вы сразу видели каждый параметр. По умолчанию закрыт, и Aurora запоминает последний выбор. Предпросмотр сам выключается, если Вы закроете его, смените страницу или свернёте окно, и тогда ничего не использует. Если данные не приходят, появляется «[[wfs.preview.noData]]».",
  "t.19nfxnidby7": "[[not2.grpWorked]] · [[not2.unconfirmed]] и [[not2.unconfirmedGrid]]: страна (или квадрат), с которой работали, но без подтверждения в журнале (LoTW или QSL), остаётся «новой» в цветах, в фильтре «Активности диапазона» и в автоматизации. Параметры движка, по умолчанию выключены; имеют значение, только если в журнале есть подтверждения. [[not2.unconfPreview]]: две примерные строки показывают разницу (настоящая новинка — сплошным цветом, новинка только без подтверждения — светлее и с полосами).",
  "t.19ng6vpv8x5": "Входящее изображение рисуется строка за строкой на большом экране, с истинным разрешением режима. Рядом — данные сигнала и элементы управления.",
  "t.19ntoe1je46": "снова передаёт в SSTV последнюю принятую картинку (n: n-я с конца)",
  "t.19o2m6xba2r": "очищает окно приёма",
  "t.19obzwu62gl": "WinKeyer (K1EL WK2, WK3 и совместимые, такие как WKUSB и WKmini) — внешний кейер на порту USB или последовательном порту: он получает текст, формирует CW, управляет PTT и ключом радио и принимает Вашу педаль. Его настройки находятся в Настройках › [[sw.sec.station]] › [[sw.pg.winkeyer]], рядом с радио и звуком.",
  "t.19odgm8727g": "Вы можете решать, что делает ротор до, во время и после каждого пролёта, а также заставить передавать по CAT радиостанции без сплита. Звуковой сигнал ротора и движение ротора — две разные вещи: звонок только предупреждает, движением управляют отсюда. Заводские значения осторожные: опережение 60 s и без парковки в конце пролёта.",
  "t.19phv7jw6sm": "Онлайн-сервисы журнала и поиск позывных",
  "t.19qgp4jedmm": "Правый щелчок по строке: «[[radar.spot]]» открывает окно DX-спота DX Cluster, уже заполненное позывным, реальной частотой в kHz (радио плюс тон станции, минус в LSB) и режимом в качестве комментария: остаётся только проверить и отправить. Если споты уходят через telnet-кластер и ни один кластер не подключён, пункт отключён, а его подсказка объясняет причину. «[[radar.copyCall]]» копирует позывной.",
  "t.19rarlma5wn": "Во время передачи полоса показывает ход (режим, прошедшее и общее время), а в предпросмотре уже отправленная часть темнее, с линией в достигнутом месте. По окончании (даже остановленной или с ошибкой) страница сама возвращается на вкладку «[[sstv.view.rx]]».",
  "t.19s9elbzpis": "Ширина водопада равна фильтру радиостанции, считанному по CAT (до 5000 Hz; 0-3000 Hz, если радиостанция его не сообщает). Зелёная линия отмечает начало каждого периода.",
  "t.19ue6fh81sp": "[[sw.pg.reporting]]",
  "t.19yzmz30m2s": "Режим и частота не меняются во время передачи, но кнопка цвет не меняет: щелчок просто игнорируется.",
  "t.1a0f724hevk": "[[gen.screen]] · [[gen2.showTx]]: флажок, по умолчанию включён. Ваши переданные сообщения появляются также в списке принятых, в окне [[rxw.title]]. Выключите, если хотите видеть только то, что принимаете (это противоположность [[bfl.hideOwnTx]]).",
  "t.1a14040cctv": "Выберите, какие типы показывать (ошибки показываются всегда) и сколько секунд они остаются.",
  "t.1a3gxq9vc2d": "В SSB соревнование проводится так же, как в других режимах: выберите соревнование в меню [[ctest.menu]], и Aurora настроит строку ввода, журнал соревнования и статистику. Журнал соревнования начинается с нуля и показывает только QSO соревнования.",
  "t.1a5f0mhdfxl": "Рядом появляется «Hound» (или «Super Hound»), если включён режим Hound: зелёная, когда Fox отправил код OTP и сервис его подтвердил, красная, если он ещё не проверен. Ниже строка сообщает «Fox … проверен» или «НЕ действителен».",
  "t.1a6o2b71hkj": "Страница [[nav.rotator]] (заголовок «[[rot.title]]») показывает розу ветров и элементы управления поворотным устройством. В верхней панели у неё больше нет кнопки: она открывается из [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] кнопкой «[[rot.set.openPage]]». Та же карточка может находиться и над «Станцией», в режимах FT8, FT4, JT65, Q65 и других, а также на странице PSK · RTTY · CW: она включается флажками «[[rot.set.home.ft8]]» и «[[rot.set.home.digi]]» группы «[[rot.set.grp.home]]», в том же месте. Настройка поворотного устройства описана в разделе «Поворотное устройство антенны».",
  "t.1a7du021j2o": "[[not2.grpDisplay]] · [[not2.hlDxCall]] (по умолчанию включено) и [[not2.hlDxGrid]] (выключено): подсвечивают в тексте сообщения позывной и локатор DX-станции, которую Вы вызываете, где бы они ни встречались. Выключите, если списки выглядят слишком пёстрыми.",
  "t.1a87ykkoqdy": "Стрелки ◀ ▶ по бокам ленты прокручивают её; прокручивать можно также колесом мыши или стрелками клавиатуры, когда лента в фокусе. На концах стрелка серая.",
  "t.1a8gpdkrntn": "Режимы JT65 и JT9",
  "t.1a8r1jrba84": "QMAP · [[sdr.openQmap]]: открывает страницу [[nav.qmap]] (в главном окне, если настройки находятся в отдельном окне), где выбираются источник I/Q, период и подрежимы. Полные инструкции — в пункте Справки о QMAP.",
  "t.1a8zw8iw8hz": "Значка нет: агент выключен. Включите «[[agent.enabled]]» в [[nav.settings]] › [[sw.sec.access]] › [[agent.tab]] и снова откройте Aurora либо перезапустите Windows.",
  "t.1a9f0rbdynx": "Откройте [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]].",
  "t.1aa6kvswdnx": "Ниже или сбоку (внизу на телефонах и в узких окнах) расположены истории «[[sstv.hist.received]]» и «[[sstv.hist.sent]]».",
  "t.1aap0hktddi": "Подробнее о CW — в разделе «Приём и передача CW».",
  "t.1ad0czydufh": "Редкая DX-экспедиция получает сотни вызовов. Чтобы провести много связей, экспедиция («Fox») использует специальный режим FT8, а вызывающие её станции («Hound») следуют точным правилам.",
  "t.1adzdsxv8w1": "«[[int.title]]»: дополнительные получатели, по одному на программу; поля и кнопки объясняются в пунктах «Интеграции: поля получателя» и «Интеграции: что получает каждая программа».",
  "t.1aeqjc4l3vv": "выделенное слово становится отправляемым обменом",
  "t.1aey1vhymrj": "Высокий КСВ: если радиостанция при передаче показывает КСВ выше предела, Aurora немедленно останавливается. Предел находится на карточке «Радиостанция» в настройках, [[radio.swr.title]] (от 1,0 до 4,0, по умолчанию 2,0).",
  "t.1afzarrwb5f": "«[[lp.log]]» (или клавиша Enter) заносит QSO в журнал с Вашими исправлениями; «[[lp.discard]]» отбрасывает его без сохранения. Esc не закрывает окно (оно остаётся до STOP TX).",
  "t.1ahmt9csj8d": "Автоматический CQ: клавиша с <AUTOCQ> (по умолчанию F1) включает его; Aurora повторяет текст макроса «AutoCqText» (если его нет, текст F2) с паузой 8 секунд после каждого вызова, пока Вы его не выключите; он не запускается, если передача не готова или если Вы уже передаёте. При пустом макросе появляется «[[digi.run.autoCqNoMacro]]».",
  "t.1ahv1wz6y6l": "В списке щёлкните по спутнику, чтобы следить за ним; галочка показывает его на карте с зоной радиовидимости. Таблица «[[sat.pass.title]]» даёт начало, максимальную элевацию, конец и азимут ближайших пролётов.",
  "t.1ai2d4t7tjl": "В DARC WAE DX Contest, помимо QSO, станции обмениваются QTC: строками «время позывной номер» уже проведённых QSO, передаваемыми другой станции сериями «QTC n/m» (серия n, m строк). Каждый QTC приносит одно очко отправителю и одно получателю. В соревнованиях WAEDC Aurora QTC уже есть: в RTTY они отправляются и принимаются между разными континентами, в CW и SSB идут только от неевропейских станций к европейским.",
  "t.1akvfqmvh5y": "Aurora декодирует всеми процессорами, кроме одного. Рекомендуется: 4 ядра и 8 ГБ памяти. С 2 ядрами или 4 ГБ она работает, но при большом числе сигналов декодирование может не уложиться во время.",
  "t.1aohw3tch91": "Если сопряжение было отозвано, выполните «[[acc.pair]]» заново на ПК.",
  "t.1aon0lpu0tq": "Каждая трасса — это станция. Зелёная полоса — Ваша частота приёма (Rx), красная — Ваша частота передачи (Tx): их ширина равна ширине сигнала режима (43,75 Hz в FT8).",
  "t.1apxqarwqh3": "Теперь у каждой вкладки одно окно (раньше в WEFAX внутри первого было второе), а заголовки совпадают с рамкой, с закруглёнными верхними углами. Раньше они были прямыми и выступали, а в SSTV заголовок обрезался.",
  "t.1aq98netqx4": "В PSK31 и PSK63 панель «[[digi.band.title]]» над водопадом читает сразу все сигналы выбранного режима, каждый своим приёмником (как браузер): сигнал попадает в список, когда приёмник распознаёт его как PSK, с частотой, S/N, позывным с флагом и последним текстом (неуверенные символы серым). Строки станций, вызывающих CQ, подсвечены и подсчитываются вверху. Щелчок — слушать станцию, двойной щелчок — её последние 60 секунд; «[[digi.band.miPsk]]» в меню «Параметры» отключает панель.",
  "t.1ar01uxubmk": "«[[onl.grpDxped]]» · «[[onl.dxped]]» (по умолчанию включено): делит панель «[[panel.cq]]»: справа — DX-экспедиции в эфире (подсвечиваются, если Вы их слышите сейчас), предстоящие и история; календарь загружается с ng3k.com каждые 6 часов, и сайт видит только Ваш IP-адрес. Это также то, что раскрашивает DX-экспедиции в DX Cluster. «[[onl.dxpedDays]]» (по умолчанию 15, от 0 до 90; хранится на этом устройстве): сколько дней завершённые DX-экспедиции ещё показываются внизу списка. «[[ens.test]]» один раз загружает календарь и проверяет, что его можно прочитать.",
  "t.1ar7v190iai": "[[lay.options]] · [[fil.worked]] и [[fil.workedAll]]: два флажка, по умолчанию выключены. Первый скрывает CQ станций, с которыми связь на этом диапазоне уже была; второй работает только вместе с первым и убирает все их сообщения, а не только CQ. Включите, чтобы перестать видеть тех, с кем Вы уже работали.",
  "t.1arakv1ra5": "Под верхней панелью, сверху вниз. На планшете в альбомной ориентации активность диапазона находится в левом столбце, остальное — справа.",
  "t.1arskzhscvp": "[[sw.digi.perMode]] · RTTY, ползунок порога шумоподавителя (S/N от 0 до 40 dB, заводское 0): в RTTY шумоподавитель уже смотрит, насколько уверены последние символы, и молчит на шуме даже при очень низком S/N; этот порог по отношению сигнал/шум учитывается только выше 0 dB. Учитывается только при включённом «[[digi.mi.squelch]]».",
  "t.1atdnpnpc37": "[[sw.contest.title]] · [[contest.set.start]] и [[contest.set.end]]: дата и время UTC вручную. Служат для контестов без фиксированного календаря (Custom, EU VHF, RSGB) или для исправления дат из правил.",
  "t.1au648yljtx": "Ничего не записывается: подключение в Log4OM должно быть активным и на том же порту, что и в Aurora; после изменения нажмите «Save and apply».",
  "t.1avz0tk1i5r": "Блок «[[toast.grp]]» находится внизу страницы [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]]: это сообщения, которые появляются на несколько секунд после команды («Операция выполнена», ошибка…). Одновременно показываются не более четырёх; щелчок по сообщению сразу закрывает его. Всё применяется сразу.",
  "t.1axb69qzdxy": "Страница [[nav.qmap]] (заголовок «[[qmap.title]]») показывает все сигналы Q65 в участке диапазона, прослушиваемом SDR-приёмником. См. также «QMAP: все Q65 в участке диапазона». Без SDR она пишет «[[qmap.needSdr]]».",
  "t.1axtagd9aw6": "aurora.local не отвечает: используйте IP-адрес, показанный в [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] → «[[acc.addresses]]».",
  "t.1ayh8ykzt86": "[[digi.scan.title]] · [[digi.scan.dwell]]: сколько времени приёмник остаётся на каждой найденной станции, прежде чем перейти к следующей, от 2 до 600 секунд (заводское 10). Больше времени — чтобы прочитать какой-то текст, меньше — чтобы быстро пройти диапазон.",
  "t.1azte05m04q": "курсивный текст окна RX (OFF — обычный)",
  "t.1b04t5kr1b0": "время UTC",
  "t.1b0bv6f36at": "«VHF»: группа режимов для УКВ, микроволн и EME. Её меню предлагает JT65, JT4, Q65 и MSK144; начальный режим — MSK144. Она работает как «FT8»: запоминает последний выбранный режим и при необходимости перестраивает радио.",
  "t.1b0jc6bfw5d": "«[[sstv.rx.fskId]]»: позывной, принятый в FSK, или прочерк. Затем «Line … of …»: ход приёма изображения с полосой.",
  "t.1b1a372v7ae": "Блок «[[stats.byBand]]»: для каждого диапазона проведённые страны и QSO, с полосой, чтобы с первого взгляда видеть, где проведено больше всего связей.",
  "t.1b1iko45s2d": "Для уже потерянных QSO: откройте [[nav.log]], отфильтруйте по дате недостающие QSO и сохраните их кнопкой «[[exp.save]]» в ADIF-файл; затем импортируйте этот файл в программу журнала (почти у всех есть «Import ADIF»). Для онлайн-сервиса (ClubLog, QRZ.com, eQSL, LoTW) тот же ADIF-файл загружается с его сайта.",
  "t.1b1seqaobfc": "полный переход на новую строку (CR + LF)",
  "t.1b33uuk0n5": "Управление: “[[wefax.rx.force]]” начинает сразу, не ожидая тона и фазировки (полезно, если карта уже идёт), “[[wefax.rx.finish]]” завершает и сохраняет, “[[wefax.rx.cancel]]” отбрасывает. В разделе “[[wefax.set.title]]”: IOC 576 (обычные карты, 1809 столбцов) или 288; строк в минуту 120 (или 60, 90, 240); “[[wefax.set.filter]]”; “[[wefax.set.manual]]” (без APT и фазировки); “[[wefax.set.slant]]” — для коррекции наклона изображения. “[[wefax.set.autoSlant]]” (по умолчанию включена) сама измеряет его по первым 400 строкам, наблюдая, насколько вертикальные линии карты идут по диагонали, и выпрямляет также уже принятые строки; она добавляется к ручной коррекции.",
  "t.1b50dz4pb4d": "Над списком: «[[contest.order]]» с «[[contest.order.value]]» (новые очки и множители сверху, только последние два периода) и «[[contest.order.time]]» (все, в порядке времени); «[[contest.onlyCq]]» (скрывает QSO между другими станциями); фильтр по локатору, который снимается значком ✕.",
  "t.1b5tsmon1wg": "Если Вы отметили «[[ens.k.PromptToLog]]», а окно не появляется, проверьте, что Вы нажали [[sw.save]] и что QSO действительно завершено (рапорт получен и завершение передано): с незавершённым QSO Aurora нечего заносить в журнал.",
  "t.1b6ddd0a5vy": "[[rot.set.apply]]: сохраняет параметры, введённые в блоке (подключение, модель, порт, скорость, адрес, диапазон вращения); становится доступной, только если есть что сохранять, и результат появляется рядом. В отличие от [[rot.set.enabled]], который сохраняется сам, эти параметры ждут этой кнопки.",
  "t.1b7ujwswh73": "[[aud.output]] (поле и список): звуковая карта, через которую выходит звук передачи, то есть звуковая карта трансивера («Speakers (USB Audio CODEC)» или подобное). Выбор применяется со следующей передачи (текущая не прерывается). Если ни один выход не открылся при запуске, строка состояния сообщает, что передача не активна, и выбор применяется со следующего запуска. В Linux выходы называются «alsa_output…».",
  "t.1b9rrr1mpru": "«[[dec.slowPc.always]]» держит режим всегда включённым, «[[dec.slowPc.never]]» — всегда выключенным (всё работает сразу, как раньше).",
  "t.1ba2uz8lpci": "как <ROTORCMD>, но команда записана в hex",
  "t.1bb8i8teu1x": "[[digi.edit.scope]]: «[[digi.edit.scopeAll]]» сохраняет макрос для всех режимов; «Only», за которым следует текущий режим, сохраняет его только для этого режима, и он имеет приоритет над базовым макросом с той же клавишей.",
  "t.1bbeh1fyud5": "Чтобы вызывать из окна «Active calls» (двойной щелчок, автовызов и автоответ LogHX), включите в Aurora [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › «[[ens.g.udp]]» › «[[ens.k.AcceptUDPRequests]]». Без этого LogHX получает всё, но не может заставить Aurora передавать.",
  "t.1bbpz2xr4xf": "[[digi.spot.ok]] отправляет спот и подтверждает «Спот отправлен в DXSummit»; [[digi.spot.cancel]] закрывает окно. Если не хватает позывного или частоты, появляется «[[digi.spot.bad]]»; если спот не ушёл — «[[digi.spot.fail]]».",
  "t.1bbrjbgcogc": "Завершённые QSO заносятся в журнал сами; «[[fox.drop]]» останавливает QSO, на которое нет ответа.",
  "t.1be0izs5xg3": "Во время передачи водопад приостанавливается (звук с радиостанции не поступает) и возобновляется на приёме; жёлтая линия отмечает паузу. В меню «[[wft.spec]]» пункт «[[wfs.specOff]]» скрывает спектр; перетащите серую полосу над спектром, чтобы изменить его высоту.",
  "t.1bf7d5bdxj7": "Строки станций Fox (DX-экспедиции в режиме Fox/Hound) показывают сообщение целиком, флаг и страну Fox (позывной внутри < >) и метку FOX.",
  "t.1bimw7f0k9x": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]. DX Cluster — это сеть серверов, где радиолюбители сообщают о станциях, которые слышат (частота, позывной, режим). Aurora входит с Вашим позывным по telnet и показывает чужие споты; сама она их никогда не отправляет. Для редких станций это самый быстрый способ узнать, где они. Эта страница сохраняется сама: каждое изменение уходит после короткой паузы или когда Вы покидаете страницу. Порядок на экране: «[[cluster.servers]]», «[[lay.settings]]», «[[cluster.add.heading]]», «[[cluster.dxpedColor]]», «[[cluster.state]]», «[[cluster.command]]».",
  "t.1bk9xt1irrr": "[[sstv.set.grpRx]] · [[sstv.rx.lock]]: в выпадающем списке есть «[[sstv.rx.lockNone]]» (заводской: режим распознаётся по коду VIS) или один конкретный режим, и тогда принимаются только изображения в этом режиме. Выбирайте режим, только если Вы слушаете на частоте, где все используют один и тот же.",
  "t.1bnxqcsemys": "[[ens.g.log]] · [[ens.k.toRTTY]] (по умолчанию выключено): в занесённых в журнал QSO записывает режим как RTTY вместо настоящего. В Aurora применяется только к JT9: в FT8 и FT4 ничего не меняет, поэтому оставьте выключенным, если у диплома нет особых требований.",
  "t.1bodazkjnp2": "[[lay.status]] · [[upd.latest]]: последняя версия, найденная на сайте (прочерк, если Aurora ещё не проверяла). Если она новее Вашей, выделяется звёздочкой и словом NEW. Только чтение.",
  "t.1bpxkr0g3n0": "Крестик ✕ вверху справа закрывает окно.",
  "t.1bqiwx44wex": "Частота Tx вне 200-2700 Hz",
  "t.1bs4nlnd5yj": "Последний пункт, мелким шрифтом, — это показанный участок звукового диапазона (например, «0–3000 Hz»); водопад такой же ширины, как фильтр радио, считанный по CAT (0-3000 Hz, если радио не сообщает).",
  "t.1bs6eqbqmqy": "[[seq2.switches]] · [[seq2.answerAll]]: отвечает каждой станции, которая Вас вызывает: каждая попадает в очередь, и после занесения QSO в журнал следует следующая. Если выключено, Вы отвечаете только тем, кого выберете (щелчок правой кнопкой или двойной щелчок). Тот же переключатель, что и на панели QSO («[[ctl.answer_all]]»).",
  "t.1bscpwbqosl": "Нижняя панель",
  "t.1bt4q0t2231": "Над окном просмотра находятся спектр и водопад звука с линейкой в Гц: две красные линии — чёрный (1500 Гц) и белый (2300 Гц), тёмная — центр. Перед картой многие станции передают постоянный тон на чёрном: он должен совпадать с линией 1500 Гц. Щелчок по спектру или водопаду переносит туда центр. «[[wefax.afc.label]]» (включён по умолчанию, зелёный) сам исправляет неточную настройку до 150 Гц, следуя за постоянным тоном, APT и фазированием. «[[wefax.sql.label]]» с порогом (0-100, 30 ≈ 6 дБ над шумом) начинает изображение, когда есть меняющийся сигнал (постоянного тона мало), и закрывает его после 3 секунд без сигнала: полезно, если нет стартового тона.",
  "t.1btu5hbhorw": "Проверьте, что телефон и ПК находятся в одной домашней сети и Aurora открыта на ПК.",
  "t.1bu6gl72ei3": "Списки внизу · [[auto.queue]] и [[auto.recent]]: первый показывает следующие станции, которые вызвала бы Aurora (порядковый номер, позывной, сигнал; при наведении показывается причина), второй — последние станции, вызванные автоматически (в том числе «ответила бы» из пробного режима), каждую только один раз, самые свежие первыми. Они только для просмотра, настраивать здесь нечего.",
  "t.1bvgptdnux8": "Выбранный файл не загружается, и появляется «[[sstv.bg.badFile]]»: читаются форматы JPEG, PNG, WebP, GIF и BMP.",
  "t.1bvxyolqiwq": "SSTV: клавиши быстрого доступа",
  "t.1bw8lawqe6a": "Esc: сразу останавливает передачу и выключает [[ctl.enable_tx]] (AutoTX и AutoSeq не затрагиваются). Работает только если «[[gen.escStop]]» включено в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Два быстрых нажатия Esc подряд (в пределах 0,7 s) также освобождают станцию для вызова, как «[[ctl.clear_dx]]».",
  "t.1bwf2e5jv1y": "Шапка · [[auto.modeChoice]]: две кнопки, [[auto.modeDry]] и [[auto.modeLive]]. В [[auto.modeDry]] (по умолчанию) она принимает решения и пишет в журнал, но никогда не передаёт и не трогает [[ctl.enable_tx]]. [[auto.modeLive]] можно выбрать только с ПК, после подтверждения уведомления (ответственным оператором остаётесь Вы; ARRL и DXCC не принимают полностью автоматические QSO), и он включает [[ctl.enable_tx]], пока автоматизации остаются включёнными. Кнопка неактивна, если передача закрыта на этом ПК. Возврат в пробный режим подтверждения не требует.",
  "t.1bxiz4ugtpe": "«[[lay.settings]]» · «[[cluster.login]]»: команды, отправляемые в кластер сразу после входа, по одной в строке (до 10, не более 80 символов), например set/ft8, чтобы получать только FT8, или accept/spots on hf/ft8. Разрешены только команды запроса и настройки (sh/, show/, set/, unset/, accept/, reject/, clear/, help, bye): никаких спотов и публичных сообщений. Запрещённая команда показывает предупреждение и не сохраняется. По умолчанию пусто; меняйте, только если хотите фильтровать споты у источника.",
  "t.1bykpr9e9s3": "Для RTTY задайте сдвиг и скорость, как у станции, которую Вы принимаете (обычно 170 Hz и 45,45 бод); «[[digi.freq.rx]]» — это середина между двумя тонами (в USB mark — верхний тон). Макросы меняются правым щелчком по клавише (см. «Редактирование макроса»).",
  "t.1byp51rg0t2": "При передаче: макросы и окно TX отправляют текст на WinKeyer; символы отмечаются как отправленные, когда он возвращает их эхом. Esc и перезапущенный макрос сразу очищают его буфер.",
  "t.1c25k5s2ln1": "порядковый номер контеста (001, растёт с каждой сохранённой QSO)",
  "t.1c6cl5docfs": "Если станция, которую Вы вызываете, не отвечает, в панели [[panel.tx]] щёлкните по позывному из очереди: Aurora покидает текущее QSO и отвечает ему. Маленькая кнопка » переходит к первой в очереди.",
  "t.1c7j2qal2k1": "[[set.add]] · кнопка [[set.add]]: ставит введённый текст в конец списка. Остаётся неактивной, пока поле пусто; текст, совпадающий с уже существующим, дважды не добавляется.",
  "t.1c7olqu1v4k": "«[[pair.code]]»: 8 цифр, показанных на ПК (действительны 2 минуты). При использовании QR-кода поле заполняется, и сопряжение начинается само. Без камеры введите код вручную.",
  "t.1c8bhspzo7b": "[[cat.backend]]: выберите Hamlib. С Hamlib вы получаете также настоящий S-метр, мощность и КСВ от радио.",
  "t.1c8pl30jqhf": "[[sstv.set.grpClock]] · [[sstv.set.slant]]: от -5000 до 5000 ppm с шагом 10 (заводское 0). Наклон исправляется сам на каждом изображении; это значение нужно только для звуковых карт, сильно ушедших по частоте, когда все строки получаются наклонёнными в одну сторону.",
  "t.1cavkdunrom": "GM, GA или GE в зависимости от времени",
  "t.1cawhcscmef": "«[[wish.notifyUrl]]» (необязательно, по умолчанию пусто): чтобы получать оповещение и на телефон, при закрытой странице и вдали от дома. Установите на телефон бесплатное приложение ntfy, выберите секретную тему (например, aurora-your-name-1234) и впишите сюда https://ntfy.sh/aurora-your-name-1234 или адрес собственного сервера ntfy (он должен начинаться с http:// или https://). Сообщение идёт через сервер ntfy: используйте тему, которую трудно угадать. «[[wish.test]]» отправляет тестовое оповещение на странице и, если адрес указан, также на телефон; сообщает, дошло ли оно. Неактивна, пока есть несохранённые изменения.",
  "t.1cecr7kle9d": "включает AFC (<AFCOFF> выключает, <AFC> переключает)",
  "t.1ci5gi4quy4": "Шапка · кнопка [[auto.turnOn]] / [[auto.turnOff]]: включает и выключает автоматические ответы. С телефона включается только в пробном режиме. В боевом режиме, когда автоматизации выключаются (вручную, при достижении предела, без подключённых устройств или по STOP TX), [[ctl.enable_tx]] возвращается в прежнее состояние.",
  "t.1ci8be5goqe": "[[tab.schedule]] · [[sch.band]] (выпадающий список в каждой строке): диапазон, на который нужно перейти в это время. Запись [[sch.none]] оставляет строку пустой: её выбор удаляет строку из расписания.",
  "t.1cilv6134mq": "Ваш выбор сохраняется сам и также действует для «[[panel.cq]]» и для Автоматизации (она отвечает только станциям, проходящим фильтр). Он не меняет декодирование: скрывает только строки.",
  "t.1cim41uxa6h": "Переключатель светлой/тёмной темы (тот же значок, что и на ПК).",
  "t.1civmd3xnne": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]], группа «[[lotw.grp]]»: «[[lotw.enable]]» (по умолчанию включено), «[[lotw.color]]» и «[[lotw.months]]» (3, 6, 12 или 24 месяца, либо «[[lotw.m0]]»). Учитываются только станции, загружавшие журнал в течение этих месяцев.",
  "t.1cj7xdjwrnj": "Под индикатором остаются только частота VFO B (если радиостанция её передаёт) и кнопка TUNE: других блоков для выбора больше нет.",
  "t.1ckgli9sce0": "отмечает время и частоту в окне RX",
  "t.1cn92wv7klq": "значение ключа из INI-файла в папке текстов макросов (только чтение)",
  "t.1cp0dqnwsi9": "Найдите записи о файлах Aurora (rigctld.exe, libhamlib-4.dll, rotctld.exe, index.html, cty.dat): откройте запись, нажмите «Действия» и выберите «Разрешить на устройстве». Файл вернётся на место. В Avast и других антивирусах панель называется «Карантин»: восстановите файл и добавьте его в исключения.",
  "t.1cqhf6dpgu4": "Нажмите «Применить» или «Сохранить», затем [[auto.turnOn]]. Сначала попробуйте [[auto.modeDry]]: [[auto.log]] сообщает, кому она ответила бы (зелёным), кого пропустила и почему (оранжевым) и что её остановило (красным). Когда будете готовы, на ПК перейдите на [[auto.modeLive]] переключателем в заголовке: Aurora попросит подтвердить уведомление (она будет передавать сама, ответственность остаётся на Вас, ARRL и DXCC не принимают полностью автоматические QSO); возврат к [[auto.modeDry]] подтверждения не требует.",
  "t.1cr24xhgigq": "[[sw.sec.sstv]] › [[sw.pg.rx]]",
  "t.1crs18dl35s": "Вверху семь блоков с цифрами (наведите курсор, чтобы прочитать, как они вычисляются): «[[stats.qsos]]», «[[stats.calls]]», «[[stats.dxcc]]», «[[stats.cq]]» и «[[stats.itu]]» (с полосой прогресса и итогом), «[[stats.grids]]» и «[[stats.prefixes]]».",
  "t.1crzd7uxt6y": "Olivia и Contestia",
  "t.1cspkkdrbxa": "Она сама выключилась: [[auto.log]] указывает причину (предел, заданный на ПК, нет подключённого устройства, STOP TX или ограничение числа QSO в час). После проверки включите её снова.",
  "t.1cvpjlcxo6b": "Водопад",
  "t.1cwle9j0if6": "меняет местами точку и тире на манипуляторе WinKeyer",
  "t.1cy2rmaiube": "Правый щелчок по элементу нижней панели открывает небольшое меню: Squelch, AFC, Lock, Snap, порог шумоподавителя, часы UTC и мигающий TX.",
  "t.1d1wpqc3d49": "[[sw.tab.info]]",
  "t.1d3p6w9atlu": "[[digi.edit.insert]]: записывает выбранную команду в текст, туда, где находится курсор (также двойным щелчком по команде).",
  "t.1d3rpz11twr": "Страница [[nav.textModes]]: как она устроена",
  "t.1d86grors3f": "местная дата",
  "t.1d8sy73ac3x": "очищает окна RX и передачи",
  "t.1d90fof88c2": "сегодняшняя дата (UTC)",
  "t.1dbblkhy5yq": "В «[[digi.ms.title]]» выберите «[[digi.cw.bandwidth]]»: 150 Hz подходит почти для всех случаев; уже (50-100 Hz) убирает шум и соседние станции. При включённой АПЧ тон захватывает станцию, даже если она отстоит на несколько десятков Hz, и следует за ней при уходе частоты; на одном шуме остаётся на месте.",
  "t.1dcx5gmduil": "Антенный ротор",
  "t.1dd5rwx8kdj": "«доброе утро», «добрый день» или «добрый вечер» на языке другой станции",
  "t.1ddsrwd8xau": "Чтобы удалить QSO, нажмите «[[exp.edit.delete]]» и подтвердите: оно исчезнет из журнала Aurora и ADIF-файла, и восстановить его из программы будет нельзя.",
  "t.1di6z25ekkg": "меняет местами основной приём и первое дополнительное окно RX",
  "t.1dj2io0vn4f": "Полоса в заголовке и афиша",
  "t.1dm6lab91ge": "В «[[acc.devices]]» Вы видите сопряжённые телефоны; «[[acc.revoke]]» удаляет один из них.",
  "t.1dmf4mgmukx": "[[sw.pg.profiles]]",
  "t.1dmm5rd94h7": "CW с WinKeyer",
  "t.1dmqqrp2y4u": "Для ротора настройте его в [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] и включите «[[sat.ctl.rotor]]»: он следует за азимутом и элевацией выбранного спутника и незадолго до пролёта поворачивается туда, где тот появится. На радаре синее кольцо — это направление ротора.",
  "t.1dmrmzse2cf": "[[tab.windows]]",
  "t.1do9cq95i3r": "Тот, кто Вас слушает, должен использовать тот же режим и тот же период T/R.",
  "t.1dpxr2d2f2o": "Вы также используете JTAlert: в BBLogger строки «Msg ID 5» и «Msg ID 12» должны указывать на порт JTAlert, 2334, а не 2237.",
  "t.1dqhquxggzz": "[[not2.grpAlerts]] · [[not2.alertMy]] (по умолчанию включено) и [[not2.alertDx]] (выключено): оповещение выбранным звуком, когда станция вызывает или отвечает на Ваш позывной, и когда приходит сообщение от DX-станции, с которой Вы работаете. Звук выбирается в меню «[[snd.ev.alert_my_call]]» и «[[snd.ev.alert_dx_call]]» блока «[[snd.title]]».",
  "t.1dr45u6ff8i": "переносит радиостанцию так, чтобы принимаемый сигнал оказался на 1500 Гц",
  "t.1dr8kawm8av": "На телефоне одно касание строки сразу отвечает.",
  "t.1du1c3fmtpz": "[[digi.mi.rx]] и [[digi.mi.tx]]: отметка показывает, принимает или передаёт Aurora. Выбор TX (сочетание клавиш: клавиша Pause) открывает передачу и удерживает её; выбор RX во время передачи закрывает её в конце текста. См. «RX/TX, Pause, Esc и Auto CQ».",
  "t.1du9gq47xox": "[[sw.tab.appearance]]",
  "t.1duv5li7fxz": "[[sw.mem.title]] · список: двадцать пронумерованных строк, у каждой краткое описание того, что в ней хранится (режим, частоты, RTTY, AFC, Snap, шумоподавитель), или «[[sw.mem.empty]]». Ячейка памяти заполняется из меню [[digi.menu.options]] › [[digi.mi.memory]] › [[digi.mi.memWrite]] рабочей страницы, а не отсюда.",
  "t.1dwhf4qy6hv": "Внизу [[about.links]]: пять кнопок, открывающих браузер: «[[about.site]]», «[[about.repo]]» (код на GitHub), «[[about.releases]]» (установщики всех версий), «[[about.issues]]» (сообщить о проблеме или написать автору) и «[[about.qrz]]».",
  "t.1dx5t4i6lp5": "«[[ens.g.udp]]» · «[[ens.k.AcceptUDPRequests]]» (по умолчанию выключено): если включено, подключённые программы могут управлять Aurora (ответить станции двойным щелчком, остановить, написать свободный текст, цвета, смена локатора…). Если выключено, они могут только читать, и никакая передача не запускается по команде UDP. Включайте, только если Вам нужен двойной щелчок в GridTracker или подобное. «[[ens.k.AcceptUDPReplyMessages]]» (по умолчанию «[[jx.reply.1]]») выбирает, какие запросы ответа принимаются: «[[jx.reply.1]]», «[[jx.reply.2]]» или «[[jx.reply.3]]»; имеет значение только при включённом предыдущем поле.",
  "t.1dxim3zrssg": "Азимут вычисляется по вашему локатору и локатору другой станции в текущем QSO; если какого-то нет, Aurora сообщает об этом и не поворачивает.",
  "t.1dzcuer81vc": "[[fil.decode]] · [[dec.ftolMsk144]]: выпадающий список от 20 до 500 Hz (20, 50, 100, 150, 200… до 500); заводское значение 50 Hz. Задаёт, насколько далеко от Rx в MSK144 ищутся метеорные импульсы. Увеличьте, если Ваша частота или частота другой станции неточна.",
  "t.1e1llz859ru": "[[cat.grp.split]] · [[cat.split]]: «[[cat.split.none]]» (заводской) оставляет трансивер в симплексе; «[[cat.split.rig]]» — настоящий сплит (передающий VFO смещается, а звук остаётся между 1500 и 2000 Hz); «[[cat.split.emulate]]» смещает частоту только во время передачи. С FT-991(A) Link настоящего сплита нет (только VFO A). Включите его, если Ваш трансивер создаёт гармоники или шум при высоком уровне звука.",
  "t.1e2awf018h0": "через s секунд запускает макрос (без макроса подаёт сигнал тревоги); <TIMER:0> останавливает его",
  "t.1e59gl2dhf3": "контест: рапорт, отправленный в последней записанной QSO",
  "t.1e7to3dfqwq": "Щёлкните предупреждение: Aurora сначала пытается исправить время Windows по серверам NTP; только если не получается (обычно не хватает прав администратора), открывается [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] с проверкой сервера NTP.",
  "t.1e9f7b3w00a": "Это список сигналов CW и PSK, которые Aurora слышит на диапазоне, на странице текстовых режимов: щелчок по строке настраивает на эту станцию.",
  "t.1e9hnn5t96k": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]] находится таблица частот настройки: когда Вы выбираете диапазон (и режим), Aurora переводит трансивер на частоту этой строки. По одной строке на выбор, и таблица сохраняется сама.",
  "t.1ea0vrameks": "[[lay.settings]] · [[upd.interval]]: числовое поле, от 1 до 168 часов (по умолчанию 1; обычно хватает 6–24). Сколько часов между собственными проверками Aurora. Становится серым, если «[[upd.enabled]]» выключено. Если значение вне пределов, появляется «[[upd.invalid]]», и оно не сохраняется. Когда: увеличьте, если хотите меньше обращений к сайту.",
  "t.1ebfzi8y99m": "Более точные Wait and Reply и Wait and Call",
  "t.1echqxiya8v": "QSO, уже внесённое в журнал Aurora, можно исправить (неверный позывной, время, диапазон, рапорты, локатор, имя, комментарий) или удалить.",
  "t.1edd5xokq1x": "[[sat.ctl.title]] · [[sat.ctl.prepoint]] (по умолчанию включено): незадолго до пролёта поворотное устройство уже направляется туда, где поднимется спутник, и не гонится за ним первые минуты. Параметр нельзя изменить, пока «[[sat.ctl.rotor]]» выключено.",
  "t.1edlzzdejx0": "Вкладка «[[contest.tab.race]]» — рабочая страница во время контеста. Сочетания F1–F4 описаны в «Контест: клавиатура и команды».",
  "t.1eex8320rxm": "то же, что <AUTOCQ>",
  "t.1ef66wv1lnh": "локатор другой станции",
  "t.1efb53tw8ft": "[[digi.scan.title]] · [[digi.scan.timeMarks]] и [[digi.scan.freqMarks]] (по умолчанию включены): для каждой найденной станции записывают в принятый текст время UTC и частоту, чтобы Вы знали, когда и где что услышали. Выключите ради чистого текста.",
  "t.1eff0n83tkc": "«[[fil.always]]»: эти станции показываются, даже если другой фильтр их скроет.",
  "t.1efqzbd7613": "включает передачу (OFF выключает)",
  "t.1egkqvm3dv3": "[[digi.edit.title]] · [[digi.edit.scope]]: «[[digi.edit.scopeAll]]» действует для PSK, RTTY и CW; «Only» используемого режима действует только для этого режима и имеет приоритет над базовым макросом той же клавиши. Макрос «только для режима», оставленный пустым, освобождает клавишу в этом режиме.",
  "t.1egmx0libb9": "Режим WSPR и загрузка на WSPRnet",
  "t.1ejrn8pty0m": "Измерения сигнала (только при включённом приёме): S/N в dB во всех режимах, IMD в PSK (измеряется во время переворотов фазы в начале каждой передачи: ниже -20 dB сигнал чистый), принимаемая скорость в CW.",
  "t.1enfkk94csc": "«+ [[int.p.loghx]]»: название LogHX, 127.0.0.1, порт 2237, включены «[[int.wsjtx]]» и «[[int.loggedAdif]]». Получает поток WSJT-X (состояние и декодирования, в том числе для окна активных вызовов) и после каждой QSO запись ADIF в сообщении 12, так что QSO доходит, даже если программа не получает её из сообщения QSO Logged. В журнале нужно включить приём UDP потока WSJT-X/JTDX с 127.0.0.1 и тем же портом, а также автоматическую запись полученных QSO. Если Вы используете порт, отличный от 2237 (например, 2239), измените его в обоих местах.",
  "t.1eofwbo071v": "Отчёты об ошибках: что отправляется и как отключить",
  "t.1ep1kkm0xz4": "[[digi.wk.test]] открывает WinKeyer и отправляет «VVV»: радио передаёт. Без теста он открывается сам при первом макросе.",
  "t.1epdsmmkxkl": "Справа от панели находится блок OTP: «[[fox.otpOn]]» / «[[fox.otpOff]]», «[[fox.otpSeed]]» (16 символов A-Z и 2-7, сохраняется на ПК; пусто = остаётся сохранённый), «[[fox.otpEvery]]» (через сколько периодов отправляется код), «[[fox.otpSave]]» и «[[fox.otpRemove]]». Он нужен, чтобы доказать Hound, что Вы настоящая экспедиция.",
  "t.1epqhlm1ww": "оповещение по принятому тексту: в Aurora такого оповещения нет, макрос не запускается",
  "t.1epsndesd4m": "Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] → «[[ens.g.adif]]»: включите «[[ens.k.EnableUDP2adifBroadcast]]», 127.0.0.1, порт 2237.",
  "t.1eu7mqksb97": "Чтобы реально пользоваться контестом (активировать его, вызывать, экспортировать Cabrillo), перейдите на страницу [[nav.contest]]: здесь Вы только готовите данные. Для контестов с MSK144 или Q65 те же настройки находятся в [[sw.sub.vhf]] › [[sw.pg.contest]].",
  "t.1ev4e58v2a9": "Двойной щелчок по строке: радио переходит на частоту спота, не передавая. Достаточно одного щелчка, если выбрать это в колесе (ниже). При «UP 5» в комментарии и включённом Split DX радио также переходит в сплит (см. «DX-сплит из DX Cluster»). Наведение курсора на позывной показывает карточку станции; щелчок правой кнопкой по DX или DE: «Открыть на QRZ.com».",
  "t.1ew5qiet1pk": "PTT — тот, что выбран в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] (CAT через Hamlib или OmniRig): убедитесь, что не остался включённым VOX.",
  "t.1ewl1p0ot03": "текст снова передаётся после <HIDETEXT>",
  "t.1ewt9mrboaa": "Если Вы прокручиваете список вручную, то через 15 секунд без касания он возвращается наверх, где находятся экспедиции в эфире. Включается и выключается с помощью «[[onl.dxped]]» в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.1ex4yqjv0m0": "Если водопад выглядит серым или слишком ярким, сначала попробуйте «[[wfs.zero]]» (понизьте его), а затем «[[wfs.gain]]»; чтобы вернуть, нажмите «[[set.reset]]».",
  "t.1exbrfu4sa3": "Служебные знаки отображаются как <AR>, <BT>, <KN> и <SK>; будучи записаны так в тексте для передачи или в макросе, они уходят в эфир как один знак.",
  "t.1ey5wbsumao": "Блок с шестью сообщениями Tx и, внизу страницы, три кнопки, всегда находящиеся под рукой.",
  "t.1eygjcs8hkz": "Панель CQ и новостей и DX-экспедиции",
  "t.1f04krwe5t5": "После обновления Aurora телефон показывает замороженные данные или старую версию.",
  "t.1f0mctbu1i4": "Режекторные фильтры, полосовой фильтр и ограниченная AFC",
  "t.1f0xpqorm5m": "Когда выходит новая версия, при запуске посередине появляется плакат с новинками: «Установить и перезапустить» устанавливает её, «Позже» скрывает до следующей версии. Тем временем Aurora сама скачивает её в фоне и проверяет подпись: небольшая оранжевая полоса вверху показывает ход загрузки, а затем «Готово · Установить и перезапустить», так что установка начинается сразу, не дожидаясь загрузки.",
  "t.1f27rcyu58z": "[[digi.mi.snap]]: щелчок по водопаду переводит настройку на пик сигнала (в RTTY — на пару двух тонов, в PSK — на середину сигнала, где несущая). Включено по умолчанию.",
  "t.1f5mqqywvhp": "записывает значение сигнала: SN (S/N), OFFSET (звуковая частота), RATE (бод или WPM), MODE, IMD",
  "t.1f64k6d5nl7": "Звук теряет блоки: кнопка «[[diag.howto]]» открывает карточку с проверками, которые нужно сделать по порядку (USB-кабель, энергосбережение USB, тяжёлые программы). «[[diag.fix]]» ведёт на страницу [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].",
  "t.1f86z2pulvm": "«[[lay.settings]]» · «[[cluster.splitDx.set]]» (по умолчанию включено, хранится на этом устройстве): при двойном щелчке по споту, в комментарии которого указано UP, DN или QSX (например, «UP 5» или «QSX 14.030»), Aurora ставит приём на частоту спота, передачу — на другой VFO со сдвигом, указанным в комментарии, и включает сплит трансивера. Относится к кластеру страницы [[nav.station]] и страницы [[nav.digi]]. Если флажок снят, двойной щелчок только настраивает частоту. Работает, если трансивер сообщает о сплите (Hamlib, OmniRig, TCI, Cat4OM); отключается сам при смене диапазона или частоты.",
  "t.1f8g1zi4jju": "Значок Aurora рядом с часами. Windows 11 обычно помещает его под стрелку «^»: Aurora сама пытается вывести его на видное место через несколько секунд; если не получается, перетащите его к часам. Подсказка над значком гласит «Aurora»; если для какого-то уведомления Вы выбрали «icon only», она показывает заголовки новых уведомлений.",
  "t.1fbjvjoh9ro": "[[sstv.set.grpTx]] · [[sstv.set.txOffset]]: от -200 до 200 Hz с шагом 5 (заводское 0). Сдвигает все передаваемые тона на столько Hz: нужен только если Ваш трансивер выдаёт их не на месте (те, кто Вас принимает, видят их смещёнными).",
  "t.1fblxmlr1r2": "[[sat.ctl.title]] · [[sat.ctl.doppler]] (по умолчанию выключено): выше минимального угла места Aurora каждую секунду корректирует частоту трансивера на доплер: приём на основном VFO, передача на VFO сплита. Включайте, когда следите за пролётом с подключённым трансивером.",
  "t.1fbmbewooka": "Эта страница не нужна, чтобы перемещать панели и менять их размер: перетаскивайте их за заголовок, меняйте размер за нижний край, а двойной щелчок по заголовку сворачивает их. Все маркеры изменения размера выполнены одинаково: короткая линия посередине.",
  "t.1fbxalikb6d": "«[[sstv.rx.cancel]]»: отбрасывает приходящее изображение (активна только во время приёма).",
  "t.1fbynbj1khn": "BBLogger: QSO по сети (UDP), рекомендуется",
  "t.1fc97smyg4l": "Правильный порт: в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] выберите COM-порт радио в [[cat.port]] (нажмите «[[cat.ports.refresh]]» после включения радио или подключения кабеля).",
  "t.1fcea7qjes4": "Включить звуковые оповещения: на нижней панели щёлкните динамик. Зачёркнут = выключено (по умолчанию); с волнами = включено. Как только они включены, ползунок рядом задаёт общую громкость (от 0 до 100%, по умолчанию 50%); когда выключены, ползунок заблокирован. Первый щелчок также позволяет браузеру разблокировать звук.",
  "t.1ff7qgfa11n": "запускает сканирование диапазона (<STOPSCAN> останавливает)",
  "t.1ffco2nw3b2": "Цвет (и подсвеченная строка) типа новинки: в [[sw.tab.colors]], в таблице, снимите флажок «[[not2.colHighlight]]» в строке и нажмите «[[sw.save]]». Чтобы изменить цвет, воспользуйтесь выбором в блоке «[[not2.grpColors]]».",
  "t.1ffv7nhfb7u": "[[gen.screen]] · [[pref.cmdTune]] и [[pref.cmdLogQso]]: два флажка, по умолчанию выключены. Они показывают на панели «Команды» кнопку Tune (постоянная несущая для настройки) и кнопку Log QSO (заносит текущее QSO в журнал вручную). Включайте их, только если они Вам нужны.",
  "t.1fgcfe9xk6i": "Настоящий ли Fox? Проверка OTP",
  "t.1fkmcx3fpuk": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]] находятся проверка Fox (для тех, кто вызывает экспедицию в режиме Hound) и настройки контестов FT8 и FT4, те же, что и в шестерёнке страницы [[nav.contest]]. Блок Fox существует только с собственным движком и применяется кнопкой [[sw.save]]; форма контеста сохраняется собственной кнопкой [[contest.set.save]].",
  "t.1fl0puxqt2a": "Один щелчок по строке выбирает её. Двойной щелчок: вы отвечаете этой станции (см. «Ответ на CQ»); нужна галочка «[[gen.dblReply]]». Двойной щелчок по этим спискам не запрашивает подтверждения («Вы хотите вызвать…?»): если оно нужно, включите «[[gen.confirmList]]». Не путайте «[[gen.confirmUnseen]]» и «[[gen.dblReply]]»: первое убирает окно подтверждения, второе отключает сам ответ по двойному щелчку. Щелчок правой кнопкой по строке: станция попадает в очередь для следующего QSO; ещё один щелчок правой кнопкой убирает её (см. «Очередь и [[ctl.answer_all]]»). Щелчок правой кнопкой по позывному: меню с «Open on QRZ.com» и «Add to queue» (или «Remove from queue»); Esc или щелчок снаружи закрывает его.",
  "t.1flo9r9pm2w": "В файлах ADIF с повреждённым полем (неверная длина, незакрытый дескриптор, запись без конца) теряется только это поле, а не остальной файл; второй позывной в той же записи больше не смешивается с полями первого, а хвост файла без конца записи не сливается со следующим файлом. JT65 безопасно отклоняет недопустимые стирания, а в Fox специальный позывной CLEARALL! очищает баллы.",
  "t.1fmyo7fb3y3": "[[rep.title]] · [[rep.sendBundle]]: загружает на сервис того, кто разрабатывает Aurora, версию пакета без личных данных (очищенный журнал работы, отчёты о сбоях, версия, трансивер, PTT, звук) и показывает код, который нужно сообщить тому, кто Вам помогает, чтобы он мог его найти. Появляется только если в этой версии задан адрес сервиса; иначе примечание сообщает, что ничего не отправляется. Во время отправки показывает «[[rep.sending]]». Когда: если Вам помогает разработчик и Вы не хотите отправлять zip вручную. Начиная с 0.11.287 пакет также содержит в «diagnostica» команды, отправленные трансиверу, с ответами, настройки и состояние трансивера, ПК, звук и окно, последние ошибки страницы и сводку журнала работы: этого достаточно, чтобы понять проблему без дополнительных вопросов, и всегда без личных данных.",
  "t.1foufdn79de": "Поднимайте ползунок TX Lvl и следите за мощностью и КСВ на дисплее, а также за ALC на собственном приборе трансивера (пункт «Ползунок TX Lvl»).",
  "t.1fs895wiqqz": "[[bak.intro]]",
  "t.1ftn1bujepw": "Одна программа на порт: COM-порт может открыть только одна программа. Закройте WSJT-X, JTDX, программы ведения журнала и всё остальное, что использует радио. Если они нужны одновременно, подключите их через OmniRig или Cat4OM: Aurora поддерживает оба ([[cat.backend]] → «[[cat.backend.omnirig]]» или «[[cat.backend.cat4om]]»).",
  "t.1fu81pckrcg": "[[seq2.switches]] · [[seq2.single]]: после завершённого QSO Aurora прекращает передачу. После QSO выбор следующего DX остаётся за Вами (или за очередью [[seq2.answerAll]]). Тот же переключатель, что и на панели QSO («[[ctl.single_qso]]»).",
  "t.1fwsnrpojq6": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. Страница для тех, у кого трансивер SDR: она собирает в одном месте всё необходимое (TCI и QMAP) и не имеет собственных настроек, потому что адрес TCI — это адрес CAT, звук TCI — это страница «Звук», а переключатель QMAP — предпочтение. С обычным трансивером (FT-2000, IC-7300…) она не нужна.",
  "t.1fwv3sy4k57": "[[lay.settings]] › [[upd.whenIdle]]: флажок, по умолчанию выключен, только на ПК, где работает Aurora. Если включён, после загрузки и проверки нового пакета Aurora сама его установит и перезапустится, но только если не идёт передача, передача не разрешена, нет открытого QSO, нет станций в очереди и 10 минут не использовались мышь и клавиатура. Если какое-то условие не выполнено, ничего не происходит: обновление ждёт и устанавливается кнопкой «[[upd.install]]». Когда включать: для станции, которую оставляют без присмотра (например, удалённой) и хотят всегда на последней версии.",
  "t.1fy81t10wtq": "В Linux не запускается rigctld? Сообщение содержит причину, названную Hamlib (с её строками): прочитайте её, чтобы понять, что неверно: модель, порт или скорость. Icom на 4800 бод открывается медленно: Aurora ждёт до 15 секунд.",
  "t.1fyr9x7b68c": "Только для CW и PSK: «[[digi.band.mi]]» (CW) или «[[digi.band.miPsk]]» (PSK31/PSK63) включает и выключает панель сигналов диапазона и их декодирование.",
  "t.1fzasidoivf": "Соревнования в SSB",
  "t.1fzm7oiirzn": "Под меню слева находится панель макросов: 4 ряда по 12 клавиш (см. «Панель макросов»). Рядом — селектор диапазона: кнопка показывает диапазон и частоту радио в MHz; щелчок открывает список частот плана диапазонов IARU для текущего режима, одна строка на диапазон. Название диапазона переводит радио на основную частоту; остальные частоты расположены рядом (маленькая метка указывает район IARU, если они действуют только в нём). Пока Вы передаёте, селектор заблокирован. В SSTV и в текстовых режимах список берётся из плана диапазонов IARU, а не из FT8. В SSB селектор заменяют кнопки диапазонов, по одной для каждого диапазона, выбранного в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]]: щелчок переводит радио на первую телефонную частоту плана диапазонов IARU Района 1.",
  "t.1fzripza1v": "«*» в тексте — это символ, которого нет в азбуке Морзе: если Вы видите их много, тон находится вне фильтра. Переместите курсор на сигнал или включите AFC.",
  "t.1g0ulcd0k3p": "В больших изображениях историй: ← и → — предыдущее и следующее, Esc — закрыть. На лентах миниатюр: ← и → — прокрутка.",
  "t.1g14b1xuwj": "Вверху диапазон и режим: если идёт передача, Aurora запрашивает подтверждение перед их сменой.",
  "t.1g33cb29v7": "Нижняя строка показывает S/N (в 3 kHz, как в WSJT-X) и считанную скорость. Шумоподавитель смотрит на тот же S/N, а не на громкость; даже когда он выключен, ниже примерно -16 dB ничего не печатается, чтобы шум не заполнял окно. При неровной работе на ручном ключе попробуйте «[[digi.cw.som]]».",
  "t.1g3q3y2yi5f": "[[wfs.res]] · [[wfs.navg]] (от 1 до 50, по умолчанию 1): сколько строк спектра усредняется, прежде чем будет нарисована одна; выше = водопад медленнее и менее шумный. [[wfs.speed]]: «[[wfs.speedWsjtx]]» (по умолчанию: одна строка на половину символа FT8, около 52 строк за период, сигналы в виде компактных блоков) или «[[wfs.speedJtdx]]» (15 строк в секунду, около 225 за период, сигналы в виде длинных полос).",
  "t.1g44wj16mhh": "отметки журнала (BIGScan, вне соревнования) учитывают только QSO за последние n минут; 0 = выкл",
  "t.1g5rzxp6r18": "Дубли: в группе [[ctest.g.dupes]] выберите, считается ли дублем также связь на другом диапазоне ([[ctest.f.noBand]]) или другим видом излучения ([[ctest.f.noMode]]). Проверка дублей по диапазону и режиму следует этому выбору.",
  "t.1g9ij3l2woy": "Под дисплеем остаются только частота второго VFO (если трансивер её выдаёт) и кнопка TUNE: флажков для выбора того, что показывать, больше нет. Частота второго VFO приходит только при включённом «[[cat.extras]]» (блок «[[cat.grp.split]]»).",
  "t.1gaua23kzwe": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] Aurora может сама отвечать на CQ, которые дают Вам что-то новое. В заголовке всегда видно, включена ли она, в каком режиме и что сделала сегодня; ниже пять блоков правил, у каждого свой значок «?».",
  "t.1gc3gttye3r": "[[digi.wk.secLink]]: выберите [[digi.wk.output]] «WinKeyer» и [[digi.wk.port]]. Строка ниже показывает, подключён ли он, и его прошивку (WK2 или WK3).",
  "t.1gd8yjcywop": "Под позывным отправителя, в Band activity и окне RX, цветная полоса показывает, что эта станция пользуется LoTW: стоит поработать с ней, если Вам нужно подтверждение.",
  "t.1geu6vx0bgr": "Первая строка: если ПК подключён по Wi-Fi, указывается название сети и сообщается, что телефон должен быть в той же (не в «гостевой»); если ПК подключён кабелем, она сообщает «[[net.cable]]». Если Вы видите «[[net.waiting]]», Aurora ждёт, пока телефон откроет адрес.",
  "t.1gfkxye3va0": "Только для FT-991(A) Link: [[cat.ft991.address]] (заводское 127.0.0.1:50001): адрес UDP, который программа FT-991(A) Link показывает после «Start UDP». Меняйте его, только если Вы выбрали в этой программе другой порт.",
  "t.1ggvmutuiwd": "то же, что <RXANDCLEAR>",
  "t.1gjcrn8sh45": "фиксирует текущий момент как время начала QSO",
  "t.1gkmv0ml1uf": "У каждого параметра есть свой «?» с кратким пояснением. Другие поведения FT8 находятся в других местах: полный дуплекс и ожидание — в [[tab.sequence]], блок [[gen2.wsjtx3]]; проверка Hound и Fox — в [[sw.sub.contest]].",
  "t.1gl50njtlnr": "[[cat.cat4om.management]]: по умолчанию 127.0.0.1:17300, порт администрирования Cat4OM. Через него Aurora сама находит группу и её порт Control (Cat4OM назначает его группе, например 5001), как Decodium с «Automatic discovery». Оставьте [[cat.cat4om.group]] и [[cat.cat4om.address]] пустыми: после подключения найденные значения появятся серым. С другого ПК введите адрес ПК с Cat4OM и включите работу по сети в Cat4OM.",
  "t.1gmkkz81qi3": "Если на телефоне данные «зависли»: нажмите ⟳. Иначе см. «Телефон не обновляется».",
  "t.1gnb95gait0": "Под индикатором, рядом с частотой VFO B, находится кнопка TUNE: щелчок запускает антенный тюнер радиостанции по CAT.",
  "t.1gotll4r1cv": "[[gen2.fox]] · [[gen2.houndAuto]]: флажок, по умолчанию включён. Когда выбранный DX передаёт как Fox в WSJT-X, Aurora сама включает Hound, переводит Tx выше 1000 Hz и включает сплит; она выключает их, если DX отвечает обычными сообщениями или если Вы выбираете другой DX. Выключите, только если хотите управлять [[ctl.hound]] вручную.",
  "t.1goxoqbvsnl": "[[digi.wk.secPaddle]]: [[digi.wk.paddle]] (Iambic A/B, Ultimatic, Bug), [[digi.wk.swap]], [[digi.wk.breakin]], [[digi.wk.sidetone]] и [[digi.wk.sidetoneHz]].",
  "t.1gplh2ip4jr": "Если же в сообщении сказано, что порт занят (или в Windows отказано в доступе), его использует другая программа или другая копия Aurora: закройте её или поделите трансивер (блок [[cat.share]]). Если сказано, что порта не существует, обновите порты, проверьте, что трансивер включён и кабель подключён, и выберите порт снова.",
  "t.1gpyz4lm6k1": "[[digi.mi.log]] (вкл.): правый столбец с вкладками DX Cluster и Журнал. В SSB журнал находится в левом столбце, в трёхколоночной раскладке, и этот пункт показывает или скрывает его. [[digi.mi.rotor]] (вкл.): вкладка ротора с направлением на DX текущего QSO; ротор подключается в [[nav.settings]] › [[sw.sec.station]].",
  "t.1gqloacf243": "онлайн-подтверждения: Aurora отправляет каждое сохранённое QSO в сервисы, выбранные в настройках (eQSL, LoTW, Club Log...), команда лишь напоминает об этом",
  "t.1gqm5n6ej0y": "WSPR-2 выбирается в переключателе режимов: двухминутные периоды, только маяк, как в WSJT-X. Рядом с режимом находятся мощность, [[mode.wsprPct]] (по умолчанию 20%, с двухчасовой таблицей WSJT-X) и [[mode.wsprType1]]; передача идёт только при включённом [[ctl.enable_tx]], в полосе от 1400 до 1600 Hz. Значение [[mode.wsprPct]] отправляется, когда Вы нажимаете Enter или выходите из поля.",
  "t.1grwql0zdh5": "Если после обновления Aurora Log4OM показывает OFFLINE, нажмите «Save and apply», чтобы подключить его заново.",
  "t.1gsb2ptdtqw": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiRxTx]]. Здесь Вы задаёте частоты, шумоподавитель и параметры PSK31, PSK63, RTTY и CW все вместе (рабочая страница показывает только параметры используемого режима). Каждое изменение применяется сразу. Имя и QTH для QSO находятся не здесь, а в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]. Если страница не загружается, движок Aurora не отвечает.",
  "t.1gshxkvwjgh": "По окончании приёма появляется «[[sstv.rx.saved]]» (изображение попало в историю) или «[[sstv.rx.lost]]» (сигнал пропал до конца, и изображение отброшено).",
  "t.1gsq8aylam8": "«вызываю CQ» на языке другой станции",
  "t.1gta7bmh47n": "Верхняя панель",
  "t.1gui3r3xvw9": "[[not2.grpAlerts]] · [[not2.popNew]] и [[not2.popNewBand]]: мигающая подсвеченная карточка вверху справа на странице «Станция», с флагом, позывным, страной и временем последнего приёма. По умолчанию включено. Первая — для страны, с которой ещё не работали, вторая — также для страны, с которой работали, но не на этом диапазоне. Карточка показывается один раз на станцию, не более двух одновременно, и исчезает через 10 минут после последнего приёма; двойной щелчок по карточке отвечает этой станции. Чтобы отключить, снимите оба флажка или нажмите «[[newdx.off]]» под карточками.",
  "t.1guxa7gkt47": "QSO не записываются в журнал: проверьте, что порт Logger32 совпадает с портом Aurora и что включено «Allow automatic WSJT/JTDX QSO logging».",
  "t.1gvjpqi085c": "Диагностика: в Logger32 Config › «Show UDP message debug window». Если Decode появляются, карта заполняется. Если появляются только QSO, Aurora отправляет этому получателю только ADIF: карте нужен поток WSJT-X на первичном UDP-сервере, одного ADIF недостаточно. Проверьте в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]].",
  "t.1gx542y76na": "Карта в панели журнала",
  "t.1gxx5w9elxg": "перезагружает журнал и его отметки",
  "t.1gzjkrghysz": "Вверху слева — выпадающий список режимов: PSK31, PSK63, RTTY, CW и SSTV; при выборе текстового режима Aurora выбирает его и открывает страницу PSK · RTTY · CW.",
  "t.1h0bwirgmqg": "Aurora не использует DDE: сохранённые QSO и так попадают в подключённые программы ведения журнала",
  "t.1h3sanzxogb": "Sq: шумоподавитель. Когда он включён, печатается только то, что превышает порог; знак «Sq *» говорит, что сигнал его превышает. Правый щелчок открывает меню с порогом.",
  "t.1h6rx6k4j43": "Спутники: следование за ручкой настройки радио",
  "t.1h6wyhsjbqd": "Я записал неверное QSO: как исправить или удалить его?",
  "t.1h88yqh4fja": "«[[contest.log]]»: журнал этого контеста (QSO попадают также в обычный журнал), с числом QSO и неуверенных. Щелчок по полученному обмену исправляет его («[[contest.edited]]»); щелчок правой кнопкой по строке: действительно, неуверенно или «[[contest.notInContest]]» (0 очков, не включается в Cabrillo). «[[contest.resetLog]]» начинает журнал заново с нуля после подтверждения (старый остаётся копией в папке данных).",
  "t.1h8qqruihtg": "Как <RX>, но после возврата на приём окно передачи очищается: и поле, и уже отправленный текст. Если макрос не передаёт, очищается сразу.",
  "t.1h9cn7c08gd": "В верхней панели «[[nav.textModes]]» открывает страницу текстовых режимов: PSK31, PSK63, RTTY и CW. Всё помещается на одном экране. Когда Вы заходите с другой страницы, радио само переходит на диапазон плана диапазонов IARU для этого режима (если у используемого диапазона нет частот для этого режима — на первую в плане); во время передачи этого не происходит. Приём начинается сам при входе и прекращается при выходе, если только в Настройках не задано [[digi.autoReceive]].",
  "t.1hbt5lgjsjq": "[[sw.pg.qso]]",
  "t.1hc6v2gc5ou": "На телефоне Настроек нет: их меняют только с ПК.",
  "t.1he4qqxg96l": "FST4 и FST4W выбираются в переключателе режимов, с периодом T/R рядом с режимом, как в WSJT-X: FST4 от 15 s до 30 min, FST4W от 2 до 30 min. FST4 предназначен для QSO со слабыми сигналами, с сообщениями и последовательностью как в FT8. FST4W — маяк, как WSPR: без QSO, принятые сообщения не запускают последовательность.",
  "t.1hgouclbjyn": "У столбцов есть заголовок — время (или «[[rxw.col.age]]»), dB, DT, «[[rxw.col.msg]]», «[[rxw.col.country]]» — который можно перетаскивать, чтобы менять порядок столбцов; перетаскивание правого края заголовка меняет ширину, а двойной щелчок по краю подгоняет столбец под содержимое. Щелчок правой кнопкой по заголовку: «Сбросить столбцы». Alt + стрелки также перемещают выбранный столбец.",
  "t.1hixrvu4m46": "Всегда сначала пробуйте в [[auto.modeDry]]: журнал сообщает, кому она ответила бы, кого пропустила и почему. Когда будете готовы, переключитесь на [[auto.modeLive]] с ПК. STOP TX всегда выключает автоматизацию и останавливает также CQ, который она вызвала сама; пределы, заданные на ПК, остаются активными. Ответственным оператором за каждую передачу остаётесь Вы.",
  "t.1hlqrnchsjx": "Полоса фильтра: «[[digi.cw.bandwidth]]» от 50 до 500 Hz и 1000 Hz «[[digi.cw.wide]]». Меньше Hz = меньше шума и меньше близких станций, но тон должен быть по центру (AFC его догоняет). Меняется из меню [[digi.menu.mode]], из выпадающего списка в строке состояния или из окна «[[digi.ms.title]]».",
  "t.1hn2wayjv6x": "Окно «[[digi.rx.title]]» показывает текст, который декодирует Aurora; окно «[[digi.tx.title]]» — поле, в котором Вы пишете то, что хотите передать. Над окном приёма небольшая панель со значками «Copy the whole receive window», «Save the receive window to a text file», «Clear», «Pause» и «Search». Pause замораживает окно, чтобы можно было спокойно читать: приём продолжается, и текст продолжает накапливаться, повторное нажатие переходит в конец. Search открывает небольшое поле: введите позывной, и все его вхождения подсвечиваются (регистр не важен); Enter переходит к следующему, Shift+Enter — к предыдущему, Esc закрывает. Между окнами «[[digi.rx.title]]» и «[[digi.tx.title]]» есть линия, которую можно перетаскивать: окно приёма никогда не опускается ниже четверти области, а двойной щелчок по линии восстанавливает исходную пропорцию.",
  "t.1hng6abwpxs": "[[digi.mi.flashTx]] (вкл.): метка TX и блок TX в строке состояния мигают, пока Вы передаёте. Также по правому щелчку на строке состояния.",
  "t.1hoembgnton": "[[ca.audio]]: «[[ca.audio.ok]]» при хорошем уровне; «[[ca.audio.warn]]», если слабый или теряет блоки; «[[ca.audio.bad]]», если тишина, перегрузка или вход завис. «[[diag.fix]]» ведёт на страницу звука.",
  "t.1hp1p894s3o": "Гистограмма (светлая полоса) показывает чёрным, куда попадали частоты сигнала в последние секунды, от 1100 до 2700 Hz. Изображение SSTV даёт широкий сплошной блок и узкий пик слева: это синхро.",
  "t.1hp88zw2v6h": "Вы можете выбрать, когда начинается декодирование FT8 и декодировать ли во время передачи.",
  "t.1hpc4qcllws": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.files]]. Внутренний журнал хранит каждую QSO, записанную Aurora. Здесь Вы скачиваете его как файл ADIF или добавляете в него свою историю без дубликатов.",
  "t.1hpccpylywu": "Панель макросов",
  "t.1hqu4cf5rx3": "Открывается из [[nav.news]], внизу дерева «Настроек» (золотой пункт). В нём перечислены последние добавленные, изменённые или исправленные функции, начиная с самых свежих, с датой и временем выхода по времени вашего устройства.",
  "t.1hqz5w2tmdi": "«[[rot.heading]]» показывает текущее направление, «[[rot.degrees]]» — поле для ввода градусов (Enter или «[[rot.go]]» — перейти), «[[rot.stop]]» останавливает сразу. Кнопка «≡» («[[rot.presetTip]]») показывает или скрывает заданные направления: 0, 45, 90… 315, затем направление на DX-станцию и Park. Кнопка с шестерёнкой («[[rot.more]]») открывает остальное: поле градусов с шагами −10, −2, +2 и +10, короткое и длинное направления на DX-станцию и Park (положение покоя, с командой для перехода в него и командой для установки его в текущее положение).",
  "t.1ht4gn9d7gk": "Кнопка RX/TX в строке состояния действует резче: пока Вы передаёте, её нажатие сразу останавливает передачу (как Esc); в покое она открывает передачу.",
  "t.1hv0xay4d2l": "В меню радиостанции: пункты, перечисленные в рамке (скорость CAT как в Aurora, звук данных по USB).",
  "t.1hvhseyxun": "С Hamlib индикатор показывает реальные значения радиостанции: S-метр на приёме, мощность на передаче.",
  "t.1hwsbqhvtjo": "Когда Вы открываете ссылку или QR с ПК, адрес уже содержит код: страница выполняет сопряжение сама, с единственной попыткой, и телефон перезагружается на странице Station. QR создаётся на ПК в [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] кнопкой «[[acc.showCode]]».",
  "t.1i06gckas5w": "[[fil.continents]]: семь флажков, [[cont.AF]], [[cont.AN]], [[cont.AS]], [[cont.EU]], [[cont.NA]], [[cont.OC]] и [[cont.SA]]; отметьте континент, чтобы перестать видеть его сообщения. Ничего не отмечено (заводское) = показываются все. Используйте их, чтобы исключить континенты, которые Вам не интересны.",
  "t.1i0o924p07w": "пауза между двумя автоматическими CQ (секунды)",
  "t.1i1bosldsfv": "[[auto.b5]] · [[auto.autoCqOn]] и [[auto.autoCq]] (один флажок и числовое поле от 2 до 120 минут, по умолчанию выключено; отметка флажка запускает со значением 5): через столько минут без CQ для ответа Aurora вызывает CQ, но только в боевом режиме, когда передача свободна и внутри окна времени. Каждый CQ считается ответом подряд без QSO: при достижении предела она выключается. См. также «Как заставить Aurora вызывать CQ самой».",
  "t.1i1dnjh9bqo": "[[wfs.palette]]: 30 палитр плюс одна Ваша собственная. [[wfs.gain]] и [[wfs.zero]] делают сигналы и фон ярче или темнее.",
  "t.1i1taskhogc": "пропускает последние n принятых секунд через приёмник ещё раз (по умолчанию 10, максимум 60)",
  "t.1i21bmmasc0": "[[digi.menu.configure]] › [[digi.mi.personal]]: открывает [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]], где записываются имя и QTH, используемые макросами (<MYNAME>, <MYQTH>).",
  "t.1i2k0q7tn8l": "В центре, вверху, находится окно «[[digi.rx.title]]» (принимаемый текст), а под ним — окно «[[digi.tx.title]]» (текст для передачи). Разделитель между ними можно перетаскивать; пропорция запоминается.",
  "t.1i3581ooo47": "[[cop.choose]] · [[cop.rotor]] (по умолчанию выключено): тем же жестом антенны поворачиваются в сторону страны спота. Нужны подключённый ротор ([[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]]) и Ваш локатор в [[sw.pg.personal]].",
  "t.1i3a9thg8ru": "История сообщений",
  "t.1i5vh9vtufb": "Страница [[nav.wefax]] принимает погодные и изобарические карты, которые метеорологические станции передают на KB (метеофакс, WEFAX), и рисует их строка за строкой. Только приём.",
  "t.1i7ci14sw7w": "Каждый автоматический CQ считается одним ответом подряд без QSO: при достижении предела, заданного на ПК, автоматизация выключается. STOP TX всегда останавливает всё. Ответственным оператором за каждую передачу остаётесь Вы.",
  "t.1i82ocqi7j9": "В режиме Hound Aurora никогда не вызывает CQ. Экспедиции, использующие SuperFox (широкий сигнал, отвечающий до 9 станциям), Aurora пока не принимает: это появится в одной из следующих версий.",
  "t.1iackvfo1m5": "Чтобы следить за QSO, дважды щёлкните по станции в Band activity: частота приёма переходит на неё, а окно RX следует за этим QSO. По умолчанию её сообщения остаются и в Band activity; если Вы хотите видеть их только в окне RX, включите «[[rxw.exclusive]]» в блоке «[[fil.grp.rx]]».",
  "t.1iczk8mwbqq": "У каждой панели страницы «Станция» есть кнопка ⧉ вверху справа («[[win.detach]]»): с её помощью панель переносится на второй экран. Размеры панелей фиксированы; см. также «Главная страница из блоков».",
  "t.1ie22j7uhnc": "Используется только VFO A: при сплите Aurora смещает частоту только во время передачи (эмулированный сплит). Если состояние сообщает, что FT-991(A) Link не отвечает, проверьте, что в FT991Link порт открыт и запущен UDP.",
  "t.1ie3e24pgz7": "«[[int.adif]]»: запись ADIF простым текстом, одна датаграмма на QSO, больше ничего (читает Log4OM 2 с соединением ADIF_MESSAGE и WaveLogGate).",
  "t.1igdm7x227r": "При «[[rot.set.launch]]»: [[rot.set.port]] и [[rot.set.baud]]. Порт — это порт интерфейса ротора, а НЕ трансивера (в Windows COM5, в Linux /dev/ttyUSB1, и для разрешения на его использование действует группа dialout из раздела о последовательных портах); для моделей, которые его не используют, его можно оставить пустым. Скорость должна быть той, что задана на интерфейсе: «[[rot.set.default]]» использует скорость модели.",
  "t.1igzy7kur7p": "«[[digi.ms.title]]» · [[digi.ms.receive]]: «[[digi.freq.rx]]» (от 200 до 3500 Hz, по умолчанию 1000), [[digi.mi.afc]], [[digi.mi.snap]], [[digi.mi.squelch]] и, в зависимости от режима, следующие пункты. Каждое изменение сохраняется сразу.",
  "t.1ihn4r86q5b": "Включите «[[int.adif]]» (Log4OM, WaveLogGate) или «[[int.n1mm]]» (HRD Logbook), затем «[[int.resend]]». Без одного из двух форматов блок остаётся серым.",
  "t.1ihq2d9lomf": "[[aud.mode]] · [[aud.keep]] (числовое поле, от 0 до 3650, заводское 7): сколько дней Aurora хранит сохранённые файлы. При запуске, а затем раз в сутки она удаляет файлы .wav периодов, сохранённых Aurora, которые старше этого срока; другие файлы в папке никогда не затрагиваются. 0 = навсегда. ALL.TXT тоже следует ограничению: когда он превышает 50 МБ или старше срока, он ротируется (переименовывается в ALL-дата.TXT).",
  "t.1iiwahowmsv": "Когда Aurora запускается и есть новая версия, появляется небольшое окно «Хотите обновить?» с кнопками «Да» и «X»: «X» откладывает, и окно возвращается на следующий день. Значок в заголовке возвращается каждый день. Агент в области уведомлений показывает карточку снова при каждом запуске и каждые 6 часов, пока Aurora не обновлена.",
  "t.1ijmmk4nzub": "Так журнал, споты и карта получают верный диапазон. Aurora запоминает это и при повторном открытии.",
  "t.1ijz0xm2m1c": "Если чего-то не хватает, под полем появляется уведомление: «[[digi.tx.notReady]]», «[[digi.tx.busy]]», «[[digi.tx.disabled]]». При открытой передаче поле подсказывает «[[digi.tx.openHint]]».",
  "t.1im3ewnkxh5": "«[[ens.info]]» (только чтение, внизу): «[[rep.cty]]» показывает, сколько стран DXCC (файл cty.dat) загружено (или «[[rep.notLoaded]]»); «[[rep.log]]» показывает, сколько QSO прочитано из журнала (или «[[rep.notRead]]») — полезно, чтобы увидеть, есть ли данные для «работал раньше» и «новая DXCC»; «[[rep.file]]» появляется, только если в окружении Aurora указан файл экспорта ADIF (AURORA_EXPORT_FILE).",
  "t.1ipaj5jk215": "«[[lay.settings]]» · «[[cluster.callsign]]» (только чтение): позывной, с которым Aurora входит в кластеры; берётся из [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]] и обновляется сам, если Вы его меняете; пароли не нужны. Если его нет, Вы видите «[[cluster.callMissing]]»: впишите его в личные данные.",
  "t.1ipvfcy7jl": "Телефон не обновляется",
  "t.1iq5jajdaiy": "Вверху Tx, Rx и Report; ниже — ряд кнопок.",
  "t.1irsegtowks": "«[[agent.kind.dxped]]»: DX-экспедиции, начинающиеся завтра, не более трёх, из списка NG3K. Если Aurora сохранила список нужных Вам стран (из панели DX-экспедиций, не старше 7 дней), она предупреждает только о них, иначе — обо всех. По умолчанию «Popup».",
  "t.1it5l6mujpr": "«[[lay.lists]]» · «[[wish.countries]]» и «[[wish.grids]]»: в «[[wish.countries]]» название страны так, как Вы видите его в списке сообщений (например, Bulgaria или Fed. Rep. of Germany; не более 60 символов в записи); в «[[wish.grids]]» 4-символьные квадраты локатора, например JN45 (две буквы от A до R и две цифры).",
  "t.1itogjsvb7a": "В «[[contest.order.value]]» сначала идут сообщения, на которые можно ответить (CQ, QRZ и станции, вызывающие Вас), затем QSO между другими станциями; «[[contest.onlyCq]]» скрывает последние. «[[contest.dupe]]» отмечает станции, с которыми на этом диапазоне уже проведена связь, и, если они ещё засчитываются в других местах, диапазоны, где они засчитываются; двойной щелчок по дублю запрашивает подтверждение. В многодиапазонных контестах тот же позывной на другом диапазоне — это новое QSO: Aurora отвечает ему. Под подсказками, при наличии более одного диапазона, небольшая таблица QSO, очков и множителей по диапазонам. F1–F4 ничего не делают, пока Вы печатаете в поле или открыто окно.",
  "t.1iv4h5nm42k": "Меню диапазонов начинается с «[[dxmap.bandNow]]»: квадраты и споты PSK Reporter диапазона, на котором Вы находитесь, в реальном времени (несколько секунд) и с обновлением каждые 10 секунд. «[[dxmap.onlyHeardMe]]» оставляет только линии к станциям, которые Вас принимали; «[[dxmap.callLabels]]» всегда подписывает позывные (при выключении они показываются при наведении). Во время передачи красная линия идёт к станции, которую Вы вызываете. Вкладка «Map» панели журнала показывает ту же карту.",
  "t.1ivha3dpex1": "[[digi.mi.lock]]: отмечено = частота передачи остаётся на месте, а Вы слушаете в другом месте (красная пара на водопаде — это передача). Полезно, чтобы ответить станции, которая слушает на другой ноте, или для сплита на странице, полной сигналов.",
  "t.1izvi4ybfcg": "Yaesu FTdx101D/MP, FTdx10, FT-991A, FT-710: USB-кабель создаёт два виртуальных COM-порта (Silicon Labs CP210x). «Enhanced COM Port» — для CAT, «Standard COM Port» — для PTT и манипуляции CW. В [[cat.rig]] выберите модель по названию радио; задайте скорость CAT в меню радио (пункт CAT RATE, см. руководство) и такую же в [[cat.baud]].",
  "t.1j13tbe6io0": "Три проверки останавливают передачу, когда ей выходить не следует; панель Tx показывает причину.",
  "t.1j22x9v8m6k": "[[sw.pg.digiMacros]]",
  "t.1j37s7ackm0": "Фильтр задерживает текст примерно на треть секунды: такова цена столь крутого среза. Без режекторных фильтров и без полосового фильтра звук доходит до декодера без задержки и вообще без изменений.",
  "t.1j39zktj8e9": "фразы INT этого макроса на языке xx (IT, EN, DE, FR, ES, PT, NL)",
  "t.1j407n77sut": "Скачайте установщик (Aurora_X.Y.Z_x64-setup.exe) со страницы Releases Aurora на GitHub и запустите его.",
  "t.1j4faqgwre5": "диапазон предыдущего QSO с этим позывным",
  "t.1j7qfadeci2": "[[cat.profile]] · [[cat.profile.pick]]: список уже сохранённых профилей (пуст, с «[[cat.profile.none]]», если их нет). Выбор профиля копирует его имя в соседнее поле, но пока ничего не меняет: нужно нажать «[[cat.profile.load]]».",
  "t.1jasswi1ga8": "Только для Hamlib: [[cat.port]]. Введите или выберите из списка порт трансивера: в Windows COM3, в Linux /dev/ttyUSB0, /dev/ttyACM0 или лучше /dev/serial/by-id/… (он не меняется после перезагрузки). Для трансивера в сети (rigctld другой программы, flrig) впишите адрес:порт, например 127.0.0.1:4532. Кнопка «[[cat.ports.refresh]]» перечитывает порты: нажмите её после включения трансивера или подключения кабеля. Windows может изменить номер COM, если Вы выключите трансивер: проверьте его снова. В Linux прочтите раздел о последовательных портах и группе dialout.",
  "t.1jb84u52ky3": "позывной последнего QSO без /P и префиксов",
  "t.1jch5sbx91r": "[[agent.title]] · [[agent.enabled]]: флажок, по умолчанию включён. Когда включён, агент запускается вместе с Windows, и его значок остаётся рядом с часами даже при закрытой Aurora (щелчок открывает Aurora). Когда выключен, таблица ниже и параметры блока «[[agent.popup]]» становятся серыми и не меняются. Когда выключить: если Вы не хотите, чтобы агент работал на ПК.",
  "t.1jfgl2apct3": "[[digi.menu.file]] › [[digi.mi.macrosMerge]]: если отмечено (по умолчанию, для каждого режима), макросы текущего режима добавляются к базовым, а для одной и той же клавиши макрос режима имеет приоритет; без отметки макросы режима полностью заменяют базовые (если у режима их нет, остаются базовые). Выбор действует для каждого режима отдельно: снимите отметку, когда Вам нужен единый набор макросов, например для RTTY.",
  "t.1jhe5j07oi7": "В верхней панели на ПК есть одна шестерёнка ⚙: она сразу открывает «Настройки», без меню. Внизу дерева находятся также [[nav.wiki]] (Руководство, зелёным) и [[nav.news]] (Новости, золотым) вместе с «[[sw.tab.info]]» (фиолетовым). На телефоне выпадающее меню остаётся.",
  "t.1jhkz5ksrw8": "Следующие два выпадающих списка выбирают диапазон («[[dxmap.bandNow]]» следует за радио, либо «[[dxmap.allBands]]», либо один диапазон) и режим квадратов («[[dxmap.allModes]]»; активен только при включённом «[[dxmap.squares]]»). Справа «n в эфире» считает станции в эфире.",
  "t.1jiu2djnrb2": "Страница [[nav.fox]] (заголовок «[[fox.title]]») предназначена для тех, кто передаёт из DX-экспедиции и обслуживает много станций одновременно. Чтобы вызвать DX-экспедицию, она не нужна: используйте Hound на Станции (см. «Работа в роли Fox (страница Fox)»). Вверху слева: Ваш позывной, режим и статус; ниже опции и панель команд.",
  "t.1jjdt2uhuef": "Панель передачи",
  "t.1jkhl5ctdid": "Число в Aurora и число в трансивере должны быть одним и тем же числом, записанным двумя способами. Быстрая проверка: если в руководстве указано «94h», в Aurora нужно 148 или 0.",
  "t.1jkl1hojcv8": "[[sw.digi.perMode]] · CW, «[[digi.cw.bandwidth]]»: 50, 100, 150 (заводское), 250, 500 или 1000 Hz (широкая, для обзора). Чем уже, тем больше убирается шума и соседних станций, но тон должен быть по центру (AFC следует за ним): 50–100 Hz для слабых и загруженных сигналов, 250–500 Hz для поиска.",
  "t.1jl21med58t": "Вкладка «[[sstv.layers]]», под списком, при выбранном тексте: [[sstv.p.text]] (с подстановками {MYCALL}, {CALL}, {RST}, {GRID}, {NAME}, {MODE}, {DATE}, {TIME}, которые заполняются сами), [[sstv.p.font]], [[sstv.p.size]], [[sstv.p.bold]], [[sstv.p.italic]], [[sstv.p.align]] ([[sstv.p.left]], [[sstv.p.center]], [[sstv.p.right]]), [[sstv.p.fill]] ([[sstv.p.solid]] или [[sstv.p.gradient]] с [[sstv.p.from]], [[sstv.p.to]] и [[sstv.p.angle]]), [[sstv.p.outline]] ([[sstv.p.width]] и [[sstv.p.color]]), [[sstv.p.shadow]], [[sstv.p.box]] (с [[sstv.p.color]] и [[sstv.p.opacity]]) и [[sstv.p.rotation]]. У каждого цвета есть выбор цвета и палитра.",
  "t.1jljwcspqpm": "В UDP BandMap откройте меню Config и включите «Allow automatic WSJT/JTDX QSO logging» (автоматическая запись QSO из WSJT-X/JTDX).",
  "t.1jm15df0wi2": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]: нажмите «[[sup.prepare]]».",
  "t.1jnamulbiwj": "«[[digi.ms.title]]» · [[digi.ms.personal]]: [[digi.f.myname]] (до 30 символов) и [[digi.f.myqth]] (до 40), те же, что в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]. «[[digi.ms.close]]» закрывает окно.",
  "t.1jnndslg531": "Страница [[nav.sat]] показывает на карте мира с днём и ночью, где находятся любительские спутники, их пролёты над Вами, радар неба и орбитальные данные. Она также может корректировать доплер на радиостанции и поворачивать ротор вслед за спутником.",
  "t.1jnpttcgvut": "Станция, которая всегда передаёт в одном режиме, принимается лучше с зафиксированным в Настройках SSTV «[[sstv.rx.lock]]»: остальные режимы игнорируются. По умолчанию действует «[[sstv.rx.lockNone]]», и режим распознаётся по VIS.",
  "t.1jpz9a35s": "С «[[rot.set.launch]]» найдите и выберите «[[rot.set.model]]», затем «[[rot.set.port]]» и «[[rot.set.baud]]» интерфейса ротора. В обоих случаях выберите «[[rot.set.range]]», то есть углы, на которые может поворачиваться ротор (по умолчанию 0° … 360°; с «[[rot.set.rangeCustom]]» впишите пределы в «[[rot.set.rangeFrom]]» и «[[rot.set.rangeTo]]»): измените его, если Ваш ротор поворачивается больше чем на полный круг (например, 0° … 450°) или имеет другой упор. Затем нажмите «[[rot.set.apply]]».",
  "t.1jq1nobzjpc": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › [[sw.pg.contest]] находятся настройки контестов, допускающих MSK144 или Q65 (например, ARRL VHF, CQ WW VHF, EU VHF). Это та же форма, что и на странице [[sw.sub.ft8]] › [[sw.sub.contest]], без блока Fox; она открывается на активном контесте, если тот относится к этой ветви. С собственным движком и используемым режимом УКВ шестерёнка страницы [[nav.contest]] приводит Вас сюда.",
  "t.1juazpii2qi": "Если декодирование часто не укладывается, окно предлагает «[[hl.slow.yes]]» (параметр «[[dec.slowPc]]» становится «[[dec.slowPc.always]]») или «[[hl.slow.no]]». Индикатор никогда ничего не меняет сам.",
  "t.1judlqsglbk": "Страница «PSK · RTTY · SSTV» умещается в один экран: вверху блоки макросов (правый щелчок — редактировать), рядом с ними выбор диапазона и частоты IARU; ниже — приём и передача (разделитель между ними можно перетаскивать), справа вкладки DX Cluster и Log с текущим QSO, а внизу водопад. Режим (PSK31, PSK63, RTTY, CW) меняется в меню «[[digi.menu.mode]]» (в нём есть и ссылка на страницу SSTV). Меню «View» включает: подчёркивание переданного текста, только заглавные, перечёркнутый ноль, мигающий TX, тонкие линии на водопаде и рапорты 599 по умолчанию. При сплите (Lock) красная пара на водопаде — это передача: щелчок перемещает её, с Ctrl вместо этого перемещается приём. В DX Cluster щелчок по споту настраивает сигнал на тон приёма и, если в комментарии есть «up N», смещает передачу; кнопка «Spot DX» отправляет спот на DXSummit.",
  "t.1jv7qzb8840": "Шапка · [[auto.status]] (метка [[auto.on]] или [[auto.off]]): сообщает, включены ли автоматизации. Если включены, в каждом цикле Aurora оценивает CQ и отвечает (или, в пробном режиме, сообщает, кому ответила бы). STOP TX всегда их выключает.",
  "t.1jvdowp8zy1": "тексты, стили, прозрачность, заголовок и строки картинки подготавливаются на странице SSTV: команда открывает её",
  "t.1jvsvcu4nl7": "[[cat.split]]: «[[cat.split.rig]]» (Rig) делает настоящий сплит в FT8 и FT4 с CAT PTT: передающий VFO смещается, а звук остаётся между 1500 и 2000 Hz, как в WSJT-X. «[[cat.split.emulate]]» (Fake It) смещает частоту только во время передачи. Оба работают с Hamlib, TCI и OmniRig; у FT-991(A) Link только Fake It. Если во время передачи вы сдвинете частоту Tx, радио следует за ней сразу.",
  "t.1jwirwgfgpk": "[[auto.b2]]: при нескольких CQ в одном цикле Aurora выбирает только один — самый редкий, самый сильный или лучший по баллам.",
  "t.1jwizxqszrl": "Шумоподавитель Aurora никогда не смотрит на громкость: в PSK он использует качество фазы, в RTTY и CW — отношение сигнал/шум. Поэтому порог остаётся действительным, даже если Вы меняете громкость звуковой карты.",
  "t.1jxdcn44rxh": "Состояние «[[rot.state.error]]»: проверьте, что COM-порт относится к ротору (а не к радиостанции) и что его не удерживает другая программа; Aurora повторяет попытку сама.",
  "t.1jxnhppjen0": "Открывается шестерёнкой вкладки «[[digi.tab.cluster]]». Выбор сохраняется на этом устройстве. Те же пункты есть и в Настройках, на странице «[[cop.title]]» раздела [[sw.sub.digi]]. Esc или щелчок снаружи закрывает окно.",
  "t.1jyb1p2d8zp": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] Вы решаете, когда Aurora оповещает Вас звуком или подсвеченной карточкой. Это первая часть, блок «[[not2.grpAlerts]]»; ниже на странице находятся блоки «[[snd.title]]» и «[[toast.grp]]». Флажки в этом блоке применяются сразу.",
  "t.1k0g0oftqe0": "Кнопка TUNE под индикатором",
  "t.1k1l4bu16bs": "«[[dxs.guide.title]]» (вверху, только чтение): пять пунктов, объясняющих, для чего нужна карточка, шесть меток, сетку, диапазоны и цвета. Полей в нём нет.",
  "t.1k2qegqxdsm": "переключает между передачей и приёмом (во время отправки: возврат на приём в конце текста)",
  "t.1k3dj142bju": "текст файла из папки текстов макросов",
  "t.1k40irhkrpr": "В службу проверки уходят только позывной Fox, время и код. У SuperFox своя проверка, которую Aurora пока не принимает.",
  "t.1k5870uxnfx": "Самый полезный: «call to me». Он звонит каждый раз, когда Вам отвечает станция.",
  "t.1k66t60oia1": "Щелчок по строке переводит приём на этот сигнал (строка захваченного сигнала выделена); двойной щелчок открывает «[[digi.band.history]]»: весь текст за последние 60 секунд, с кнопками «[[digi.band.tune]]» (переводит приём туда), «[[digi.band.toQso]]» (помещает позывной в QSO) и «[[digi.band.close]]». После 45 секунд тишины канал закрывается («[[digi.band.historyGone]]»).",
  "t.1k6cl1762wj": "[[gen2.wsjtx3]] · [[gen2.pounce]] (выпадающий список, по умолчанию «[[gen2.pounceFirst]]»): на какой CQ отвечает кнопка «[[ctl.pounce]]»: [[gen2.pounceFirst]] (первый декодированный), [[gen2.pounceMaxDist]] (нужен локатор в CQ), [[gen2.pounceMaxDb]] или [[gen2.pounceMinDb]]. Станции, с которыми связь уже была в этом сеансе, пропускаются. [[gen2.pounceNone]] выключает Wait and Pounce.",
  "t.1ka4doqv3g0": "«[[ens.g.hamqth]]» · «[[ens.k.HamQTHLookup]]» (по умолчанию выключено), «[[ens.k.HamQTHUser]]» и «[[ens.k.HamQTHPasswd]]»: HamQTH — бесплатный справочник позывных (достаточно зарегистрироваться на hamqth.com). Aurora использует его после QRZ.com или вместо него, если тот выключен или не находит позывной: это способ получить имя и город без XML-подписки QRZ. Те же правила: только имя, город и страна, результаты в памяти три дня, при выключении запросов нет. «[[ens.test]]» открывает сеанс.",
  "t.1kalhnd5his": "«[[int.title]]»: другие программы, у каждой свой адрес, порт и то, что она получает. Кнопки: «+ [[int.p.wsjtx]]» (2237), «+ [[int.p.adif]]» (2333), «+ [[int.p.multicast]]» (239.255.0.1).",
  "t.1kbe0eun7no": "Всё ещё не подключается? Отправьте тому, кто вам помогает, точный текст сообщения об ошибке или пакет поддержки: [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] → «[[sup.prepare]]». В нём журналы и настройки, без паролей.",
  "t.1kbuel2sbk": "В [[gen2.decStart]] выберите [[gen2.decStartEarly]], чтобы было больше времени на ответ, [[gen2.decStartLate]], чтобы ловить запоздавшие сигналы; по умолчанию [[gen2.decStartNormal]].",
  "t.1kd6hzk0usg": "Пункты с «[[digi.mi.soon]]» (QPSK31, FSK31, MFSK, MT63, Throb, Hellschreiber, Packet, Pactor, Amtor) серые: их пока нет, и выбрать их нельзя.",
  "t.1kdpbt2ezzu": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.wspr]] Вы настраиваете маяк (WSPR и FST4W) и отправку спотов в WSPRnet. Три элемента блока [[sw.wspr.beacon]] — те же, что находятся рядом с режимом, когда используется WSPR или FST4W, и они действуют сразу, без [[sw.save]]; отправка в WSPRnet применяется после [[sw.save]] и существует только с собственным движком.",
  "t.1ke0r1007a": "При включённом [[digi.mi.lock]] красная пара — это передача, и она остаётся на месте: щелчок перемещает передачу; с удерживаемым Shift щелчок перемещает вместо этого приём (Ctrl+щелчок ставит режекторный фильтр).",
  "t.1ke1o23cl3v": "В большом изображении: «[[sstv.clean.original]]» или «[[sstv.clean.cleaned]]» с теми же двумя ползунками, что и при приёме; подпись с позывным, режимом, измерениями, временем и качеством синхронизации; флажок «[[sstv.rx.smooth]]» (мягкое увеличение вместо чётких пикселей, только для этого просмотра).",
  "t.1kebnr02zh2": "задаёт время начала QSO (с % записывает время начала в этом формате)",
  "t.1keqpjlzqfg": "режим последней QSO с этим позывным",
  "t.1kfgmmasif8": "Кнопки внизу: [[sw.testCat]], [[sw.testPtt]], [[sw.close]], [[sw.save]]",
  "t.1kfjy4emkdy": "Два оповещения выделяются сильнее остальных: карточка нового DXCC, которая мигает вверху справа, и панель списка желаемых станций вверху страницы.",
  "t.1kib551fpw0": "Верхний край панели (тонкую линию) можно перетаскивать, чтобы изменить высоту (от трёх строк до половины столбца); высота запоминается.",
  "t.1kil71ov64s": "Панель разделена по высоте: сверху CQ в горизонтальной полосе из двух рядов (одна станция на плитку; если их больше, чем помещается, она прокручивается сама и останавливается под мышью); ниже — DX-экспедиции, по одной строке на каждую, с флагом и датой, включая те, что начнутся в ближайшие 120 дней.",
  "t.1klbkeb9zrk": "OM или YL по имени другого оператора",
  "t.1km1rflm8l5": "ищет сигнал слева",
  "t.1kn5j8wcgho": "Полная статья: «Обновления»; «[[tab.updates]]».",
  "t.1knsrz0uuos": "Прохождение: все панели",
  "t.1ko6xk2wgyb": "При входе на страницу SSTV радиостанция сама переходит на 20 м (14,230 MHz).",
  "t.1kppp22q67t": "Каждое QSO может уходить прямо в eQSL, Wavelog/Cloudlog, ClubLog, QRZ.com, HRDLOG.NET и LoTW, без посредников.",
  "t.1kppryvgfgk": "Включите в Настройки › Станция › SDR · TCI · QMAP → «QMAP page in the menu»: вверху появится пункт QMAP.",
  "t.1kqcoaidxlg": "частота трансивера в МГц (<MHZ:n>)",
  "t.1kqegwdx6nc": "Вверху страницы Вы найдёте однострочную сводку выбранного и предпросмотр следующего пролёта. «[[sat.trk.reset]]» возвращает всё к заводским значениям. Чтобы меньше изнашивать ротор: уменьшите опережение, увеличьте допуск и интервал.",
  "t.1kqsisk9emz": "Если установщик был старым, при первом запуске сначала появится плакат о новой версии: нажмите «[[upd.poster.install]]», Aurora обновится, перезапустится, и только потом начнётся мастер. С «[[upd.later]]» мастер начинается сразу.",
  "t.1krcgrff5qc": "«[[digi.rtty.title]]» · «[[digi.rtty.factory]]»: восстанавливает заводские значения только выбранного набора (Set 1 и 4: 170 Hz и 45.45 baud; Set 2: 22 Hz и 45.45 baud с дискриминатором; Set 3: 30 Hz и 10 baud). «[[confirm.ok]]» сохраняет выбранный набор и вводит его в действие; «[[confirm.cancel]]» оставляет всё как было.",
  "t.1ksu63cdmi1": "[[aud.mode]] (поле и список): сохраняет ли Aurora принятые периоды как звуковые файлы. «[[aud.save.0]]» (заводской) ничего не сохраняет; «[[aud.save.1]]» хранит только периоды хотя бы с одним декодированным сообщением; «[[aud.save.2]]» сохраняет всё. Каждый файл — это WAV (12 kHz, 16 бит) около 360 кБ на 15-секундный период, и Aurora сама удаляет их через число дней, указанное в «[[aud.keep]]»; с «[[aud.save.2]]» диск всё равно быстро заполняется. Включайте это только для поиска проблемы с декодированием.",
  "t.1kt5z6okc1r": "[[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]]. Позволяет управлять Aurora, работающей на ПК, с телефона или планшета в домашней сети. На странице четыре блока, один под другим. Менять её можно только с ПК, на котором работает Aurora: если открыть её с телефона, изменение отклоняется и появляется «[[acc.pcOnly]]».",
  "t.1ku4hm4fo5q": "[[lay.options]] · [[fil.nonStandard]]: флажок, по умолчанию выключен. Скрывает сообщения со свободным текстом и необычные форматы (контест, телеметрия) и оставляет обычные QSO. Включите, чтобы навести порядок в списке; не включайте во время контеста.",
  "t.1kuju737m0l": "[[ap.text]] · [[ap.fontData]]: моноширинный шрифт декодирований, частот и времени, чтобы столбцы оставались выровненными. По умолчанию JetBrains Mono; варианты: Consolas, Cascadia Mono, Courier New.",
  "t.1kx2aaacao8": "Меню [[ctest.menu]] всегда находится в строке. Каждое соревнование — это файл .contest в папке соревнований в данных Aurora, с его макросами (contest/macros) и списками провинций, штатов и зон (contest/dom). При первом запуске Aurora копирует 90 готовых соревнований, не трогая файлы, которые Вы изменили. Одновременно активно только одно соревнование.",
  "t.1l1azje4nrq": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], первый блок. CAT — это кабель управления: с его помощью Aurora считывает и меняет частоту и режим трансивера и управляет PTT. Набор параметров зависит от выбранного [[cat.backend]]: ниже для каждого указано, когда он появляется. Допустимые значения применяются сами через мгновение ([[cat.apply]] применяет их сразу); менять их можно только с ПК, на котором работает Aurora.",
  "t.1l3myjbzmek": "Band Hopping",
  "t.1l4707nfvug": "[[ctl.filter]]: в FT8 декодирует только ±60 Hz вокруг частоты Rx (±290 Hz в Hound). Когда включён, он становится жёлтым и об этом говорит подсказка: все остальные сигналы в водопаде игнорируются. Полезен на очень загруженном диапазоне, когда Вы следите только за своим корреспондентом.",
  "t.1l736q7gops": "Для следующих QSO: в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] включите «[[int.resend]]» у получателя Вашего журнала (см. «Журнал закрыт: QSO приходят позже»). Aurora откладывает QSO, проведённые при закрытом журнале, и сама отправляет их примерно через 15 секунд после его повторного открытия, в том порядке, в каком Вы их проводили. Работает для журнала на том же ПК (адрес 127.0.0.1) с «[[int.adif]]» или «[[int.n1mm]]».",
  "t.1l89kj9kpyd": "[[snd.title]] · три кнопки: «[[snd.auto]]» даёт каждому событию свой звук, подобранный так, чтобы самые важные можно было отличить на слух; «[[snd.clear]]» убирает звук у всех событий (тогда ничего не воспроизводится, пока Вы не выберете звуки); «[[snd.stop]]» останавливает воспроизводимый сейчас звук. По умолчанию звук есть только у подсвеченного оповещения о новой DXCC и у записанной QSO.",
  "t.1l8jdfbu153": "[[nav.settings]] › [[sw.sec.access]] › [[tab.updates]]. Сообщает, какую версию Aurora Вы используете, вышла ли новая и как часто проверять. Проверка обращается к сайту GitHub, где Aurora публикует свои версии, и читает только последний релиз (название, примечания и адрес). На ПК, когда находит новую, Aurora сразу загружает её в фоне и проверяет подпись, но не устанавливает, пока Вы не попросите. Изменения в полях сохраняются сами («[[sw.updatesSelf]]»).",
  "t.1lan6yye1bh": "[[sat.set.update]] · [[sat.set.every]]: выпадающий список: [[sat.set.manual]], каждые 6 часов, каждые 12 часов, каждый день (по умолчанию), каждые 2 дня, каждые 7 дней. Чаще — если Вы следите за спутниками, орбиты которых быстро меняются; «[[sat.set.manual]]» — если хотите обновлять данные только сами.",
  "t.1lb7266qm92": "[[gen2.fox]] · [[gen2.showOtp]]: флажок, по умолчанию выключен. Показывает среди декодирований также строки с кодом Fox (CALL.123456), которые обычно скрыты. Включите из любопытства или для проверки.",
  "t.1lc1paiuq0d": "Блок RX/STOP: зелёная «RX» при приёме; во время передачи он превращается в красную кнопку «[[stop.button]] (Esc)», и щелчок сразу останавливает передачу. Двойной щелчок по «RX» делает то же, что «[[ctl.clear_dx]]»: освобождает станцию и очищает сообщения QSO.",
  "t.1ld7rjrz10g": "возобновляет остановленный Auto CQ",
  "t.1ldzqn2e27i": "В Band activity у столбцов есть заголовки и хорошо видимые линии, как в DX Cluster: перетащите заголовок, чтобы переместить столбец, его правый край — чтобы расширить (двойной щелчок по краю: подгонка по содержимому); щёлкните правой кнопкой по заголовкам: «[[cluster.cols.reset]]». Порядок и ширина запоминаются.",
  "t.1leq5wewlcy": "Столбцы слева направо: время UTC (или возраст сообщения, если включить это в [[sw.pg.messages]]), рапорт в dB, DT (сдвиг времени в секундах относительно Ваших часов: близко к нулю — хорошо), звуковая частота в Hz (только в Band activity), сообщение, флаг и страна с расстоянием и азимутом (если включить их в предпочтениях) и, наконец, цветная метка. В строках Tx (Ваши собственные передачи) вместо рапорта стоит «Tx», а при одинаковых повторах — одна строка с «×N».",
  "t.1lesqrb69fw": "[[wfs.spectrum]] · [[wfs.gain2d]] и [[wfs.zero2d]] (от −50 до 50, по умолчанию 0): усиление задаёт, насколько кривая поднимается на каждый дБ сигнала; ноль сдвигает её целиком вверх или вниз. Они влияют только на график, а не на водопад.",
  "t.1lf8manqtgj": "Три красные метки — это правильные места: короткая на 1200 Hz (синхро), две длинные на 1500 Hz (чёрный) и 2300 Hz (белый). При правильной настройке блок находится между двумя длинными метками, а пик попадает на короткую; строка ниже сообщает «[[sstv.tune.good]]».",
  "t.1lfird6dd4q": "[[acc.pair]] · [[acc.showCode]]: кнопка. Создаёт одноразовый код и показывает ниже QR-код, код, ссылку для открытия на телефоне и адреса ПК. Когда: чтобы подключить новый телефон или планшет. Как только телефон связывается, QR-код исчезает сам и появляется уведомление о подтверждении.",
  "t.1lfzsw1w0p5": "[[digi.log.search]]: введите позывной, даже неполный, и список сузится до QSO, которые его содержат.",
  "t.1lge3qmk75c": "Телефон и планшет",
  "t.1lm8xq5grfe": "Настройтесь на источник с точным временем (см. последний пункт этого списка) и примите целое изображение.",
  "t.1loioodcann": "[[ap.text]] · [[ap.logSize]]: размер шрифта журнала, от 10 до 24 px (по умолчанию 12). Столбцы подстраиваются сами: текст не обрезается.",
  "t.1lpo3kfdiah": "Оповещения об AOS: кнопка с колокольчиком «[[sat.alert.title]]» в заголовке открывает панель. С помощью «[[sat.alert.on]]» Вы включаете оповещения; «[[sat.alert.lead]]» — предупреждение заранее; для каждого события («[[sat.alert.ev.pre]]», «[[sat.alert.ev.aos]]», «[[sat.alert.ev.los]]») выберите звук среди «[[sat.alert.snd.bell]]», «[[sat.alert.snd.radar]]» и «[[sat.alert.snd.arpeggio]]» (или «[[sat.alert.snd.off]]»); отрегулируйте «[[sat.alert.volume]]» и прослушайте с помощью «[[sat.alert.test]]». При AOS вокруг спутника на карте появляются кольцо и вспышка. Оповещения действуют для всех отмеченных спутников или только для выбранного при включённом «[[sat.alert.only]]».",
  "t.1lqal3sf1o3": "Закройте JTAlert и GridTracker, если они используют тот же порт 2237: две программы не могут слушать один порт на одном ПК. Если нужны обе, используйте ретранслятор RPTR в Logger32: щёлкните правой кнопкой по RPTR › «Setup additional UDP ports» › «Enable sender A», порт 2238, и задайте этот порт для GridTracker.",
  "t.1ltexjmlf2l": "текст, который повторяет Auto CQ (если не задан — текст F2)",
  "t.1lx8ejbcxsa": "«[[wefax.set.afcRadio]]» (по умолчанию выключено, нужны подключённое радио и включённая АПЧ): между картами, никогда внутри изображения, измеренное АПЧ отклонение переносится на частоту радио, не чаще чем раз в 20 секунд. Меняется и частота, записываемая в журнал.",
  "t.1lzxrpei3al": "Приём, точная настройка, передача, сканирование и память. У многих пунктов есть также кнопка в строке состояния.",
  "t.1m2pd8yelrr": "[[digi.menu.file]] › [[digi.mi.macrosFldigi]]: переносит в Aurora макросы, которые были у вас в fldigi. Выберите файл макросов fldigi (.mdf): Aurora переводит теги с тем же значением (<MYCALL>, <CALL>, <NAME>, <RST>, который становится <RSTS>, и т. д.), показывает те, у которых нет эквивалента (они остаются в тексте: поправьте их вручную) и размещает 48 макросов fldigi на клавишах F1-F12 и в рядах Ctrl, Shift и Ctrl+Shift. Затем выберите, куда их поместить, «[[fldigi.where.all]]» или «[[fldigi.where.mode]]», и как: «Добавить» (меняются только клавиши из файла, остальные остаются) или «Заменить» (выбранная группа станет только тем, что в файле). Нажмите «[[fldigi.import]]»; если передумаете, это можно отменить.",
  "t.1m5azjmn0bd": "«[[cluster.command]]»: выберите сервер («[[cluster.command.server]]», только подключённые), введите команду (например, sh/dx 20 для последних 20 спотов или sh/users) и нажмите «[[cluster.command.send]]». Только запрос и настройка; ответ кластера не показывается, но следующие за ним споты появляются в панели DX Cluster. Запрещённая команда или неподключённый сервер вызывают предупреждение.",
  "t.1m5wqpcgl39": "«[[adifauto.title]]»: Aurora записывает каждую QSO в файл aurora_log.adi в папке данных (%APPDATA%\\Aurora) без каких-либо действий с Вашей стороны. Если включено «[[ens.k.AdifAutoSave]]» (по умолчанию выключено), она при каждой QSO записывает дополнительную копию в файл aurora_log.adi в папке, указанной в «[[ens.k.AdifFolder]]» (полный путь, создаётся, если отсутствует). Файл в папке данных остаётся как есть. Действует сразу, без перезапуска.",
  "t.1m7yrckldff": "JT4 (подрежим A) выбирается в переключателе режимов, как JT65 и JT9: минутные периоды, четыре тона на расстоянии 4,375 Hz. Официальные частоты JT4 находятся на СВЧ; на КВ-диапазонах кнопки используют частоту JT65.",
  "t.1m84pmgnudn": "[[cat.profile]] · [[cat.profile.name]]: имя, под которым Вы сохраняете или создаёте профиль, до 80 символов (например, «FT-2000 home station» или «IC-705 portable»). Недопустимое или уже используемое имя отклоняется с сообщением.",
  "t.1m94nrx8jbx": "Вкладка «[[sstv.tpl.title]]»: «[[sstv.tpl.cq]]», «[[sstv.tpl.reply]]» и «[[sstv.tpl.qsl]]» ставят готовый шаблон вместо текущих слоёв. «[[sstv.tpl.save]]» запрашивает имя и сохраняет изображение как есть (с фото, если оно не слишком велико); в «[[sstv.tpl.mine]]» щелчок по названию открывает его снова, а кнопка «Delete» удаляет. Шаблоны хранятся на этом компьютере.",
  "t.1mazfrzlv4e": "Если COM-порт FT-991 занят программой FT-991(A) Link, Aurora отправляет ей команды CAT по UDP: частоту, режим и PTT, не борясь за порт.",
  "t.1mazjigzo66": "[[rot.set.grp.home]]: где отображается поворотное устройство, теперь, когда его нет в верхней панели. «[[rot.set.home.ft8]]» помещает карточку поворотного устройства в панель «Станция» страницы FT8; «[[rot.set.home.digi]]» помещает её на страницу PSK · RTTY · CW. Кнопка «[[rot.set.openPage]]» открывает полную страницу поворотного устройства.",
  "t.1mf289yh8w0": "Сообщения, декодированные во время передачи, показываются, но последовательность на них не отвечает.",
  "t.1mgpf1mz65": "Внизу панели [[panel.tx]] (или в одну строку, на странице из блоков) есть два уровня звука: «Rx» — вход и «TX Lvl» — выход к трансиверу.",
  "t.1mi6c64pwgi": "Контест: диапазон или режим не разрешены правилами, либо составной позывной не допускает контестных сообщений. Ссылка ведёт на страницу [[nav.contest]].",
  "t.1mjm8oy8wyz": "[[sw.contest.title]] · [[contest.set.activity]] и [[contest.set.cqWord]]: выпадающий список определяет форму сообщений контеста ([[contest.act.standard]], NA VHF, ARRL Digi, WW Digi, EU VHF, Field Day, RTTY Roundup (RU)); по умолчанию это та, которую предусматривают правила. Поле [[contest.set.cqWord]] меняет слово CQ; пустое использует слово из правил (показано как подсказка). Меняйте их, только если этого требуют правила.",
  "t.1mkjao9mp1m": "В том же окне есть также «[[digi.olivia.syncMargin]]» (насколько широко ищется сигнал вокруг выбранной частоты, по умолчанию 8) и «[[digi.olivia.syncInteg]]» (по скольким блокам суммируется синхронизация, по умолчанию 4): обычно их трогать не нужно. В плане диапазонов Aurora пока нет частот для Olivia и Contestia: при входе на страницу в этих режимах радио остаётся там, где есть.",
  "t.1mmnuixmr07": "QMAP слушает сразу участок шириной до 90 kHz и декодирует каждый найденный сигнал Q65: полезно на 6 м, 2 м и EME, где станции разбросаны по многим частотам. Только для владельцев SDR-приёмника: с обычной радиостанцией (FT-2000, IC-7300 и подобные) ему нечего читать.",
  "t.1mmskya4au0": "Включите передачу и следите за мощностью и КСВ на индикаторе; ALC — по собственному прибору радиостанции.",
  "t.1mns1xms7ct": "[[sw.tab.rotator]]",
  "t.1moll0yjdy8": "[[digi.menu.help]] › [[digi.mi.guide]]: открывает Справку Aurora (целиком, а не только раздел для этой страницы).",
  "t.1moo47q4zlj": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] откройте блок «[[toast.grp]]».",
  "t.1moq7aeiyb5": "Правый щелчок открывает меню. «Open Aurora» делает то же, что и левый щелчок.",
  "t.1mq4nvufifm": "Кнопкой «[[ctl.spot]]» вкладки «[[digi.tab.cluster]]». Она сообщает в DXSummit о станции, которую Вы услышали. Работает, только если в [[nav.settings]] › [[sw.fam.log]] › «Онлайн-сервисы» включено «Спот на DXSummit».",
  "t.1mqui58y085": "У DX-экспедиции есть строка с позывным, флагом, страной, сокращённым путём QSL и датой: «до …» (в эфире), «с …» (скоро, до 120 дней вперёд) или «закончена …» (завершена, в течение дней, выбранных в «[[onl.dxpedDays]]»). Метка «Fox/Hound» говорит о том, что Вы слышите, как экспедиция работает в Fox/Hound (чтобы провести с ней связь, нужен Hound).",
  "t.1mrf5akt2fn": "Каждый вариант записывается как тоны/полоса: 8/250 означает 8 тонов в 250 Гц. Для слабых сигналов чаще всего используют Olivia 8/250 (по умолчанию) и Contestia 16/500 (по умолчанию); Olivia 32/1000 быстрее и всё ещё устойчива, но занимает 1 кГц. Больше тонов делают режим быстрее и менее устойчивым, более широкая полоса — быстрее.",
  "t.1mucbufzfgc": "В конце QSO, если Вы включили «[[jx.PromptToLog]]» (по умолчанию выключено), посреди экрана появляется окно, чтобы Вы могли проверить данные перед сохранением в журнал. Когда выключено, QSO сохраняется само без вопросов.",
  "t.1mvhrdwqri2": "Ошибка часов звуковой карты одинакова для каждой карты: Aurora запоминает её от одного приёма к другому и показывает в «[[wefax.set.learned]]»; на изображениях без фазировки вторая карта начинается уже ровно. «[[wefax.set.slantReset]]» рядом стирает её, а при смене частоты дискретизации входа она сбрасывается сама.",
  "t.1n0lohc57ij": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.jt]] находятся параметры декодирования JT65 и JT9 с заводскими значениями WSJT-X. Страница существует только с собственным движком; параметры применяются со следующего периода, после [[sw.save]]. У FST4 и FST4W здесь собственных параметров нет.",
  "t.1n0nk84yblu": "Органы управления QSO находятся внутри [[panel.tx]], под шестью сообщениями, с ползунками Rx и TX Lvl в одной строке. [[ctl.enable_tx]] и [[ctl.auto_tx]] красные, когда включены: они вот-вот начнут передачу.",
  "t.1n0sg4vvbuz": "[[auto.b1]]: отметьте нужные новинки (новая страна, новая на диапазоне, [[auto.newMode]], квадрат, зона) и минимальный сигнал.",
  "t.1n0uutf1rlb": "передаёт текст в CW через WinKeyer (как <WKTEXT>)",
  "t.1n1fmy0w2g8": "Карта остаётся пустой: см. шаг 6 (отладка UDP).",
  "t.1n2v06cxt7k": "Страница [[nav.contest]] делает всё в одной программе: последовательность сообщений контеста, дубли, очки, множители, текущий счёт, темп и файл для организатора. Включены правила WW Digi, ARRL Digi, ARRL Field Day, FT Challenge, ARRL VHF, CQ WW VHF, IARU MGM 50/70 MHz, EU VHF, ARI FT8 Activity, DARC FT4, RSGB FT4, PACCdigi, YBDXPI FT8, VHF-UHF FT8 Activity (EU и NA), NCCC FT4 Sprint и контест «Custom».",
  "t.1n5vy4gb548": "Вычитание уже декодированных сигналов использует более быстрый фильтр (скользящие суммы вместо двух длинных БПФ): это помогает медленным компьютерам. Когда поздняя декодировка меняет только номер рапорта (R-15 становится R-16), сообщение, уже идущее в эфир, больше не прерывается для замены на середине, потому что слабая станция его не декодировала; новое уходит в следующем периоде.",
  "t.1n5w993z0iv": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]] › [[sw.pg.rx]]. Как Aurora принимает изображения SSTV: режим, настройка, автоматическое прослушивание, часы звуковой карты и вид просмотрщика. Изменения проходят кнопкой «[[sw.save]]» внизу (кроме «[[sstv.rx.smooth]]»). Если появляется уведомление о том, что число неверно, исправьте поле: поправки — целые числа.",
  "t.1n5zdkgejfv": "«[[contest.qsoNow]]»: станция, с которой Вы на связи, и её автоматическая последовательность ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): щелчок по строке выбирает это сообщение, «[[contest.onAir]]» сообщает, какое уходит. Если станция не участвует в контесте (отвечает рапортом в dB), появляются «[[contest.normal.rpt]]», «[[contest.normal.rrpt]]» и «RR73» для завершения обычными сообщениями: QSO попадает в обычный журнал и не засчитывается в контесте.",
  "t.1n7jm671654": "пишет TEST, если соревнование активно, иначе ничего",
  "t.1n7lcbqrhc5": "Просмотр: «[[wefax.view.fit]]» вписывает изображение по ширине, «[[wefax.view.actual]]» показывает его в реальном размере с прокруткой, «[[wefax.view.zoomIn]]» и «[[wefax.view.zoomOut]]» увеличивают и уменьшают, «[[wefax.view.follow]]» удерживает в поле зрения поступающую строку.",
  "t.1n89ohehd44": "Предупреждения в верхней части блока: если выбран OmniRig, но он не установлен («[[cat.omnirig.absent]]» в списке), Aurora сообщает об этом, и лучше перейти на Hamlib, который уже входит в комплект. Если выбран Hamlib, а rigctld (программа Hamlib, которую антивирус обычно удаляет) отсутствует, появляется предупреждение с кнопкой «[[cat.restore]]» (только Windows): она заново скачивает его из официального релиза и проверяет его отпечаток. В Linux положите rigctld рядом с Aurora или впишите путь к нему в переменную AURORA_RIGCTLD.",
  "t.1n8jooh9mjh": "Выбор аудиовхода и аудиовыхода радио.",
  "t.1n9j1c56due": "Если сообщение «исчезает», сначала попробуйте [[fil.bypass]]: если оно возвращается, дело в фильтре на этой странице. У каждого параметра также есть «?» с кратким пояснением.",
  "t.1n9px455ceb": "[[lay.settings]] · [[clock.servers]]: серверы NTP, по одному в строке, от 1 до 8, в виде имени или адреса (с :порт, если не 123). Aurora использует тот, у которого наименьшая сетевая задержка. Заводские: it.pool.ntp.org, ntp1.inrim.it, time.cloudflare.com и time.windows.com. Меняйте их, только если сервер не отвечает или чтобы использовать свой; при недопустимых значениях появляется «[[clock.invalid]]», и они не сохраняются.",
  "t.1n9ybcyuosc": "Дважды щёлкните по споту (одинарный щелчок на страницах PSK, RTTY и CW, если Вы так выбрали): приём (VFO A) на споте, передача (VFO B) со сдвигом, сплит включён. Над таблицей появляется «DX split: Tx 14.030» с кнопкой «[[cluster.splitDx.off]]».",
  "t.1na24bum64c": "«[[ens.g.dxsummit]]» · «[[ens.k.AllowSpotsDXSummit]]» (по умолчанию включено): включает кнопку «[[ctl.spot]]» панели «[[panel.cluster]]» на странице [[nav.station]]. Спот никогда не уходит сам: Вы отправляете его, один раз на станцию, с частотой трансивера, а также частотой приёма и режимом в комментарии, и он публикуется в интернете от Вашего имени. Выключите, если не хотите, чтобы кнопка была активна. «[[ens.test]]» читает последний спот DXSummit, чтобы проверить, отвечает ли сайт; спот он не отправляет.",
  "t.1naa68bepjx": "Удалять, добавлять и исправлять можно только с ПК или из домашней сети («[[exp.localOnly]]»). При пустом журнале на странице написано «[[exp.empty]]». Чтобы импортировать ADIF-файл (Вашу историю), см. «Статистика и карточка DXCC», блок «[[logio.title]]».",
  "t.1nb5s77g5m3": "«[[ens.g.eqsl]]» · «[[ens.k.EQSLSend]]» (по умолчанию выключено): отправляет в eQSL каждую записанную QSO. «[[ens.k.EQSLUser]]» и «[[ens.k.EQSLPasswd]]» — имя пользователя и пароль Вашей учётной записи eQSL. «[[ens.k.EQSLNick]]» нужен, только если в Вашей учётной записи больше одного «QTH» (например, дом и выезд): впишите название нужного, иначе оставьте пустым. «[[ens.test]]» входит в eQSL без отправки QSO.",
  "t.1nb7cjsalkc": "Импорт: в «[[ctest.listTitle]]» нажмите «[[ctest.import]]» и выберите пакет .zip (файл .contest с его макросами и списком доменов) либо отдельный файл .contest. Aurora проверяет его перед копированием; соревнование с тем же названием не заменяется: у нового в конце названия добавляется «(2)».",
  "t.1nbx182aqi5": "печатает QSL-карточку текущего QSO",
  "t.1nbztqomue9": "Пусть Log4OM читает радио через Aurora (общий CAT).",
  "t.1ndvgssh1u4": "Что перечислять, выбирается в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], блок «[[cqp.title]]»: типы сообщений, только определённые станции, станции для скрытия, максимум строк.",
  "t.1nfuqa95elu": "Неверное значение отмечается красным с указанием причины под полем, и QSO не сохраняется, пока Вы его не исправите.",
  "t.1nhlpa88l8i": "Кнопки вверху (под текстом «[[int.empty]]» или «[[int.addMore]]»): «+ [[int.p.wsjtx]]», «+ [[int.p.bblogger]]», «+ [[int.p.loghx]]», «+ [[int.p.multicast]]», «+ [[int.p.adif]]» и «+ [[int.p.n1mm]]». Каждая добавляет получателя с правильными начальными значениями для этой программы (см. «Интеграции: что получает каждая программа»). На шестнадцатом получателе они отключаются («Не более 16 получателей»).",
  "t.1ni3unh1nno": "«rotctld не найден»: восстановите Hamlib в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] (rotctld находится рядом с rigctld).",
  "t.1ninkrr3hrj": "Если появляется «[[ctl.unavailable]]», органы управления Aurora недоступны: проверьте, что Aurora открыта на ПК.",
  "t.1nkuvsk2v0q": "Включены по умолчанию, их можно выключить: они помогают исправлять проблемы без отправки личных данных.",
  "t.1nmyxgmntjg": "Отправка: в конце QSO предложите QTC (макрос «I Have QTC»), затем F12 (<QTCSEND>) открывает окно [[qtc.title]] на вкладке [[qtc.send]] с позывным QSO. Aurora предлагает QSO соревнования, которые ещё можно отправить этой станции, сначала самые старые, с номером следующей серии. Снимите отметку [[qtc.c.use]] у тех, которые Вам не нужны, затем [[qtc.header]] отправляет «QTC n/m», [[qtc.sendAll]] отправляет заголовок и строки и запрашивает QSL, [[qtc.sendLine]] отправляет (или повторяет) одну строку.",
  "t.1nq8adeziei": "Панель DX Cluster: фильтры и столбцы",
  "t.1nr5zmhuna": "Столбцы: «[[exp.col.date]]», «[[exp.col.time]]», «[[exp.col.call]]», «[[exp.col.band]]», «[[exp.col.mode]]», «[[exp.col.sent]]» и «[[exp.col.rcvd]]» (рапорты в dB, которые Вы отправили и получили), «[[exp.col.grid]]», «[[exp.col.country]]» и кнопка «[[exp.edit.btn]]». В больших журналах показывается по 300 строк за раз: прокрутите вниз или нажмите «[[exp.more]]»; фильтры, выбор и экспорт применяются ко всему журналу.",
  "t.1nrjmdq2y9g": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]. Интернет-сервисы, которыми Aurora пользуется для спотов, поиска и данных о прохождении. Они необязательны: на этой странице Вы можете включать и выключать их, когда захотите. Aurora делает лишь редкие запросы и не отправляет ничего из того, что Вы принимаете или передаёте, кроме оговорённых случаев (споты, от Вашего имени). Блоки «[[onl.psk]]», «[[onl.solar]]» и «[[onl.dxped]]» сохраняются сразу; блоки со строками (споты, поиск) — кнопкой «[[sw.save]]». Спот на WSPRnet находится не здесь, а в [[sw.fam.modes]] › [[sw.sub.wspr]].",
  "t.1nsn7sqwcyz": "Заголовок «[[sstv.title]]» и рядом метка состояния: «[[sstv.state.sending]]», «[[sstv.state.receiving]]» или «[[sstv.state.off]]». Когда Вы просто слушаете, ничего не появляется (это нормальное состояние).",
  "t.1nsus64hw9x": "Откройте [[nav.contest]], выберите контест в меню и нажмите «[[contest.activate]]». Aurora настраивает сообщения и слово CQ, обмен, Fox и Hound выключает, AutoSeq включает, Hold Tx Freq и режим; прежние настройки запоминаются.",
  "t.1nswq13snr1": "<RX> — метка внутри текста: когда передача доходит до этого места, происходит возврат на приём. Текст, написанный после <RX>, не отправляется: он остаётся в окне передачи, готовый для следующего раза. Если макрос не передаёт и Вы не передаёте, <RX> ничего не делает.",
  "t.1nt2a4h3xfp": "Индикатор статуса: [[fox.state.off]] (Fox выключен), [[fox.state.waiting]] (Fox включён, но Enable Tx выключен), [[fox.state.ready]] (готов, ожидает следующего периода) или [[fox.state.onair]] (в эфире).",
  "t.1nt5janboxe": "«[[cop.choose]]»: «[[cop.double]]» (по умолчанию) или «[[cop.single]]». Выберите одиночный щелчок, если хотите работать быстрее и не боитесь выбрать не ту строку.",
  "t.1ntjzddhowx": "Если выбор диапазона отправляет трансивер не туда, куда Вы ожидаете, посмотрите на эту таблицу: у какой строки для этого диапазона и режима стоит галочка [[freq.preferred]] и не затемнена ли строка выбранным регионом.",
  "t.1nukdavcstj": "уровень выхода: ослабление в дБ (0 = максимум)",
  "t.1nv2yx6sed2": "«[[contest.tips]]»: темп за последние 12 часов и предупреждения («[[contest.alert.ok]]», когда всё в порядке; затем начало, конец, неуверенные QSO, обязательный запуск человеком, часы активности). При нескольких диапазонах есть также таблица QSO, очков и множителей по диапазонам.",
  "t.1nxf0wro3n0": "В «[[digi.scan.title]]» выберите, сколько оставаться на каждой станции («[[digi.scan.dwell]]»), останавливаться ли на первой («[[digi.scan.once]]») и печатать ли в тексте время и частоту каждой станции.",
  "t.1nyyqk07klz": "Карточка новой DXCC не зависит от «[[alert.button]]»: она появляется в любом случае; от «[[alert.button]]» зависит только её звук. Чтобы не было ни карточки, ни звука, нажмите «[[newdx.off]]».",
  "t.1nz9r3nc6ik": "Вы можете менять размер окна или перемещать панель: водопад сохраняет уже нарисованные строки.",
  "t.1nzr1mxhurj": "С FT-2000 или другими радиостанциями без потока I/Q оставьте QMAP выключенным: для обычного Q65 достаточно переключателя режима на странице «Станция».",
  "t.1o19je3tq73": "Для каждого розыгрыша ведётся свой журнал контеста (день начала указан в имени файла), поэтому еженедельные и ежемесячные контесты не смешиваются; журналы из прежних версий по-прежнему читаются. Когда контест заканчивается, журнал остаётся как есть, и в течение двух дней фаза — «завершён»: Aurora никогда сама не удаляет QSO, даже если Вы вручную меняете начало и конец. Порядковый номер всегда равен числу QSO в журнале контеста + 1, в том числе после отброшенного QSO или «Сброса». В Cabrillo отсутствующий обмен остаётся «-», и проверка сообщает об этом; QSO на диапазонах, которые правила не разрешают, пропускаются с предупреждением; CATEGORY-TIME и CATEGORY-OVERLAY записываются, только если Вы задали их в настройках.",
  "t.1o2xhc31037": "Пульт дистанционного управления: сообщения Tx и панель команд",
  "t.1o30t9yaio2": "Частота VFO B поступает только при включённом «[[cat.extras]]» (с Hamlib); кнопка TUNE показывается и без него.",
  "t.1o3wjpjjrp3": "[[rot.set.connection]]: «[[rot.set.launch]]» (заводской), если ротор подключён к этому компьютеру: Aurora сама запускает входящий в комплект rotctld с моделью, портом и скоростью. «[[rot.set.remote]]», если rotctld уже запущен другой программой или работает на другом компьютере. Если при «[[rot.set.launch]]» предупреждение сообщает, что rotctld не найден, восстановите Hamlib на странице [[sw.pg.radio]] (кнопка «[[cat.restore]]») или перейдите на «[[rot.set.remote]]».",
  "t.1o3zqh5j7cv": "Выберите свободное место на водопаде правой кнопкой: красный маркер Tx переместится туда.",
  "t.1o45n1jb3w0": "Другое, что снижает нагрузку: выключите «[[jx.SWLMode]]» (он ищет глубже и в более широком окне: полезен только когда Вы не передаёте) и закройте тяжёлые программы. Сразу после запуска Aurora, пока трансивер и звук ещё поднимаются, карточка не появляется (около 20 секунд), а уже показанная карточка исчезает сама примерно через 10 минут.",
  "t.1o7o55g8zq9": "[[cqp.title]] · [[cqp.limit]]: числовое поле от 5 до 200, заводское значение 40. Сколько строк хранит окно [[panel.cq]]; самые старые выпадают. Увеличьте, если хотите более длинный список.",
  "t.1oa9533g8uv": "Справа от кнопок режимов находятся страницы. Сначала страницы используемой группы, затем разделитель и страницы, работающие в любом режиме, и в конце шестерёнка, которая открывает «Настройки».",
  "t.1oc2ghw18qs": "На странице QMAP, в «I/Q source», выберите «SDR via TCI» с адресом (например, 127.0.0.1:40001) или «I/Q WAV file» с путём; затем период и подрежим (например, 60 s, A) и «Apply». «+30 s» ищет и Q65-30, «Average» суммирует периоды для более слабых сигналов.",
  "t.1oeh4xw2ujr": "Что отправляется разработчикам Aurora и как это выключить?",
  "t.1oena7wqfvj": "«[[ens.test]]» (в каждом сервисе, кроме оговорённых случаев) проверяет уже сохранённые настройки, не записывая ни одной QSO. Перед сохранением выводится сообщение «проверить можно после сохранения изменений». После этого показывается «[[ens.test.ok]]» или «[[ens.test.err]]» (подробности при наведении курсора). Проверка запускается сама один раз при открытии страницы, если сервис включён, и сразу после сохранения, когда Вы подтвердили пароль или ключ. Рядом — «[[ens.st.title]]»: результат последней выгрузки («[[ens.st.ok]]» или «[[ens.st.err]]») со временем; если сети нет, QSO остаются в очереди («QSO в очереди: N») и отправляются повторно сами.",
  "t.1ofxzbd7vfn": "Чтобы сразу перейти на следующий элемент, не дожидаясь, щёлкните правой кнопкой по полосе диапазонов.",
  "t.1ogwl5ntunj": "«[[sstv.tx.to]]»: позывной другой станции, для подстановки {CALL} в текстах; если пусто, Aurora использует DX, выбранный на странице Station (показан в поле серым). Только буквы, цифры и «/».",
  "t.1oht1t6ifr4": "«[[int.n1mm]]»: для каждой QSO XML-сообщение «contactinfo» от N1MM Logger+ (базовый порт 12060): читают HRD Logbook и программы, имитирующие N1MM.",
  "t.1oimmcrprwt": "[[cop.title]]",
  "t.1oiyuq5cwtm": "[[sw.pg.digiScan]]",
  "t.1olh8317ke6": "На странице приёма есть и кнопка «[[sstv.rx.tx]]»: она передаёт изображение, подготовленное в «[[sstv.view.tx]]», и переводит Вас туда. Когда передача заканчивается, страница сама возвращается к приёму, который и не прерывался: следующее изображение можно готовить, пока принимается текущее.",
  "t.1oqzylbm8qv": "ПК декодирует слишком медленно: карточка сообщает, сколько секунд уходит на период, и предлагает две кнопки, «[[diag.slow_pc.to2]]» или «[[diag.slow_pc.to1]]», которые сразу меняют глубину декодирования (действует со следующего периода), а также «[[diag.slow_pc.setting]]» для открытия настройки. Если это происходит часто, ПК не соответствует требованиям (см. «Какой компьютер нужен»).",
  "t.1or9w39ewb0": "Сервис с паролем или ключом не отображается: Windows не предоставляет защиту секретов на этом ПК; остаётся только LoTW.",
  "t.1osf8rf5gdh": "[[sw.sub.digi]]: четыре страницы, [[sw.pg.digiRxTx]], [[sw.pg.digiMacros]], [[sw.pg.digiScan]] и [[cop.title]]. Первые две сохраняются сами при каждом изменении в движке Aurora (ползунки — когда Вы их отпускаете, числа — когда покидаете поле). Свойства и память сканирования и параметры DX Cluster остаются на этом устройстве.",
  "t.1ovap98yqn3": "Ваша станция",
  "t.1oxid21krfy": "«[[qmap.spectrum]]»: спектр участка с найденными сигналами; ниже — сколько кандидатов и сообщений найдено и сколько секунд данных используется. Строка Луны показывает азимут, угол места и доплеровское эхо по Вашему локатору.",
  "t.1oxr4gmnslm": "Пресет «[[cat.preset.title]]» (блок после подключения, для известных моделей) сам записывает скорость 115200, PTT по CAT и CI-V 0: для IC-7300, IC-7610, IC-705 или IC-9700 это самый надёжный путь. Затем проверьте, что в меню трансивера скорость CI-V USB равна 115200, а адрес CI-V заводской.",
  "t.1oyvfniwx1r": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], нижняя часть страницы: совместное использование трансивера с другими программами и вид дисплея в шапке. Варианты дисплея чисто графические и применяются сразу.",
  "t.1ozdi7tuoua": "[[sstv.log.his]] и [[sstv.log.my]]: рапорты (по умолчанию 59, до 3 символов).",
  "t.1p0k6o0ro6g": "[[clock.state]] (блок, со светодиодом проверки рядом с заголовком): сообщает, точны ли часы, «[[clock.good]]» или «[[clock.bad]]», и показывает [[clock.offset]] (на сколько мс часы отстают или спешат относительно серверов), [[clock.delay]] (сетевая задержка), [[clock.server]] (используемый), [[clock.answered]] (сколько серверов ответило) и [[clock.when]] (время последнего измерения); если время было исправлено, появляется «[[clock.corrected]]». До первого измерения показывается «[[clock.none]]». Вне допуска означает за пределами порога тревоги, выбранного ниже.",
  "t.1p0t4u81ppf": "[[sw.station]] · [[gen2.grid]]: Ваш локатор Maidenhead из 4 или 6 символов (например, IO91wm). Он используется для расстояний, азимутов (в том числе для ротора) и карты; сообщения FT8 содержат первые 4 символа. Введите его правильно: при пустом или неверном локаторе расстояния и ротор будут неверными.",
  "t.1p1rh6goeue": "В PSK, RTTY и CW можно убрать из звука несущие и узкополосные помехи с помощью режекторных фильтров (notch) и оставить только слушаемый сигнал с помощью полосового фильтра. Они действуют перед декодером, а режекторные фильтры — ещё и перед поиском сигналов по всему диапазону; водопад по-прежнему показывает звук как есть.",
  "t.1p23wjrb01e": "Вверху: «[[sstv.tx.send]]» (клавиша F1) передаёт составленное изображение и, пока Вы передаёте, становится «[[sstv.tx.stop]]» (клавиша Esc). Рядом появляются «[[sstv.tx.done]]», «[[sstv.tx.aborted]]» или ошибка последней передачи. Кнопка серая, если передавать нельзя: появляется «[[sstv.tx.notReady]]».",
  "t.1p4qow4ppjy": "параметр режима: BW (фильтр CW, полоса Olivia и Contestia или полоса пропускания), TONES (тоны Olivia и Contestia), SHIFT, BAUD, WPM, SQUELCH, SUBMODE (BPSK31, PSK63, RTTY, CW, OLIVIA-8-250, CONTESTIA-16-500); подрежимы, которых в Aurora нет, пропускаются",
  "t.1p526ct6pav": "Позывной отправителя выделен жирным внутри сообщения, чтобы Вы сразу его заметили; порядок остаётся таким же, как в FT8 (кому, от кого, информация).",
  "t.1p5u2n9yj1n": "Панель [[panel.cq]] состоит из двух частей: слева станции, вызывающие CQ, справа (если включён календарь NG3K) список DX-экспедиций с заголовком «[[dxp.title]]». Содержимое CQ выбирается в «[[cqp.title]]» (см. «[[panel.cq]] и DX-экспедиции»).",
  "t.1p8m3mbnpj1": "Первая настройка: Hamlib → выберите модель → выберите порт → [[cat.baud]], как у трансивера → нажмите [[cat.connect]] (блок [[cat.grp.test]]). Если Вы не знаете порт и скорость, попробуйте «[[cat.detect]]». О том, что проверить, если подключения нет, см. пункт «Connecting the radio: the checklist».",
  "t.1pb1pvdwybs": "Частота радио в MHz, слева. Рядом метка RX или TX: TX, пока Вы передаёте, и страница меняет вид.",
  "t.1pb3wk1m7v2": "Таблица сообщений: «[[qmap.col.freq]]», «[[qmap.col.sked]]» (частота, на которой передаёт станция, корректирующая свой доплер), «[[qmap.col.mode]]» и «[[qmap.col.msg]]». Кнопка «[[qmap.qso]]» переводит радио на этот сигнал в Q65 с правильным периодом и подрежимом; если не всё в порядке, сообщается, чего не хватает (центра участка или того, что радио не перешло). Если сообщений нет: «[[qmap.empty]]».",
  "t.1pbabn0hgmk": "На водопаде Вы работаете мышью. Основные жесты описаны в «Водопад»; здесь остальное.",
  "t.1pbluzqf2yi": "время UTC начала последней передачи",
  "t.1pckqyeogq6": "[[about.donateTitle]]: две необязательные ссылки, открывающиеся в браузере: «[[about.donateButton]]» (вклад, а не обязанность; Aurora бесплатна и останется бесплатной) и «[[about.star]]» (звезда на репозитории, которая ничего не стоит, но помогает).",
  "t.1pdjf40s2q1": "[[tab.schedule]] · [[sch.hour]] и [[sch.minute]] (два числовых поля в строке, пять строк): час (0–23) и минута (0–59) UTC, в которые срабатывает смена. Ввод часа в пустой строке создаёт строку (с диапазоном 20m, который затем нужно изменить).",
  "t.1pdpc7rgl48": "[[cop.columns]]: по одному флажку на каждый столбец спота, [[cluster.col.by]], [[cluster.col.freq]], [[cluster.col.call]], [[cluster.col.country]], [[cluster.col.mode]], [[cluster.col.comment]] и [[cluster.col.time]]. По умолчанию все видны; снимите флажок, чтобы скрыть столбец и освободить место. Один столбец должен всегда оставаться включённым: последний выключить нельзя.",
  "t.1pf5606ge68": "«[[sat.pass.title]]»: ближайшие пролёты выбранного спутника, с «[[sat.pass.hours]]» (окно времени) и «[[sat.pass.minEl]]» (пролёты ниже этого значения не показываются). Таблица — перемещаемая сетка: перетаскивайте заголовки, чтобы переместить столбцы, границу между двумя заголовками — чтобы расширить их, двойной щелчок по заголовку — чтобы восстановить. Столбцы: «[[sat.pass.date]]», «[[sat.pass.aos]]», «[[sat.pass.los]]», «[[sat.pass.dur]]», «[[sat.pass.max]]» и «[[sat.pass.az]]» (только градусы, от начала до конца; сторона света указана во всплывающей подсказке). В строке указано «[[sat.pass.now]]» или «[[sat.pass.next]]».",
  "t.1ph5e2phwwb": "[[ca.title]] · [[ca.run]]: открывает карточку, которая за один раз проверяет станцию, трансивер, звук, часы и телефон (см. «Карточка «Проверить всё»»). Закрывается кнопкой «[[ca.close]]» или Enter.",
  "t.1piztfaz526": "На странице [[nav.station]] нажмите диапазон (например, 40m): Aurora задаст собственную частоту для этого диапазона и режима, не трогая радио.",
  "t.1plg9g16i9b": "Полная статья: «Поиск параметра в настройках»; «Как работают настройки».",
  "t.1pm1q9uo0va": "[[cat.cat4om.key]]: пароль группы, только если группа его запрашивает (иначе пусто). [[cat.cat4om.radio]]: имя радио в Cat4OM (например, kenwood/ts-990), а не имя группы; пусто = первое доступное радио. Если порт администрирования не отвечает или запрашивает пароль, введите в [[cat.cat4om.address]] порт «Control» группы, показанный Cat4OM или Decodium (например, 127.0.0.1:5001).",
  "t.1pm3ikhiwro": "В контесте «Enable Tx» и Auto CQ больше не выключаются сами: когда QSO заканчивается (или DX отвечает кому-то другому, или срабатывает сторожевой таймер), станция освобождается и сразу возвращается к CQ. Остановить её можете только Вы, клавишей Esc или квадратом TX. Со стандартными сообщениями (например, DARC FT4) «Skip Tx1» при активации выключается сам, так что первое сообщение несёт локатор, а обмен отправляется полностью.",
  "t.1po4ykgfyv3": "[[ssbc.statsTitle]] — это таблица с диапазоном, QSO, дублями, очками, средним (очков на QSO) и множителями, итоговая строка выделена, а рядом с крупным числом идёт строка «Score: N points × M multipliers». [[ctw.card.rate]] показывает QSO, очки, множители и итог, темп (последние 10 минут, последний час, средний), прошедшее и оставшееся время и число QSO в час.",
  "t.1pow3d1vysk": "[[digi.wk.secPtt]]: [[digi.wk.ptt]] (выключено, если радио использует собственный break-in), [[digi.wk.lead]], [[digi.wk.tail]] и [[digi.wk.hang]].",
  "t.1pp73lflofw": "отправляет DX-спот другой станции на частоте сигнала через DX Cluster",
  "t.1pq1etxtlh2": "С телефона или планшета в домашней сети Вы управляете Aurora, запущенной на ПК.",
  "t.1pqvj82xwh3": "Блок «[[logio.title]]» (по умолчанию открыт): «[[logio.export]]» открывает страницу [[nav.log]] для экспорта; «[[logio.import]]» добавляет в журнал QSO из Вашего ADIF-файла (до 256 MB; уже имеющиеся QSO не дублируются; только с ПК или из домашней сети). В конце сообщается, сколько QSO добавлено, сколько уже было и сколько отброшено.",
  "t.1psrttb03bl": "Часы",
  "t.1pulxnwsbmn": "Столбец «Режим» берётся из комментария или из частоты (см. «Режим спотов DX Cluster»). Весь комментарий можно прочитать, наведя курсор на ячейку.",
  "t.1pum2pk1l1": "Только для Hamlib: [[cat.rig.search]] и [[cat.rig]]. Введите марку или модель (например, FT-2000 или IC-7300): подходящие модели появятся под полем, щёлкните свою. Или выберите из списка «[[cat.rig]]» (начальная запись — «[[cat.rig.none]]»: при Hamlib без выбранного трансивера [[cat.connect]] остаётся недоступной). Если Вашей модели нет, попробуйте близкую модель той же марки. Строка ниже сообщает, сколько моделей знает Hamlib.",
  "t.1pv0k6vyo70": "[[lay.settings]] · [[clock.enabled]] (по умолчанию включено): Aurora сама проверяет часы через выбранные интервалы. Если выключено, проверка только по кнопке. Оставьте включённым.",
  "t.1pvb194pdhw": "Время, дата и таймер: время и дата, в том числе в выбранном формате, время последней передачи и таймер, запускающий макрос. Пример: <TIME:%H%M>Z <TIMER:600,F2> повторяет F2 через десять минут.",
  "t.1pyx17dqp3l": "[[bfl.title]] · [[bfl.minSnr]]: числовое поле от −40 до 40; скрывает сигналы слабее записанного значения. Пусто = без ограничения. Увеличьте, когда диапазон полон почти шумовых сигналов, которые Вам не нужны.",
  "t.1q2kiqw13wm": "TX Lvl — это уровень звука, который Aurora посылает на трансивер: по умолчанию он уменьшает генерируемый сигнал (как в WSJT-X и JTDX) и никогда не трогает громкость Windows. В [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]] можно сделать так, чтобы он управлял громкостью Windows выхода.",
  "t.1q4vbcjsu3r": "Дубли QSO: один и тот же журнал получает данные двумя путями (поток, ADIF, пересылка из GridTracker или JTAlert). Оставьте только один.",
  "t.1q55kvgaymm": "Контест [[ctw.card.cluster]]: слева «[[ctl.spot]]» на цветном фоне, затем «[[cluster.filter.search]]», затем шестерёнка. Состояние сервера («[[cluster.pop.serversOn]]») находится в панели шестерёнки ([[cluster.pop.tip]]). У кластера и журнала нет полос прокрутки: прокручивайте колесом мыши.",
  "t.1q6je2jwmqd": "[[wfs.spectrum]]",
  "t.1q6zv16gs3z": "закрывает все дополнительные окна RX",
  "t.1q70sz2v7hl": "Пароли и ключи (секретные поля): введите и нажмите Enter или покиньте поле (в поле видно «[[ens.pw.type]]»); затем в поле отображается «[[ens.pw.savedShort]]» •••• с кнопками «[[ens.pw.change]]» (ввести новый) и «[[ens.pw.remove]]» (стереть сохранённый с ПК). Секрет никогда не читается обратно и не покидает ПК; он остаётся «ожидающим», пока Вы не нажмёте «[[sw.save]]».",
  "t.1q7xrk6nllj": "Aurora говорит, что передаёт, а радио нет: что проверить?",
  "t.1q8yg3bylzb": "Сменить язык: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], блок «[[ap.theme]]», пункт «[[gen.language]]». В меню флаги семи языков (итальянский, английский, немецкий, французский, испанский, португальский, нидерландский); с клавиатуры: стрелки — открыть и перемещаться, Enter или пробел — выбрать, Esc — закрыть, Home и End — первый и последний. Изменение сразу применяется ко всему интерфейсу, включая Справку, и остаётся на этом устройстве (у телефона свой выбор).",
  "t.1q8zhxoi4t9": "Слева — Солнце и условия на диапазонах; справа — карта и список тех, кто Вас принимал (PSK Reporter): новые приёмы поступают в реальном времени, в течение нескольких секунд, а страница обновляется каждые 10 секунд. Включено с завода; отключить можно в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.1qa5280a7rh": "С «[[wefax.rec.on]]» (включено по умолчанию) каждая принятая карта записывается и как звук: WAV-файл 12000 Гц, моно, около 1,4 МБ в минуту, в подпапке «audio» с тем же именем, что и карта, от стартового тона (с несколькими секундами до него) до конца; если карта отброшена, файл удаляется. «[[wefax.rec.keep]]» (по умолчанию 7) сам удаляет старые файлы. Неудачную карту можно повторить через «[[wefax.file.open]]». «[[wefax.folder.images]]» и «[[wefax.folder.audio]]» открывают Проводник на ПК, где работает Aurora; с телефона или другого ПК кнопки выключены и показывается путь для копирования.",
  "t.1qad7hwsv41": "Aurora общается с Logger32 так же, как WSJT-X и JTDX: отправляет получателю те же Heartbeat, Status, по одному Decode на каждое сообщение и записанные QSO. По умолчанию получатель — 127.0.0.1, порт 2237 («[[ens.g.udp]]» в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]). «Logged ADIF» не нужен: Logger32 его не требует.",
  "t.1qjd9ur0oks": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]] › [[sw.pg.tx]]. Как Aurora передаёт изображения SSTV. Изменения проходят кнопкой «[[sw.save]]» внизу окна. Передаваемый позывной — позывной станции ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]).",
  "t.1qjgrrs264w": "[[not2.grpMapColors]] · [[kind.grid_worked]] и [[kind.grid_confirmed]]: два цвета квадратов локатора на странице «DX-карта» (отработан, подтверждён). Измените их, если Вы не различаете жёлтый и зелёный.",
  "t.1qjljgk37g8": "Панель «Журнал» и карточка DXCC",
  "t.1qljk09ybmv": "[[lay.options]] · [[fil.bypass]]: флажок, по умолчанию выключен. Показывает всё, не удаляя фильтры: выключите его, и фильтры вернутся как были. Используйте для быстрой проверки того, что Вы скрываете.",
  "t.1qn6uq1vslt": "[[auto.b4]] · [[auto.excluded]] (текстовое поле): позывные, которым никогда не отвечать, через запятую (например, IU3ABC, IK1ABC); от 3 до 13 символов, только буквы, цифры и «/», до 200. Сохраняются в верхнем регистре.",
  "t.1qnqcwyai3c": "Выбирает режим и, для RTTY и CW, также показывает пункты, нужные этому режиму. Режим меняется сразу, без открытия окон.",
  "t.1qq3b86nnjf": "При включённом [[ctl.answer_all]] каждая станция, которая Вас вызывает, ставится в очередь сама.",
  "t.1qqko6bkngw": "[[bfl.title]] · [[bfl.hideToMe]]: флажок, по умолчанию выключен. Убирает из [[panel.all]] сообщения, адресованные Вашему позывному; ответы остаются в окне [[rxw.title]]. Включите, если не хотите видеть их дважды.",
  "t.1qtt8iwfgwv": "азимут в градусах на другую станцию (? без локатора)",
  "t.1qv03nv9ppk": "Включается и выключается в [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] переключателем «[[cluster.splitDx.set]]» (включён по умолчанию; значок «?» рядом всё объясняет).",
  "t.1qv4awrekwi": "Что считается «разыскиваемым», задаётся в [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (позывные, префиксы, страны, квадраты, диапазоны, пауза между двумя оповещениями об одной станции, оповещение на телефоне).",
  "t.1r08s26z8d4": "Чтобы проверить данные перед сохранением: отметьте «[[ens.k.PromptToLog]]» и нажмите [[sw.save]]. По окончании QSO появляется окно подтверждения: исправьте [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] или [[lp.f.comment]] и нажмите [[lp.log]]; при [[lp.discard]] QSO в журнал не попадает.",
  "t.1r0oe24ei5m": "На странице [[nav.sat]] включите доплер и покрутите ручку радио, чтобы настроиться на станцию; затем оставьте ручку неподвижной на пару секунд.",
  "t.1r1x30wk19z": "Каждое соревнование в текстовых режимах — это текстовый файл .contest: при хорошо написанных правилах Aurora подсчитывает очки, множители и счёт, как организатор. Можно написать новое, исправить имеющееся или передать его другим.",
  "t.1r2fg4ttgdc": "«[[pair.button]]»: выполняет сопряжение. Если всё хорошо, страница перезагружается, и появляется станция. Телефон запоминает адрес (также постоянное имя aurora.local), чтобы снова найти Aurora, если IP ПК изменится.",
  "t.1r3dp264fbm": "Только что занесённое QSO мигает вверху. Сколько QSO показывать: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] → «[[gen.log4omCount]]».",
  "t.1r6gh0c0a5i": "[[cat.profile.delete]]: удаляет профиль, выбранный в «[[cat.profile.pick]]» (трансивер и текущие настройки не меняются). Подтверждения нет, и отменить удаление нельзя: если профиль ещё нужен, создайте его заново. Остаётся недоступной, пока Вы не выберете профиль.",
  "t.1r7xjwn5s98": "Вверху таблица условий, такая же, как на странице [[nav.propagation]]: четыре группы диапазонов (80-40 m, 30-20 m, 17-15 m, 12-10 m), столбец для дня и для ночи, с тремя небольшими полосками и оценкой («[[prop.cond.Good]]», «[[prop.cond.Fair]]», «[[prop.cond.Poor]]»). Текущий столбец помечен «[[prop.here]]», а группа, на которую настроено радио, — «[[prop.tuned]]».",
  "t.1r7zsrl00so": "время UTC в формате ЧЧММ",
  "t.1r8ve2nizkv": "Показания S-метра, мощности и КСВ.",
  "t.1r9wsj1w0ot": "Рядом с режимом появляются его подрежимы, все в виде маленьких выпадающих списков. JT4: [[mode.jt4sub]] от A до G. JT65: [[mode.jt65sub]] A, B или C. Q65: [[mode.q65period]] (15, 30, 60, 120 или 300 секунд) и [[mode.q65sub]] от A до E. FST4 и FST4W: [[mode.fst4period]] (FST4 от 15 s до 30 минут, FST4W от 2 до 30 минут). Период и подрежим должны совпадать с теми, что у станции, с которой Вы работаете.",
  "t.1raz2iaalxv": "Споты не доходят до WSPRnet: проверьте, что [[ens.k.WSPRnetUpload]] включён и сохранён, что позывной и локатор заполнены, что CAT считывает частоту, и прочтите ошибку в «[[ens.st.title]]».",
  "t.1rfi9mr2ib1": "CAT и радио: команды радио в виде текста или hex, паузы между командами, громкость и подключение. Пример для Icom: <CATCMDHEX:FE FE 94 E0 03 FD>; Kenwood: <CATCMD:AN1;><CATWAIT:200><CATCMD:AN2;>.",
  "t.1rhb4eq28xk": "Стрелка ▲ рядом с Tx копирует частоту Rx в Tx («[[ctl.rx_to_tx]]»); стрелка ▼ рядом с Rx копирует Tx в Rx («[[ctl.tx_to_rx]]»).",
  "t.1rhna7q8olw": "Куда они уходят: на сервис того, кто разрабатывает Aurora. Обновления (проверка версии) — это другое: они обращаются к сайту релизов GitHub и отключаются через «[[upd.enabled]]» в [[tab.updates]]. «[[sup.prepare]]» и «[[bak.make]]» ничего не отправляют: они только создают zip на Вашем рабочем столе.",
  "t.1riobx5qgg8": "[[sw.behavior]] · [[gen2.monitorOff]]: с отмеченным флажком приём при запуске остаётся выключенным, и Вы включаете его кнопкой монитора; без галочки (по умолчанию) Aurora запускается уже слушающей. Вступает в силу при следующем запуске. Отметьте, если не хотите, чтобы Aurora декодировала или передавала сразу после открытия.",
  "t.1rja8pkyfpz": "[[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]]. Aurora поворачивает антенну через rotctld — программу Hamlib для поворотных устройств (тот же Hamlib, что и для CAT). Здесь вы выбираете, как к нему подключаться; команды (повернуть на DX, длинный путь, стоп) находятся на странице [[nav.rotator]], которой больше нет в верхней панели: она открывается кнопкой «[[rot.set.openPage]]», ниже. Нужен ваш локатор в [[sw.pg.personal]]: азимут вычисляется по нему.",
  "t.1rkmw5aevjt": "[[digi.edit.macro]]: какую клавишу Вы меняете. В списке 48 клавиш (4 ряда панели: клавиша на клавиатуре есть только у F1…F12 первого) и несколько специальных макросов: Gray+ (клавиша + цифровой клавиатуры), AutoCqText (текст, который повторяет автоматический CQ; если его нет, используется текст F2), Hello, OnStart, OnEnd, OnTX, OnCR, OnClickAny, OnAlarm, OnSP0 и OnSP1. Aurora выполняет Gray+, AutoCqText, OnStart (страница открывается), OnEnd (страница закрывается), OnTX (начинается передача), OnCR (Enter в поле передачи) и OnClickAny (слово из окна приёма попадает в поле журнала); OnAlarm, OnSP0, OnSP1 и Hello можно сохранить, но сами они не запускаются.",
  "t.1rm6giw4t0x": "Афиша посередине экрана: показывает ленту «[[upd.poster.ribbon]]», новинки версии на Вашем языке (под «[[upd.poster.news]]») и кнопки «[[upd.open]]», «[[upd.later]]» (скрывает её до следующей версии) и «[[upd.poster.install]]». Когда пакет уже загружен и проверен, сам запускается обратный отсчёт в несколько секунд с кнопкой «[[upd.poster.cancel]]», чтобы его остановить; он никогда не запускается, пока трансивер передаёт. При первом запуске со старым установщиком она появляется первой, с «[[upd.poster.firstRun]]».",
  "t.1rnxt49n999": "«Rx»: индикатор уровня входящего звука (пиковый и средний уровень в dB — при наведении курсора) с оценкой — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] или [[rxl.state.overdrive]] — и подсказкой, что делать. Правильный уровень — «Good».",
  "t.1rocambmqij": "Вверху шесть меток: три для страны — «NEW ONE» (никогда не проводилась связь ни на одном диапазоне и режиме), «NEW BAND» (никогда на этом диапазоне), «NEW MODE» (никогда в этом режиме) — и три для локатора: «NEW GRID», «GRID BAND» и «GRID MODE». Они загораются, если относятся к станции; при наведении курсора Вы читаете, что означает каждая.",
  "t.1roiyfbc9hz": "Полная статья: «Панель «Сигналы» (CW и PSK)»; «Панель «[[digi.band.title]]»».",
  "t.1rpt7b90t8z": "Режим спотов DX Cluster",
  "t.1rqgnay0i4g": "запускает внутри этого другой макрос (ключ или имя, например <Hello>), до 10 уровней",
  "t.1rr2r697p2n": "Данные режима (в PSK31 «31 bd», в PSK63 «63 bd», в CW скорость в WPM): щелчок открывает окно «[[digi.ms.title]]».",
  "t.1rr7kw6ygmm": "Только при активном соревновании WAE. «QRV» сообщает, что вы готовы, «Взять из приёма» считывает из окна RX заголовок «QTC n/m» и строки время-позывной-номер, которые можно исправить; «AGN» просит повторить строку, все строки или заголовок. «Сохранить» записывает серию и отправляет подтверждение. Имя <STATS:ReadQTC> из импортированных файлов тоже работает.",
  "t.1rse3hhz1b0": "[[acc.pair]] · при QR-коде на экране: сам QR-код (отсканируйте его камерой телефона и откройте в Chrome или Safari: внутри Messenger или WhatsApp страница часто не открывается), «[[acc.code]]» (введите вручную, если камеры нет), «[[acc.link]]», «[[acc.addresses]]» и сколько минут действителен код. Пока QR-код открыт, список устройств перечитывается каждые 2 секунды.",
  "t.1rufjj5pua3": "Ctrl+Enter передаёт содержимое поля (если передача не открыта): весь текст уходит, затем Вы возвращаетесь на приём.",
  "t.1rukb0zxmjb": "Вход: карта, которая принимает звук от радио (обычно «Microphone (USB Audio Device)»).",
  "t.1rw20gbn18l": "[[gen.screen]] · [[gen.showDistance]] и [[gen2.azimuth]]: первый, по умолчанию включён, показывает расстояние от Вашей станции в сообщениях с локатором; второй, по умолчанию выключен, добавляет азимут, то есть градусы, на которые нужно направить антенну. Включите азимут, если у Вас направленная антенна.",
  "t.1rzewyz4ro5": "Щелчок открывает окно «[[hl.title]]»: по одной строке для процессора, декодирования, звука, CAT и часов с её точкой и тем, что делать, и график за последние 10 минут (процессор в процентах и декодирование в процентах от доступного времени, с пунктирной границей 70 %). Закрывается значком ×, кнопкой «[[hl.close]]» или клавишей Esc.",
  "t.1rzidah40i4": "Другие блоки страницы [[nav.contest]]: совет по диапазонам, карта множителей и журнал контеста находятся на вкладке «[[contest.tab.race]]», под декодированиями; у тренировки и анализа по своей вкладке.",
  "t.1rzpec2w1jr": "Над водопадом, только в CW и в PSK31/PSK63: список всех сигналов звуковой полосы, декодируемых вместе, одна строка на сигнал. В RTTY её нет. Включается пунктом «[[digi.band.mi]]» (CW) или «[[digi.band.miPsk]]» меню [[digi.menu.options]] и видна, если в меню [[digi.menu.view]] также отмечено [[digi.band.view]]; по умолчанию она включена.",
  "t.1s0s73ycfgk": "[[sstv.log.call]]: позывной, заглавными буквами. Ниже строка указывает страну (из cty.dat) и, если поиск ответил, «Данные от», за которым следует название использованного сервиса; если станции там нет — «[[sstv.log.notFound]]».",
  "t.1s1oz3ztszu": "Переключатели QSO",
  "t.1s2btcanvky": "Проверьте полосу Rx: она должна показывать «Good».",
  "t.1s2n8ru7w0h": "Вызов CQ",
  "t.1s5jn106avk": "Проблемы с передачей: «передавать нельзя, потому что радио не подключено» (CAT не настроен), «Вы передаёте без радио» (PTT не управляется, допустимо только с VOX), «радио не перешло на передачу» (с указанием причины; см. «PTT не включается»), «радио перезапустилось с мощностью x%» (на некоторых радио она задаётся только ручкой RF PWR), «OmniRig не отвечает», «радио не подключается» (порт занят). Кнопки «[[diag.fix]]» ведут в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]].",
  "t.1s5zttamv23": "шрифт окна RX",
  "t.1s69opejj7j": "[[ens.g.alltxt]] · [[ens.k.WriteDecodedALLTXT]] (по умолчанию включено): записывает каждое декодирование в файл ALL.TXT, полезный для проверок и статистики. Выключите, если он Вам не нужен и Вы хотите файл поменьше.",
  "t.1s7hyz257aa": "Щелчок по строке переводит приём на эту станцию (строка выделена); двойной щелчок переводит приём туда (в RTTY — в центр пары тонов) и помещает позывной в QSO. Рядом с позывным стоит метка: «B4» (зелёная) — уже проведена связь на этом диапазоне и в этом режиме; «DXCC» (фиолетовая) — страна, с которой связи не было; «NEW» (жёлтая) — позывной, с которым связи не было; «BM», «B» (голубая) — диапазон и режим вместе новые или новый диапазон; «M» (светло-зелёная) — новый режим; метки нет, если ничего нового нет. Вне соревнования учитывается локальный журнал; макросы «<IGNOREBEFORE:yyyy-mm-dd hh:mm>» и «<PERIOD:n>» ограничивают его QSO начиная с даты или за последние n минут; «<IGNOREBEFORE:ERASE>» снимает ограничение по дате. При активном соревновании учитывается только журнал соревнования (более ранние QSO не учитываются никогда): «DUPE» (красная) — дубль по правилам соревнования (тот же диапазон и режим либо без учёта диапазона или режима, как предписывают правила) и «MULT» (фиолетовая) — новый множитель, вместо «B4» и «DXCC»; «<QSONR>» начинается заново с 001 с последнего номера, отправленного в соревновании, + 1. Легенда находится в верхней панели: при наведении на неё также сказано, откуда берутся метки. На водопаде появляются только надёжные позывные.",
  "t.1s7oy1wvrhd": "В PSK нижняя строка показывает S/N и IMD (IMD измеряется во время непрерывных инверсий в начале каждой передачи; ниже -20 dB сигнал чистый). Шумоподавитель смотрит на качество фазы (0-100), а не на громкость: при 15 шум не печатается, а сигналы проходят примерно до -10 dB. АПЧ следует за станцией только при наличии сигнала PSK, поэтому на шуме остаётся на месте.",
  "t.1sa47j02te6": "«[[ens.g.adif]]» · «[[ens.k.EnableUDP2adifBroadcast]]» (по умолчанию включено), «[[ens.k.UDP2Server]]» (127.0.0.1) и «[[ens.k.UDP2ServerPort]]» (2237): вторичный UDP-сервер отправляет для каждой QSO только запись ADIF в виде текста, одна датаграмма на QSO, для журналов, которые принимают её так (Log4OM 2, WaveLogGate). Обратите внимание: по умолчанию первичный и вторичный серверы оба указывают на 127.0.0.1:2237; оставьте включённым только тот, который нужен Вашему журналу, или задайте другому другой порт. Если тот же адрес указан и в «[[int.title]]», Aurora отправляет QSO только один раз. «[[ens.test]]» отправляет Heartbeat на второй сервер.",
  "t.1sa6276eapv": "С TCI (SDR) ползунок TX Lvl не используется: задайте мощность на SDR кнопками PWR − / + на дисплее трансивера.",
  "t.1sb89l13z26": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.pg.qso]] Вы решаете, как заносятся QSO в журнал (для всех режимов), какие QSO в журнале считаются «уже проведёнными» и что делает Aurora при запуске. Параметры сохраняются кнопкой [[sw.save]] внизу окна; почти все вступают в силу сразу.",
  "t.1semxb1qq5o": "[[digi.mi.waterfall]] (вкл.): водопад со шкалой. [[digi.band.view]] (вкл.): панель с сигналами всего диапазона; появляется только в CW и PSK и при включённом декодировании диапазона в меню [[digi.menu.options]]. [[digi.band.wfCalls]] (вкл.): позывные, написанные над трассами на водопаде. [[digi.band.wfWords]] (вкл.): под каждым позывным последние слова его канала (например «CQ TEST» или «5NN 123 TU»), с выделением позывных и слов соревнования и приглушением неуверенных символов; строка гаснет, когда канал затихает. При наведении на позывной показывается текст за последние три минуты, щелчок настраивает на станцию. Можно переключить и из контекстного меню водопада. [[digi.mi.statusBar]] (вкл.): строка внизу.",
  "t.1seypt02j9w": "Aurora: перенесите основной сервер на другой порт (например, 2238 или порт GridTracker), чтобы 2237 остался для Log4OM.",
  "t.1sgay2jjqf8": "Карточка вверху справа для новой DXCC (флаг, позывной, страна): под карточками есть кнопка «[[newdx.off]]», которая отключает их все. Чтобы вернуть их: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], флажки «[[not2.popNew]]» и «[[not2.popNewBand]]». Чтобы переместить: «[[not2.popPos]]». Значок × на карточке («[[newdx.close]]») закрывает только эту станцию, до следующего запуска Aurora.",
  "t.1sgb3odor9o": "Заголовок: число сигналов и сколько из них вызывают CQ, а также легенда неуверенных символов (серым). Когда список пуст, панель сообщает, что ни один сигнал пока не распознан: они появляются сами.",
  "t.1sigctm4a3z": "Включите [[ctl.enable_tx]]: в следующем периоде Aurora передаст CQ. Тому, кто Вам ответит, она ответит автоматически, если включён [[ctl.autoseq]]. Когда QSO закончено, CQ начинается снова сам только при включённом [[ctl.auto_tx]]; при включённом [[ctl.single_qso]] после одного QSO Aurora останавливается.",
  "t.1sik69dc9dg": "Статистика и карточка DXCC",
  "t.1skigz1cxph": "[[sw.sec.sstv]] › [[sw.pg.tx]]",
  "t.1skl7kd3qfl": "При каждой смене частоты карта очищается: остаются только станции, услышанные после этого.",
  "t.1smhh26ne7x": "Спутники: пролёты, доплер и ротор",
  "t.1snkagke9i": "[[fil.decode]] · [[dec.aggressive]]: числовое поле от 0 до 10, заводское значение 4. Насколько принимать неуверенные сообщения JT65: 0 — осторожно, 10 даёт больше сообщений и больше ложных. Увеличьте, если теряете слабые сигналы JT65, уменьшите, если появляется слишком много неверных сообщений.",
  "t.1snl5a2r5o8": "[[cat.auto]] (по умолчанию выключено): при каждом запуске Aurora сама подключает трансивер. Включите, когда настройка работает и Вы не хотите каждый раз нажимать [[cat.connect]]. [[cat.extras]] (по умолчанию выключено): помимо частоты и режима Aurora считывает с трансивера частоту второго VFO и состояние тюнера, только на приём: они питают частоту VFO B и кнопку TUNE под дисплеем. На медленных последовательных портах это немного занимает порт. Эти два флажка (и следующие два) сохраняются сразу, без «[[cat.apply]]».",
  "t.1sq3eav55us": "[[gen2.bandHop]] · [[gen2.bandHopList]] (текстовое поле, по умолчанию пусто): записи через запятую, например «FT8 20m, FT4 40m, MSK144 6m» (частота берётся из таблицы частот) или до 8 собственных частот в kHz (например, 14090), всегда в FT8. Недопустимые записи отбрасываются; при пустом списке Band Hopping ничего не делает.",
  "t.1sq7mehdjr3": "включает шумоподавитель (<SQUELCHOFF>, <SQUELCH>)",
  "t.1sqy9r71htr": "«мы уже работали» на языке другой станции",
  "t.1srk1cj2ej3": "Счёт и Cabrillo: отправленные и принятые QTC добавляются к QSO, (QSO + QTC) × множители; после QSO в Cabrillo идут строки «QTC:» в формате правил (частота, режим, дата и время серии, получатель, серия n/m, отправитель, время, позывной и номер QSO). В [[ctest.editActive]] пункт [[ctest.f.qtc]] выбирает, есть ли в соревновании QTC.",
  "t.1ssewnwrcgh": "«[[l4.title]]» · «[[l4.choose]]»: открывает окно Windows «Открыть файл» для выбора файла Log4OM .SQLite (кнопка есть, только если Вы работаете с Aurora на самом ПК). Aurora проверяет файл, запоминает его и сразу перезагружает QSO, без перезапуска.",
  "t.1su2cqddso3": "Когда карта заканчивается (конечный тон, даже слабый), Aurora сама закрывает и сохраняет её целиком; как только начинается сигнал новой карты, окно очищается и начинается с нуля. Сохранённые карты можно открыть крупно в любой момент: приём никогда не останавливается, а зелёная метка сверху напоминает, что он идёт.",
  "t.1sunaza27gn": "CW выбирается в меню [[digi.menu.mode]], как и другие режимы. Aurora передаёт текст, который Вы пишете, или макросы, а принимает, сама определяя скорость декодированием. Входа для телеграфного ключа или электронного кейера нет: CW всегда начинается с клавиатуры.",
  "t.1sw98yncjwc": "Строка состояния под входом: имя используемого устройства или, если ни один вход не активен, красное предупреждение «[[aud.nowInNone]]»; если вход не открылся, появляется также причина, названная системой. Если шкала Rx молчит, смотрите сначала здесь.",
  "t.1swx4rp37vc": "Оповещения и карточки, появляющиеся сами",
  "t.1t281kj2gi": "[[sw.contest.title]] · [[sw.contest.which]]: выпадающий список с контестами, допускающими FT8 или FT4; включённый отмечен словом «[[sw.contest.active]]». Он сам открывается на активном контесте, если тот относится к этой ветви; иначе в нём написано «[[sw.contest.choose]]», и пока Вы не выберете контест, появляется только примечание [[sw.contest.note]]. Без собственного движка он показывает «[[contest.unavailable]]».",
  "t.1t30rd0u6zu": "[[sw.pg.orbits]] · [[sat.set.servers]]: по одному флажку на каждый сервер, предлагаемый Aurora (адрес сайта появляется под названием); отметьте те, с которых нужно скачивать. Строка «[[sat.set.serversHint]]» выше напоминает, для чего они нужны. По умолчанию отмечены те, что предлагает Aurora.",
  "t.1t6pt5vdhva": "[[tab.frequencies]] · [[freq.addRow]]: добавляет строку внизу таблицы (по умолчанию 20m, FT8, 14.074 MHz, [[gen2.regionAll]], галочка [[freq.preferred]] стоит); затем измените поля строки. Используйте для альтернативной частоты (например, DX-экспедиции) или для режима, которого нет для этого диапазона.",
  "t.1t7vpdl0joq": "сплит включён (1) или выключен (0): передача остаётся на месте, пока вы перемещаете приём",
  "t.1t9bov6fz66": "Над водопадом панель «[[digi.band.title]]» декодирует сразу все сигналы CW в звуковой полосе, каждый своим приёмником: одна строка на сигнал с частотой, WPM, S/N, позывным (флаг, CQ или DE; курсивом, пока не подтверждён) и последним текстом, с неуверенными символами серым. Позывной появляется и на водопаде над трассой. Щелчок переносит приём на этот сигнал, двойной щелчок показывает весь текст за последние 60 секунд. Включается и выключается из меню «Параметры» («[[digi.band.mi]]»); при слишком большом числе сигналов остаются самые сильные, чтобы не использовать больше четверти ядра.",
  "t.1tfukx8jvj3": "Оповещения действуют для спутников, отмеченных в списке: за [[sat.alert.lead]] мин до пролёта на странице [[nav.sat]] звучит предварительное предупреждение. Если включить флажок «[[sat.alert.bar]]» (по умолчанию выключен), звук и метка с названием спутника и обратным отсчётом до восхода появляются на любой странице Aurora (FT8, PSK · RTTY · SSTV, WEFAX, Станция…), в свободном месте посередине верхней панели. После восхода метка показывает время до захода и сама исчезает через минуту. Щелчок выбирает этот спутник и открывает страницу [[nav.sat]]; ✕ закрывает метку на этот пролёт. Если оповещения выключены или предупреждение заранее равно 0, метка не показывается и звука нет. При выключенном «[[sat.alert.bar]]» оповещения остаются только на странице [[nav.sat]].",
  "t.1tgne2dwtt5": "Изображение приходит наклонённым: Aurora сама исправляет наклон в каждом изображении; «[[sstv.set.slant]]» нужен только для звуковых карт с очень большим уходом частоты.",
  "t.1thrgm9cge3": "В таблице семь столбцов: «[[cluster.col.by]]» (кто отправил спот), «[[cluster.col.freq]]» (в kHz), «[[cluster.col.call]]» (DX), «[[cluster.col.country]]», «[[cluster.col.mode]]», «[[cluster.col.comment]]» и «[[cluster.col.time]]». Порядок меняется перетаскиванием заголовка (или Alt + стрелки), ширина — перетаскиванием правого края (Alt + Shift + стрелки); щелчок правой кнопкой по заголовку: «[[cluster.cols.reset]]».",
  "t.1ti1wh8oi3e": "Подрежимы JT65 и усреднение",
  "t.1tjjhwkzkwg": "В «Fast QSO», в меню под «Auto-Save», выберите Aurora и отметьте «Auto-Save».",
  "t.1tl7lrbvmm4": "Каждое QSO попадает в обычный журнал и в журнал контеста. Если другая станция повторяет обмен после Вашего RR73, Aurora сама повторно отправляет RR73 и помечает QSO как «[[contest.state.incerto]]»; принятый обмен исправляется одним щелчком в журнале.",
  "t.1tn475j648c": "[[sat.set.update]] · строка состояния и «[[sat.tle.refresh]]»: в строке указано, как давно были загружены данные (или «[[sat.tle.none]]»); кнопка загружает их сразу и показывает уведомление с числом обновлённых спутников или причиной ошибки. Она неактивна во время загрузки или если не отмечен ни один сервер.",
  "t.1tppo6ct1re": "QSO не приходят после открытия: порт назначения должен быть тем, который слушает журнал (в Log4OM подключение ADIF_MESSAGE должно быть активным).",
  "t.1tq7llthkmo": "«[[sstv.tx.mode]]»: выпадающий список режимов, с разрешением и длительностью рядом с названием (от полминуты до почти пяти минут). Он следует за режимом, распознанным при приёме (при открытии начинается с режима, выбранного в Настройках SSTV), и не может меняться, пока Вы передаёте.",
  "t.1ttvpvj8v0f": "После подключения ротора откройте [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.tracking]] и включите «[[sat.trk.master]]»: когда выключено, ротор никогда не получает команд от Aurora.",
  "t.1tu027f31ke": "В сообщении позывной передающей станции выделен жирным (с цветным подчёркиванием, если она использует LoTW); позывной DX, которого Вы вызываете, подсвечен. Наведите курсор на позывной, и появится карточка станции: страна, континент, имя, город, азимут и расстояние от Вашей станции (если локатор известен) и способы подтверждения QSO (LoTW, eQSL, прямая QSL, бюро, QSL через). Данные берутся с QRZ.com или HamQTH, если Вы их включили ([[nav.settings]] › [[sw.fam.log]]).",
  "t.1tv61ps80tc": "Внимание: с этими функциями передача может начаться без Вашего нажатия. Когда QSO завершено, очистите DX.",
  "t.1tv9jvs6mjs": "Linux: порты — это файлы в /dev. Кабели USB-serial (микросхемы CP210x, FTDI, CH340) отображаются как /dev/ttyUSB0, /dev/ttyUSB1…; трансиверы с собственным USB — как /dev/ttyACM0. Они появляются в списке [[cat.port]], и путь можно также ввести вручную. Пути /dev/serial/by-id/… лучше: они не меняются после перезагрузки или при перестановке двух кабелей. После включения трансивера или подключения кабеля нажмите «[[cat.ports.refresh]]».",
  "t.1tvewzg3yzz": "[[sw.pg.files]]",
  "t.1twlsupsx6u": "[[cat.share]] · [[cat.share.on]] (только Hamlib, по умолчанию выключено): порт COM может использовать только одна программа. С этой галочкой Aurora держит COM трансивера, а остальные программы (Log4OM2, JTDX, GridTracker, flrig…) подключаются к Aurora как к трансиверу «Hamlib NET rigctl». Работает только на этом ПК. После включения нажмите [[cat.apply]], а затем [[cat.connect]]; всегда сначала запускайте Aurora.",
  "t.1u0h6448o4j": "Внизу окна узкая панель показывает состояние периода и держит под рукой звуковые оповещения, тему и время UTC.",
  "t.1u2tdrladea": "Log4OM 2: приём QSO",
  "t.1u42db17y1s": "С двухприёмным SDR выберите RX1 или RX2 в [[cat.tci.receiver]]: частота, режим, PTT и звук используют именно его. RX2 включается сам, если выключен.",
  "t.1u5zsuahxe5": "В программе SDR включите сервер TCI (обычно порт 40001).",
  "t.1u6dm99tcxt": "[[sw.contest.title]] · [[contest.set.cabrillo]], [[contest.set.catTime]], [[contest.set.catOverlay]], [[contest.set.soapbox]]: [[contest.set.cabrillo]] — название контеста в Cabrillo (пусто = из правил; нужно для контеста Custom); [[contest.set.catTime]] (например, 6-HOURS) и [[contest.set.catOverlay]] (например, ROOKIE) — только если их предусматривают правила, иначе строка в Cabrillo опускается; [[contest.set.soapbox]] — заключительный свободный текст.",
  "t.1u6tqf56tmd": "[[sw.station]] · [[gen2.type2]]: касается только составных позывных «type 2» (необычный префикс или суффикс, например PJ4/K1ABC), как в JTDX. В FT8 и FT4 он не меняет ни одного сообщения: оставьте как есть (заводское значение «[[gen2.type2Full]]»; другие варианты — «[[gen2.type2Tx1]]» и «[[gen2.type2Tx5]]»).",
  "t.1u9dwcsgvma": "[[sw.contest.title]] · [[contest.category]], [[contest.set.mode]], [[contest.set.power]] и [[contest.set.bonus]]: [[contest.category]] — категория из правил (выпадающий список), [[contest.set.mode]] — режим, предлагаемый при старте среди допустимых, [[contest.set.power]] — мощность в ваттах (заводское значение 100; в Field Day это множитель мощности). [[contest.set.bonus]] появляется только в контестах, где в зачёте есть бонусы (Field Day): бонусные очки, отмеченные вручную.",
  "t.1uazifalbvr": "Отчёты об ошибках",
  "t.1ubtxqei8s7": "Панель внизу: «[[phone.cq]]» (вызов CQ), «[[ctl.enable_tx]]» (становится «[[phone.txOn]]») и «[[phone.stop]]» (становится «[[stop.button]]», пока Вы передаёте); два быстрых касания кнопки «стоп» также освобождают выбранную станцию. Они всегда остаются под рукой.",
  "t.1ubvur66aan": "используемый диапазон",
  "t.1uc4y6a61ns": "[[sat.ctl.title]] · [[sat.ctl.minEl]]: от 0 до 60 градусов (по умолчанию 0). Ниже этого угла места доплер и поворотное устройство ничего не делают. Увеличьте значение (например, до 5–10 градусов), если Вы не слышите спутник у горизонта среди домов и деревьев и не хотите зря двигать поворотное устройство.",
  "t.1uc64ndbftg": "имя в последнем записанном QSO",
  "t.1uc91txk2yr": "В [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] Вы решаете, где живёт каждый элемент Aurora: в главном окне, в отдельном окне (например, на втором экране) или скрыт. Отсюда всегда можно найти всё снова, даже закрытое окно или окно, оставшееся на экране, которого больше нет. Выбор применяется сразу.",
  "t.1uccgqhc8c0": "Диагностические оповещения остаются не более 10 минут с момента последнего подтверждения; если Вы их закрыли и проблема та же, они не возвращаются.",
  "t.1ucwfa6iolp": "[[sw.pg.radio]]: [[cat.share]], [[rd.title]]",
  "t.1ud3mfnrn3f": "«[[list.bottom.off]]» / «[[list.bottom.on]]»: где появляются новые сообщения. Со стрелкой ↑ самое свежее сверху, и список прокручивается вниз; с ↓ самое свежее — последняя строка. Каждый список помнит свой выбор.",
  "t.1ud7f9imig9": "[[ap.text]] · [[ap.fit]]: кнопка «[[ap.fitBtn]]» возвращает размер текста к автоматическому для ширины Вашего экрана. На узких экранах (например, 1280 × 800 и 1366 × 768) Aurora выбирает его сама, от 65% до 100%, чтобы ничего не выходило за края. Если Вы потом изменили его вручную через «[[ap.size]]» или клавишами Ctrl + и Ctrl −, нажмите «[[ap.fitBtn]]», чтобы вернуться к автоматическому.",
  "t.1ueeu1aj94b": "Агент — это небольшая программа, та же Aurora, запущенная тихо, без окна и без движка: он остаётся значком рядом с часами Windows, даже когда Aurora закрыта, чтобы открывать её щелчком и показывать Вам уведомления (новые версии, сообщения автора и некоторые другие). По умолчанию он включён: запускается вместе с Windows, а если его нет — запускается при открытии Aurora. На одного пользователя запускается только один.",
  "t.1ueewvblym0": "PTT не включается",
  "t.1ugqcge21v0": "В панели «Журнал», показывающей журнал Log4OM2, QSO доступны только для чтения: исправляйте их в Log4OM2.",
  "t.1uh3h1boiav": "Журнал на другом ПК: отсюда невозможно узнать, открыт ли он, поэтому QSO отправляются сразу, как всегда. Держите журнал открытым или используйте прямую загрузку (Wavelog, ClubLog, QRZ.com), у которой своя очередь.",
  "t.1uh8cjimotu": "Телефон не открывает страницу? Телефон и ПК должны быть в одной сети Wi-Fi (не «гостевой»), на телефоне должны быть выключены мобильные данные и VPN. Откройте ссылку в Chrome или Safari, а не внутри другого приложения. На Android, если Chrome не открывает страницу, попробуйте отключить «Always use secure connections» или используйте Firefox.",
  "t.1uhawnxgp5p": "[[digi.mi.threshold]]: открывает окно «[[digi.ms.title]]» (описано далее), где Вы задаёте порог шумоподавителя текущего режима.",
  "t.1ui7owwixdm": "«[[ens.g.adif]]»: «[[ens.k.EnableUDP2adifBroadcast]]», [[ens.k.UDP2Server]] и [[ens.k.UDP2ServerPort]]. Отправляет только QSO в виде текста ADIF, по одному в датаграмме.",
  "t.1ul3pkmah86": "Звук не воспроизводится: нужны три условия одновременно. 1) «[[alert.button]]» включён. 2) Включено оповещение этой функции (например, «[[not2.alertMy]]» или «[[not2.alsoSound]]» в таблице цветов). 3) В её меню выбран звук, а не «[[snd.none]]». Затем: Вы не передаёте при включённом «[[not2.muteTx]]», и Вы хотя бы раз щёлкнули в окне Aurora (этого требует браузер).",
  "t.1ulihrix3x": "CI-V — это «имя», по которому трансивер Icom узнаёт команды. В руководствах Icom оно записывается в ШЕСТНАДЦАТЕРИЧНОМ виде (с буквой h, например 94h или 0x94); Aurora в поле [[cat.civ]] в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] требует ДЕСЯТИЧНЫЙ вид (0x94 = 148). Путаница между двумя числами — самая частая ошибка: трансивер не отвечает.",
  "t.1uo3cnt8zrj": "открывает страницу SSTV для выбора отправляемой картинки",
  "t.1uoc8nlye95": "Статус приходит, а QSO нет: в Aurora включите «[[int.loggedAdif]]» у получателя или выберите в BBLogger «UDP 5».",
  "t.1up1u53isyf": "Ctrl+Z отменяет последнее изменение; Ctrl+Shift+Z или Ctrl+Y повторяют его. Не действуют, если Вы печатаете в поле.",
  "t.1up5fsrynhn": "[[toast.grp]] · [[toast.position]]: где они появляются, «[[toast.pos.top]]» (по умолчанию), «[[toast.pos.topRight]]» или «[[toast.pos.bottom]]». [[toast.size]]: «[[toast.sz.small]]», «[[toast.sz.normal]]» (по умолчанию) или «[[toast.sz.large]]».",
  "t.1upjl8lr9ne": "контест: позывной последней записанной QSO",
  "t.1upqxbvj83": "Рядом с выбором режима и частоты находится небольшая полоса состояния. Обычно она почти пуста: что-то показывает только при возникновении проблемы.",
  "t.1uqymfao55v": "«[[fox.callers]]» (слева): кто ответил на Ваш CQ. Поля: «[[fox.filter]]», «[[fox.sort]]» и «[[fox.sort2]]» (SNR, позывной, локатор, расстояние, возраст, Hz, внешнее значение), «[[fox.snrMin]]» и «[[fox.snrMax]]», «[[fox.onlyNew]]» (скрывает тех, кто уже есть в журнале на этом диапазоне), «[[fox.addBest]]» (ставит в очередь первых 5 из списка). Двойной щелчок по строке или «[[fox.add]]» помещает станцию в конец очереди; «[[fox.top]]» помещает её в начало (её обслужат следующей). Метка «[[fox.dupe]]» говорит, что она уже есть в журнале.",
  "t.1url27n4utt": "Текст слишком мелкий? Нажмите Ctrl + на любой странице или выберите «[[ap.size]]». Aurora на неправильном языке? Измените «[[gen.language]]» в первой строке этой страницы.",
  "t.1us8tiurido": "Контест: F1 запускает Auto CQ, F2 — обмен, F3 — R + обмен, F4 — завершение (см. «Контест: клавиатура и команды»). Окно «Занести QSO»: Enter заносит. Выпадающие меню и окна: Esc закрывает. Язык: стрелки, Enter, Esc, Home, End.",
  "t.1ut3rkw70gl": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] Вы решаете, что видите в списках сообщений: фильтры [[panel.all]] и [[rxw.title]], окно [[panel.cq]] и как рисуется каждая строка. Сверху вниз: флажки фильтров, затем [[cqp.title]], затем [[gen.screen]]. Фильтры влияют только на то, что Вы видите: скрытые сообщения остаются декодированными, и автоматизации их по-прежнему видят. Выбор действует сразу и запоминается при перезапуске, без [[sw.save]].",
  "t.1utqh1ljiik": "Порт трансивера выбирается в [[cat.port]] ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]); то же относится к [[cat.ptt.port]] и к [[rot.set.port]] ротора. Имя порта различается, а в Linux нужно разрешение.",
  "t.1uuh0fcd3s2": "Для Wavelog, ClubLog, QRZ.com, HRDLOG.NET и LoTW прямая отправка уже имеет собственную очередь: неотправленные QSO ждут и уходят, как только сервис отвечает (см. «Онлайн-сервисы журнала и поиск позывных»).",
  "t.1uv3fwp0m14": "«[[dxs.colors]]» · группы «Ячейки FT8», «Ячейки FT4» и «Ячейки DIG»: для каждого режима три выбора цвета — для ячеек «[[dxcc.cell.worked]]» (по умолчанию зелёный), «[[dxcc.cell.unconfirmed]]» (оранжевый) и «[[dxcc.cell.none]]» (пустые). Рядом с каждым цветом кнопка ↺ («[[dxs.factory]]») возвращает исходный цвет, то есть цвет темы. У каждого режима свои цвета, так что FT8 и FT4 можно различать. У ячейки всегда есть контур, даже если Вы выберете цвет, равный фону.",
  "t.1uwtnabcpz8": "[[digi.mi.autoCq]]: [[digi.mi.autoCqStart]] и [[digi.mi.autoCqStop]] включают и выключают автоматический вызов; [[digi.mi.autoCqText]] открывает макрос AutoCqText с текстом CQ; [[digi.mi.autoCqDelay]] задаёт секунды между одним вызовом и следующим (от 1 до 600), которые сохраняются.",
  "t.1ux97dxno81": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiScan]]. Два блока: свойства автоматического сканирования диапазона и 20 ячеек памяти, хранящих Ваши любимые настройки. Оба остаются на этом устройстве. Сканирование запускается и останавливается из меню [[digi.menu.options]] страницы PSK · RTTY · CW; «[[digi.mi.scanProps]]» в том же меню открывает эту страницу.",
  "t.1uxdk4bim11": "возврат на приём, когда весь текст отправлен",
  "t.1uyq3qrk0l3": "На страницах CW и RTTY «[[radar.title]]» прослушивает всю звуковую полосу и показывает справа от окон RX и TX надёжно прочитанные станции: одна строка на позывной, без дубликатов, у каждой свой цвет. Позывной появляется только после того, как он был прочитан несколько раз без сомнений, поэтому странных прочтений нет. В CW и RTTY он заменяет панель «[[digi.band.title]]», которая остаётся для PSK. Станции не копируются в Ваш DX Cluster: чтобы отправить настоящий спот, щёлкните правой кнопкой по станции › «[[radar.spot]]».",
  "t.1v11owa6bds": "в Aurora нет соответствующего события: макрос не запускается",
  "t.1v3jzvlxy79": "Что такое панель «Сигналы»?",
  "t.1v64424vgwy": "[[sstv.set.grpRx]] · [[sstv.set.autoReceive]] (по умолчанию выключено): при включённом флажке прослушивание SSTV начинается при запуске Aurora и остаётся включённым, даже когда Вы покидаете страницу SSTV; при выключенном Вы запускаете его со страницы.",
  "t.1v8d5pvbv0h": "[[gen2.fox]] · [[gen2.otpVerify]]: флажок, по умолчанию включён. В Hound, когда Fox присылает свой код (CALL.123456), Aurora спрашивает у сервиса, действителен ли он, и записывает ответ на странице «Станция» («verified» или «not valid»). В сервис уходят только позывной Fox, время и код; код 000000 (тесты) никогда не проверяется. Выключите, если не хотите никаких сетевых запросов.",
  "t.1v8iexpszal": "Подрежимы JT65: рядом с режимом выберите A (тоны на расстоянии 2,69 Hz, KB и 6 м), B (двойной шаг, EME на 2 м и 70 см) или C (учетверённый, EME от 23 см и выше); он должен совпадать с подрежимом корреспондента. В B и C Aurora ищет единственный сигнал, самый сильный в пределах F Tol от частоты Rx, измеряет его ширину и соответственно сглаживает спектры.",
  "t.1v8w9vban0e": "Если ключ отклонён, проверьте также часы ПК: Cat4OM получает только доказательство, вычисленное с учётом времени, но никогда не сам ключ.",
  "t.1vapycu94ze": "В строке [[ssbc.enter]] посередине заполните: [[ssbc.qsoNr]] (номер QSO), [[ssbc.call]], [[ssbc.serialSent]] (номер, который Вы передаёте) и [[ssbc.serialRcvd]] (номер, который Вы принимаете). [[ssbc.enterHint]]. Имя, QTH и локатор заполняются сами по данным поиска на QRZ.com или HamQTH, если он настроен в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]: текст, введённый вручную, никогда не перезаписывается.",
  "t.1varj1btb3z": "Aurora и Log4OM управляют одним и тем же радио одновременно через Cat4OM.",
  "t.1vb760rz85j": "[[fil.highlight]] · [[fil.hlCalls]] и [[fil.hlCountries]]: два текстовых поля со списками через запятую (VK*, ZL*; названия стран, как в столбце страны). Строки этих станций или стран становятся фиолетовыми с полосой. Они ничего не скрывают: они выделяют те, что Вы ищете.",
  "t.1vdn2dgjs4s": "Над водопадом находится панель «[[digi.band.title]]» (только в CW и PSK31/PSK63 и только если она включена): список всех сигналов звуковой полосы.",
  "t.1vfbyl054cy": "[[not2.grpWorked]] · [[not2.hide]]: CQ уже отработанных станций вообще не показываются (их обмены с другими остаются). По умолчанию выключено; блокируется, как и остальные, без подсветок «нового». [[not2.invert]]: для цветных типов окрашивает текст вместо фона строки (относится ко всем цветам на этой странице; по умолчанию выключено).",
  "t.1vhb0bky0gd": "Фильтр «[[cluster.filter.spotter]]» рядом с диапазоном и режимом: «[[cluster.filter.spotterMine]]» показывает только споты, отправленные станциями Вашего континента (то, что слышно там, где Вы находитесь); можно также отметить нужные континенты.",
  "t.1vj2dwripam": "Band activity: строка заголовка и фильтр",
  "t.1vkiacik8st": "Fox передаёт ниже 1000 Hz и отвечает сразу нескольким станциям в одном периоде, рядом расположенными сигналами.",
  "t.1vlaqw2ni2t": "«[[dxs.colors]]» · шесть групп «Метка NEW ONE», «NEW BAND», «NEW MODE», «NEW GRID», «GRID BAND» и «GRID MODE»: для каждой четыре цвета, «[[dxs.bg]]» и «[[dxs.ink]]» при «[[dxs.on]]» и при «[[dxs.off]]», с кнопкой ↺ для возврата исходного цвета. Метки: NEW ONE = страна, с которой ещё не работали; NEW BAND = страна, с которой уже работали, но не на этом диапазоне; NEW MODE = страна, с которой уже работали, но не этим режимом; NEW GRID, GRID BAND и GRID MODE — то же самое для локатора (4-символьный квадрат). Они принимают цвета «вкл», когда относятся к станции, в остальных случаях остаются «выкл».",
  "t.1vn10vzlzce": "QSO, потерянные, пока журнал закрыт: где это включить",
  "t.1vpu6tk7tdu": "Подождите, пока Вы не декодируете Fox, затем дважды щёлкните по одной из его строк: Aurora вызовет его с позывным и локатором.",
  "t.1vqq5ctcf3j": "Каждое QSO отправляется только один раз: сразу, если журнал открыт, или из очереди, но никогда дважды. Очередь сохраняется при закрытии Aurora (файл log-in-attesa.json в папке данных); QSO, стоящее в очереди дольше семи дней, отбрасывается.",
  "t.1vt9yrn7uqs": "Значок динамика и ползунок громкости: звуковые оповещения (см. «Язык, тема и громкость на панели»). Рядом луна, солнце или наполовину закрашенный круг: тема.",
  "t.1vu11y1lyw8": "[[fil.decode]] · [[dec.includeAveraging]]: флажок, по умолчанию выключен. В Q65, если одного периода недостаточно, пробует среднее периодов той же чётности на частоте приёма. Включите для EME и для сигналов ниже шума. Рядом с режимом есть кнопка «Avg».",
  "t.1vvcjb9w30": "Добавьте входящее UDP-подключение: тип ADIF_MESSAGE, порт 2237 (как в Aurora); включите его и нажмите «Save and apply».",
  "t.1vve1bfk5f4": "Захват обмена никогда не смотрит на строки «» …» переданного текста: при включённом эхо передачи наш собственный номер после позывного другой станции не попадает в принятый номер.",
  "t.1w00z7qhoby": "Интеграции: поля получателя",
  "t.1w4s17hd7m6": "[[not2.grpColors]] · [[not.restoreColors]]: возвращает цвета, флажки звука по типам, а также вид сообщений (уже отработано, маркеры, «[[not2.invert]]») такими, как в только что установленной Aurora. Осторожно: это также снова включает подсвеченное оповещение о новой DXCC и сбрасывает флажки звуковых оповещений к значениям по умолчанию. Звуки, выбранные на странице «[[sw.pg.alerts]]», и положение оповещения не удаляются.",
  "t.1w4so9pt156": "смещение трансвертера: задайте его в настройках радиостанции, команда показывает уведомление",
  "t.1w5ce84ewqj": "[[lay.settings]] · [[set.save]]: сохраняет расписание; оно также сохраняется само примерно через секунду и при выходе со страницы. Если появляется «[[sch.invalid]]», что-то выходит за допустимые пределы (час, минута, диапазон или более пяти строк), и расписание не сохранено.",
  "t.1w5kvmhd2tj": "Столбец [[freq.band]] и столбец [[freq.mode]] (два выпадающих списка): диапазон и режим, к которым относится строка. Допустимые режимы: FT8, FT4, JT65, JT9, Q65, MSK144, FST4, FST4W, WSPR. У одного и того же диапазона и режима может быть несколько строк (стандартная и альтернативные).",
  "t.1w6wyoixqln": "Скорость приёма: Aurora следует за ней сама в пределах от половины до удвоенной заданной и показывает её в WPM в строке состояния.",
  "t.1w70nnn6s8u": "«+ [[int.p.n1mm]]»: название N1MM XML, 127.0.0.1, порт 12060, включено только «[[int.n1mm]]». Для каждой QSO получает XML-сообщение «contactinfo» в том виде, в каком его отправляет N1MM Logger+: позывные, диапазон, частоты, режим, рапорты, локатор, имя, мощность, комментарий и идентификатор, постоянный для одной и той же QSO, с Aurora в качестве отправляющей программы. Для HRD Logbook и программ, имитирующих N1MM. Попробуйте с Вашей программой, прежде чем на неё полагаться: для всех она не проверялась. Можно также включить «[[int.resend]]» для QSO, проведённых при закрытом журнале.",
  "t.1w7om5wef33": "[[gen2.fox]] · [[gen2.otpUrl]]: текстовое поле, заводское значение https://www.9dx.cc. Это адрес сервиса, проверяющего коды Fox: он должен начинаться с http:// или https://, без пробелов, не более 200 символов. Остаётся серым, пока [[gen2.otpVerify]] выключен. Меняйте, только если сервис сменит адрес.",
  "t.1w9n1nx07vj": "Экран: пока ничего не пришло, он сообщает «[[sstv.rx.waiting]]» (или, если приём выключен, «[[sstv.rx.offHint]]»). Во время приёма яркая линия движется вниз до того места, до которого дошла передача. Вверху изображения появляется позывной, прочитанный из FSK ID, если станция передаёт его после изображения ([[sstv.rx.fskIdHint]]).",
  "t.1wazioxaytv": "[[sstv.log.name]], [[sstv.log.qth]], [[sstv.log.grid]] (до 8 символов) и [[sstv.log.note]]: они заполняются по результатам поиска, либо запишите их сами.",
  "t.1wbbmca6k3n": "[[gen.screen]] · [[gen.miles]]: флажок, по умолчанию выключен (расстояния в километрах). Если включён, расстояния показываются в милях.",
  "t.1wcasa1q6f0": "[[auto.b3]] · [[auto.perHour]] (числовое поле, от 0 до 120, по умолчанию 0): не более этого числа QSO за последний час; когда оно достигнуто, Aurora перестаёт отвечать, пока самое старое не выпадет из часа. 0 = без ограничения. В пробном режиме учитываются станции, которым она ответила бы.",
  "t.1wcbz1ao4rb": "Последовательность продолжается сама: рапорт, R-рапорт, RR73. QSO заносится в журнал, когда уходит Ваш RR73 (или Ваш 73), при условии, что Вы приняли их рапорт.",
  "t.1wdvph425mi": "В Logger32, Config: время видимости станций должно быть 30 секунд или больше. Для проверки снимите отметку «Block callsigns worked before», иначе уже отработанные станции не появляются.",
  "t.1we3mimq1t8": "Позывные всего диапазона появляются под шкалой, над трассой сигналов: два соседних чередуются по высоте; они исчезают через 75 секунд после последнего раза, когда их слышали. Отключаются пунктом «[[digi.band.wfCalls]]» в меню [[digi.menu.view]].",
  "t.1we6dmssbsh": "Макрос — это клавиша с текстом и, при необходимости, командами между < >. «Клавиша» — это одновременно кнопка на экране и клавиша на клавиатуре с тем же названием. Aurora поставляется с готовыми заводскими макросами.",
  "t.1wggkcdvzqm": "[[sstv.set.grpFolders]] · [[sstv.set.folder]]: куда сохраняются принятые и переданные изображения. Пусто (заводское): папка истории внутри папки Aurora, которую поле показывает серым. Изменить её можно только с ПК Aurora, а не с телефона; введите полный путь существующей папки.",
  "t.1wit9dx0me": "как <CATCMD>: принимает также байты, записанные \\0xNN",
  "t.1wkdh41n1we": "Щелчок по позывному или точке: Aurora вызывает эту станцию.",
  "t.1wl4m4ntrp6": "[[ctl.enable_tx]] (при включении становится «[[phone.txOn]]»): разрешает передачу или снимает разрешение, как на ПК. Серая, если передача не разрешена.",
  "t.1wmv0ry1dhb": "Тон: это «частота приёма (Hz)» радио в звуке (по умолчанию 1000 Hz; от 200 до 3500). Он перемещается щелчком по водопаду, вводом числа в строке состояния или с помощью «[[digi.mi.seekLeft]]» и «[[digi.mi.seekRight]]». При передаче используется тот же тон, если не включено [[digi.mi.lock]].",
  "t.1wq6ohp347g": "[[sw.digi.perMode]] · CW, «[[digi.cw.receiver]]»: «[[digi.cw.receiverPrecise]]» печатает каждую букву, когда уверен, примерно через 1,25 секунды после знака. «[[digi.cw.receiverFast]]» (заводской) показывает буквы сразу светло-серым курсивом (примерно через полсекунды после знака), затем точный приёмник подтверждает или исправляет их: итоговый текст одинаков, меняется только то, как скоро Вы его видите. Применяется и к дополнительным окнам RX; требует немного больше вычислений.",
  "t.1wre4jdmr94": "Команда макроса <EXEC:...> ничего не делает: Aurora не запускает внешние программы и при запуске удаляет её из файлов макросов (предварительно сохранив копию). Резервное копирование, которое делали старые файлы .bat, выполняет сама Aurora: по одному в день в copie-automatiche, в папке данных, с настройками, журналом, макросами и соревнованиями; хранятся последние 28.",
  "t.1wrlq0mhxqj": "Официальное руководство Logger32 по FT8 датировано 2018 годом (версия 3.50): используйте свежую версию Logger32 4.x, так как меню могли измениться.",
  "t.1wssal1jmc9": "В CW: «[[digi.cw.bandwidth]]» (по умолчанию 150 Hz), «[[digi.cw.som]]» (для неровной ручной манипуляции; по умолчанию выключено), поле [[digi.band.mi]], выпадающий список «[[digi.band.validation]]» ([[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]], [[digi.band.valMaximum]]) и ползунок порога шумоподавителя (S/N от -30 до +20 dB, по умолчанию -15).",
  "t.1wx484ag7n4": "Дополнительные окна RX (до 4): каждое декодирует другую станцию в диапазоне рядом с главным приёмом. Они небольшие, перемещаются перетаскиванием за заголовок и закрываются крестиком; на водопаде пронумерованный маркер показывает, где они слушают, и его можно перетащить, чтобы перевести их на другую станцию. Двойной щелчок по слову: позывной переходит в QSO. Каждый приём сам начинает новую строку после паузы, так что каждый вызов и ответ находятся в отдельной строке.",
  "t.1wxxjvcxhp7": "выделенное слово становится отправляемым рапортом",
  "t.1wzq934f1w0": "Столбцы: «[[digi.band.colFreq]]» (относительно радио), WPM (только CW: скорость), S/N в dB, «[[digi.band.colCall]]» и «[[digi.band.colText]]». В столбце позывных: флаг, позывной, метка CQ или DE; курсивом и бледнее, пока позывной не подтверждён («[[digi.band.notVerified]]»: услышан только один раз или с неуверенными символами), обычным шрифтом, когда он подтверждён («[[digi.band.verified]]»). Если сигналов нет, в списке написано «[[digi.band.empty]]» (или «[[digi.band.emptyPsk]]»).",
  "t.1x130kzrk9g": "[[toast.test]] сразу показывает их Вам.",
  "t.1x2ru976tjd": "Панель DX Cluster пуста: проверьте, что включено «[[cluster.enabled]]», что у хотя бы одного сервера включено «[[cluster.server.on]]» и горит зелёный индикатор, что позывной не отсутствует («[[cluster.callMissing]]»), и прочитайте причину в «[[cluster.state]]». Если сервер красный, попробуйте другой из списка «[[cluster.add.catalog]]».",
  "t.1x3s6suspr1": "Как пользоваться Aurora с телефона или планшета?",
  "t.1x5cc5hr1jz": "«[[contest.adv]]» (каждые 15 секунд по декодированиям): для каждого диапазона из правил — станции, услышанные за последние 15 минут, новые множители, которые слышны, и оценочный темп. Сообщает «Оставайтесь на диапазоне · режиме» или «Перейдите на диапазон · режим» с причиной, и щелчок переводит радио на рекомендованный диапазон и режим; «[[contest.adv.ignore]]» отклоняет совет. Также показывает, сколько смен диапазона Вы сделали из максимально разрешённых.",
  "t.1x6t0m4q83y": "Основная кнопка зависит от уведомления: «Update now» (обновление), «Open» или «OK» (сообщения автора, в зависимости от наличия ссылки), «Open Aurora» (прохождение, DX-экспедиция, сводка). Закрытие карточки не закрывает агента.",
  "t.1x87t95dm0t": "[[digi.spot.freq]]: реальная частота сигнала в kHz, уже рассчитанная (частота радио плюс нота приёма); при необходимости исправьте её.",
  "t.1x9kz6mt197": "[[bar.decodes]]: сколько декодирований дал последний период. Рядом полоса показывает, где Вы находитесь в периоде (во время передачи она краснеет), и счётчик «секунда/длительность» (например, 7/15). На страницах PSK·RTTY·SSTV и спутников этой части нет.",
  "t.1xci23m1uk8": "Выпадающий список «[[digi.band.validation]]» определяет, насколько строго проверять позывные: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] или [[digi.band.valMaximum]]. Чем строже проверка, тем больше раз нужно услышать позывной необычной формы, чтобы он засчитался. Значок «?» объясняет правила.",
  "t.1xdxzdn8xta": "обмен, принятый в последнем записанном QSO",
  "t.1xh2rl98mtg": "[[gen.screen]] · [[set.reset]]: кнопка; возвращает ВСЕ настройки отображения Aurora к заводским значениям, а не только этого блока (в том числе, например, «[[list.bottom]]» и «[[rxw.exclusive]]»). У фильтров и [[cqp.title]] есть свои [[set.reset]].",
  "t.1xiq6r01gkw": "При включённом [[digi.mi.hairlines]] Вы видите также две тонкие линии в точках приёма и передачи.",
  "t.1xkwffolvaa": "Справа на панели две вещи появляются только при необходимости: значок новой версии (см. «Уведомление об обновлении на панели») и кнопка ⤓, возвращающая все отдельные окна в главное окно (см. «Отдельные окна и раскладка»).",
  "t.1xl4lfazo0t": "Если частоты радио и Aurora различаются, QSO записываются на неверном диапазоне: проверяйте их при смене диапазона.",
  "t.1xmyad4ojfd": "«[[list.clear]]»: очищает только этот список; сообщения, пришедшие позже, появляются снова. Другой список (окно RX) не меняется.",
  "t.1xmynhsnj5": "Контекстное меню в текстовых полях",
  "t.1xnqm9v3kam": "Когда всё на месте, перезапустите Aurora: проверка файлов выполняется при запуске, и полоса исчезнет. «[[files.missing.dismiss]]» скрывает её только для этого списка файлов: если пропадёт другой файл, она вернётся.",
  "t.1xo8gnk8pe": "Три механизма, все по умолчанию включены и все отключаются в [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] › [[rep.title]]: отчёт после сбоя («[[rep.ask]]»), автоматические отчёты («[[rep.auto]]») и статистика использования («[[rep.active]]»). Позывные, локаторы, сообщения, IP-адреса, адреса электронной почты, пароли и имя Вашего пользователя удаляются перед отправкой; минидампы не отправляются никогда.",
  "t.1xorohm8ie0": "сдвиг RTTY в Гц",
  "t.1xoxysn097e": "Передаёт, но мощность нулевая",
  "t.1xqgmrpsbzu": "Уровни Rx и TX Lvl",
  "t.1xrh8431s6z": "Включите [[ctl.hound]]: проверка стартует сама, когда приходит код ([[gen2.otpVerify]] включено по умолчанию).",
  "t.1xrpgghr2qj": "«[[wft.flatten]]» убирает кривую фонового шума (полезно, если фильтр радио наклоняет фон). «[[wft.stamp]]» записывает на водопаде время UTC и диапазон в начале каждого периода.",
  "t.1xs35cohobi": "[[toast.position]]: [[toast.pos.top]], [[toast.pos.topRight]] или [[toast.pos.bottom]]. [[toast.size]]: [[toast.sz.small]], [[toast.sz.normal]] или [[toast.sz.large]].",
  "t.1xukskylzn2": "«[[agent.kind.daily]]»: сводка за предыдущий день («Yesterday: N QSOs» и число разных стран), прочитанная из журнала Aurora, после 8 утра. По умолчанию «Off».",
  "t.1xuxwr6pbzu": "С телефоном в той же домашней сети: [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]], чтобы выполнить сопряжение, затем откроется удалённый вид.",
  "t.1xybilmpeta": "Панель «UDP» не становится синей: откройте UDP BandMap (Ctrl+J) и проверьте порт.",
  "t.1xyqn9z00s2": "На вкладке Hamlib отметьте «Connect to active HAMLIB instance» (127.0.0.1, 4532) и «VFO MODE», чтобы видеть оба VFO.",
  "t.1y05phwogo8": "SSTV: вкладка «[[sstv.view.rx]]»",
  "t.1y0qptypi4m": "Страница [[nav.dxmap]] — это карта мира со станциями в эфире, Вашими квадратами и линиями. Над картой находится панель со всеми командами; у каждого пункта есть подсказка. Та же карта находится на вкладке «[[log.tab.map]]» панели «Журнал», с одной строкой команд (см. «Карта в панели «Журнал»»).",
  "t.1y0xe9drskz": "Панель перечисляет станции, вызывающие CQ, и новые для Вас; [[panel.all]] вместо этого показывает всё.",
  "t.1y2vsauswvw": "[[wfs.bars]] · [[wft.stamp]] (по умолчанию включено): пишет на водопаде время UTC и диапазон в начале каждого периода. [[wfs.freqOn]] (выключено): при наведении указателя на водопад показывает звуковую частоту этой точки в Гц.",
  "t.1y4xew5rsjv": "В нижней строке, рядом с «WPM» передачи, маленькие кнопки − и + меняют скорость CW на 1 WPM (на 5 с Shift) в пределах минимума и максимума настроек режима; значение сразу сохраняется и, если выходом CW служит WinKeyer, передаётся и ему.",
  "t.1y50gr2vo54": "Уведомление об обновлении на панели",
  "t.1y58codxhjv": "Звуки",
  "t.1y6xb0ap5kl": "Путь: [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (блок «[[rep.title]]»). Aurora может анонимно отправлять ошибки тем, кто её разрабатывает, чтобы их исправляли: без позывного, локатора, сообщений, IP-адресов, адресов электронной почты и паролей. Флажки по умолчанию включены, и их можно выключить в любой момент. Менять их можно только с ПК, на котором работает Aurora (иначе Вы видите «[[rep.onlyPc]]»), и они сохраняются сразу.",
  "t.1y884omhn4p": "Кнопка отсоединения открывает страницу в отдельном окне, чтобы перенести её на второй экран.",
  "t.1y8dxnpf6a": "Подключение радио: контрольный список",
  "t.1y8wmxsu4br": "Уведомления агента появляются в «карточке»: небольшом окне без рамки в правом нижнем углу экрана, над панелью задач, всегда поверх остальных, но не отнимающем фокус у того, что Вы делаете.",
  "t.1y9ut713uut": "[[snd.title]] · таблица остальных оповещений (столбцы «[[snd.col.event]]», «[[snd.pick]]», «[[snd.col.state]]»): по одной строке для «[[snd.ev.alert_my_call]]», «[[snd.ev.alert_dx_call]]», «[[snd.ev.first_message]]», «[[snd.ev.wanted]]» (станции из списка желаемых, всегда активно), «[[snd.ev.new_dx_popup]]» и «[[snd.ev.qso_logged]]» (всегда активно). В каждой строке Вы выбираете звук и читаете состояние: «[[snd.state.ok]]» (будет воспроизводиться), «[[snd.state.none]]» (звук не задан) или «[[snd.state.off]]» (звук задан, но оповещение выше выключено).",
  "t.1ybm8c81c31": "[[not2.grpWorked]] · [[not2.potential]]: окрашивает новинки и в сообщениях между другими станциями, а не только в CQ (параметр движка, по умолчанию выключено). Включите, если хотите сразу видеть, кто вызывает кого-то нового.",
  "t.1ybodi5214s": "Подключение радио (CAT)",
  "t.1yiftorqf9n": "Редактирование макроса",
  "t.1yjtxoiq14c": "Ползунок «Rx» задаёт громкость записи в Windows и пишет рядом её процент. «[[rxl.auto]]» задаёт её сам: он сразу понижает уровень, если сигнал насыщается, и медленно повышает, если сигнал остаётся слабым; он приостанавливается во время передачи и выключается, если Вы двигаете ползунок.",
  "t.1yla87l81du": "передаёт текст в CW через WinKeyer",
  "t.1yncitjzmj8": "Печатайте в окне передачи и отправляйте по Ctrl+Enter (весь текст уходит в эфир, затем Вы возвращаетесь на приём) или откройте передачу кнопкой RX/TX в строке состояния либо клавишей Pause: передача остаётся включённой, и текст уходит по мере набора (уже переданные символы становятся красными). Чтобы остановить: Esc, либо снова RX/TX или Pause (см. «Окна приёма и передачи» и «RX/TX, Pause, Esc, двойной Esc и автоматический CQ»). Переданный текст появляется и в окне приёма, только если в меню [[digi.menu.view]] включено «[[digi.mi.echoRx]]» (по умолчанию выключено).",
  "t.1ynjqqvjiph": "Локатор используется для расстояний, карты и станций, которые вас слышат.",
  "t.1ynn900fe9i": "Настройка водопада",
  "t.1yosswbtubd": "В PSK, RTTY и CW сканирование переходит от одной станции к другой, а 20 ячеек памяти хранят Ваши любимые настройки. Они задаются в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiScan]].",
  "t.1yqbp3rksei": "[[wfs.res]] · [[wfs.bpp]] (от 1 до 100, по умолчанию 4; 5 с быстрым стилем): сколько каналов спектра суммируется в одном пикселе. Меньше каналов = больше деталей и больше шума; больше каналов = более плавный водопад, но более широкие сигналы. [[wfs.start]] (от 0 до 4900 Гц, по умолчанию 0): звуковая частота левого края; если её повысить, нижняя часть обрезается, а остальное увеличивается.",
  "t.1yqhwb7hea9": "[[acc.pair]] · проверка сети: под QR-кодом список отметок показывает состояние Wi-Fi, брандмауэра и адреса. Это объясняется в разделе «Проверка сети при связывании».",
  "t.1yrzckfpfeg": "Контесты",
  "t.1yswkpjltnt": "когда слово из окна приёма попадает в поле журнала (двойной щелчок или контекстное меню)",
  "t.1ytpyx23xqm": "[[lay.lists]] · [[fil.calls]]: текстовое поле, позывные для скрытия через запятую; звёздочка соответствует всему, что так начинается (JA* = все японские). Для станций, которые вызывают всё время и Вам не интересны.",
  "t.1yvqhlmtani": "«[[int.multicast]]»: если включено, адрес — это группа multicast, и все программы, подписанные на группу, получают данные одновременно (например, GridTracker и QLog на одном порту). Если выключено, поток идёт одной программе (unicast). При включённом поле появляются «[[int.ttl]]» и «[[int.iface]]».",
  "t.1ywexuxzvj0": "[[rep.title]] · [[rep.ask]]: флажок, по умолчанию включён. Если Aurora закрылась из-за ошибки, при следующем запуске она спрашивает, хотите ли Вы отправить отчёт (см. «Отчёты об ошибках: что отправляется и как отключить»). Выключите, если Вы не хотите, чтобы Вас когда-либо прерывали.",
  "t.1yx1p1ga9wn": "Журнал сообщает «port already in use»: порт удерживает другая программа (JTDX, GridTracker, JTAlert). Закройте её или используйте другой порт либо multicast.",
  "t.1yyfgwlr3ta": "Если окно дат не задано или истекло, появляется предупреждение: [[ssbc.windowOff]] Нажмите «[[ssbc.windowSet]]» и задайте даты.",
  "t.1z09c4ovwts": "Строка брандмауэра: если сеть задана как «Общедоступная» («[[net.public]]») или брандмауэр Windows блокирует телефон («[[net.blocked]]»), появляется красная строка с кнопкой «[[net.allow]]» (затем «[[net.allowing]]», пока Вы подтверждаете в окне Windows): Aurora снимает блокировку и открывает порт во всех сетях. Если Вы отмените подтверждение Windows, Вы видите «[[net.allowFailed]]». Когда всё в порядке, строка сообщает «[[net.allowed]]».",
  "t.1z2t3zlbae3": "[[lay.lists]] · [[fil.showOnly]]: текстовое поле; если Вы впишете позывные или префиксы через запятую (JA*), показываются только сообщения станций, передающих с ними. Пусто = все. Полезно, чтобы следить за экспедицией или группой друзей.",
  "t.1z4nlm6cwky": "Правила: QSO передаётся только один раз и никогда не той станции, с которой оно проведено; не более 10 QTC всего с каждой станцией (в RTTY отправленные плюс принятые), даже за несколько связей. Окно проверяет это само и сообщает, почему это невозможно (тот же континент, неверное направление, уже обменяно 10).",
  "t.1z5pky297pd": "экранное оповещение со звуком",
  "t.1z61kch23ks": "Работа в роли Fox (страница Fox)",
  "t.1z6wlr84lqy": "Переключатель «[[contest.toggleOff]]» / «[[contest.toggleOn]]» включает выбранный контест (Aurora готовит сообщения, обмен, выключает Fox и Hound, включает AutoSeq и Hold Tx Freq) или выключает его и восстанавливает прежние настройки.",
  "t.1z730hc0uot": "[[toast.grp]] · [[toast.secs.ok]], [[toast.secs.info]], [[toast.secs.error]]: как долго каждый тип остаётся видимым, прежде чем исчезнет сам, от 1 до 30 секунд (по умолчанию 4,5, 5,5 и 8). Сделайте дольше, если не успеваете прочитать, короче — если сообщения мешают.",
  "t.1z7e2f06cq7": "Двойные QSO: QSO приходит двумя путями. В [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] основной и дополнительный UDP-серверы Aurora тоже работают на 127.0.0.1:2237: отключите ненужные или не используйте одновременно способ с ADIF-файлом.",
  "t.1z8nn0zv4m3": "[[auto.b5]] · [[auto.bandHop]] и [[auto.bandHopWhere]]: флажок включает Band Hopping движка (в заданное время трансивер переходит с одного диапазона списка на следующий, и автоматизация продолжает работу на новом диапазоне); сохраняется кнопкой [[sw.save]]. Кнопка [[auto.bandHopWhere]] открывает страницу [[tab.sequence]], где Вы записываете список диапазонов ([[gen2.bandHopList]]). Без собственного движка Aurora вместо флажка появляется «[[auto.bandHopNa]]».",
  "t.1z947gcpyrw": "[[wfs.bars]] · кнопки «[[wfs.wsjtx]]» и «[[wfs.jtdx]]»: одним щелчком устанавливают все параметры водопада (разрешение, палитру, уровни, спектр) в один из двух готовых стилей; кнопка остаётся подсвеченной, пока параметры совпадают со стилем. «[[wfs.wsjtx]]» — начальный стиль (4 канала на пиксель, Flatten включён); «[[wfs.jtdx]]» — быстрый водопад (15 строк в секунду, 5 каналов, Flatten выключен). [[set.reset]]: возвращает все параметры этой страницы к значениям по умолчанию.",
  "t.1z98j8powch": "Открывается из верхней панели «[[nav.textModes]]» (затем «[[nav.sstv]]» в меню [[digi.menu.mode]] страницы текстовых режимов). Приём включается сам при входе и остаётся включённым, пока Вы не нажмёте «[[sstv.rx.stop]]», даже пока Вы готовите изображение; он выключается при выходе со страницы, если только в Настройках SSTV не задано [[sstv.set.autoReceive]].",
  "t.1zd9uzuy2fr": "Передача: пишите в поле. Кнопкой «RX/TX» в строке состояния или клавишей Pause передача открывается и остаётся включённой, а написанное уходит по мере написания: символы, уже отправленные в эфир, краснеют с небольшой чертой в достигнутой точке; находящиеся в очереди подчёркнуты. Ещё не отправленную часть можно исправить или удалить.",
  "t.1zgpfghippf": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]] Вы решаете, как проходит QSO: когда Aurora сама переходит к нужному сообщению, кому она отвечает, сколько раз повторяет и когда останавливается, а также тайминг передачи. Параметры показываются с собственным движком Aurora (используемым по умолчанию); они сохраняются кнопкой [[sw.save]] и вступают в силу сразу, без перезапуска.",
  "t.1zhaf8g68o8": "Если что-то идёт не так, карточка сообщает причину и показывает «Retry»: «Aurora is transmitting: retry when the transmission ends» (обновление ждёт окончания передачи), «The update starts only from the PC where Aurora runs», «This Aurora cannot install updates by itself», «Aurora is not responding».",
  "t.1zhh1y7uwjj": "[[nav.dxmap]]: карта мира со станциями в эфире (см. «Карта DX: панель команд и шестерёнка»). [[nav.propagation]]: солнце, диапазоны и те, кто принял ваш сигнал (см. «Прохождение: все панели»). У поворотного устройства в панели больше нет кнопки: его страница открывается из «Настроек» (см. «Поворотное устройство: страница и карточка»).",
  "t.1zhpy3ofbvs": "Каждый получатель — это блок с названием (или адресом:портом) в заголовке и кнопкой «[[int.remove]]», которая удаляет строку из списка.",
  "t.1zidjqu82en": "После «Too many attempts» подождите показанное число секунд: блокировка защищает от тех, кто подбирает случайные коды.",
  "t.1zim2twmzeg": "[[auto.b5]]: через заданное число минут без CQ, достойного ответа, Aurora может сама вызвать CQ (только в боевом режиме, при свободной передаче) или включить Band Hopping для смены диапазона.",
  "t.1zjl1df211w": "[[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.orbits]]. Откуда Aurora скачивает данные об орбитах (TLE) и как часто их обновляет: без актуальных данных рассчитанные пролёты неверны. Каждое изменение сохраняется сразу. Нужна сеть.",
  "t.1zjnmwz59wn": "«[[ens.g.hrdlog]]» · «[[ens.k.HrdlogSend]]» (по умолчанию выключено): отправляет каждую QSO в Ваш журнал на HRDLOG.NET с той же очередью и повторами, что и остальные. «[[ens.k.HrdlogCall]]»: позывной журнала (пусто = Ваш). «[[ens.k.HrdlogCode]]»: код выгрузки, который HRDLOG.NET показывает в Вашем профиле. Здесь «[[ens.test]]» лишь проверяет наличие данных: код проверяется при первой QSO.",
  "t.1zl6bnco93c": "«[[sstv.rx.sync]]»: качество синхронизации в процентах (полоса меняет цвет выше 80% и выше 40%). «[[sstv.rx.level]]»: уровень звука в dB с полосой. «[[sstv.rx.offset]]»: на сколько Hz синхро отстоит от правильной точки.",
  "t.1zm3ns05ngn": "В другой программе выберите сетевой Hamlib (NET rigctl), адрес 127.0.0.1, порт 4532.",
  "t.1zmwgx1n59w": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], блоки под подключением: рекомендуемые настройки, состояние и проверка, PTT, сплит, режим и чтение. В порядке появления.",
  "t.1zngm8tbqza": "Когда выходит новая версия Aurora, справа на верхней панели появляется небольшой значок (стрелка вниз с точкой). На ПК Aurora скачивает версию в фоне и проверяет её подпись.",
  "t.1zodsfb8ol": "В программе Aurora для Windows правая кнопка не открывает меню браузера: вне текстовых полей ничего не происходит; внутри поля открывается небольшое меню только с полезными пунктами.",
  "t.1zpb1dogm0m": "переносит приём на эту звуковую частоту водопада",
  "t.1zqf61w3j79": "[[sw.contest.title]] · [[contest.set.save]]: кнопка; сохраняет форму и показывает «[[contest.set.saved]]». Форма не сохраняется сама, а [[sw.save]] внизу окна её не сохраняет: не забудьте нажать эту кнопку.",
  "t.1zqfiu2yndq": "Если сигнал не захватывается при щелчке, выключите [[digi.mi.snap]] и переместите курсор вручную; затем включите AFC, которая следует за небольшим уходом частоты.",
  "t.1zrv2e8arm6": "У JT65 есть также «[[dec.short.JT65AP]]» (априорное декодирование), «[[dec.short.IncludeCorrelation]]» (глубокий поиск) и кнопка ⟲ ([[mode.jt65clearAvg]]). У MSK144 есть выпадающий список [[mode.mskperiod]] (5, 10, 15 или 30 секунд) и «[[mode.mskSh]]» (короткие сообщения). У WSPR и FST4W есть [[mode.wsprPower]], «[[mode.wsprPct]]» (доля периодов, в которых маяк передаёт) и «[[mode.wsprType1]]». Заводские значения: мощность 37 dBm (5 W), Tx Pct 20%.",
  "t.1zt7h0shgkk": "«[[exp.edit.save]]»: сохраняет исправления (если ничего не менялось, просто закрывает). «[[exp.edit.cancel]]», Esc или щелчок вне окна: закрывают без изменений. «[[exp.edit.delete]]»: удаляет QSO из журнала Aurora и из её ADIF-файла после подтверждения; восстановить из программы нельзя.",
  "t.1zu9wsz6z6m": "Шапка · сегодняшние числа (сутки UTC): [[auto.today.replies]] (в пробном режиме появляется [[auto.today.would]] — те, что она дала бы), [[auto.today.qsos]] (QSO, занесённые в журнал со станциями, вызванными автоматизацией или ответившими на её CQ) и [[auto.today.last]] (время и позывной, или CQ).",
  "t.1zumgwqig6b": "Руководство открывается из [[nav.wiki]], внизу дерева «Настроек» (зелёный пункт). Слева оглавление глав, справа текст.",
  "t.1zumwm5gl60": "В радио: звук данных по USB (например, DATA MOD USB на Icom, DATA VOX OFF на Kenwood).",
  "t.1zxrc8yhpit": "PSK Reporter (блок только для приёма) · «[[onl.psk]]» (по умолчанию включено): Aurora в реальном времени слушает mqtt.pskreporter.info на предмет новых приёмов Вашего позывного и каждые 5 минут запрашивает у pskreporter.info приёмы за последние 3 часа и показывает их в [[nav.propagation]] (карта и список): кто Вас принял и где. Оба сайта видят Ваш позывной и Ваш IP-адрес. Выключите, если не хотите, чтобы Aurora обращалась к PSK Reporter для чтения.",
  "t.1zyec6zb70w": "«[[sstv.rx.mode]]» (справа): распознанный режим. Ниже — как он был выбран: «[[sstv.rx.byVis]]», «[[sstv.rx.bySync]]» (без VIS, если в Настройках включено «[[sstv.set.autoSync]]») или «[[sstv.rx.byHand]]» (с «[[sstv.rx.force]]»).",
  "t.1zyp4qx3qdi": "не поддерживается из соображений безопасности: Aurora не запускает внешние программы",
  "t.2008xw2r7nc": "Первая вкладка правого столбца показывает споты DX Cluster Aurora; щелчок по споту переводит радио на эту станцию. Выбранная вкладка запоминается.",
  "t.2012n4alzvz": "[[digi.menu.configure]] › [[digi.mi.modeSettings]]: открывает Настройки на странице «[[sw.pg.digiRxTx]]» текстовых режимов.",
  "t.201f5suqu8w": "печатает текст окна RX",
  "t.201laoj2kku": "[[sw.contest.title]] · [[contest.set.freqs]] и [[contest.set.save]]: кнопки частот (один щелчок переводит трансивер на предложенную частоту, нужен CAT) появляются, если правила их перечисляют; [[contest.set.save]] сохраняет форму и показывает «[[contest.set.saved]]». Форма не сохраняется сама, а [[sw.save]] окна её не сохраняет.",
  "t.201ro5aqnk8": "как <RX> и, после возврата на приём, очищает окно передачи",
  "t.203aamp1587": "[[about.news]]: последние три новости на языке Aurora и ссылка «[[about.allNews]]», открывающая страницу «Что нового» в главном окне Aurora.",
  "t.203wdkps573": "Звук с SDR и сетевыми программами: при CAT по TCI (раздел [[sw.pg.sdr]]) два списка показывают «TCI (dalla radio)» как вход и «TCI (alla radio)» как выход, без виртуальных аудиокабелей; с Cat4OM появляется «Cat4OM (audio in rete)». Кнопка «[[sdr.useAll]]» на странице SDR выбирает их за Вас. Блок [[lay.notes]] внизу повторяет общие пояснения.",
  "t.2051s3gm1ss": "Сообщения автора: поздравления и важные уведомления, написанные тем, кто разрабатывает Aurora, по одному, каждое только один раз; если есть ссылка, кнопка «Open» открывает её в браузере. Они появляются и в режиме «Не беспокоить» и сегодня не следуют строке «[[agent.kind.news]]» в Настройках.",
  "t.205m6hveyjn": "[[ctl.split]] включает сплит, [[ctl.clear_dx]] очищает станцию для вызова.",
  "t.206ei34l6qb": "[[nav.news]]",
  "t.207qkeyjdqt": "Каждая ячейка памяти хранит режим, частоты, RTTY, AFC, Snap и шумоподавитель. Она сохраняется из меню страницы [[digi.menu.options]] › [[digi.mi.memory]] › [[digi.mi.memWrite]]; в «[[sw.mem.title]]» Вы видите её, вызываете кнопкой «[[sw.mem.load]]» или очищаете кнопкой «[[sw.mem.clear]]».",
  "t.20965jg1461": "RX / TX: показывает, принимаете Вы или передаёте; щелчок открывает передачу (в покое) или сразу останавливает её (пока Вы передаёте). Мигает, если включено [[digi.mi.flashTx]].",
  "t.209rth7eacg": "QTH другой станции",
  "t.209z0b0ni5y": "«[[rep.show]]» и «[[rep.showAuto]]» показывают точно тот текст, который был бы отправлен. Отчёты уходят в сервис разработчика Aurora (на Cloudflare) и удаляются через 90 дней; идентификатор — случайное число, которое можно создать заново кнопкой «[[rep.newId]]».",
  "t.20a5tqkgjzi": "[[hl.title]]",
  "t.20ae4rzhupk": "Макросы соревнования занимают место макросов режима на тех же клавишах; при [[ctest.f.merge]] остальные макросы режима остаются. При [[ctest.f.grabNumber]] и [[ctest.f.grabState]] номер или домен, принятые после позывного, сами попадают в принятый номер, если он пуст.",
  "t.20bkxhtwl5x": "Время от времени внизу справа приходит карточка со звуком, написанная разработчиками Aurora (приветствия, служебные уведомления, важные обновления). Она приходит только один раз на сообщение, на языке Aurora, даже при закрытой Aurora через агента в области уведомлений; кнопка «[[agent.msg.open]]» открывает ссылку из сообщения, если она есть. Отключить её нельзя.",
  "t.20bry53rkhx": "Язык, тема и громкость на панели",
  "t.20e78cp0jos": "[[sw.fam.modes]]",
  "t.20ehd3jbsbl": "[[tab.clock]]",
  "t.20esz68pfos": "принятый RST",
  "t.20frlozdny3": "Aurora сама проверяет и предлагает новую версию: «[[upd.poster.install]]» устанавливает и перезапускает, «[[upd.later]]» откладывает. Параметры находятся в [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].",
  "t.20fxbx3p8f7": "Прослушивание начинается само: когда приходят стартовый тон и фазировка, карта рисуется строка за строкой.",
  "t.20i9uzmikd": "Пункт внизу дерева «Настроек» (золотым, после [[nav.wiki]]): последние изменения Aurora, по одной строке на версию, с типом (новое, изменено, исправлено), заголовком, а также датой и временем выхода по вашему местному времени. Щелчок по строке открывает её текст; три фильтра ([[news.kind.new]], [[news.kind.changed]], [[news.kind.fixed]]) показывают или скрывают типы (см. «Страница новостей»).",
  "t.20j1ndldluq": "[[lay.status]] · [[upd.install]]: выделенная кнопка, которая появляется только когда есть новая версия и Aurora может её установить (то есть на компьютере, где работает Aurora, а не с телефона). Загружает и проверяет подпись, затем закрывает Aurora и открывает её обновлённой, с индикатором выполнения ниже ([[upd.progress.title]]). Если не удалось, появляется сообщение, и Вы можете скачать установщик вручную по ссылке «[[upd.open]]».",
  "t.20jd6etq7vv": "[[not2.grpAlerts]] · [[not2.soundMy]]: флажок, который на каждое сообщение с Вашим позывным воспроизводит звук, выбранный для «[[kind.my_call]]» на странице «[[sw.tab.colors]]». По умолчанию включено; отличается от оповещения выше, которое срабатывает, когда Вас кто-то вызывает.",
  "t.20jmfs0uzs": "Когда ПК уже скачал версию, вместо значка появляется небольшая оранжевая полоса с ходом процесса («Проверка…», «Установка…»); по окончании загрузки она показывает «[[upd.strip.ready]]» с кнопкой «[[upd.strip.install]]» (один щелчок — и установка). Если загрузка не удалась, появляется «[[upd.strip.failed]]» с кнопкой «[[upd.strip.retry]]».",
  "t.20kddj4t9q": "Переходит на передачу, но нет мощности: проблема в звуке (выход в [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]], звук данных по USB, уровень).",
  "t.20lo1gtlb1z": "запускает или останавливает автоматический CQ; если указан текст, он становится вызовом",
  "t.20myrhzl46s": "[[not2.grpTable]] · [[not2.perBand]] и [[not2.perMode]] (два флажка после «[[not2.colHighlight]]»): они определяют, что считается уже сделанным. «[[not2.perBand]]»: это новинка, даже если Вы работали на другом диапазоне; «[[not2.perMode]]»: это новинка, даже если Вы работали другим режимом (FT8, FT4…). Они остаются выключенными и заблокированными, если флажок «[[not2.colHighlight]]» в строке снят. По умолчанию: страна и позывной по диапазону и по режиму; квадрат только по диапазону; зоны и префикс выключены.",
  "t.20n6onq38at": "Поля: [[exp.f.call]] (от 3 до 13 букв, цифр или «/»), [[exp.f.date]] и [[exp.f.time]] (в UTC), [[exp.f.band]] (выпадающий список), [[exp.f.freq]] в MHz (например, 14.074, или пусто), [[exp.f.mode]] (выпадающий список, разделённый на «[[exp.mg.digital]]», «[[exp.mg.voice]]», «[[exp.mg.cw]]» и «[[exp.mg.other]]»), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 или 8 символов, или пусто), [[exp.f.name]], [[exp.f.qth]] и [[exp.f.comment]].",
  "t.20o1ldevfg3": "Загрузка данных не удаётся: проверьте соединение, что отмечен хотя бы один сервер, и попробуйте другой сервер; если Вы добавили свой, проверьте, что по этому адресу действительно выдаётся список TLE.",
  "t.20pkwpsdcyp": "Направление вычисляется от Вашего локатора до локатора DX-станции: нужны оба.",
  "t.20q16eoo4pl": "Aurora показывает TX, но радио остаётся на приёме: почти всегда дело в CAT или PTT.",
  "t.20qi9sydfd5": "«[[sup.sendMail]]» серая? Сначала введите полный адрес (с @ и доменом) в «[[sup.email]]».",
  "t.20uzsoaq7g2": "Приёмник RTTY декодирует каждый символ целиком и присваивает ему вероятность правильности: неуверенные символы отображаются бледными. Три цепочки работают вместе (простая, с ограничителем и с уровнями относительно шума), и для каждого символа побеждает самая надёжная: это справляется с замираниями, флаттером и «качающейся» АРУ радиостанции. Потерянное переключение букв/цифр исправляется в конце слова, а повторяющиеся слова (позывные, рапорты) суммируются.",
  "t.20v3nqqvvok": "[[ctl.hound]]: режим Hound, для вызова DX-экспедиции в Fox/Hound (обычно включается сам, см. «Работа с DX-экспедицией как Hound»). [[ctl.swl]]: только прослушивание, декодер ищет глубже.",
  "t.20vp1pglfk6": "Окно RX включено по умолчанию, как «Rx Frequency» в WSJT-X: оно показывает сообщения вокруг частоты приёма, адресованные Вам и Ваши собственные передачи. Выключайте и включайте его кнопкой RX в панели водопада; выбор запоминается.",
  "t.20w36e9pqt0": "В каждой строке значок типа, номер версии, заголовок и дата; щелчок по строке открывает текст. Строка используемой Вами версии уже открыта и помечена «[[news.current]]».",
  "t.20yls9a5lmo": "Страница [[nav.sstv]] принимает и передаёт изображения (Martin, Scottie, Robot, PD, Wraase) с той же звуковой картой и PTT, что и FT8, не мешая ему.",
  "t.210fiinkhek": "Что отправляют автоматические отчёты: версия Aurora и Windows, движок, модель трансивера, PTT, backend CAT, название звуковой карты, область проблемы, очищенное сообщение об ошибке и сколько раз она произошла. После сбоя также очищенный журнал работы и текстовые отчёты. Что не отправляется никогда: позывной, локатор, декодированные сообщения, журнал QSO, ALL.TXT, настройки, пароли и ключи, IP-адреса, адреса электронной почты, имя Вашего пользователя Windows. Идентификатор — случайное число, которое Вы можете создать заново через «[[rep.newId]]».",
  "t.2117n5wb41l": "Язык не вверху: измените его в [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], пункт «[[gen.language]]». Звуковые сигналы (динамик с громкостью рядом) и светлая или тёмная тема находятся в нижней панели справа, рядом с часами (см. «Язык, тема и громкость на панели»).",
  "t.211kx04qlqj": "[[not2.grpColors]]: по одному блоку на каждый из 17 типов сообщений («[[kind.tx_msg]]», «[[kind.cq]]», «[[kind.my_call]]», «[[kind.standard_call]]», новинки по зоне CQ, зоне ITU, стране, квадрату, префиксу и позывному, каждая также «на новом диапазоне или режиме», и «[[kind.worked_call]]»). В каждом блоке слева направо: меню звука этого типа, образец цвета с Вашим позывным и выбор цвета. Щёлкните по выбору и выберите понравившийся цвет: Вы сразу увидите его в образце и в списках.",
  "t.211ykywfwvg": "Некоторые макросы относятся только к одному режиму: по умолчанию F10-F12 — это скорости, PSK31/PSK63 для PSK, 15, 20 и 25 WPM для CW, 45.45, 50 и 75 baud для RTTY. Они заменяют базовые или дополняют их в соответствии с «[[digi.mi.macrosMerge]]».",
  "t.21446bqttn4": "Если журнал пуст, появляется «[[cta.log.none]]» с кнопкой «[[cta.log.go]]», которая ведёт к настройкам журнала. Сколько QSO показывать, выбирается в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] («[[gen.log4omCount]]»).",
  "t.214pt3p7h1q": "Это три самых частых вопроса. Язык, тема и громкость находятся не в одном месте: язык — в настройках, громкость и тема — на нижней панели.",
  "t.216kjz1gmzj": "Окна «Настройки режима» и «Настройки RTTY»",
  "t.2179qtk8zku": "QSO, которое Вы исправляете или удаляете в Aurora, не исправляется и не удаляется в других журналах: там это тоже нужно сделать вручную.",
  "t.217tjo3iwzn": "На странице SSTV клавиши работают, когда видна вкладка «[[sstv.view.tx]]» (кроме Esc, который во всей Aurora имеет и общее действие).",
  "t.21a1efmlhqh": "[[win.where]]: по одной строке на элемент («[[panel.waterfall]]», «[[panel.station]]», «[[panel.tx]]», «[[panel.cq]]», «[[panel.all]]», «[[panel.log]]», «[[panel.cluster]]», «[[nav.dxmap]]», «[[prop.psk]]», «[[win.display]]», «[[nav.rotator]]», «[[nav.sstv]]») с меню, в котором указано, где он находится. Пункты: «[[win.place.main]]» (по умолчанию), «[[win.new]]» (собственное окно, чтобы перенести на второй экран), «[[win.dash]]» (блочная панель — одно окно, собирающее помещённые в него элементы), список уже открытых отдельных окон (чтобы поместить внутрь одного из них или рядом с ним) и «[[win.place.hidden]]».",
  "t.21ahubc4g2k": "фразы INT остаются на языке xx, пока вы его не смените (пусто: снова по позывному)",
  "t.21ay8497o2v": "«TX Lvl»: уровень звука на выходе (по умолчанию он уменьшает генерируемый сигнал, не трогая громкость Windows; с опцией «TX Lvl = громкость Windows» он управляет микшером Windows). Если трансивер перегружается (высокий ALC на его собственном приборе), уменьшите этот уровень; для чистого сигнала ALC трансивера должен оставаться на 0, а мощность и КСВ на дисплее Aurora — такими, как вы хотите. Его можно задать и при остановленной передаче. При наведении курсора виден процент и ослабление в дБ. Без управления трансивером и при включённой Aurora появляется «TX Lvl –» (см. «Ползунок TX Lvl»).",
  "t.21bar5xhxz1": "LogHX и GridTracker вместе: в Aurora используйте «+ [[int.p.multicast]]» (239.255.0.1, порт 2237), а в LogHX включите multicast с той же группой и портом; либо пусть LogHX пересылает пакеты другой программе (rebroadcast).",
  "t.21blg5x59q1": "Агент в области уведомлений (рядом с часами) использует язык, выбранный в Aurora: всплывающие карточки следуют ему сразу, меню в области уведомлений — после перезапуска агента (например, при следующем запуске Windows).",
  "t.21dpexqeny0": "«Check for updates»: сразу проверяет, есть ли новая версия (на GitHub), и всегда отвечает карточкой: «Aurora X is ready» с кнопкой «Update now» и кратким перечнем новостей, либо «Aurora is up to date», либо «Check failed», если GitHub не отвечает.",
  "t.21esaya6sz": "Индикатор радиостанции вверху не отображается: без CAT ему нечего было бы показывать. Он появится, как только Вы выберете Hamlib, OmniRig или TCI.",
  "t.21f35vil0te": "Откройте UDP BandMap в Logger32: нажмите Ctrl+J или щёлкните правой кнопкой по панели «UDP» в строке состояния и выберите «Open UDP BandMap». Когда панель UDP станет синей, сокет открыт. Запись QSO в журнал работает и при закрытой карте; карту Вы видите, только если её открыть.",
  "t.21gkdzekv6r": "На слабом ПК, пока идёт декодирование, фоновые задачи (DX Cluster, DX-экспедиции, PSK Reporter, поиск позывных, список LoTW, спутниковые данные, проверка обновлений) откладываются и выполняются сразу после конца декодирования, не позже чем через 30 секунд. Так звук не теряет блоков, а декодирование не опаздывает. Ничего не пропадает: споты и данные просто приходят на несколько секунд позже. Кроме того, пока вы работаете в FT8, SSTV, PSK · RTTY · CW и со спутниками, они ничего не потребляют, если их страницы закрыты.",
  "t.21gpc0ka26m": "Укажите свой локатор в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]], затем откройте страницу [[nav.sat]] и нажмите «[[sat.tle.refresh]]»: Aurora загрузит орбитальные данные с серверов, выбранных в [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.orbits]] (по умолчанию это серверы, предлагаемые Aurora; данные обновляются сами каждый день).",
  "t.21gw3dm3a8g": "Без QR: на ПК сгенерируйте код, затем введите его в поле «[[pair.code]]»: 8 цифр, только числа (остальные символы игнорируются), те, что ПК показывает в «[[acc.code]]». Код действителен в течение времени, заданного в «[[acc.ttl]]» (по умолчанию 10 минут), используется только один раз, а после нескольких неверных попыток ПК на какое-то время отказывает.",
  "t.21idyztdfns": "Панель сигналов (CW и PSK)",
  "t.21jh5pzljj4": "Свободный текст длиннее 13 символов по-прежнему обрезается до 13.",
  "t.21lx89o54mz": "Показывает последние QSO: из Log4OM, если Aurora читает его журнал, иначе из собственного журнала Aurora, со страной и рапортами.",
  "t.21sk97fza8c": "STOP TX всегда выключает автоматизацию и останавливает также CQ, который она вызвала сама. Ограничения, заданные на ПК, и отключение при отсутствии подключённого устройства остаются в силе. В боевом режиме Aurora сама включает [[ctl.enable_tx]] (без него ни один ответ не уходит); когда автоматизация останавливается, по любой причине, [[ctl.enable_tx]] возвращается в то состояние, в котором был до включения.",
  "t.21trv0vcmh2": "Полная статья: «Радио не передаёт»; «Передаёт, но мощность нулевая»; «PTT не включается».",
  "t.21y3v2t291c": "[[sw.station]] · [[gen2.call]]: Ваш позывной в том виде, как Вы его передаёте (например, IU3ABC или IU3ABC/P при работе с выезда). Он попадает в сообщения и журнал. Меняйте его, только если Вы сменили позывной или работаете с выезда. Применяется после «[[sw.save]]» внизу; если у параметра указано «[[ens.restart]]», он применяется при следующем запуске.",
  "t.21yup8z1c8p": "[[ens.g.wsprnet]] · [[ens.k.WSPRnetUpload]]: флажок (подписан «[[ens.svc.on]]»), по умолчанию выключен. Если включён, после каждого принятого периода WSPR или FST4W Aurora отправляет на wsprnet.org отчёт по каждому декодированному сигналу (или, если ничего нет, состояние Вашей станции). Споты становятся публичными на сайте и передаются по http, без шифрования; если выключено, ничего не отправляется. Нужны Ваш позывной и локатор ([[sw.sec.station]] › [[sw.pg.personal]]) и частота трансивера, считанная по CAT.",
  "t.21yuqhi6ilk": "Строка заголовка: «[[rxw.title]]», справа частота Rx с допуском (например, «1500 Hz ±50»), затем «[[list.clear]]» и «[[list.bottom.off]]» / «[[list.bottom.on]]», которые работают как в Band activity, но действуют только здесь.",
  "t.223uns9doq0": "Карточка DXCC сообщает, является ли станция, которую Вы вызываете, новой страной для Вас. Она находится в панели «Журнал», а полностью — на странице [[nav.stats]]. Настраивается в [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (какие строки и диапазоны, итог, поле «Try», подписи).",
  "t.226h99jaxuu": "Радио не подключается: с чего начать?",
  "t.227dtqmxn71": "Остановка передачи",
  "t.228yttvgcve": "Для дат откройте [[ctest.editActive]] в меню [[ctest.menu]] и в группе [[ctest.g.validity]] введите [[ctest.f.start]] и [[ctest.f.end]] в UTC. Для CQ WW DX, CQ WPX и JIDX кнопка «Suggest» подставляет даты этого года: сверьте их с правилами, затем нажмите OK.",
  "t.22901fmxpqh": "Нажмите «[[sstv.tx.send]]»: радиостанция передаёт, а полоса показывает ход передачи; «[[sstv.tx.stop]]» немедленно отключает звук и PTT. Переданное изображение остаётся в «[[sstv.hist.sent]]». С клавиатуры: F1 — передача, Esc — стоп (см. «SSTV: горячие клавиши»).",
  "t.229k1hp15wk": "[[sw.pg.radio]]: [[cat.grp.test]], [[cat.grp.ptt]], [[cat.grp.split]]",
  "t.22ajjfmkbez": "[[sw.testPtt]]: запрашивает подтверждение («[[sw.pttConfirm]]») и затем заставляет трансивер ПЕРЕДАВАТЬ одну секунду. Проверка начинается в начале следующего периода (в FT8 до 15 секунд: строка состояния говорит «[[sw.pttWait]]»), затем завершается сообщением «[[sw.pttDone]]»; если трансивер не выходит в эфир, сообщается «[[sw.pttFail]]» (передача не разрешена, неверный PTT или CAT). Сначала подключите эквивалент антенны или подходящую антенну.",
  "t.22bwkb77sn3": "Светодиод AutoSeq несёт уровень в своём тексте («AutoSeq 3»). Подробности о «[[ctl.wait_call]]» и «[[ctl.pounce]]» находятся в «Ожидание и ответ и [[ctl.wait_call]]».",
  "t.22d54cz1fd8": "Строка управления приёмом",
  "t.22dc4uvhe8a": "[[digi.tx.title]] · [[digi.autoReceive]] (по умолчанию выключено): при включённом флажке прослушивание PSK, RTTY и CW начинается само при запуске Aurora; при выключенном Вы запускаете его с рабочей страницы.",
  "t.22eo1jl1r4": "Сводка всех особых клавиш и щелчков страницы «Станция» и соседних страниц.",
  "t.22f5qaykw46": "«[[pair.name]]»: имя, под которым телефон появится в «[[acc.devices]]» на ПК. Aurora предлагает имя по модели телефона; Вы можете свободно его изменить (от 1 до 64 символов).",
  "t.22fvp56w44y": "[[sw.digi.perMode]] · RTTY, «[[digi.rtty.shift]]» и «[[digi.rtty.baud]]»: два выпадающих списка с самыми употребительными значениями. Заводской сдвиг 170 Hz (можно выбрать от 23 до 850) и скорость 45,45 бод (от 45 до 300). Они должны быть такими же, как у станции, которую Вы слушаете: при неверных значениях получается бессмысленный текст.",
  "t.22h82abtngk": "Левый выпадающий список ([[map.style]]) меняет фон карты; ползунок ☼ ([[dxmap.brightness]]) осветляет или затемняет его.",
  "t.22hzrgy103u": "[[cat.restoreStart]] и [[cat.restoreExit]] (по умолчанию включены, сохраняются сразу): первый при запуске возвращает трансивер на последнюю частоту и режим; если он выключен, Aurora не трогает трансивер при запуске, и если Вы сменили диапазон на трансивере до открытия Aurora, Вы найдёте его таким, каким он был. Второй при выходе возвращает трансивер таким, каким он был до открытия Aurora (только Hamlib и только если трансивер не передаёт).",
  "t.22i3addk47y": "[[nav.sstv]]: переключает на страницу SSTV (на странице SSTV такой же список режимов вверху, и она возвращает Вас сюда).",
  "t.22jpnmqkbfv": "Столбцы в лёгкой сетке (перетащите заголовок, чтобы переместить столбец, перетащите его край, чтобы расширить, как в DX Cluster; правый щелчок: «[[cluster.cols.reset]]»): «[[radar.colCall]]» (точка цвета станции, флаг и позывной), «[[radar.colFreq]]» (относительно радио), WPM и S/N (только CW) и CQ для вызывающих. Вверху — сколько всего станций. Ручка между окнами RX/TX и таблицей меняет её ширину (двойной щелчок — по умолчанию). Станция, не слышимая более 75 секунд, остаётся бледнее.",
  "t.22klgq4ux9j": "OFF: <MARK> и <BOOKMARK> перестают писать отметки; ON включает их снова",
  "t.22lgdc68zg9": "Если ваш внешний журнал уже отправляет данные в сервис, не включайте его ещё и в Aurora: QSO придёт дважды.",
  "t.22ljnjrah7v": "[[cat.grp.link]] · [[cat.backend]]: как Aurora общается с трансивером. «[[cat.backend.hamlib]]» (заводской) подходит почти для любого трансивера с кабелем; «[[cat.backend.omnirig]]» (только Windows) нужен, только если трансивер уже настроен в OmniRig; «[[cat.backend.tci]]» для SDR; «[[cat.backend.ft991link]]», если эта программа занимает порт FT-991; «[[cat.backend.cat4om]]», чтобы делить трансивер с Log4OM; «[[cat.backend.none]]» для работы без CAT (диапазон вручную). Меняйте его, только если Вы не используете Hamlib.",
  "t.22m8cfu5mxs": "[[ap.text]] · [[ap.color]]: цвет всего текста. «[[ap.colorTheme]]» (по умолчанию) использует цвет темы; затем шесть готовых образцов и свободный выбор «[[ap.colorFree]]». Запоминается отдельно для светлой и тёмной темы. Под строкой Вы видите коэффициент контраста: если он падает ниже 4,5:1, предупреждение сообщает, что текст может плохо читаться, и желателен более насыщенный цвет.",
  "t.22mlcj14nt5": "Страница Fox: все команды",
  "t.22pi0qcdhbf": "«[[int.ttl]]» (только с multicast; по умолчанию 1, от 1 до 255): через сколько маршрутизаторов может пройти датаграмма. 1 остаётся внутри домашней сети и является рекомендуемым значением. «[[int.iface]]» (только с multicast, необязательно): IPv4-адрес этого ПК, с которого уходит multicast: 127.0.0.1 для программ на этом ПК, адрес в домашней сети для другого компьютера; если пусто, выбирает Windows.",
  "t.22tr1pcmp26": "В Aurora есть три карты Земли NASA: “[[sat.map.terra]]” (с рельефом и дном морей, дневной снимок и ночью огни городов: по умолчанию), “[[sat.map.terraRelief]]” и “[[sat.map.terraBase]]”, а также “[[sat.map.builtin]]” (суша и границы, нарисованные Aurora, облегчённая): выбираются они в выпадающем списке “[[sat.map.pick]]” в настройках страницы, где находится и “[[sat.set.mapAuto]]” (по умолчанию: первая Земля). На карте все спутники обозначены одним значком, а у МКС свой силуэт; автоматическое масштабирование доходит максимум до 3x. Изображения, добавленные через “[[sat.map.add]]” (эквидистантная цилиндрическая проекция 360° × 180°, в папке “maps” данных Aurora), всегда остаются доступными для выбора. Частоты спутников стоит проверять на AMSAT; чтобы добавить другие спутники, напишите файл satelliti-utente.json.",
  "t.22xdapv3zda": "[[auto.b4]] · [[auto.continents]]: флажок [[auto.contExcludeShort]] и семь флажков континентов (EU, NA, SA, AF, AS, OC, AN). Если отмечен хотя бы один континент, Aurora отвечает только тем, кто там; при отмеченном [[auto.contExcludeShort]] она делает наоборот и НЕ отвечает выбранным континентам. Ничего не отмечено = все. Станция с неизвестным континентом пропускается.",
  "t.22yo6033mvl": "Макросы делятся на две группы, каждая в своём файле в папке данных: «[[sw.macros.tabCommon]]» (macro/comuni.macro, для всех режимов) и «Только для этого режима» (macro/psk31.macro, macro/rtty.macro, macro/cw.macro…). В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › «[[sw.pg.digiMacros]]» у каждой группы своя вкладка, и она редактируется отдельно. Отметка «[[digi.mi.macrosMerge]]» (также в меню [[digi.menu.file]]) определяет, как они сочетаются: включена — действуют общие, а макросы режима заменяют клавиши с тем же названием; выключена — только макросы режима. Пример: общий F2 «CQ CQ DE <MYCALL>» и F2 для CW «CQ CQ DE <MYCALL> <MYCALL> K»: в CW при включённой отметке F2 отправляет версию для CW, а остальные клавиши остаются общими; при выключенной отметке в панели только клавиши CW.",
  "t.22yx5jaqxm4": "запустила бы внешнюю программу: Aurora программы не запускает и удаляет команду из макросов; резервную копию, которую делали старые файлы .bat, Aurora делает сама при запуске",
  "t.22z0t7y55r": "Ничего не посылается, если передача не разрешена: если «[[sw.testPtt]]» говорит «[[sw.pttFail]]», сначала проверьте [[sw.testCat]] и метод PTT в [[sw.pg.radio]].",
  "t.22z33rx43xk": "[[digi.menu.configure]] › [[digi.mi.macrosMode]] и [[digi.mi.macrosDefault]]: оба открывают Настройки на странице «[[sw.pg.digiMacros]]» ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]]), где макросы меняются в таблице. Чтобы изменить только один, быстрее щёлкнуть правой кнопкой по клавише.",
  "t.2307tdiv9lq": "Страница [[nav.contest]] содержит вверху панель контеста и, когда контест включён, три вкладки: «[[contest.tab.race]]», «[[contest.training]]» и «[[contest.analysis]]». Как настроить контест, описано в «Контесты».",
  "t.231gqsmkmh3": "RX/TX, Pause, Esc, двойной Esc и автоматический CQ",
  "t.23678e8t5x7": "Источники с точным временем: метеокарты WEFAX немецкой метеослужбы DWD из Пиннеберга (DDK3) на 3855 кГц, 7880 кГц и 13882,5 кГц (несущая, USB, поднесущая 1900 Гц) имеют фиксированную скорость 120 строк в минуту. На странице WEFAX значение «learned ppm», которое Aurora выводит из этих карт, — та же ошибка звуковой карты (если вы используете ту же звуковую карту и ту же частоту дискретизации), и его можно скопировать в поле SSTV. Для SSTV официальной эталонной передачи нет: SSTV с МКС (ARISS, 145,800 МГц FM, только во время мероприятий) или станция, о которой вы знаете, что у неё точные часы, подходят, только если вы в этом уверены.",
  "t.236uxnknikc": "[[not2.markers]] · [[not2.markOther]] (по умолчанию включено): метка на сообщениях между другими станциями, содержащих новинку. [[not2.markRed]] (включено): красная метка на строках, где Вас кто-то вызывает. [[not2.markBlue]]: метка становится синей на строках QSO, которую Вы проводите; разблокируется только при включённой красной; по умолчанию выключено.",
  "t.237o2e61l01": "Дубли QSO: не допускайте, чтобы то же QSO приходило ещё и из GridTracker или JTAlert.",
  "t.238rnajf5jo": "На странице [[nav.station]], под сообщениями Tx, появляется зелёным «Fox verified» или красным «Fox NOT valid».",
  "t.2394v8pkc77": "копирует текст, выделенный в окне RX, в буфер обмена",
  "t.23ad4blye5p": "«частота занята?» на языке другой станции",
  "t.23atwqme89o": "[[digi.wk.secKeying]]: вес, соотношение точка/тире, [[digi.wk.keyComp]] и [[digi.wk.firstExt]] для радио, которые укорачивают или обрезают элементы, [[digi.wk.autospace]] и [[digi.wk.contestSpacing]].",
  "t.23b5c3vq97s": "В звуковом меню каждого оповещения, помимо звуков Aurora, есть «Voice» и «[[snd.myFiles]]».",
  "t.23cvbvmuo7m": "Два переключателя существуют только в FT8 и находятся в ряду элементов управления приёмом.",
  "t.23d1nrl16ab": "В [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]] выберите «TCI (dalla radio)» как вход и «TCI (alla radio)» как выход.",
  "t.23dkvz8i4hz": "Почти всегда дело в часах ПК: в FT8 они должны быть верны с точностью до доли секунды. Проверьте предупреждение о часах вверху и [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].",
  "t.23e3uxn4izm": "«кто вызывает?» на языке другой станции",
  "t.23el4uxiawd": "Ничего не приходит: порт 2237 уже занят другой программой (JTDX, WSJT-X, GridTracker). Закройте её или используйте другой свободный порт (например, 2239) и в Aurora, и в двух строках BBLogger.",
  "t.23fi4rzrqrl": "отметки журнала (BIGScan, вне соревнования) игнорируют QSO до этих даты и времени UTC; <IGNOREBEFORE:ERASE> снимает ограничение",
  "t.23g3w7frcxk": "Внизу дерева находится «[[sw.tab.info]]»: это страница, которую вы видите при открытии настроек, с последними новостями Aurora и «[[about.donateTitle]]».",
  "t.23g9wixqo90": "[[sw.sub.ft8]] · [[fil.decode]]",
  "t.23hwcxsjqii": "После «[[contest.exp.save]]» в Cabrillo указывается официальное название контеста (например, JIDX-CW, CQ-WW-RTTY, ARRL-DX-CW), и Aurora предупреждает, если находит QSO без обмена, QSO вне дат или отсутствие QSO вообще: исправьте их в журнале и сохраните снова. Если окно дат истекло или ещё не началось, очки, дубли и Cabrillo считают QSO с момента, когда Вы активировали контест, как и журнал, который Вы видите. Для CQ WW RTTY, CQ WPX RTTY, ARRL DX (CW и SSB) и ARRL 10 m Aurora теперь сама предлагает даты по правилам.",
  "t.23jjz5ohuct": "[[sw.digi.perMode]] · PSK31 · PSK63, ползунок порога шумоподавителя (от 0 до 100, заводское 15): измеряет качество фазы сигнала, а не громкость, поэтому работает одинаково при сильном и слабом звуке. На одном шуме качество остаётся ниже 10; при 15 проходят сигналы примерно до −10 dB S/N. Увеличьте, если на шуме появляются символы, уменьшите, если теряете слабые сигналы. Учитывается только при включённом «[[digi.mi.squelch]]».",
  "t.23le4ssow6p": "«[[wish.recent]]» (внизу): последние сработавшие оповещения (до 12), по одному в строке, с позывным, причиной срабатывания (позывной, префикс, страна или квадрат), откуда (сообщение, кластер или тест), диапазоном, частотой и временем. Если оповещений нет, Вы видите «[[wish.none]]». Это помогает проверить, что список делает то, что Вы хотели.",
  "t.23mimunzod0": "Почти всегда трогать его не нужно: оставьте 0, что означает «заводское значение модели». Поле появляется только при выбранных Hamlib, последовательном порте и трансивере Icom (или когда значение не равно 0) и принимает числа от 0 до 255.",
  "t.23mupz92383": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]]. Станции, с которыми Вы хотите провести связь: Aurora следит за каждым декодированным сообщением и каждым спотом кластера, даже при закрытой странице, и оповещает Вас один раз по каждой станции (затем ждёт выбранное Вами время). Одна запись в строке. Страница сохраняется сама; если запись неверна, появляется красное предупреждение, и она не сохраняется. Порядок на экране: «[[lay.lists]]», «[[lay.options]]», «[[wish.notifyUrl]]», «[[wish.recent]]».",
  "t.23nepszvfx4": "Правила запрещают Fox/Hound и мультипоточность: пока контест активен, они остаются выключенными. Многие также требуют, чтобы оператор сам начинал каждое QSO (без автоматического CQ без присмотра). Правила меняются каждый год: «[[contest.rules]]» показывает дату проверки, пункты для сверки и ссылку на официальные правила. Составные позывные не подходят для сообщений контеста (только /P и /R): Aurora остаётся на обычных сообщениях.",
  "t.23p4nc2krob": "С «[[aud.bandMem.on]]» (в [[sw.tab.audio]], по умолчанию выключено) ползунок «Ур. TX» возвращается на уровень, который был на этом диапазоне и в этом режиме; с «[[aud.tuneMem.on]]» у Tune тоже свой уровень на каждый диапазон, а после Tune возвращается обычный. Значение ползунка показано в дБ.",
  "t.23sksb828q3": "Левая кнопка перемещает зелёную полосу (Rx), правая — красную (Tx); Shift + щелчок тоже перемещает красную. Удерживайте кнопку, и полоса следует за мышью. Красная перемещается даже во время передачи: тон меняется сразу. Выберите свободное место для передачи.",
  "t.23toivqqjjw": "Вторая часть [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: график спектра под водопадом, полосы и частота, готовые стили и собственная палитра. Всё применяется сразу.",
  "t.23tti1u10ta": "Вверху расположена строка меню: [[digi.menu.file]], [[digi.menu.edit]], [[digi.menu.mode]], [[digi.menu.options]], [[digi.menu.view]], [[digi.menu.configure]], [[digi.menu.help]]. Каждый пункт описан в разделах о меню ниже. Щелчок открывает меню; при наведении на другие меню происходит переключение на них, а щелчок снаружи или Esc закрывает меню.",
  "t.23vatsl8ye7": "OmniRig: Aurora управляет им напрямую через COM, как WSJT-X, без PowerShell. Ошибка «access denied» исчезла, окно OmniRig больше не всплывает, а PTT работает быстрее. OmniRig нужно только установить и настроить в нём радио.",
  "t.23xmg2eqqh0": "В «[[fox.callers]]» ставьте станции в очередь (в том числе двойным щелчком); Aurora отправляет рапорт, ждёт R+рапорт и завершает RR73, в том числе в сочетании с рапортом следующей станции.",
  "t.2401bzqbejm": "[[digi.mi.squelch]]: печатается только то, что превышает порог режима. По умолчанию выключено; порог задаётся в «[[digi.mi.threshold]]».",
  "t.241cmb347b6": "Откройте [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] и в [[cat.backend]] выберите «[[cat.backend.cat4om]]».",
  "t.241htyt2li8": "QTC в WAE DX Contest",
  "t.24426cgkizo": "После хорошо принятой карты от точной станции (например, DDK3) «[[wefax.set.calibrate]]» превращает выученную ошибку в постоянный наклон и обнуляет остальное: поправка остаётся, и следующие карты выходят ровными.",
  "t.244ncipyxnt": "[[sw.contest.title]] · [[sw.contest.open]]: кнопка; открывает страницу [[nav.contest]] в главном окне, где Вы активируете контест, вызываете и экспортируете журнал (EDI для контестов УКВ).",
  "t.2471n4jkyk0": "Откройте [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] и в блоке [[auto.b5]] отметьте «[[auto.autoCqOn]]». В поле «[[auto.autoCq]]» введите, через сколько минут без CQ для ответа Aurora должна вызвать CQ (от 2 до 120; отметка флажка запускает со значением 5).",
  "t.248k7d5gnb6": "[[cop.rotor]]: тем же действием радио и антенна поворачиваются в сторону страны спота. Нужны подключённый ротор и Ваш локатор. По умолчанию выключено.",
  "t.24adwogtq3j": "«[[ens.g.adif]]» · «[[ens.k.UDP2Resend]]» (по умолчанию включено): если журнал закрыт, когда Вы проводите QSO, Aurora откладывает её и сама отправляет примерно через 15 секунд после того, как Вы его снова откроете, в том порядке, в котором Вы их провели. Относится к журналу на этом ПК (127.0.0.1); если указан адрес другого ПК, QSO уходят сразу. Каждая QSO отправляется один раз, очередь сохраняется при закрытии Aurora, а через семь дней отбрасывается. Подробности — в пункте «QSO, потерянные, пока журнал закрыт: где это включить».",
  "t.24angffq46q": "принятый обмен плюс один (с теми же ведущими нулями)",
  "t.24b20akmiin": "[[cat.grp.test]] · [[cat.state]]: светодиод и текст показывают, как идут дела: «[[cat.state.disconnected]]», «[[cat.state.connecting]]», «[[cat.state.connected]]» (с [[cat.freq]], [[cat.radiomode]] и [[cat.ptt.state]], считанными с трансивера), «[[cat.state.reconnecting]]» (Aurora повторяет попытки сама) или «[[cat.state.error]]» с причиной словами. Если чтение не удаётся, об этом сообщает дополнительная строка. Если у Icom используется PTT по CAT и скорость не 115200, появляется красное предупреждение: это самая частая причина того, что передача не начинается.",
  "t.24bagfpncpn": "Столбцы: «[[hist.col.when]]», «[[hist.col.band]]», «[[hist.col.mode]]», «[[hist.col.snr]]», «[[hist.col.freq]]» (звуковая частота в Hz), «[[hist.col.text]]» (с отметкой LoTW, если станция её использует) и «[[hist.col.country]]». Щелчок по строке с позывным помещает его в поле поиска («[[hist.pick]]»).",
  "t.24cgobhw5cc": "SSB: это голос. Aurora ничего не декодирует и не отправляет текст: Вы говорите в микрофон, а частоту и режим USB/LSB выбираете на радио. Страница состоит из трёх столбцов: [[digi.log.title]] слева, блок «[[ssbc.enter]]» посередине в одну строку, [[digi.tab.cluster]] справа. В строке Вы записываете [[ssbc.call]], [[ssbc.name]], [[ssbc.qth]], [[ssbc.rsts]] (по умолчанию 59) и [[ssbc.rstr]]; Enter («[[ssbc.enterHint]]») записывает QSO, кнопки нет. Если из меню [[ctest.menu]] выбрано соревнование, строка меняется: [[ssbc.qsoNr]], [[ssbc.call]], [[ssbc.serialSent]] (автоматический счётчик) и [[ssbc.serialRcvd]] (Вы вводите его сами); ниже видны счёт, множители и предупреждения «[[ssbc.dupe]]» и «[[ssbc.newMult]]». Если Вы пытаетесь отправить текст, появляется предупреждение. В меню пункты, имеющие смысл только для цифровых режимов, затенены с пометкой «[[digi.mi.onlyDigital]]». Имя, QTH и локатор заполняются сами по запросу QRZ.com или HamQTH, если он настроен в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]: текст, введённый Вами вручную, никогда не перезаписывается.",
  "t.24hht2sedgq": "Ограничения и сообщения: файл не может превышать 256 МБ (если он больше, экспортируйте его в двух частях, например по годам, и импортируйте по очереди); пустой файл даёт сообщение «Файл пуст»; импорт возможен только с самого ПК или из домашней сети, не извне.",
  "t.24hpi0bswsx": "Текст слишком мелкий? В [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] выберите «[[ap.size]]» (от 90% до 140%) или нажмите Ctrl + и Ctrl − на любой странице (Ctrl + доходит до 160%); Ctrl 0 возвращает 100%.",
  "t.24i13rn28oj": "подключает или отключает радиостанцию (CAT); <TOGGLEPTTPORT> тоже, так как в Aurora PTT идёт через CAT",
  "t.24i2e8hwaxe": "Работа с DX-экспедицией как Hound",
  "t.24jr886z2g2": "снимает ограничение <IGNOREBEFORE>: отметки журнала снова учитывают все QSO",
  "t.24kbvcadra2": "Даты повторяются каждый год: учитываются день и время в UTC. QSO вне окна дат никогда не бывают дублями.",
  "t.24n77kjl1el": "возвращает в QSO позывной последнего записанного QSO",
  "t.24ne5y8joa1": "Полная статья: «Какой нужен компьютер»; «Если ПК медленно декодирует».",
  "t.24o72g76kap": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]] → блок «[[rep.title]]»: включите «[[rep.ask]]» и, если хотите, «[[rep.auto]]». Чтобы выключить, снимите отметки: ничего больше не отправляется, а очередь очищается.",
  "t.24opqblujze": "Окно RX",
  "t.24pnj3k5z6s": "[[sw.sub.vhf]] · [[sw.pg.vhfModes]]",
  "t.24pqb3n8q72": "[[cmd.tune]] и [[cmd.logQso]] появляются, если Вы включите их в Настройки › Режимы › FT8 · FT4 › Сообщения и фильтры: Tune передаёт несущую для настройки (красная во время передачи), Log QSO заносит текущее QSO в журнал вручную. Tune стартует сразу, даже посреди длинного периода (FST4, FST4W, WSPR), и длится не более 2 минут.",
  "t.24qk7v26bam": "До пролёта: с помощью «[[sat.trk.preOn]]» и «[[sat.trk.lead]]» выберите, за сколько секунд до этого ротор отправляется в точку восхода. Пример: при 60 s, если спутник восходит в 18:42:00, ротор стартует в 18:41:00.",
  "t.24qv6x1jb5m": "Правый столбец: вкладка «[[digi.log.title]]» и текущее QSO",
  "t.24r101mriao": "позывной, за которым следует текст, только если есть позывной",
  "t.24t7zl4wmkm": "открывает окно редактирования макроса (F5, Ctrl-F5...)",
  "t.24ubsy0p5ud": "RST для передачи",
  "t.24uwtfqkts3": "Что показывают водопад и полосы Rx и Tx.",
  "t.24w5xxygqd6": "Если макрос, упоминающий позывной, имя или QTH, выходит с пропусками, сначала заполните данные: позывной и данные другой станции находятся в голубой строке «[[digi.log.title]]», Ваше собственное имя и QTH — в «[[sw.pg.personal]]».",
  "t.24x12qzxet1": "Кнопки карточки: «[[diag.slow_pc.to2]]» или «[[diag.slow_pc.to1]]» (сразу меняет глубину декодирования; действует со следующего периода), «[[diag.slow_pc.setting]]» (открывает страницу «Декодирование») и «×», закрывающий карточку. После закрытия она не возвращается для той же глубины до перезапуска Aurora. Если изменение не удалось, карточка сообщает об этом. После изменения счёт медленных периодов начинается заново с нуля.",
  "t.24xzt2qgjzu": "Примечание о медленном ПК остаётся и в журнале работы Aurora (с процессорами, потоками декодирования, глубиной и SWL), его полезно отправить тому, кто помогает Вам, через «[[sup.prepare]]».",
  "t.24yhilxh6v1": "Несколько минут нет ни одного декодированного сообщения (после 3 минут тишины, голубое): диапазон закрыт или приём остановлен, проверьте [[ctl.monitor]] и звук.",
  "t.24yyynbym0j": "[[aud.apply]] (блок): «[[aud.apply]]» применяет выбор сразу (обычно не нужно: он применяется сам примерно через секунду и при выходе со страницы); «[[aud.discard]]» отменяет ещё не применённый выбор; «[[aud.refresh]]» перечитывает устройства системы — нажмите после включения трансивера или подключения кабеля USB. Рядом появляется число ожидающих изменений, а ниже — простой итог: что было применено, что нет и почему, и какое устройство остаётся в использовании.",
  "t.250gdylhk7j": "Два небольших окна, открывающиеся поверх страницы. «[[digi.ms.title]]» открывается щелчком по данным режима в строке состояния или через «[[digi.mi.threshold]]»; «[[digi.rtty.title]]» — щелчком по названию RTTY внизу (в RTTY также из контекстного меню строки состояния). Esc закрывает их.",
  "t.2523yuk19dr": "размер текста окна RX в пикселях (пусто: по умолчанию)",
  "t.254y02fzch8": "Двойные QSO: QSO приходит двумя путями. В [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] основной и дополнительный UDP-серверы Aurora тоже работают на 127.0.0.1:2237: отключите ненужные или уберите получателя LogHX и оставьте основной сервер.",
  "t.255ebaro6az": "берёт последний принятый в окне RX позывной (не ваш) и вносит его в QSO: следующий за ним <CALL> сразу использует его",
  "t.258p5r9c7rl": "Есть настройка «[[dec.slowPc]]» ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]]): «[[dec.slowPc.auto]]» (по умолчанию), «[[dec.slowPc.always]]» или «[[dec.slowPc.never]]». Когда она включена, во время декодирования Aurora откладывает фоновые задачи (DX Cluster, PSK Reporter, LoTW и подобные) до конца декодирования. Кроме того, когда декодирование не укладывается во время, появляется предупреждение с кнопкой «[[diag.slow_pc.to2]]», которая снижает глубину декодирования до «Обычно»: Aurora никогда не меняет её сама.",
  "t.259lq1uavvh": "[[digi.edit.subset]] и список ниже: все команды, которые знает Aurora, разделённые на группы ([[digi.edit.group.text]], [[digi.edit.group.program]], [[digi.edit.group.frequency]], [[digi.edit.group.autocq]], [[digi.edit.group.macros]], [[digi.edit.group.mode]], [[digi.edit.group.rotor]], [[digi.edit.group.rtty]], [[digi.edit.group.sstv]], [[digi.edit.group.cw]], [[digi.edit.group.hell]]), каждая со своим объяснением. Команда с «[[digi.edit.soon]]» есть в списке, но Aurora её пока не выполняет.",
  "t.25a2bfwt7os": "Панель [[panel.tx]] показывает, с кем вы на связи и как далеко продвинулось QSO, и содержит переключатели QSO (см. «Переключатели QSO») и уровни звука (см. «Уровни Rx и TX Lvl»).",
  "t.25aimgdpxu": "Если Вы запрашиваете обновление из агента в области уведомлений, афиша не появляется: всё делает карточка в трее. В окне «Настройки» афиша появляется только после «[[upd.check]]», сама никогда. Когда у Вас уже последняя версия, она открывается с «[[upd.poster.upToDate]]», Вашей версией и кнопками «[[upd.poster.allNews]]» и «[[upd.poster.ok]]».",
  "t.25crq7s5inx": "Проверка: проведите QSO в Aurora (или добавьте его вручную на странице журнала): оно должно появиться в BBLogger.",
  "t.25d17bdh2w1": "Столбцы перемещаются перетаскиванием заголовков и расширяются перетаскиванием края заголовка (двойной щелчок по краю: подгонка под содержимое); правый щелчок по заголовкам также открывает меню столбцов. Левый край всего столбца можно перетаскивать, чтобы расширить журнал.",
  "t.25d49mp5xg1": "Для Logger32 достаточно одного первичного UDP-сервера (127.0.0.1, порт 2237). Не добавляйте вторую запись в «Интеграциях» (например, «BBLogger» или «WSJT-X flow») на тот же порт: каждое сообщение приходило бы дважды, а при включённом «ADIF по UDP» Logger32 получал бы ещё и текст ADIF, которого не ожидает на порту 2237. Если UDP-карта остаётся пустой, но в «UDP message debug window» Logger32 декодирования видны, проверьте также в меню Config карты пункт «Block callsigns worked before» и время видимости станций.",
  "t.25dynay9sku": "[[wfs.colors]] · [[wfs.palette]]: цвета водопада, выбираются из 30 палитр плюс «[[wfs.paletteUser]]» (Ваша собственная, создаётся в «[[wfs.palette.title]]»). По умолчанию «Default» (чёрный, синий, жёлтый, красный). Рядом с меню полоса показывает цвета выбранной палитры, от низких уровней (слева) до сильных (справа).",
  "t.25fic3gxngi": "«[[ctl.split]]»: держит частоту передачи отдельно от частоты приёма (сплит радио). «[[cmd.logQso]]»: появляется, только если включена там же; сразу заносит в журнал QSO с DX, на случай если последовательность не сделала этого сама. «[[ctl.clear_dx]]»: освобождает станцию для вызова и подготовленные сообщения.",
  "t.25fsht9y7mj": "Windows: порты называются COM3, COM4… Если порта нет в списке, откройте Диспетчер устройств Windows, раздел «Порты (COM и LPT)»: порт трансивера должен быть там при включённом трансивере и подключённом кабеле; если его нет, установите USB-драйвер производителя.",
  "t.25h5cad6val": "[[clock.state]] · [[clock.correct]]: сдвигает время Windows на измеренное смещение и затем измеряет снова. Aurora должна быть запущена от имени администратора (щёлкните значок правой кнопкой › Запуск от имени администратора: без этого Windows отказывает и появляется предупреждение), и это работает только с ПК, на котором работает Aurora. В Linux этого нет: используйте синхронизацию системы (NTP).",
  "t.25h5jjp955l": "«[[l4.title]]» · поле «[[l4.pathPlaceholder]]» с кнопками «[[l4.use]]» и «[[l4.remove]]»: введите или вставьте путь вручную и нажмите «[[l4.use]]» (пока поле пусто, кнопка неактивна); «[[l4.remove]]» заставляет Aurora перестать использовать базу данных (неактивна, если базы нет). Результат: «База данных используется: N QSO» или ошибка (это не база Log4OM, файл заблокирован, изменить можно только из домашней сети). Если путь записан в файле aurora.env (AURORA_LOG4OM_DB), поля и кнопок нет: измените его там, и он вступит в силу со следующего запуска.",
  "t.25jf1lw7w2s": "Кто пользуется LoTW",
  "t.25lc21xqqxb": "[[nav.fox]]: появляется только в группе «FT8». Предназначена для тех, кто передаёт из DX-экспедиции (см. «Страница Fox: все команды»); чтобы вызвать DX-экспедицию, она не нужна, используйте Hound на странице «Станция».",
  "t.25lzwi0iowk": "На одном unicast-порту может слушать только одна программа. Две программы: по одному получателю с разными портами или multicast, если обе могут его слушать.",
  "t.25mvirv3e8d": "[[wfs.bars]] · [[wfs.barsOn]] (по умолчанию включено): две вертикальные полосы на водопаде (зелёная Rx, красная Tx) шириной с сигнал режима и две белые линии, следующие за указателем. Когда выключено, остаются только подписи. [[wfs.periodLine]] (включено): зелёная горизонтальная линия в каждом новом периоде (жёлтая, если Вы передавали в этом периоде), чтобы разделять периоды.",
  "t.25my4rmsgi3": "Используйте один способ за раз (сеть или файл), иначе QSO будут приходить дважды.",
  "t.25nc6txfjd2": "⟳ «[[phone.refresh]]»: очищает кэшированную копию интерфейса в телефоне и перезагружает страницу с ПК. Нужна после обновления Aurora, если телефон показывает старую версию.",
  "t.25qo8pv5yg8": "[[cat.grp.ptt]] · [[cat.ptt.method]] (только Hamlib): как Aurora переводит трансивер на передачу. «[[cat.ptt.cat]]» (заводской) посылает команду по кабелю CAT и подходит для современных Icom, Yaesu и Kenwood по USB; «[[cat.ptt.dtr]]» или «[[cat.ptt.rts]]» используют линию последовательного порта (интерфейсы с PTT на RTS или DTR, например FT-2000 с RTS порта COM); «[[cat.ptt.vox]]» не посылает команд: трансивер передаёт, когда слышит звук. Если трансивер не переходит на TX, причина почти всегда здесь или в скорости.",
  "t.25rx9t07yfm": "Для ответа [[ctl.auto_tx]] не нужен: двойной щелчок работает и при выключенном [[ctl.auto_tx]]. Включайте его, только если хотите, чтобы CQ начинался заново сам по окончании QSO.",
  "t.25scbtkflcb": "Не знаете порт и скорость? Попробуйте «[[cat.detect]]»: он найдёт их за вас.",
  "t.25trvgawcfs": "[[ens.g.log]] · [[ens.k.PromptToLog]] (по умолчанию выключено): если выключено, завершённое QSO попадает в журнал само, сразу, без вопросов. Если включено, по окончании QSO открывается окно с данными ([[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]], [[lp.f.comment]]) для проверки или исправления, с кнопками [[lp.log]] и [[lp.discard]]. Если QSO накапливаются, окно сообщает, сколько их ждёт; когда очередь заполнена, самое старое попадает в журнал само, а выключение флажка отправляет в журнал все ожидающие. Вступает в силу со следующего завершённого QSO.",
  "t.25vkgwwqfx3": "«[[cluster.add.heading]]» · «[[cluster.add.catalog]]»: выпадающий список с проверенными публичными серверами (название, программа, место и адрес); выберите один (сначала «[[cluster.add.choose]]»): ниже появится примечание об этом сервере; затем «[[cluster.add.button]]». Порт 7300 — самый распространённый; серверы «RBN» выдают автоматические споты сети RBN (FT8 и FT4 на порту 7001). Aurora не отправляет споты: для этого нужны регистрация у оператора и программа ведения журнала.",
  "t.25whsahqizm": "В BBLogger откройте «Nuovo QSO» (новое QSO) или «Fast QSO» и нажмите значок шестерёнки рядом с «Auto-Save»: откроется «Configurazione interfaccia Wsjtx».",
  "t.25wvjaa1rb2": "В разделе [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] выберите стиль в блоке «[[rd.title]]»: у каждого стиля есть свой предпросмотр.",
  "t.25xeofr566x": "Отсканируйте QR-код камерой телефона: Aurora откроется, и сопряжение завершится само. Без камеры откройте показанную ссылку и введите код.",
  "t.25ycs8nulrz": "[[nav.settings]] › [[sw.sec.station]] › [[tab.audio]]: выход должен быть звуковой картой радио (часто «USB Audio CODEC»).",
  "t.25zuygqeklr": "Undo, Redo, Cut, Copy, Paste, Delete и Select all: системные пункты, которые работают всегда.",
  "t.2610crp25wp": "Заголовок блока: «[[phone.txMessages]]» с частотой Tx в Hz; во время передачи он становится «[[phone.transmitting]]» с секундами периода, а блок краснеет и получает полосу хода.",
  "t.2616x4et8mr": "«[[ens.g.qrz]]» · «[[ens.k.QRZLogSend]]» (по умолчанию выключено): отправляет каждую QSO в Ваш журнал на QRZ.com; нужна подписка QRZ, допускающая вставку через API, а дубликаты не перезаписывают уже имеющиеся QSO. «[[ens.k.QRZLogKey]]» — ключ журнала из настроек журнала на QRZ.com (не пароль учётной записи). «[[ens.k.QRZLogCall]]» (необязательно): если Вы проводите QSO с префиксами или суффиксами (/P, /QRP, EA3/…), QRZ отбрасывает те, у которых позывной отличается от позывного журнала; если вписать его здесь, они уйдут с этим позывным; пусто = собственный позывной QSO. Поиск позывных на QRZ.com — это другое, он находится в «[[tab.online]]». «[[ens.test]]» запрашивает у QRZ состояние журнала, ничего не записывая.",
  "t.262541qcmzv": "На странице каждое QSO сначала выбрано: фильтруйте по позывному, датам, диапазону и режиму и снимайте или ставьте отметки у нужных строк.",
  "t.262ajet4le7": "Панель [[panel.log]]",
  "t.265lo2epe9t": "Дайте Aurora поработать: когда Fox даёт Вам рапорт, она передаёт R+рапорт, а когда приходит его RR73, QSO заносится в журнал.",
  "t.265u9csd92a": "Внизу слева — водопад со шкалой частот; его верхний край можно перетаскивать, чтобы изменить высоту (от 50 до 400 точек).",
  "t.266jitm6su3": "[[set.back]] возвращает на главную страницу.",
  "t.266k5ify31t": "Режим DX-экспедиции, для пайлапов со сплитом: щёлкните правой кнопкой по строке DX и выберите «[[radar.pileupDx]]» (или, под списком, «[[radar.pileupFromQso]]» с позывным QSO). Aurora следит за текстом DX: когда он отправляет рапорт или подтверждение вызывающему («K1XYZ 5NN», «K1XYZ 599», «K1XYZ TU»), она ищет этот позывной среди станций, услышанных на других частотах за последнюю минуту, — именно там DX слушал. Оценку дают последние восемь проведённых корреспондентов: под списком строка «DX … слушает» с частотой, смещается ли она вверх или вниз, и последними позывными (подсказка перечисляет их с частотой и временем); на водопаде — оранжевая полоса «[[digi.wf.pileup]]» шириной с окно последних вызывающих и точка для каждого. Пока вызывающий не найден, учитывается собственная подсказка DX («UP», «UP 2», «UP 1-3», «DOWN 1»: 1 kHz на радио = 1000 Hz тона), пунктиром. «[[radar.pileupTx]]» переносит передачу туда с Lock (сплит), приём остаётся на DX; «[[radar.pileupOff]]» выключает режим.",
  "t.267on4keatd": "У Q65 есть также: «[[mode.q65lor]]» или «[[mode.q65gau]]» ([[mode.q65fading]]), «[[mode.q65drift]]» от 0 до 50 (0 = выкл.), переключатели «[[mode.q65eme]]» (задержка эха от Луны) и «[[mode.q65contest]]» (список контестов Q65), «[[dec.short.IncludeAveraging]]» и «[[dec.short.AutoClearAvg]]» (усреднение периодов) и кнопка ⟲ ([[mode.q65clearAvg]]). Значок «?» рядом с каждым пунктом (наведите на него курсор) объясняет, что он делает.",
  "t.26aqds6ogyf": "На главной странице шкала Rx должна показывать «Хорошо». Если показано «Слабо» или «Перегрузка», сдвиньте ползунок Rx (или оставьте включённым AUTO).",
  "t.26azanme6la": "[[ap.theme]] · [[ap.contrast]]: флажок. Нейтральный фон, текст полной яркости, чёткие границы и насыщенные цвета состояния: включите, если Вам трудно читать или Вы работаете при ярком свете. Работает и для светлой, и для тёмной темы. По умолчанию выключено.",
  "t.26bxr500q8": "При включённом шумоподавителе текст печатается, только когда последние символы вероятны: никаких выдуманных символов на шуме, даже с очень слабыми сигналами. Порог S/N в настройках добавляется, только если Вы поднимете его выше 0 dB.",
  "t.26c1vfv047q": "[[aud.input]] · [[aud.vol.in]]: ползунок громкости записи выбранного устройства (рядом индикатор AUTO, если включён). См. раздел о ползунках Rx, TX Lvl и AUTO. Если появляется «[[aud.vol.off]]», громкость этого устройства отсюда регулировать нельзя.",
  "t.26cprmogjym": "сразу переносит приём на ближайший сигнал",
  "t.26e2axizetj": "Как альтернатива сети, BBLogger читает файл aurora_log.adi, который Aurora пишет при каждом QSO. QSO попадает в BBLogger, когда Aurora заносит его в журнал: это самый надёжный способ, но он не показывает QSO, пока оно идёт.",
  "t.26ed7gren5s": "[[sw.sub.wspr]]",
  "t.26ekur0jp06": "«[[dxs.bands]]» · 160m, 80m, 60m, 40m, 30m, 20m, 17m, 15m, 12m, 10m, 6m, 4m и U (все включены): столбцы сетки; снимите отметку с диапазонов, которыми Вы не пользуетесь, чтобы карточка стала уже. «U» объединяет диапазоны короче 4 метров. Хотя бы один диапазон должен остаться включённым.",
  "t.26exok9uiwk": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]. Здесь Вы сообщаете Aurora, кто Вы: позывной и локатор попадают в сообщения, журнал, расстояния и азимут ротора; имя, фамилия, QTH и email — данные оператора.",
  "t.26f4y57z8cc": "Адрес CI-V трансиверов Icom (в десятичном виде)",
  "t.26gw81yrnaw": "Ваш выбор сохраняется сам ([[cat.apply]] применяет его сразу). В блоке «[[cat.grp.test]]» нажмите [[cat.connect]]: состояние должно стать «Подключено», и появится частота радио.",
  "t.26hmxfx0wih": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]. Собирает то, что нужно, когда что-то идёт не так или когда Вы меняете ПК. На странице пять блоков в таком порядке: «[[bak.title]]», «[[sup.title]]», «[[diag.crashFolder]]» (только если у ПК есть папка сбоев), «[[ca.title]]» и «[[rep.title]]». Блоки резервной копии и пакета работают только с ПК, на котором работает Aurora: с телефона Вы читаете «[[sup.onlyPc]]».",
  "t.26hpradlxhm": "принятый обмен (контест)",
  "t.26i58pj035v": "Сообщения: неверный код («[[pair.badCode]]»), истёк («[[pair.expired]]»), слишком короткий («[[pair.short]]»), нет имени («[[pair.nameRequired]]»), слишком много попыток (подождите указанное число секунд). Если Aurora не отвечает: «[[app.noCore]]», с кнопкой повторной попытки и, если найден другой уже используемый адрес, с кнопкой перехода на него.",
  "t.26jiqxihpxl": "очищает окно передачи (поле и уже отправленный текст) до этого места: текст после него остаётся",
  "t.26laufj8yrn": "Если блок смещён, поверните VFO радио. В USB звуковая частота — это частота сигнала минус VFO: если сигнал слишком высокий (блок справа от меток), поднимите VFO, если слишком низкий — опустите. Строка ниже сообщает, на сколько: «Move the VFO by +40 Hz» означает поднять его на 40 Hz.",
  "t.26lgpbks0ap": "Щелчок по кнопке или клавиша на клавиатуре (F1…F12 в первом ряду, Ctrl+F1… во втором, Shift+F1… в третьем, Ctrl+Shift+F1… в четвёртом) запускает макрос. Клавиша «+» цифровой клавиатуры запускает также макрос «Gray+» (по умолчанию он сохраняет QSO).",
  "t.26lwqr1gqqg": "Полная статья: «Подключение радио: контрольный список»; «Адрес CI-V радио Icom (в десятичном виде)»; в Linux: «Последовательные порты: Windows и Linux (группа dialout)».",
  "t.26n0cdth37s": "режим предыдущего QSO с этим позывным",
  "t.26o5kbyakjj": "[[cat.txAlc]] (по умолчанию выключено, только с Hamlib, сохраняется сразу): при передаче Aurora читает с трансивера и уровень ALC, который показывает, не слишком ли сильный звук вы подаёте (уменьшите его ползунком «Lvl TX»: ALC должен оставаться низким). Значение появляется в поле ALC дисплея трансивера, рядом с мощностью и КСВ, только во время передачи. Без флажка поле остаётся «—». По умолчанию выключено, потому что это ещё один измеритель, и на некоторых трансиверах он щёлкает переключателем, как описано выше.",
  "t.26rfvjjw01o": "Когда DX-экспедицию заспотили с «UP 5» в комментарии, двойной щелчок (или одинарный, если на страницах PSK, RTTY и CW Вы выбрали «[[cop.single]]») по споту переводит радиостанцию на приём на частоте спота и на передачу на 5 kHz выше, на втором VFO (настоящий сплит). Это работает в DX Cluster страницы «Станция» и страницы PSK · RTTY · CW.",
  "t.26sr01hqnt2": "Журнал внизу · [[auto.log]] (с его «?»): последние 100 решений, самые свежие сверху, у каждого время, тип ([[auto.kind.reply]], [[auto.kind.would_reply]], [[auto.kind.call_cq]], [[auto.kind.would_call_cq]], [[auto.kind.skipped]], [[auto.kind.blocked]], [[auto.kind.halted]], [[auto.kind.paused]], [[auto.kind.info]]) и причина. Зелёным: ответы и CQ; оранжевым: пропущенные, с причиной; красным: заблокированные пределом или STOP. Это помогает понять, почему Aurora ответила или нет.",
  "t.26u9johrm0s": "Предупреждения безопасности передачи (высокий КСВ, сообщение, которое нельзя отправить, Tx заблокирован внешней программой, Hound включился или выключился сам) появляются красным под строкой DX и исчезают через две минуты.",
  "t.26vb5wjjhcp": "Без CAT: выбор диапазона вручную",
  "t.26vylg8smn4": "Проверьте «[[contest.settings]]»: фиксированный обмен (Field Day «1D DX»), первый порядковый номер, категория, мощность, данные Cabrillo; для контестов без фиксированного календаря выберите начало и конец. Частоты из правил переводят радиостанцию на нужную частоту одним щелчком.",
  "t.26w4kex4k4q": "[[seq2.switches]] · [[seq2.maxDist]] (по умолчанию выключено): при равенстве нескольких станций выбирает самую дальнюю. Чтобы знать расстояние, ему нужен локатор в сообщениях. Вступает в силу после [[sw.save]].",
  "t.26yjyvs1hr2": "[[sw.station]] · [[gen2.region]]: регион IARU ([[gen2.regionAll]], [[gen2.region1]], [[gen2.region2]], [[gen2.region3]]). Он определяет, какие строки таблицы частот (страница [[sw.tab.freq]]) применяются: он не меняет частоту диапазона, у которого одна строка, но скрывает строки других регионов. Заводское значение «[[gen2.regionAll]]»; выберите свой, если в диапазоне показаны частоты, не используемые в Вашем регионе.",
  "t.26zjnhes1kb": "передача, когда сигнал на частоте приёма спадает (не более чем через 30 с; Esc отменяет)",
  "t.270whsy2n0c": "По умолчанию Aurora заносит QSO в журнал, как только начинает уходить Ваш RR73 или Ваш 73 (один RRR не заносит), при условии что рапорт другой станции получен; затем она прекращает передачу, ничего не спрашивая. Если Вы передаёте RRR, QSO заносится, когда приходит их 73 или, если он так и не приходит, при последней попытке завершения. В Hound оно заносится, когда приходит RR73 от Fox. Чтобы продолжить, снова вызовите CQ или выберите другой DX.",
  "t.270xta5hr57": "В CW и RTTY карточка [[radar.title]] показывает все станции в диапазоне. Включите её в меню [[digi.menu.view]] (пункт «[[radar.mi]]») или в параметрах приёма ([[sw.pg.rx]]); когда она выключена, карточки нет.",
  "t.270yrzpe6gz": "[[agent.popup]] · [[agent.seconds]]: числовое поле, от 3 до 60 секунд (по умолчанию 10). По истечении этого времени карточка закрывается сама; если курсор мыши над ней, она остаётся открытой. Значение вне пределов приводится к ближайшему пределу. Когда: увеличьте, если не успеваете прочитать.",
  "t.271j844791o": "При первом запуске полоса сообщает, что анонимные ошибки отправляются разработчикам Aurora без позывного, локатора, сообщений и паролей и что Вы можете выключить это в любой момент. Ссылка «[[rep.notice.open]]» ведёт на нужную страницу; «[[rep.notice.ok]]» закрывает полосу навсегда. Переключатели находятся в [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (см. «Отчёты об ошибках»).",
  "t.272rqnjaxxc": "[[ctl.monitor]]: приём включён или выключен. Когда выключен, Aurora ничего не декодирует: это первый переключатель, который нужно проверить, если список сообщений остаётся пустым.",
  "t.272vbpbmb35": "«Clear all» («Clear all», «Alles löschen»… на языке Aurora): внизу, только в полях, которые можно редактировать, очищает поле, по которому Вы щёлкнули, и обновляет страницу. Полезно, чтобы разом очистить поле поиска или позывной.",
  "t.278aqncv5n7": "Кнопка ⧉ вверху справа переносит карту в отдельное окно (см. «Отдельные окна и раскладка»).",
  "t.278vfr7jbnn": "В Linux в списке появляются порты «/dev/ttyUSB*» и «/dev/ttyACM*», а также принимаются пути «/dev/serial/by-id/…», которые не меняются после перезагрузки. Чтобы использовать только PTT по RTS/DTR, без CAT, выберите модель Hamlib «Dummy» и укажите порт. Если Linux пишет «Permission denied», порт не занят: у вас нет прав на его использование. Добавьте своего пользователя в группу dialout командой «sudo usermod -aG dialout $USER», затем выйдите из системы и войдите снова (см. «Последовательные порты: Windows и Linux (группа dialout)»).",
  "t.27azdat040u": "Поле «[[guide.search]]» находится вверху оглавления: введите слово, и останутся только статьи, которые его содержат (в заголовке, тексте, шагах, советах и пунктах «[[guide.fix]]»), на выбранном Вами языке. Если ничего не найдено, написано «[[guide.none]]».",
  "t.27c873c32jp": "Щёлкните правой кнопкой по кнопке частоты: она сразу переходит на следующую частоту из списка Band Hopping (радио должно управляться; список задаётся в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). При включённом контесте выпадающий список показывает только диапазоны, разрешённые правилами.",
  "t.27cyotftpzy": "Карточки агента",
  "t.27ec1taxjnf": "«+ [[int.p.bblogger]]»: название BBLogger, 127.0.0.1, порт 2237, включены «[[int.wsjtx]]» и «[[int.loggedAdif]]». Получает тот же поток, что и в предыдущем пункте, и после каждой QSO запись ADIF в сообщении 12. В BBLogger (интерфейс Wsjt_I) нужны строки «Msg ID 5» и «Msg ID 12» на 127.0.0.1:2237, меню «UDP 12» и «Auto-Save». Используйте только один способ: сеть или файл ADIF; по умолчанию первичный и вторичный UDP-серверы тоже работают на 127.0.0.1:2237, и с BBLogger это может дать дубликаты QSO.",
  "t.27eqtyfroi9": "Снова щёлкните правой кнопкой по строке: станция покидает очередь.",
  "t.27evdgqb8ra": "Экспорт: выберите соревнование в списке и нажмите «[[ctest.export]]»: Aurora сохраняет <name>.zip с файлом .contest, его макросами и списком доменов, готовый к отправке другому радиолюбителю, который открывает его через «[[ctest.import]]».",
  "t.27f5span6qc": "[[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.doppler]]. Что делают трансивер и поворотное устройство во время пролёта. Каждое изменение сохраняется сразу. Для доплера нужен подключённый трансивер ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]), а для режима с поворотным устройством — подключённое поворотное устройство ([[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]]). Транспондер и частота приёма выбираются на странице «Спутники», а не здесь.",
  "t.27g67wmhrjz": "цвет текста окна RX",
  "t.27jvpqwnyop": "Водопад: маркеры, стрелки и позывные",
  "t.27mzrviv0ck": "включает Snap (<SNAPOFF>, <SNAP>)",
  "t.27o5bsdp2vf": "Если Вы пользуетесь лишь несколькими диапазонами, выключите остальные: полоса станет короче и удобнее для чтения (в справке страницы сказано: используемый диапазон показывается всегда).",
  "t.27oqxs8tjk5": "Индикатор соединения: его нет, пока всё работает. Если страница теряет связь с Aurora на ПК, появляется «[[conn.connecting]]» (идёт повторная попытка) или «[[conn.closed]]» (связь прервана). Проверьте, что Aurora открыта на ПК и сеть работает.",
  "t.27qvlhxb5yq": "«[[lay.options]]» · «[[wish.enabled]]» (по умолчанию выключено): если выключено, список остаётся, но оповещения не срабатывают. Включите, когда заполните списки. «[[wish.fromDecodes]]» (включено): ищет нужные станции среди принимаемых Вами сообщений. «[[wish.fromCluster]]» (включено): ищет их также в спотах DX Cluster, так что Вы видите их, даже если ещё не принимаете (кластер должен быть включён).",
  "t.27qwztq5wu4": "Шапка · [[auto.outWindow]] (метка, появляющаяся лишь временами): автоматизации включены, но местное время ПК находится вне окна времени, выбранного в блоке [[auto.b3]]; пока они не отвечают и не вызывают CQ.",
  "t.27rl18sw1i8": "контест: дата более ранней QSO с этим позывным",
  "t.27sdwkur167": "Две ленты миниатюр: одна для принятых изображений (Aurora хранит последние 200) и одна для переданных (последние 20; см. «[[sstv.set.saveTx]]» в Настройках SSTV). Рядом с заголовком указано число изображений.",
  "t.27t9b219d2q": "[[lay.lists]] · [[fil.only]]: выпадающий список с [[fil.onlyAll]] (заводское значение), [[fil.onlyCq]], [[fil.onlyCqRrr]] и [[fil.onlyCqRr73]]. Выберите один, чтобы видеть только CQ и завершения QSO вместо всех сообщений.",
  "t.27x5dvlh2fz": "[[ap.theme]] · [[ap.theme]]: три кнопки, «[[theme.dark]]», «[[theme.light]]» и «[[theme.auto]]» (следует теме Windows и меняется вместе с ней). По умолчанию тёмная. Тот же элемент управления — кнопка-значок внизу справа, рядом с часами UTC.",
  "t.27xy8ty69ko": "очищает принятый обмен",
  "t.27yl42huy5k": "Откройте [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]].",
  "t.27zdr47xv8w": "[[sw.tab.macros]]",
  "t.28020xv63w6": "[[nav.sat]] › [[sw.pg.orbits]]",
  "t.280j5bevfwp": "Блоки посередине: «[[fox.inProgress]]» (рапорт отправлен, ожидается подтверждение, с числом попыток; «[[fox.drop]]» закрывает QSO, которое не отвечает, и освобождает слот), «[[fox.onAir]]» (сообщения, которые передаёт Fox, по одному на слот), «[[fox.queue]]» (ожидают свободного слота; «[[fox.remove]]» убирает станцию из очереди) и «[[fox.log]]» (последние 500 QSO, закрытых в этом сеансе, с кнопками ADIF, Cabrillo и Club Log для сохранения или отправки).",
  "t.280t4if1gdy": "сохраняет QSO и очищает поля",
  "t.282bhrwaeq6": "Когда выходит новая версия, на панели появляется значок или плакат (см. «Уведомление об обновлении на панели»). До первого QSO, если журнал пуст, панель «Журнал» предлагает импортировать его или подключить внешний журнал.",
  "t.283v078fxpq": "Только для TCI: [[cat.tci.address]] (заводское 127.0.0.1:40001: измените его, если SDR работает на другом ПК или на другом порту) и [[cat.tci.receiver]] (RX1 или RX2: частота, режим, PTT и звук используют выбранный; при SDR с одним приёмником оставьте RX1). См. также раздел «SDR с TCI».",
  "t.284dwsyaj5h": "[[tab.sequence]]",
  "t.2851rho2bp2": "Обновления",
  "t.285detvuzoj": "«[[ens.g.qrzlookup]]» · «[[ens.k.QRZLookup]]» (по умолчанию выключено): когда Вы наводите курсор на позывной в DX Cluster, Aurora запрашивает у QRZ.com имя и город этой станции (показываются только имя, город и страна того, кого Вы ищете). «[[ens.k.QRZUser]]» и «[[ens.k.QRZPasswd]]» — Ваши имя пользователя и пароль QRZ.com (не ключ журнала). С подпиской «XML Logbook Data» QRZ выдаёт полные данные, без неё — сокращённые. Результаты хранятся в памяти три дня; если выключено, запросы не делаются. «[[ens.k.LookupToQso]]» (по умолчанию включено, действует при включённых QRZ.com или HamQTH): каждая записанная QSO получает имя и город (если ответ не приходит за 2,5 секунды, QSO записывается без них); относится к журналу, экспорту ADIF, прямым выгрузкам и ADIF по UDP. «[[ens.test]]» открывает сеанс и сообщает, есть ли подписка. Отправка QSO в журнал — это другое, оно находится в [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]].",
  "t.289w9na0ikb": "Когда контест активен, страница текстовых режимов (SSB, CW, RTTY, PSK) состоит из карточек, которые Вы перемещаете и масштабируете так же, как на странице «Спутники»; каждая уже имеет нужный для своих данных размер. Без контеста страница остаётся такой, какой была всегда.",
  "t.28arann7ke6": "Новый штат (США)",
  "t.28b8wuap0up": "Строка текущего QSO: [[digi.log.num]] (номер, который оно получит), [[digi.log.mode]], [[digi.log.freq]] (kHz: радио плюс нота приёма), [[digi.log.date]] и [[digi.log.utc]] (сейчас), затем четыре поля для ввода: [[digi.log.call]] (переводится в заглавные, до 16 символов), [[digi.log.name]] (до 30), [[digi.log.qth]] (до 40) и [[digi.log.grid]] (до 8, заглавными); [[digi.log.country]] заполняется само по запросу; наконец [[digi.log.rsts]] и [[digi.log.rstr]] (до 4 символов, по умолчанию 599, и после каждого QSO они возвращаются к 599 при включённом [[digi.mi.defaultRst]]).",
  "t.28bo7povrj1": "Чтобы переместить макрос, нажмите и удерживайте его кнопку: через мгновение рамка загорится, и кнопку можно перетащить (мышью или пальцем) на другую клавишу в любом ряду, которая подсвечивается. Когда Вы отпускаете, две клавиши обмениваются макросами (название, текст, цвет), а макрос получает клавишу своего нового места: перемещённый на пятое место первого ряда, он становится F5. На пустой клавише макрос перемещается и освобождает исходную. Макрос «только для этого режима» остаётся только для этого режима, макрос «для всех режимов» остаётся для всех. Короткий щелчок запускает макрос, как всегда; отпускание после загорания рамки без перемещения ничего не делает. С клавиатуры: Alt+стрелки на кнопке в фокусе. В уведомлении «[[digi.bar.moved]]» есть кнопка «[[digi.bar.undo]]», которая возвращает панель в прежний вид.",
  "t.28cluiskou6": "Язык агента — тот, что выбран в Aurora (иначе язык Windows, иначе английский): карточки следуют ему сразу, меню — после перезапуска агента.",
  "t.28csy2l4t1a": "[[sw.sec.sstv]] › [[sw.pg.images]]",
  "t.28d8j1gkct1": "несущая настройки на частоте передачи (<TUNE:s> на s секунд, по умолчанию 10)",
  "t.28evv74qci7": "[[sw.contest.title]] · форма контеста: [[contest.set.activity]], [[contest.set.cqWord]], [[contest.set.exchange]], [[contest.set.serial]], [[contest.category]], [[contest.set.mode]] (здесь также MSK144 и Q65), [[contest.set.power]], [[contest.set.bonus]], [[contest.set.holdTx]], [[contest.set.rrr]], [[contest.set.callContest]], [[contest.set.grid6]] (в контестах УКВ он действительно важен: он попадает в журнал EDI), [[contest.set.antenna]] (для заголовка EDI, например «Yagi 9 el»), [[contest.set.operators]], [[contest.set.club]], [[contest.set.name]], [[contest.set.email]], [[contest.set.location]], [[contest.set.assisted]], [[contest.set.cabrillo]], [[contest.set.catTime]], [[contest.set.catOverlay]], [[contest.set.start]], [[contest.set.end]], [[contest.set.address]], [[contest.set.soapbox]]. Каждое поле ведёт себя так же, как на странице [[sw.sub.ft8]] › [[sw.sub.contest]], где они объяснены по одному.",
  "t.28fis2inowz": "Для DX-экспедиций: в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] «[[onl.dxped]]» включено с завода (отключить можно здесь). Календарь берётся с NG3K.",
  "t.28hoh3pip1p": "[[seq2.switches]] · [[seq2.autoseq]]: автоматическая последовательность. Если включена, при каждом ответе станции Aurora сама переходит к нужному сообщению (рапорт, R+рапорт, RR73, 73); если выключена, сообщение меняется только когда Вы щёлкаете Tx1…Tx6. Это тот же переключатель «[[ctl.autoseq]]», что и на панели QSO: в обоих местах одно состояние, запоминается при перезапуске.",
  "t.28ikghd862u": "Блок «[[dxcc.title]]»: карточка DXCC (см. «Карточка DXCC») с метками станции, которую Вы вызываете, таблица по режимам и диапазонам и, внутри «[[dxcc.countries.title]]» (открывается щелчком), список стран с полем «[[dxcc.countries.filter]]» и выпадающим списком для выбора, какую строку таблицы (FT8, FT4, DIG или все режимы) показывать для каждой страны.",
  "t.28jorqvoft7": "[[sw.digi.perMode]] · CW, «[[digi.band.validation]]»: насколько строго относиться к услышанным позывным. [[digi.band.valMinimal]]: достаточно правдоподобной формы. [[digi.band.valNormal]] (заводской): существующая страна, подозрительные формы только если услышаны несколько раз. [[digi.band.valStrict]]: без подозрительных, необычные только если подтверждены. [[digi.band.valMaximum]]: только подтверждённые позывные с типичной формой. Чем строже, тем меньше появляется неверных позывных, но и верных тоже меньше.",
  "t.28leoc269th": "[[ctl.mtd]] (включено по умолчанию) использует все процессоры ПК: декодирование заканчивается раньше, когда диапазон загружен, с теми же результатами.",
  "t.28lfz7zcr54": "Aurora оповещает Вас четырьмя разными способами, и каждый отключается в своём месте. Вот где, вкратце; подробности — в разделах «[[sw.pg.alerts]]» и «[[sw.tab.colors]]» и других этого семейства. Всё находится в [[nav.settings]] › [[sw.sec.look]].",
  "t.28lg1d7bnks": "Синяя точка с цифрой: станция в очереди, цифра — её место.",
  "t.28my3jwfrri": "Нажмите «[[sw.save]]».",
  "t.28n14pnerrd": "[[wfs.bpp]] (по умолчанию 4; 5, если в [[wfs.speed]] выбрано «[[wfs.speedJtdx]]») и [[wfs.start]]: сколько деталей и откуда начинается водопад. [[wfs.navg]]: чем больше, тем медленнее и тише водопад.",
  "t.28nyzqmn52d": "Если STOP не отвечает, появляется «[[stop.fail]]» (проверьте соединение) или «[[stop.unpaired]]» (телефон больше не сопряжён: выполните сопряжение заново с ПК).",
  "t.28o0obkeqrz": "[[sat.set.servers]] · уведомление «[[sat.set.noServer]]»: появляется, если не отмечен ни один сервер; без серверов кнопка обновления ничего не скачивает. Отметьте хотя бы один сервер.",
  "t.28p57kkm0ab": "Rx показывает «[[rxl.state.silent]]»: проверьте звуковой кабель, что в [[sw.tab.audio]] выбран правильный вход (строка состояния под списком) и громкость записи. Rx «[[rxl.state.overdrive]]»: снизьте ползунок или уровень звука на трансивере.",
  "t.28q11y4ob4j": "По умолчанию основной и вторичный серверы оба идут на 127.0.0.1:2237: оставьте включённым только тот, который нужен Вашему журналу, или задайте другому иной порт.",
  "t.28tm9xkd059": "Оповещение появляется вверху страницы с кнопкой «[[wish.tune]]» для перехода на частоту; звуки и способ оповещения настраиваются в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]].",
  "t.28tz0vcjkbd": "[[digi.wk.secSpeed]]: ползунок WPM Aurora (также <WPM:n> в макросах) или [[digi.wk.pot]] с [[digi.wk.potMin]] и [[digi.wk.potSpan]]; [[digi.wk.farnsworth]] для более длинных пауз.",
  "t.28w558c4vr5": "[[win.where]] · «[[win.place.hidden]]»: существует только для панелей главной страницы и для поворотного устройства (для поворотного устройства отключает карточку над «Станцией»; страница «Поворотное устройство» остаётся в меню). «DX-карту», «[[prop.psk]]» и «Дисплей» трансивера скрыть нельзя: их перемещают или оставляют на месте. Чтобы вернуть элемент, выберите «[[win.place.main]]».",
  "t.28z08ckxhcq": "[[wfs.palette.title]]: для создания собственной палитры. У каждой цветовой точки свой выбор цвета и × («[[wfs.removeColor]]»; нужно не менее двух); между одной точкой и следующей цвет плавно нарастает, от 2 до 255 точек. «[[wfs.addColor]]» добавляет одну; «[[wfs.copyColors]]» начинает с цветов палитры, выбранной в меню. Изменение цвета само активирует «[[wfs.paletteUser]]».",
  "t.28z0ewbtpbd": "Под изображением «[[sstv.clean.cleaned]]» показывает его очищенным от шума, даже пока оно принимается; оригинал не меняется.",
  "t.29106by5070": "Wait and Call: при заданном DX и включённом [[ctl.autoseq]] включите [[ctl.wait_call]]. Когда DX вызывает CQ или завершает своё QSO (RR73, RRR, 73), Aurora сама вызывает его, до трёх раз.",
  "t.292xuepvp76": "Строка брандмауэра: если сеть задана как «Общедоступная» или брандмауэр Windows блокирует телефон (это бывает, если Вы нажали «Отмена» в вопросе Windows), строка красная и содержит кнопку «[[net.allow]]» («[[net.allowing]]» во время операции). Windows запрашивает подтверждение: затем Aurora снимает блокировку и открывает порт во всех сетях. Если Вы отмените подтверждение, правило не добавляется: «[[net.allowFailed]]». Когда брандмауэр пропускает телефон, строка зелёная: «[[net.allowed]]». Кнопка действует только на брандмауэр Windows.",
  "t.294uorrnow0": "[[not2.grpColors]] · меню звука (слева от каждого образца): «[[snd.none]]», голос, Ваши файлы или один из звуков Aurora; кнопка ▶ воспроизводит его. Выбор звука также включает оповещение этого типа. Как работают звуки и голос, объясняется на странице «[[sw.pg.alerts]]».",
  "t.294wdwjjob8": "Две вкладки «[[sstv.view.rx]]» и «[[sstv.view.tx]]». Переключение с одной на другую ничего не останавливает: приём продолжается, даже пока Вы составляете изображение, а работа в редакторе не теряется.",
  "t.2962ypc64ar": "Откройте [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], блок [[gen2.bandHop]].",
  "t.296j581dkql": "Текст определяется вероятностным декодером: он держит открытыми наиболее вероятные варианты (скорость от 5 до 60 WPM, стиль манипуляции, слова телеграфного трафика) и выбирает, прослушав ещё два символа; он справляется с гораздо более слабыми сигналами и с ручным ключом. Шумоподавитель импульсных помех убирает атмосферные разряды перед фильтром. Полосу фильтра можно менять на лету из меню «Режим» или из раскрывающегося списка в нижней строке, в том числе широкую (1000 Hz) для обзора.",
  "t.296k9r2p06v": "[[nav.settings]] › [[sw.sec.station]] › [[tab.audio]]: выход и вход на звуковой карте радиостанции (современные Icom, Yaesu и Kenwood: «USB Audio CODEC»).",
  "t.298cyxf5i80": "Колонка «Режим» берётся из комментария спота («FT8 -10 dB», «CW 22 wpm», «VarAC VARA»). Если в комментарии его нет, Aurora смотрит на частоту: вблизи рабочих частот FT8, FT4, JS8, WSPR и PSK31 показывается этот режим; иначе она следует бэндплану IARU Region 1: CW в участках только для CW и SSB в телефонных (FM выше 29,52 MHz). В смешанных участках (цифровые и CW, маяки, спутники) и когда в комментарии только «Digi», колонка остаётся пустой, чтобы не гадать.",
  "t.299344liqlm": "В PSK: ползунок порога шумоподавителя (качество фазы от 0 до 100, по умолчанию 15) с текущим качеством рядом; поле [[digi.band.miPsk]].",
  "t.2993u7g46ue": "[[cat.preset.title]] (только с Hamlib и известной моделью: Icom IC-7300, IC-7610, IC-705, IC-9700; Yaesu FT-991, FT-710, FTDX10, FTDX101, FT-2000; Kenwood TS-590, TS-890): три столбца — [[cat.preset.aurora]] (рекомендуемая скорость, PTT и CI-V), [[cat.preset.radio]] (параметры, которые нужно задать в меню трансивера, записанные по-английски так, как их пишет трансивер) и [[cat.preset.audio]] (какую звуковую карту выбрать; «[[cat.preset.openAudio]]» открывает страницу «Звук»). «[[cat.preset.apply]]» записывает только скорость, PTT и CI-V, но никогда не порт; затем появляется «[[cat.preset.done]]». Используйте её при первой настройке.",
  "t.299vwd5jcqb": "[[digi.mi.controlBar]] (вкл.) показывает или скрывает панель макросов (по умолчанию 4 ряда по 12 клавиш, F1-F12 в первом; «[[digi.mi.macroRows]]» выбирает, сколько рядов показывать).",
  "t.29ae2xe57j3": "Щелчок по строке переводит приём на этот сигнал (строка слушаемого сигнала выделена); строки станций, вызывающих CQ, выделены иначе. Двойной щелчок открывает «[[digi.band.history]]».",
  "t.29c31girjrp": "Станции в эфире на карте мира, цвета как в Band activity: со временем они блёкнут, и дуга соединяет их с Вами. Фон, яркость, серая линия, квадраты проведённых (жёлтые) и подтверждённых (зелёные) связей по диапазонам и режимам находятся в панели; ⚙ открывает остальное (автоматическая ночная карта, сумерки, Луна). Щёлкните по точке: квадрат, расстояние, страна и зоны. «Propagation» показывает тепловую карту тех, кто Вас принимал (PSK Reporter), со Spot RX, максимальным возрастом и линией от Вашей станции к каждой; «Who calls whom» рисует пунктирную линию между двумя станциями каждого вызова (цвета, толщина и скорость в меню ⚙); квадраты в эфире — QSX, CQ, CQDX или QRZ, как сказано в легенде внизу слева.",
  "t.29d65zls4xz": "[[cat.connect]]: подключает трансивер с применёнными значениями (если есть неприменённые изменения, сначала применяет их). При открытии PTT выключается, и в течение 5 секунд передача не принимается. При Hamlib кнопка остаётся недоступной, пока Вы не выберете модель. [[cat.disconnect]]: выключает PTT, снимает сплит и освобождает порт: нажмите её, когда порт трансивера должна использовать другая программа.",
  "t.29dg91r0c9m": "Если Aurora сообщает, что порт занят или доступ запрещён, этот COM-порт уже использует другая программа (или другая копия Aurora): закройте её или разделите радио, как описано выше. Если сообщается, что порт не существует или не найден, Windows, возможно, изменила его номер: обновите список портов, проверьте, что радио включено и кабель подключён, и снова выберите COM-порт. В Linux «Permission denied» не означает, что порт занят: у вас нет прав на его использование. Решение: добавьте своего пользователя в группу dialout командой «sudo usermod -aG dialout $USER», затем выйдите из системы и войдите снова (см. «Последовательные порты: Windows и Linux (группа dialout)»).",
  "t.29dpsfbrs0h": "Возраст сообщений и новые сообщения внизу",
  "t.29e8yllybml": "Linux, «Permission denied»: это не значит, что порт занят, а значит, что Вашему пользователю не разрешено использовать /dev/ttyUSB* и /dev/ttyACM*. Это разрешение даёт группа «dialout». Откройте терминал и введите: sudo usermod -aG dialout $USER. Затем ВЫЙДИТЕ из системы и войдите снова (или перезагрузите ПК): без выхода новая группа не применяется. Проверьте командой groups: dialout должна быть в списке.",
  "t.29ewnt4619m": "Пункты, которые открытое соревнование не использует, затенены и не могут быть изменены (наведите на один из них, чтобы прочитать «Not used by this contest»): например, в ARRL 10-Meter Contest остаются активными только CW и телефон, диапазон 10 м и обмен со штатом или провинцией, а RTTY, PSK, остальные диапазоны и подсказки зон CQ и ITU выключены. У входящих в поставку соревнований правила подсчёта очков и счётчики доступны только для чтения, с правилами, показанными вверху: [[ctest.ro.copy]] создаёт копию, которую можно редактировать.",
  "t.29gm646lvp0": "Aurora поворачивает антенну с помощью rotctld из Hamlib (того же Hamlib, что и для CAT): на DX-станцию, по длинному пути или туда, куда Вы щёлкнете.",
  "t.29hnc4ubx2k": "Выберите соревнование в меню [[ctest.menu]]: Aurora сама настроит диапазоны и обмен.",
  "t.29j8jsrkd5a": "UltraFOX",
  "t.29jg8hff56r": "Приём: F11 (<QTCREAD>) открывает вкладку [[qtc.receive]]. QRV говорит, что Вы готовы; когда серия пришла, [[qtc.grab]] считывает из окна приёма заголовок «QTC n/m» и строки (с пробелами или тире, повторённые или нет). Исправьте вручную то, что нужно: неполные строки краснеют. AGN рядом со строкой просит повторить её, AGN ALL — все, AGN QTC — заголовок. [[qtc.saveReceived]] сохраняет серию и передаёт подтверждение.",
  "t.29joipc7j4t": "RTTY: движок сам передаёт переключение на цифры там, где нужно, команда ничего не добавляет",
  "t.29k7q3taryr": "Что не отправляется никогда: позывной, локатор, декодированные сообщения, журнал QSO, ALL.TXT, настройки, пароли и ключи, IP-адреса, электронные адреса, имя пользователя Windows и минидампы (они содержат память программы).",
  "t.29kva7b2i63": "Некоторые контесты (например, ARRL VHF) допускают FT8 наряду с MSK144 и Q65: они появляются в обеих ветвях, и форма одна и та же.",
  "t.29l2bu6gcvk": "Когда Вы наводите курсор на водопад, две белые линии показывают ширину сигнала; при включённом «[[wfs.freqOn]]» появляется также частота в Hz под указателем. Линии и маркеры выключаются с помощью «[[wfs.barsOn]]» (подписи остаются).",
  "t.29m0f0lipne": "«Voice» произносит оповещение и позывной по фонетическому алфавиту (например, «New DXCC! Zulu Six Two November Sierra»). Работает без интернета.",
  "t.29m0h15c0nd": "[[seq2.group]] · [[seq2.answerCq]], [[seq2.answerInCall]], [[seq2.sentRReport]], [[seq2.sentRR7373]] (четыре строки, у каждой флажок и число от 1 до 5 «[[seq2.times]]»): число — это максимальное количество передач одного и того же сообщения в этой ситуации; при превышении следующая передача не уходит, и последовательность возвращается к поиску среди CQ или останавливается. Число можно ввести только при отмеченном флажке. Заводские настройки: первые две выключены (при включении 2 и 3 раза), последние две включены на 5 раз. Они не действуют для нужных станций и новых DXCC, которых Вы продолжаете вызывать, пока они не ответят. Включите первый, чтобы не настаивать на том, кто не отвечает на Ваш вызов; последний оставьте включённым, так как многие станции никогда не посылают заключительный 73.",
  "t.29me59w0bqf": "Телефон: касание сообщения отвечает; два быстрых касания STOP останавливают передачу и также освобождают DX.",
  "t.29mingwu2o": "[[cat.port]]: COM-порт радио. [[cat.baud]]: такая же, как в меню CAT радио. У Icom адрес CI-V ([[cat.civ]]) записывается в ДЕСЯТИЧНОМ виде (IC-7300 = 148, а не 94h): см. «Адрес CI-V радио Icom (в десятичном виде)».",
  "t.29pj7b7xj9c": "[[digi.log.cols]]: значок карандаша открывает список столбцов для показа (QSO, Mode, Band, Frequency, Date, UTC, Callsign, Name, QTH, Country, Locator, RST sent, RST received). По умолчанию отсутствуют Band, Country и Locator. Внутри есть также «[[digi.log.fitAll]]» и «[[digi.log.resetWidths]]». В соревновании есть также «[[digi.log.exs]]» и «[[digi.log.exr]]».",
  "t.29qq1mmqokp": "Откройте [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] и выберите «[[rot.set.connection]]»: «[[rot.set.launch]]», если ротор подключён к этому компьютеру, «[[rot.set.remote]]», если rotctld уже запущен (в том числе на другом компьютере); затем впишите адрес в «[[rot.set.host]]» (127.0.0.1, если это этот компьютер) и порт в «[[rot.set.tcpPort]]» (по умолчанию 4533).",
  "t.29r8jbu8671": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]]. Здесь Aurora отправляет каждую записанную QSO прямо в онлайн-журналы, без промежуточных программ, и читает базу данных Log4OM. Одна строка — один сервис: индикатор, название со знаком «?», поля, «[[ens.test]]» и результат. Изменения сохраняются кнопкой «[[sw.save]]» внизу окна. Пароли и ключи используются, только если Windows защищает секреты на Вашем ПК (без этого такие сервисы не отображаются); для LoTW это не требуется.",
  "t.29uml83vhoy": "В панели [[panel.tx]], под DX, «[[tx.queue]]» перечисляет ожидающие станции с их номерами. Их вызывают одну за другой, как только текущее QSO записано в журнал.",
  "t.29w34io3g4v": "Подключение, частота и часы вверху слева",
  "t.29wcqhwibo1": "Блок «[[prop.psk]]»: карта с линией и точкой для каждой станции, принявшей Вас (PSK Reporter), и таблица со столбцами «[[prop.col.when]]», «[[prop.col.who]]», «[[prop.col.band]]», «[[prop.col.snr]]» и «[[prop.col.distance]]». Если приёмов нет, сообщается, что за последние часы Вас не принимала ни одна станция. Новые приёмы приходят в течение нескольких секунд.",
  "t.29xmolx0f09": "[[digi.spot.info]]: режим и короткий комментарий; по умолчанию содержит название режима (PSK31, RTTY, CW).",
  "t.29zsdycnkvw": "Приём: текст приходит посимвольно и сам прокручивается вниз. Неуверенные символы появляются более светлым оттенком (бледнее). Двойной щелчок по позывному помещает его в текущее QSO и запрашивает имя, QTH, локатор и страну.",
  "t.2a005jnjipp": "Как изменить язык или размер текста?",
  "t.2a04osblb2s": "Кнопка остаётся подсвеченной, пока работает тюнер.",
  "t.2a08rfk4zps": "[[digi.mi.slashedZero]] (вкл.): ноль в окнах приёма и передачи перечёркнут, чтобы его не путали с буквой O в позывных.",
  "t.2a1wt6ayp4g": "Панель [[panel.station]] имеет вверху три больших числовых поля, а под ними ряд кнопок. Это полная версия раздела «Панель «Команды»».",
  "t.2a23eeytz4q": "Строка состояния",
  "t.2a267i3u37b": "«[[rbn.server.title]]» (по умолчанию выключено): Aurora работает как telnet-кластер на выбранном порту (по умолчанию 7300) и отправляет в формате строк RBN (DX de YOURCALL-#: частота, позывной, режим, дБ, WPM, CQ, время) станции с CQ, проверенные Aurora BIGScan в CW и RTTY. В программе ведения журнала добавьте кластер 127.0.0.1 с этим портом и войдите со своим позывным; «[[rbn.server.lan]]» открывает его для других домашних компьютеров. Отправка в RBN: сеть принимает споты только от собственной программы сбора, которая читает их с telnet-порта поддерживаемых автоматических приёмников (а для FT8 — из декодирований по UDP); чтение сервера Aurora этой программой не проверялось, и сеть может его не принять, поэтому Aurora не отправляет споты в RBN.",
  "t.2a5rv882vw5": "Двойной щелчок по строке или «[[exp.edit.btn]]»: открывает окно для исправления или удаления этого QSO (см. «Окно исправления или удаления QSO»).",
  "t.2a6i92r2swj": "Хотите полностью отключить цвет какого-то типа? В таблице предыдущего раздела снимите флажок «[[not2.colHighlight]]» в этой строке и нажмите «[[sw.save]]».",
  "t.2a9w69ww8ry": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]: [[cat.backend]] FT-991(A) Link (UDP), [[cat.ft991.address]] 127.0.0.1:50001 (или заданный в FT991Link), затем [[cat.connect]].",
  "t.2ad7lperylj": "В ряду вкладок справа находится выпадающий список частот только с разрешёнными диапазонами и небольшой блок RX/TX: зелёный «RX» при приёме (щелчок освобождает текущее QSO, как «Clear DX»), красный «TX» при передаче (щелчок сразу останавливает её).",
  "t.2ae4yd2gj6n": "при открытии страницы текстовых режимов",
  "t.2agfc84lfkq": "[[sw.digi.perMode]] · PSK31 · PSK63, «[[digi.band.miPsk]]» (по умолчанию включено): декодирует каждый сигнал PSK31 или PSK63 в звуковой полосе собственным приёмником и строит список сигналов рабочей страницы. Выключите, если ПК медленный и достаточно одного сигнала за раз.",
  "t.2agmwjdl4zt": "Выберите свободное место на водопаде правой кнопкой (красная полоса).",
  "t.2ahi00pgr86": "Блоки CQ расположены в два ряда и сами прокручиваются вперёд и назад, если их слишком много (останавливаются, когда над ними мышь): в каждом блоке флаг, позывной и страна; сообщение, рапорт и время указаны в подсказке. Цвет соответствует цвету новости. Двойной щелчок: Вы отвечаете. Щелчок правой кнопкой: в очередь. Станция, не слышимая 15 минут, исчезает.",
  "t.2ahk19xvg8w": "[[fil.worked]]; с «[[fil.workedAll]]» исчезают и их обмены с другими станциями.",
  "t.2ai1xkvmggn": "Кнопка частоты рядом с переключателем режимов показывает диапазон и MHz и открывает список всех частот текущего режима, сгруппированных по диапазонам: стандартную и альтернативные (в том числе для DX-экспедиций); основная частота каждого диапазона отмечена цветной точкой. Выберите одну, и Aurora настроит радиостанцию на неё. Редактируйте список в Настройки › Режимы › Общие для всех режимов › Частоты.",
  "t.2ai4e3rn7rv": "Метка приближающегося спутника и звук на каждой странице: это опция, по умолчанию выключена. Включается флажком «[[sat.alert.bar]]» в [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › «Tracking and rotator» (группа «[[sat.alert.title]]») и в панели с колокольчиком этой страницы. Когда она включена, метка с обратным отсчётом (по умолчанию за 5 минут до пролёта) появляется на любой странице, в свободном месте посередине верхней панели, только для отмеченных спутников. Щелчок выбирает этот спутник и открывает страницу «Спутники»; ✕ закрывает метку; она сама исчезает через минуту после восхода. Когда опция выключена, оповещения остаются только на этой странице.",
  "t.2ake1tgchk3": "время UTC (ЧЧММ) предыдущего QSO с этим позывным",
  "t.2akh9th7n56": "Вручную: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › «[[dec.depth]]», три пункта «[[dec.depth1]]», «[[dec.depth2]]» и «[[dec.depth3]]» (по умолчанию Deep; Q65 всегда использует глубокий). Чем глубже, тем больше слабых сообщений находится и тем больше используется процессор. Если FT8 хорошо работает только с «[[dec.depth1]]» или «[[dec.depth2]]», это означает, что ПК ниже рекомендуемых требований (4 ядра и 8 ГБ; Aurora декодирует всеми процессорами, кроме одного).",
  "t.2amnb881j8m": "При 0 («[[sstv.tune.auto]]») Aurora следует за настройкой сама по синхро; если ползунок не на 0, действует Ваша поправка. Когда радио меняет частоту, ползунок возвращается на 0. Изображение, уже сохранённое в истории, остаётся как было.",
  "t.2ao7fnv2z0y": "Откройте [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › вкладка радио, группа «[[sat.knob.title]]», и проверьте, что флажок «[[sat.knob.on]]» включён (снимите его, если не хотите, чтобы Aurora следовала за ручкой).",
  "t.2aon5agjsb1": "Тоны и полоса меняются в меню [[digi.menu.mode]] (пункты «[[digi.olivia.tones]]» и «[[digi.olivia.bandwidth]]», которые появляются только в Olivia и Contestia), двумя списками в строке состояния или в окне «[[digi.ms.title]]». Olivia и Contestia хранят каждый свои значения. В макросах действуют <SET TONES:n>, <SET BW:Hz> и <SET SUBMODE:OLIVIA-8-250>.",
  "t.2ap4rqp1ib8": "Откройте «Безопасность Windows» (найдите её в меню «Пуск») › «Защита от вирусов и угроз» › «Журнал защиты».",
  "t.2apjiphfq94": "В программе SDR включите сервер TCI (обычно порт 40001) и поток I/Q на 96 kHz; настройте SDR на центр участка, который нужно слушать (например, 144,100 MHz).",
  "t.2apzlz7zkcm": "[[sup.title]] · [[sup.sendMail]]: серая, пока адрес в «[[sup.email]]» неверен. Подготавливает пакет (если Вы не создавали его менее 5 минут назад — тогда использует его повторно), показывает его в Проводнике и открывает во вкладке браузера Gmail с уже написанными получателем, темой и текстом (версия, позывной, трансивер, PTT). Zip сам не прикрепляется: перетащите его в сообщение. Почтовая программа не нужна, но нужен Gmail.",
  "t.2argorylobz": "Флаг, страна, расстояние, азимут, DT, возраст вместо времени, Ваши собственные передачи в списке и пустая строка между двумя периодами включаются и выключаются в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Пустое состояние гласит «[[decode.empty]]» (или, в JT65 и JT9, что сообщения приходят в конце минуты).",
  "t.2at251u72qg": "тексты на картинке пишутся на странице SSTV: команда открывает её",
  "t.2av7dzvquyq": "Используйте режим Fox, только если Вы действительно экспедиция и объявили об этом: на обычном диапазоне он создаёт помехи.",
  "t.2axxq6uinl": "Одна радиостанция, несколько программ",
  "t.2ay2195oeeg": "Станция, вызывающая CQ, остаётся в списке, пока читается, даже если читаются лишь части позывного или с ошибочным символом; отвечающие станции её не удаляют. CQ, прочитанный в главном окне RX или в дополнительных окнах RX, всегда появляется в списке.",
  "t.2azbozybpk": "SSTV: панель «[[sstv.log.title]]»",
  "t.2azs9jgpbk0": "Вторая часть страницы [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]: настоящие цвета каждого типа сообщений, цвета карты и полоса пользователей LoTW. Всё здесь применяется сразу.",
  "t.2b0gnoalz6a": "На странице [[nav.rotator]] кнопка «[[rot.onStation.on]]» / «[[rot.onStation.off]]» убирает или показывает карточку над страницей Station. У карточки есть строка заголовка: кнопка свёртывания закрывает или снова открывает её («[[rot.close]]» / «[[rot.open]]»); крестик скрывает её («[[rot.hideStation]]»); если карточка плавающая, её перемещают за строку заголовка (двойной щелчок — вернуть на место), а размер меняют за угол («[[rot.resize]]»); кнопкой ⧉ она переносится в отдельное окно. На телефоне и планшете карточки на странице Station нет: Вы пользуетесь этой страницей.",
  "t.2b0gvzmdowi": "Если Aurora закрылась сама и Вы просили уведомлять об этом, при перезапуске появляется окно «[[rep.crashTitle]]» с тремя кнопками: «[[rep.crashSend]]» (отправляет отчёт), «[[rep.show]]» (показывает, что было бы отправлено, прежде чем Вы решите) и «[[rep.no]]».",
  "t.2b0ybm69e7k": "Страница [[nav.stats]] подводит итоги по журналу. Если Aurora не находит журнал QSO, она пишет «[[stats.unavailable]]».",
  "t.2b1dgatwn6v": "[[snd.title]] · сообщение «[[snd.off]]»: появляется над таблицей, когда «[[alert.button]]» выключен; напоминает, что никакой звук не запускается сам, а проверка ▶ работает всегда.",
  "t.2b24nd8nolq": "В Настройках много страниц, разделённых на семейства. Вверху есть поле «[[sw.search]]»: введите слово из названия параметра (диакритика не важна), и появится список параметров, найденных на всех страницах.",
  "t.2b41az7zasi": "[[fil.grp.both]] · [[gen.showAge]]: флажок, по умолчанию выключен. В [[panel.all]] и [[rxw.title]] первый столбец показывает возраст сообщения (45 с, 3 мин) вместо времени UTC и обновляется сам; наведите курсор, чтобы увидеть время. Это тот же флажок, который есть в блоке [[gen.screen]].",
  "t.2b4corn2m2f": "Выпадающий список «[[contest.choose]]» перечисляет контесты по группам и по дате начала; выберите один, и, если контест уже включён, произойдёт переключение на этот. Рядом «[[contest.how]]» открывает карточку с тем, что отправляется (с примером), временем в UTC и местном времени, продолжительностью, максимальным числом часов, минимальным перерывом и ссылкой на официальные правила.",
  "t.2b4k8fgn2is": "[[fil.decode]] · [[dec.autoClearAvg]]: флажок, по умолчанию выключен. В Q65 новое сообщение на частоте приёма очищает среднее своей чётности, так что следующее QSO начинается с чистого листа. Включите, если проводите несколько QSO подряд при включённом усреднении; рядом с режимом есть кнопка «Auto ⟲».",
  "t.2b7bt5j443q": "Щелчок по главе в оглавлении прокручивает к ней. В статьях используются настоящие названия кнопок и блоков (те же, что Вы видите на экране): если искать название блока, Вы найдёте статью, которая его объясняет.",
  "t.2b94upr6wkv": "«*» — это символ, которого нет в азбуке Морзе: если их много, проверьте, что тон находится внутри полосы фильтра, или включите АПЧ.",
  "t.2b9j3f8i019": "«[[logio.export]]»: открывает страницу экспорта внутреннего журнала: выберите QSO и сохраните их как файл ADIF, где Вам удобно (для резервной копии или для загрузки в другую программу).",
  "t.2bbvzhr5g66": "открывает дополнительное окно RX на частоте приёма",
  "t.2bczmuc2ube": "Спутники: страница по панелям",
  "t.2bdl46jl2g8": "Wait and Reply и [[ctl.wait_call]]",
  "t.2bgenbx171q": "Полная статья: о звуках и всплывающих сообщениях — «Выключение или изменение оповещений: выделенные карточки, звуки, цвета, сообщения». Как работают карточки — «Новый DXCC и желанная станция: выделенные оповещения».",
  "t.2bh6ldyhkos": "[[ctl.ap_list]] и [[ctl.mtd]]: появляются только в FT8. «a7/a8» — декодирование по списку (находит сигналы примерно до −24 dB; найденные так сообщения отмечены звёздочкой); «Multithread» декодирует на всех процессорах ПК: те же сообщения за меньшее время на загруженных диапазонах.",
  "t.2bmcu2lqo80": "Слабый ПК",
  "t.2bpa6k6kj0c": "Как выключить оповещения о новом DXCC в правом верхнем углу?",
  "t.2bpke0mfbez": "Файлы и сценарии: тексты, случайные строки, значения INI и сценарии макросов из папки текстов макросов; ожидания по принятому тексту. Пример: <RANDOM:frasi.txt> или <OnRX:*QRZ*,F3>.",
  "t.2bq4an6ime0": "[[cmd.report]]: dB, которые Вы отправляете. Aurora задаёт их по принятому сигналу; изменённые вручную, они применяются сразу.",
  "t.2bqaizwuc5q": "[[sw.contest.title]] · [[contest.set.holdTx]] и [[contest.set.rrr]]: два флажка. [[contest.set.holdTx]] (по умолчанию включён) удерживает частоту передачи неизменной во время контеста; [[contest.set.rrr]] заставляет QSO завершаться RRR (включается сам в контестах, правила которых этого требуют).",
  "t.2bs5eqzdp8x": "На вкладке журнала Вы видите последние QSO, из Log4OM2, если Aurora читает его журнал (только чтение), иначе из внутреннего журнала Aurora. Столбцы: «[[log.col.date]]», «[[log.col.call]]», «[[log.col.band]]», «[[log.col.mode]]», «[[log.col.rst]]» (отправленный и полученный), «[[log.col.country]]». Заголовки перетаскиваются и меняют размер так же, как в DX Cluster; щелчок правой кнопкой по заголовку сбрасывает их.",
  "t.2bsbgy9z8xj": "[[sw.wspr.beacon]] · [[mode.wsprPct]]: числовое поле от 0 до 100, заводское значение 20. Это процент периодов, в которых маяк передаёт (при значении ниже 40 % две передачи подряд не бывает). Отправляется при нажатии Enter или выходе из поля; Esc отменяет; пустое поле ничего не меняет. Маяк передаёт только при включённом [[ctl.enable_tx]]: при 0 Вы только слушаете.",
  "t.2bu4vemnore": "Пульт дистанционного управления: все кнопки",
  "t.2bujz0z2fyg": "После QSO CQ возобновляется сам, только если включён [[ctl.auto_tx]].",
  "t.2bv68rg6q5u": "CW и RTTY: отправляемый символ отмечается вместе со звуком",
  "t.2bxipwxugoe": "«[[cop.columns]]»: по одному полю на столбец ([[cluster.col.by]], [[cluster.col.freq]], [[cluster.col.call]], [[cluster.col.country]], [[cluster.col.mode]], [[cluster.col.comment]], [[cluster.col.time]]). По умолчанию все видны; хотя бы один должен оставаться включённым.",
  "t.2bxlau1uxbl": "Исправление или удаление QSO",
  "t.2bxlh7u6234": "Проверьте «Защиту передачи»: активная защита может блокировать Tx.",
  "t.2byz50l6nue": "частота передачи (VFO B, сплит) в кГц",
  "t.2c1ll6zhiu9": "[[seq2.stop]] · [[seq2.haltReplyOther]] (по умолчанию включено): если станция, которую Вы вызываете, отвечает кому-то другому, Вы перестаёте её вызывать, а не настаиваете. Если выключено, передача останавливается, только когда другая станция работает вблизи Вашей частоты передачи (около 50 Hz в FT8, 84 Hz в FT4).",
  "t.2c412xf6at5": "[[sw.pg.sdr]]",
  "t.2c6n3daq1f9": "При «[[rot.set.launch]]»: [[rot.set.search]] и [[rot.set.model]]. Введите часть названия (например, GS-232 или Yaesu) и щёлкните ротор среди результатов или выберите из списка («[[rot.set.none]]» в начале). Это модели ротора или его интерфейса (GS-232, EasyComm, SPID…); «Hamlib Dummy» служит для проверки без ротора. Строка ниже сообщает, сколько моделей знает Hamlib.",
  "t.2c7bagwlhvb": "«[[lay.options]]» · «[[wish.bands]]» (по умолчанию пусто = все диапазоны): впишите диапазоны через запятую, например 20m, 15m; оповещения срабатывают только на них. «[[wish.cooldown]]» (по умолчанию 15, от 1 до 240 минут): после оповещения о станции Aurora столько ждёт, прежде чем снова оповестить Вас о ней же; так станция, дающая CQ каждые 15 секунд, оповестит Вас один раз. Неверное значение показывает красное предупреждение и не сохраняется.",
  "t.2c9hhmwr4m0": "[[digi.menu.edit]] › [[digi.mi.clearRx]]: очищает окно приёма (также правым щелчком внутри окна).",
  "t.2cazgx9b23d": "Последние три категории учитывают «[[agent.quiet]]»: в эти часы ничего не появляется. «Icon only» не показывает карточку и записывает заголовок в подсказку значка.",
  "t.2cc3cerk1m6": "Чтобы задать режим принудительно, выберите его и нажмите «[[sstv.rx.force]]». Готовые изображения попадают в «[[sstv.hist.received]]», в колонку справа (внизу страницы в узких окнах и на телефоне); щёлкните по изображению, чтобы увеличить его, очистить от шума, сохранить или ответить.",
  "t.2cd68ucu2rn": "Фильтры в одной строке: поле «[[exp.search]]» (фильтрует по мере ввода), «[[exp.from]]» и «[[exp.to]]» (даты UTC; можно задать только одну из двух), «[[exp.band]]» и «[[exp.mode]]» (заполняются диапазонами и режимами, которые есть в Вашем журнале). «[[exp.clear]]» появляется только когда активен фильтр и убирает их все.",
  "t.2cf01w07pll": "запускает указанный макрос, если с этим позывным уже была связь",
  "t.2ch4m9usxak": "Столбец «[[ctl.grp.seq]]»: [[ctl.autoseq]] (последовательность идёт сама: рапорт, R+рапорт, RR73, 73, и QSO попадает в журнал, когда уходит Ваше RR73 или 73); [[ctl.single_qso]] (после завершённого QSO Aurora прекращает передачу); [[ctl.answer_all]] (каждая станция, которая Вас вызывает, попадает в очередь); [[ctl.answer_b4]] (отвечает также тем, с кем Вы уже проводили связь); [[ctl.bypass]] (пропускает проверку сообщений от станций, которых нет в списке); [[ctl.skip_tx1]] (при ответе на CQ начинает с Tx2 вместо Tx1; выключено в Hound); [[ctl.rrr]] (завершение — RRR вместо RR73); [[ctl.tx_period]] (один щелчок переключает между двумя периодами передачи: «Tx 00/30» или «Tx 15/45»; когда Вы отвечаете станции, нужный период устанавливается сам).",
  "t.2cj1e9rk1as": "[[not2.grpDisplay]]",
  "t.2cjubxqyjmg": "[[ctl.split]]: включено (подсвечено) — частота передачи отделена от частоты приёма. Касание включает и выключает.",
  "t.2cprgy2f5po": "Другая станция и предыдущее QSO: расстояние, направление, OM или YL и данные последнего записанного QSO (имя, QTH, рапорт) и более раннего QSO с тем же позывным на том же диапазоне и в том же режиме. Пример: <CALL> DE <MYCALL> QRB <DIST> KM <ONQSOBEFORE:F9> запускает F9, если позывной уже в журнале.",
  "t.2cpzz4u5ug4": "DX Map: панель команд и шестерёнка",
  "t.2cqfi5td91b": "Глубина ([[dec.depth]]) и одиночное декодирование ([[dec.singleDecode]]) находятся на странице [[sw.sub.ft8]] › [[fil.decode]]; одиночное декодирование применяется и к Q65. Контесты УКВ находятся на странице [[sw.sub.vhf]] › [[sw.pg.contest]].",
  "t.2cr7hvt9vae": "[[toast.grp]]",
  "t.2crv3ns50s3": "Вверху строка «[[net.waiting]]», пока телефон не свяжется; внизу совет: «[[net.tips]]»",
  "t.2cthvm684ff": "SSTV: истории «[[sstv.hist.received]]» и «[[sstv.hist.sent]]»",
  "t.2cu85j9bfa1": "Полная статья: «Звуковая карта»; «Ползунок TX Lvl»; «[[sw.tab.audio]]»; «Передаёт, но мощность нулевая».",
  "t.2cu9fbyvd16": "«[[ens.g.wavelog]]» · «[[ens.k.WavelogSend]]» (по умолчанию выключено): отправляет каждую QSO в Wavelog или Cloudlog (тот же API). «[[ens.k.WavelogUrl]]» — адрес, по которому Вы открываете сайт (с /index.php или без). «[[ens.k.WavelogKey]]» — ключ API с правом чтения и записи, создаётся в меню пользователя в разделе «API». «[[ens.k.WavelogStation]]» — выпадающий список станций, считанных с сервера (адрес и ключ должны быть уже сохранены): выберите свою; кнопка с двумя стрелками («[[ens.wl.read]]») перезагружает список. Если сервер не отвечает, список превращается в поле, где Вы вводите номер (station_profile_id), с указанием причины и кнопкой «[[ens.wl.read]]» («[[ens.wl.reading]]» во время чтения). Номер, которого нет на сервере, помечается «[[ens.wl.unknown]]». «[[ens.test]]» проверяет ключ и станцию, не записывая в журнал.",
  "t.2cuwemslunb": "Aurora пробует и те сообщения, которые ожидает: так она читает более слабые сигналы, чем обычно.",
  "t.2cw6em54wa2": "После срабатывания [[ctl.wait_call]] выключается: включите его снова, чтобы ждать ещё раз.",
  "t.2cxhbcch408": "Перезагрузите страницу в браузере телефона.",
  "t.2cy49mm5uf4": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]] › [[sw.pg.images]]. Что сохраняется из изображений и в какие папки. Изменения проходят кнопкой «[[sw.save]]» внизу окна.",
  "t.2cyynnkxskx": "Агент в трее: значок и меню",
  "t.2czjn0ggihu": "принятый обмен, в котором цифры, сокращённые в CW, возвращены в обычные (T и O = 0, A = 1, N = 9), затем текст",
  "t.2czlhquwaxz": "Водопад с полосами Rx и Tx, низкий, под сообщениями.",
  "t.2d05egqawi2": "В таблице есть строка для каждого режима (FT8, FT4 и DIG — прочие цифровые режимы) и столбец для каждого диапазона, от 160 m до 4 m плюс «U» (диапазоны короче 4 m). Если станция выбрана, показывается её страна: зелёный = связь проведена (и подтверждена, либо журнал ничего не сообщает о подтверждениях), оранжевый = связь проведена, но не подтверждена, серый = никогда. Если станции нет, показывается, сколько стран проведено в каждой ячейке.",
  "t.2d0mswp5ay0": "Если появилось предупреждение «ПК не успевает декодировать», нажмите «[[diag.slow_pc.to2]]»: глубина декодирования снизится до «Обычно» (её можно изменить и в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › «[[dec.depth]]»). Если предупреждение вернётся, нажмите «[[diag.slow_pc.to1]]». Aurora никогда не меняет её сама. Помогает также включить многопоточность, выключить SWL и a7/a8 и закрыть тяжёлые программы (браузеры с множеством вкладок, игры, видеозвонки).",
  "t.2d220vjotqe": "[[fil.decode]] · [[dec.singleDecode]]: флажок, по умолчанию выключен. Хотя он находится на этой странице, он действует на JT65 и Q65: они ищут только вокруг частоты приёма (в пределах F Tol) и останавливаются на первом сообщении. Включите, если в JT65 или Q65 хотите декодировать только сигнал, на котором находитесь; на FT8 и FT4 он не влияет.",
  "t.2d280rwlj8w": "Меню [[digi.menu.file]], [[digi.menu.edit]], [[digi.menu.configure]] и [[digi.menu.help]]",
  "t.2d3an0st1y1": "Строка состояния рядом с кнопками: показывает результат двух проверок; если есть несохранённые изменения параметров движка, вместо этого показывает, сколько их («n changes to apply»).",
  "t.2d3zxdlh24j": "Режим MSK144 (метеорная связь)",
  "t.2d62y3ela4x": "Начало декодирования и Full duplex",
  "t.2d7e7t4wnc1": "На спотах FT8 и FT4 DX-сплит не используется: DX-экспедиции работают в Fox/Hound, а сплитом радиостанции Aurora управляет из Настройки › Станция › Радиостанция. При выключенном переключателе спот только настраивает частоту, а метка «UP 5» — просто информация.",
  "t.2d7uf3nns9s": "Где менять режим, диапазон, язык, звуки и тему.",
  "t.2d9ovvfqw51": "После первой передачи появляются три точки («[[tx.chain.title]]»): «[[tx.chain.mode]]», «[[tx.chain.audio]]» и «[[tx.chain.ptt]]». Зелёный — всё в порядке, красный — проблема, серый — радио не сообщает (VOX, OmniRig или радио, которое не отвечает). Причину можно прочитать во всплывающей подсказке при наведении. Aurora также записывает в журнал пик звука и состояние PTT, считанное с радио.",
  "t.2dca1i4hu67": "[[ap.text]] · [[ap.fontUi]]: шрифт меню, подписей и кнопок. По умолчанию IBM Plex Sans; варианты: System UI, Segoe UI, Verdana, Tahoma, Arial, Calibri. Если его нет на компьютере, используется наиболее похожий; из интернета ничего не загружается.",
  "t.2dd993mqjoi": "«[[cmd.tune]]»: появляется, только если Вы включили её в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Передаёт несущую для настройки антенны; повторное нажатие останавливает её; длится не более 2 минут, и передача должна быть открыта.",
  "t.2del8sdimr3": "В панели журнала выберите «Map»: станции, передающие свой локатор, появляются с позывным, цветом новизны (как в Band activity); у вызывающих CQ есть рамка.",
  "t.2dfcj401ku3": "Переход к станции из очереди",
  "t.2dfwl3gz3ze": "«[[ens.g.tcp]]» · «[[ens.k.EnableTCPConnection]]» (по умолчанию выключено), «[[ens.k.TCPServer]]» (127.0.0.1) и «[[ens.k.TCPServerPort]]» (52001): отправляет каждую записанную QSO в программу ведения журнала по TCP, как JTDX делает с N1MM Logger+: для каждой QSO — новое соединение с сообщением «Log», содержащим запись ADIF; если программа отвечает NAK, QSO отклоняется. Включайте, только если Ваш журнал принимает QSO таким образом. «[[ens.test]]» открывает и закрывает соединение, не отправляя QSO.",
  "t.2dg458a4wkn": "В панели [[panel.tx]], вверху справа рядом с DX, значок показывает RX (зелёный), пока Вы слушаете; во время передачи он превращается в красную кнопку «[[stop.button]] (Esc)».",
  "t.2dh5fku7vyc": "[[digi.mi.capsOnly]] (выкл.): всё, что Вы набираете в окне передачи, и макросы уходят заглавными буквами; полезно в RTTY, где по умолчанию нет строчных букв.",
  "t.2di2swvoeuk": "[[rep.title]]",
  "t.2diwua90zor": "Номер для передачи: в группе [[ctest.g.serial]] задайте [[ctest.f.nrs]]. При включённом [[ctest.f.autoInc]] серийный номер начинается с записанного числа (001, если поле пусто) и увеличивается на единицу при каждом сохранённом QSO; без него всегда передаётся фиксированный обмен.",
  "t.2dn8j0wfrp2": "[[nav.stats]]: цифры Вашего журнала (см. «Статистика и карточка DXCC»).",
  "t.2dnhupy2umv": "Журнал закрыт: QSO придут позже",
  "t.2do1itf2vdh": "[[tab.frequencies]] · [[set.save]]: сохраняет таблицу. Она также сохраняется сама примерно через секунду и при выходе со страницы; кнопка остаётся неактивной, пока Вы ничего не измените. Если появляется «[[freq.invalid]]», таблица не была сохранена: исправьте неверную строку.",
  "t.2dqac6b8dvi": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] включите «[[not2.unconfirmed]]» (и «[[not2.unconfirmedGrid]]» для квадратов): страна, с которой проведена связь, но нет подтверждения (LoTW или QSL в журнале), остаётся «новой DXCC» в цветах, фильтре Band activity и Автоматизации. На DX Map подтверждённые квадраты зелёные, только проведённые — жёлтые.",
  "t.2dqwxlgrvu2": "Большое оповещение о новой DXCC показывается один раз на станцию; в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] выберите «[[not2.popPos]]» и «[[not2.popSound]]». Под карточками новой DXCC (показываются не более двух) есть кнопка «[[newdx.off]]», которая отключает их все; чтобы вернуть их, отметьте «[[not2.popNew]]» в том же блоке «[[not2.grpAlerts]]» (см. «Новая DXCC и искомая станция: выделенные оповещения»).",
  "t.2dr9kuuacvp": "Над списком декодированных сообщений выберите «[[contest.order]]»: «[[contest.order.value]]» показывает только последние два периода, чтобы не слышимые больше станции не оставались сверху; «[[contest.order.time]]» показывает все по порядку времени, самые новые внизу, как в Band activity, и список следует сам, пока Вы не прокрутите вверх, чтобы почитать. Выбор запоминается.",
  "t.2dra90twxoa": "«[[snd.addFile]]» загружает Ваш собственный звук (до 5 MB): он остаётся в списке для каждого оповещения; × удаляет его.",
  "t.2drtg3y6ebq": "Под журналом находится карточка DXCC станции, которую Вы вызываете (см. «Карточка DXCC»). Вкладка «[[log.tab.map]]» показывает DX Map используемого диапазона (см. «Карта в панели «Журнал»»).",
  "t.2drv3hme8w": "дата и время предыдущего QSO с этим позывным на том же диапазоне и в том же режиме (пусто, если нет)",
  "t.2dt57u62w1t": "Ротор: страница и карточка",
  "t.2dtkfixnzrn": "[[ctl.ap_list]] (включено по умолчанию): «a8» ищет вблизи полосы Rx ответы Вашего корреспондента, если заполнены DX Call и DX Grid; «a7» ищет следующие сообщения QSO, услышанных в предыдущем периоде.",
  "t.2dugwn8lxl0": "Кнопка показывается, если радиостанция сообщает, что у неё есть тюнер, или если «[[cat.extras]]» выключено и это неизвестно: если тюнера нет, щелчок объяснит причину.",
  "t.2dv7juu1jq1": "[[digi.edit.title]] · «[[digi.edit.clear]]» очищает подпись, текст и цвет (клавиша остаётся выбранной); «[[digi.edit.cancel]]» закрывает без сохранения; «[[digi.edit.ok]]» сохраняет макрос. Сохранение пустого макроса освобождает клавишу.",
  "t.2dwed4z4exj": "Кнопка [[ssbc.logAll]] показывает весь журнал; [[ssbc.logOnly]] возвращает только QSO контеста. Журнал обновляется сразу после каждого QSO.",
  "t.2dwzs9qtm0j": "[[digi.log.clear]] (красный ✕): очищает данные QSO и возвращает рапорты к 599 (при включённом [[digi.mi.defaultRst]]).",
  "t.2dxw0er8iof": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.autocq]] находится [[tab.schedule]]: список не более чем из пяти моментов времени UTC, в которые Aurora сама меняет диапазон. Обратите внимание: эта страница не заставляет Aurora вызывать CQ; об автоматическом CQ см. ниже «Как заставить Aurora вызывать CQ самой».",
  "t.2e0t0i7wr2n": "Наведите курсор на «?» рядом с пунктом, чтобы прочитать, что он делает; щелчок оставляет пояснение открытым.",
  "t.2e14d3t0tsj": "[[snd.title]] · [[snd.volume]]: ползунок громкости всех звуков Aurora, от 0 до 100% (по умолчанию 50%), без изменения громкости Windows. Это тот же ползунок рядом со значком громкоговорителя внизу справа.",
  "t.2e1eq1gw5ix": "Ничего не приходит: адрес и порт должны совпадать в обеих программах, а прослушивание должно быть запущено в журнале.",
  "t.2e2cxs9k50n": "[[gen2.operation]] · [[gen2.watchdog]] (числовое поле, от 0 до 99, по умолчанию 6): защита от передачи без присмотра. Если в течение этого числа минут Вы ничего не делаете и не приходит нового сообщения, автоматическая передача останавливается. 0 = без сторожевого таймера. Отсчёт начинается заново, когда Вы к чему-то прикасаетесь или приходит сообщение, требующее ответа; увеличьте значение для длительной активности, уменьшите, если Вы часто передаёте без присмотра.",
  "t.2e2ewbx8nlc": "[[digi.mi.echoRx]] (выкл.): передаваемый Вами текст появляется и в окне приёма, строка за строкой, с предшествующим знаком ». Когда выключено, переданный текст остаётся в окне передачи (над полем, как «[[digi.tx.sentTitle]]»).",
  "t.2e2pbeuneo7": "Проводите QSO, даже когда журнал закрыт: Aurora ставит их в очередь.",
  "t.2e40tft2qym": "Если в «[[sup.email]]» указан адрес помощника, «[[sup.sendMail]]» открывает в браузере Gmail с уже заполненным письмом: перетащите в него zip.",
  "t.2e52qb0zx37": "[[not2.grpTable]] · [[not2.colAlert]]: «[[not2.playAlert]]» — решительное звуковое оповещение, призванное не пропустить новинку, даже находясь вдали от ПК; следующий за ним столбец «[[not2.perBand]]» учитывается, только если включён первый, и заставляет оповещение срабатывать также для новинки по диапазону или режиму. Доступно для зоны CQ, зоны ITU, страны, квадрата и префикса; для нового позывного стоит «—». По умолчанию выключено. Работают только при включённом «[[alert.button]]».",
  "t.2e8lox35yt8": "Над водопадом появляются метки спотов DX Cluster, попадающих в видимую звуковую полосу: позывной и отметка на частоте спота. Если места не хватает, споты собираются в одну метку «+N» (наведите курсор, чтобы увидеть список). Щелчок по споту переводит частоту приёма на него (только приём: передачи не происходит).",
  "t.2e8lx2ahqoo": "Aurora может сама поочерёдно переключаться между несколькими диапазонами или частотами, по одному каждые две минуты, чтобы слушать там, где есть активность.",
  "t.2e92k81cws8": "[[digi.ms.receive]] · [[digi.mi.snap]] (по умолчанию включено): щелчок по водопаду рабочей страницы привязывается к ближайшему пику (в RTTY — к паре тонов). Выключите, если хотите, чтобы частота была точно там, где Вы щёлкаете.",
  "t.2e9zhw2njk6": "Введите слово в поле «[[sw.search]]» вверху дерева настроек: останутся только страницы, где оно упоминается. В этой Справке главы «Настройки: …» описывают каждую страницу и каждый пункт в порядке дерева.",
  "t.2eavi3d6zg0": "«[[cluster.servers]]» · «[[cluster.test]]»: проверяет каждый сервер; проверка не входит в кластер и не сообщает Ваш позывной. Запускается сама при открытии страницы и при добавлении сервера; нажмите, чтобы повторить после смены сети или если сервер был недоступен.",
  "t.2ebqyjli9nk": "Звук: записать принимаемый звук, воспроизвести последние секунды, передать файл WAV или тоны DTMF, сохранить принятый текст. Пример: <STARTRECORD:qso> в начале и <STOPRECORD> в конце; <TX><WAVE:cq.wav>.",
  "t.2ecvxrlsbw1": "[[tab.frequencies]] · [[freq.reset]]: ставит вместо текущей начальную таблицу Aurora (исходные строки FT8 и FT4); Ваши собственные строки теряются, как только таблица сохраняется. Используйте, если Вы всё запутали.",
  "t.2edi99hgbvm": "В MSK144 рядом с режимом выберите период T/R (5, 10, 15 или 30 s, как в WSJT-X): он запоминается для каждого диапазона, по умолчанию 15 s на 6 м и 4 м и 30 s на 2 м и остальных диапазонах. Кнопка «Sh» включает короткие сообщения: R+рапорт, RRR и 73 уходят как «<DX MY> R+03» (рапорт округляется до -03, +00, +03, +06, +10, +13, +16), а отправленные Вам декодируются. «Sh» и SWL исключают друг друга. Ваш корреспондент должен использовать тот же период и включить «Sh».",
  "t.2eg8vhnprpk": "[[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]]. Здесь Вы выбираете, откуда Aurora получает звук трансивера (водопад и декодирование) и куда она отправляет звук передачи. Выбор применяется сам через мгновение, без перезапуска; если новое устройство не открывается, остаётся прежнее, и выбор не сохраняется. Выбор сохраняется между запусками. Страница работает с собственным движком Aurora.",
  "t.2egulvy7q5l": "[[agent.tab]]",
  "t.2ei8shrmg6s": "BBLogger (бесплатный итальянский журнал, сайт aribusto.it, сейчас его развивает IZ2BKT) получает QSO из Aurora так же, как из WSJT-X и JTDX. Нужны две вещи: получатель в Aurora и «интерфейс Wsjtx» в BBLogger с одинаковыми адресом и портом.",
  "t.2ej5dl6kg23": "сохраняет QSO в журнал (как <SAVEQSO>)",
  "t.2emb7wzh83v": "AFC: следует за сигналом, когда он уходит по частоте. Lock: частота передачи остаётся неизменной. Snap: щелчок по водопаду захватывает пик. Это три переключателя; объяснение есть в меню [[digi.menu.options]].",
  "t.2eov9vdvqgz": "Вкладка «[[contest.analysis]]»: выберите «[[contest.an.edition]]» (или активный контест) и читайте QSO, множители, очки, неуверенные QSO и активные часы; график показывает QSO по часам (зелёный = лучший, оранжевый = худший), затем «[[contest.an.band]]», «[[contest.an.best]]» и «[[contest.an.lost]]» (пропуски более 15 минут без QSO), с советом.",
  "t.2epnrn7gpk0": "Обмен, передаваемый в контесте. Если поле пусто, Aurora использует порядковый номер: последний отправленный номер + 1, дополненный нулями до трёх цифр (001). Цифры всегда передаются полностью (без сокращённых номеров вроде T вместо 0).",
  "t.2eqcnflmxgj": "Голос и собственные файлы для оповещений",
  "t.2esnjm739fr": "[[not2.grpWorked]] · [[not2.strike]] и [[not2.underline]]: как помечается уже отработанная станция — зачёркиванием (по умолчанию включено) или подчёркиванием; эти два варианта исключают друг друга. Они заблокированы, если не включена ни одна подсветка «нового».",
  "t.2ev2ls3l72d": "Вкладка «[[sstv.tab.adjust]]» (активна, когда есть фото): «[[sstv.bg.zoom]]» (100-600%), «[[sstv.bg.panX]]» и «[[sstv.bg.panY]]», «[[sstv.bg.brightness]]», «[[sstv.bg.contrast]]», «[[sstv.bg.saturation]]» (от -100 до +100), «[[sstv.bg.reset]]» и «[[sstv.bg.remove]]». Название, ползунок и значение расположены в фиксированных столбцах. В предпросмотре правая кнопка перемещает фото, а Ctrl + колесо меняет масштаб.",
  "t.2ew9w3aqrj3": "Вверху страницы звуков — «[[snd.voiceLang]]»: язык Aurora или всегда английский.",
  "t.2ewj97dsxt6": "Сообщения, которые невозможно отправить: если позывной или сообщение дошли бы не такими, как написаны, оно не уходит в эфир, а последовательность отключается.",
  "t.2f16pxt5g7p": "В журнале столбец [[ssbc.logMark]] отмечает дубли и новые множители. Позывной, с которым уже была проведена связь в контесте, очков не даёт (DUPE). Дубли и множители учитываются только внутри контеста: QSO вне окна дат никогда не считаются дублями.",
  "t.2f1kgdymfwv": "Удалённый вид",
  "t.2f2251yvs2a": "Исправьте нужные поля. Дата и время указаны в UTC; локатор может быть пустым или состоять из 4, 6 или 8 символов (IO91wm).",
  "t.2f3wlj8tio0": "На страницах CW и PSK над водопадом панель «[[digi.band.title]]» декодирует все сигналы звуковой полосы одновременно и перечисляет их по одному в строке. Она включается и выключается из меню «Параметры» («[[digi.band.mi]]» в CW, «[[digi.band.miPsk]]» в PSK) и показывается или скрывается из меню «Вид» («[[digi.band.view]]»).",
  "t.2f3y16qo0rm": "При первом запуске после обновления или с очень старой версией может появиться плакат «[[upd.poster.available]]»: «[[upd.poster.install]]» обновляет сразу (запускается сам через несколько секунд, «[[upd.poster.cancel]]» останавливает), «[[upd.later]]» откладывает, «[[upd.poster.news]]» открывает новости.",
  "t.2f4qg59r63a": "Фильтры: поле «[[hist.search]]», выпадающие списки «[[hist.band]]», «[[hist.mode]]» и «[[hist.period]]» («[[hist.p.1h]]», «[[hist.p.24h]]», «[[hist.p.7d]]» или «[[hist.p.all]]»). Кнопка «[[hist.clear]]» удаляет все сохранённые сообщения после подтверждения; журнал QSO не меняется.",
  "t.2f750qz2l2b": "Настройки: доступ и поддержка",
  "t.2f7pbzvck1o": "[[sw.wspr.beacon]] · [[mode.wsprPower]]: выпадающий список без видимой подписи, со значениями от 0 dBm (1 mW) до 60 dBm (1 kW); заводское значение 37 dBm (5 W). Это мощность, объявляемая в сообщении маяка: выбирайте реальную на антенне, а не ту, которую Вам хотелось бы.",
  "t.2f89aom91t7": "Как <TX>, но сначала ждёт, пока сигнал на частоте приёма спадёт (другая станция закончила). Через 30 секунд всё равно передаёт; Esc отменяет ожидание.",
  "t.2f999839t2h": "Настройки: Станция",
  "t.2fa4wuik4yb": "«[[rep.show]]» и «[[rep.showAuto]]»: открывают окно «[[rep.previewTitle]]», которое показывает в точности тот текст, который был бы отправлен: файлы пакета (каждый открывается для чтения содержимого) или образец автоматического отчёта. Закрывается кнопкой «[[rep.close]]» или клавишей Esc. Посмотрите, прежде чем доверять.",
  "t.2fakik3gql3": "«[[ctl.hold_tx]]»: фиксирует частоту передачи; когда Вы отвечаете станции, перемещается только приём. Нужен, чтобы оставаться на свободном месте.",
  "t.2faxaquer0m": "Первая настройка с SDR: включите сервер TCI в программе SDR, впишите адрес здесь (обычно достаточно оставить пустым) и нажмите «[[sdr.useAll]]». Затем проверьте вверху, что CAT сообщает «[[cat.state.connected]]» с частотой SDR. Подробности — в пунктах «SDR с TCI (ExpertSDR, Thetis)» и «QMAP».",
  "t.2fco4n32ksg": "Новые сообщения внизу: в заголовке Band activity и окна RX нажмите «[[list.bottom.off]]». Кнопка превратится в «[[list.bottom.on]]»: последнее сообщение всегда в последней строке, а список прокручивается вверх. У каждого списка свой выбор; он есть и в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], «[[list.bottom]]».",
  "t.2fcoi5jx851": "[[lay.status]] · [[upd.check]]: кнопка, которая сразу ищет новую версию, не дожидаясь интервала. Когда проверка заканчивается, всегда открывается афиша: с новой версией и её новинками или с «[[upd.poster.upToDate]]». Серая, пока Вы вводите данные в полях ниже и изменения ещё не сохранены. Когда: после того как Вы прочитали о новой версии на сайте или чтобы убедиться.",
  "t.2fde743duxg": "[[tab.updates]]",
  "t.2fdp8n8suaz": "показывает уведомление с этим текстом",
  "t.2ffyl8gsh3u": "Пульт дистанционного управления: активность диапазона, DX Cluster и журнал",
  "t.2fg29dkas1b": "Я вижу сигналы в водопаде, но ничего не декодируется",
  "t.2fgo7ka7o2w": "[[sw.digi.perMode]] · RTTY, «[[digi.rtty.receiver]]»: [[digi.rtty.receiverAuto]] (заводской), [[digi.rtty.receiverFilters]] или [[digi.rtty.receiverDisc]]. Дискриминатор лучше работает с узкими сдвигами, менее 40 Hz; при 170 Hz просто оставьте «Автоматически».",
  "t.2fgpckgo5fw": "[[sdr.tci]] · [[sdr.address]]: хост и порт сервера TCI у SDR; это тот же параметр, что [[cat.tci.address]] на странице [[sw.pg.radio]]. Пусто = 127.0.0.1:40001 (порт ExpertSDR и Thetis, где нужно включить сервер TCI). Измените его, если SDR работает на другом ПК или на другом порту. Сохраняется само после короткой паузы; если формат не host:port, поле помечается и появляется «[[sdr.badAddress]]».",
  "t.2fgwyi6dy7d": "QSO и счёт показываются в меню [[ctest.menu]] и в панели внизу. [[ctest.stats]] открывает таблицу по диапазонам (QSO, дубли, очки, множители, CW, телефон, цифровые). [[ctest.cabrillo]] сохраняет файл Cabrillo 3.0 активного соревнования (режим CW, RY, PH или DG, частота в kHz, отправленный и принятый обмен); перед отправкой проверьте и дополните строки CATEGORY вручную.",
  "t.2fi46ts2c5k": "При новом запуске Aurora возвращается на последнюю страницу, на которой Вы были, если это одна из [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], «Настройки» или «Справка». Из Станции, групп режимов и других страниц она всегда запускается заново со Станции.",
  "t.2fiovn4ytm3": "[[bar.watchdog]] с минутами, например «WD 6m»: сторожевой таймер передачи. Через столько минут без QSO передача останавливается сама; наведите курсор, чтобы прочитать. Появляется, только если таймер включён (не ноль).",
  "t.2fj7d8psror": "[[tab.cluster]]",
  "t.2fkazq80xif": "Индикатор включается, как только радиостанция отвечает, даже если состояние CAT не показывает «подключено»; он остаётся тёмным с надписью «[[rd.off]]» только тогда, когда данные не поступают.",
  "t.2fkk2o0ktvw": "Откуда уходит спот, выбирается в [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › «[[cluster.spotVia]]»: «[[cluster.spotVia.dxsummit]]» (как в JTDX: спот появляется на dxsummit.fi, но не попадает в сеть telnet-кластеров) или «[[cluster.spotVia.telnet]]» (Aurora отправляет его через подключённый кластер командой DX и пишет «готово», только когда кластер его повторяет; оттуда он попадает во всю сеть). Многие кластеры принимают споты только после входа: рядом с каждым сервером есть «[[cluster.access.user]]» (позывной, также с SSID) и «[[cluster.access.password]]», который отправляется только когда кластер его запрашивает и после сохранения больше не показывается.",
  "t.2fkwan48q8h": "В LogHX откройте настройку цифровой программы: Ctrl + щелчок по значку JTDX (или WSJT-X) в главном окне либо из меню Setup. Aurora представляется как JTDX: используйте настройку JTDX.",
  "t.2foeu7imhfg": "Aurora принимает новую частоту как выбранную частоту приёма, а частота передачи следует за ней с тем же смещением; ползунок «[[sat.ctl.downlink]]» на странице обновляется сам. Скачок более 80 кГц (смена диапазона) не отслеживается.",
  "t.2fohrcsswxh": "Блок «[[snd.title]]» находится на странице [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], под блоком оповещений: громкость, голос, остальные оповещения с их звуком и банк звуков для прослушивания. Всё применяется сразу.",
  "t.2fopm25y6cu": "Вверху три кнопки — [[news.kind.new]], [[news.kind.changed]] и [[news.kind.fixed]] — показывают или скрывают каждый тип новостей (включено = цветная). Они полезны, например, чтобы искать только исправления.",
  "t.2fpcqtb67zr": "Жёлтое предупреждение о часах (со значком ⚠): появляется только если время ПК выходит за допуск относительно серверов NTP или его не удавалось проверить более суток. Щелчок сразу пытается исправить время Windows; если Windows не позволяет, открывается [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] с проверкой по серверам NTP (см. «Часы»).",
  "t.2fpihd6elsv": "Всплывающие сообщения вверху («Операция выполнена», «Отвечаю…»): в [[sw.pg.alerts]], блок «[[toast.grp]]», снимите «[[toast.show.ok]]» и «[[toast.show.info]]». Ошибки («[[toast.show.error]]») показываются всегда и не отключаются. Где они появляются и какого размера: «[[toast.position]]» и «[[toast.size]]».",
  "t.2fqm22rs92q": "Включите [[gen2.bandHopOn]] и сохраните: в следующую чётную минуту радиостанция перейдёт на первый элемент.",
  "t.2fr1stggnb7": "название программы",
  "t.2fs0g40xi6w": "Создание и распространение соревнования",
  "t.2fsww6z0z6t": "Панель команд",
  "t.2fx9uh3o8d": "[[not2.grpAlerts]] · [[not2.soundFirst]]: звук при первом декодированном сообщении каждого периода, чтобы знать, что приём работает. По умолчанию выключено; звук выбирается в меню «[[snd.ev.first_message]]» блока «[[snd.title]]». При большой активности может раздражать: включайте только для проверки.",
  "t.2fzo599hhzs": "[[sdr.tci]] · [[sdr.useAll]]: кнопка, которая делает всё за один раз. Она запрашивает подтверждение, затем переключает CAT на TCI с введённым адресом, звуковой вход «TCI (dalla radio)» и выход «TCI (alla radio)», и подключает. Прежний выбор трансивера и звука заменяется (чтобы вернуться к другому трансиверу, используйте профиль или верните параметры в [[sw.pg.radio]] и [[sw.tab.audio]]). Результат появляется ниже, строка за строкой. Когда всё уже идёт через TCI, кнопка уступает место «[[sdr.allDone]]».",
  "t.2g07hbfzsh": "При включённом усреднении периодов сигнал, слишком слабый для одного периода, суммируется с предыдущими периодами той же чётности (та же частота в пределах F Tol, тот же DT в пределах 0,2 s, до 64 периодов), и сообщение из среднего несёт отметку априорных сообщений. «Clear Avg» очищает среднее; оно очищается и само при смене режима, подрежима или частоты, а с «Auto Clear Avg» — после сообщения из среднего вблизи частоты Rx. Тот же сброс выполняет кнопка ⟲ «Clear Avg» рядом с AP и Prof.: нажмите её, когда хотите начать заново.",
  "t.2g1o7ysm2p7": "Под экраном «[[sstv.clean.title]]»: «[[sstv.clean.original]]» или «[[sstv.clean.cleaned]]» (серое, пока нет изображения). Очищенное убирает шум, не размывая детали, и обновляется каждые 4 секунды, пока приходит изображение; оригинал никогда не меняется. При включённом «Cleaned» появляются два ползунка: «[[sstv.clean.order]]» (от 1 до 6, по умолчанию 3) и «[[sstv.clean.smooth]]» (от 0,10 до 1,00, по умолчанию 0,40): чем выше, тем чище, но мягче.",
  "t.2g27efsfj54": "Если принимаемая карта наклонена, кнопки наклона действуют сразу: уже принятые строки выпрямляются, а приём не начинается заново. «[[wefax.slant.measure]]» над просмотрщиком измеряет наклон за вас: щёлкните начало и конец линии, которая должна быть вертикальной (чем дальше друг от друга, тем лучше), и поправка прибавляется к ручной. Та же кнопка на карте, открытой крупно из истории, выпрямляет сохранённую карту: как новую копию или, с «[[wefax.slant.replace]]» и после подтверждения, вместо оригинала.",
  "t.2g35jdpt4mp": "Только для Cat4OM: кнопка «[[cat.cat4om.search]]» запрашивает у Cat4OM группы и трансиверы с их состоянием, используя записанные здесь значения (ничего не меняет и не берёт управление трансивером). В списке «[[cat.cat4om.found]]» кнопка «[[cat.cat4om.use]]» записывает группу и трансивер в поля (затем «[[cat.cat4om.inUse]]»). Если сетевой звук не работает, ниже появляется «[[cat.cat4om.audioProblem]]» с указанием причины.",
  "t.2g3fo34thpb": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]. Профиль — это именованная копия настроек трансивера (система управления, модель, порт, скорость, PTT, сплит, режим, адреса TCI и Cat4OM): он предназначен для тех, у кого несколько трансиверов или несколько кабелей и кто хочет переключаться между ними одним щелчком. Он не содержит звука, позывного и других данных станции.",
  "t.2g4sd55iai0": "Вверху: анимированный логотип, название AURORA, «[[about.tagline]]» и «[[about.version]]» с номером используемой версии (прочерк, если Aurora не отвечает). Когда нужно: это версия, которую следует сообщить тому, кто Вам помогает.",
  "t.2g4yjcpieqw": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]: нажмите [[cat.connect]]; в статусе должно быть «Connected» с частотой радио.",
  "t.2g5c1977d4w": "Kenwood TS-590SG, TS-890S: виртуальный COM-порт по USB. В [[cat.rig]] выберите модель; [[cat.baud]] такая же, как в меню радио (см. руководство).",
  "t.2g5pkeg2sma": "Это страница, которую телефон видит в первый раз или после удаления сопряжения. Сюда попадают по QR-коду на ПК (ссылка «#/associa?codice=…») или набрав адрес Aurora.",
  "t.2g66olze4e9": "Режекторный фильтр показан флуоресцентно-зелёной полосой с небольшой планкой сверху: перетащите его, чтобы переместить, перетащите один из его краёв, чтобы расширить или сузить (от 10 до 100 Hz), щёлкните правой кнопкой, чтобы удалить. «[[digi.notch.clear]]» в строке состояния и в меню [[digi.menu.options]] удаляет их все: кнопка появляется, только когда есть хотя бы один режекторный фильтр, и показывает их число.",
  "t.2g7bkmainlc": "Окна и текст: дополнительные окна RX, панели для показа или скрытия, прокрутка, шрифт и цвет приёма, метки, оповещения. Пример: <NEWRXWINDOW><TOGGLE:WORLDMAP><MARK>.",
  "t.2g9tyx70ry2": "«[[bfl.button]]»: открывает ряд кнопок под строкой заголовка, с помощью которых Вы выбираете, какие новости показывать. Когда Вы что-то выбрали, кнопка подсвечивается и показывает их число (например, «Filter 3»). Второй щелчок закрывает ряд, не убирая Ваш выбор.",
  "t.2gc22c5g439": "[[digi.tx.title]] · [[digi.freq.tx]]: звуковая частота передачи, от 200 до 3500 Hz (заводское 1000). Её можно редактировать только при включённом «[[digi.mi.lock]]»; без него она следует за приёмом.",
  "t.2genu3weta6": "Карта остаётся пустой, хотя Decode приходят: обновите Aurora до 0.11.282 или новее. Состояние «декодирование» теперь меняется в каждом периоде, как в WSJT-X, а карта перерисовывается в конце каждого периода.",
  "t.2getrrv5tz2": "[[cat.share]] · [[cat.share.port]]: появляется только при включённом совместном использовании. Заводское 4532 — порт, который JTDX, Log4OM2 и другие предлагают для «Hamlib NET rigctl»; от 1024 до 65535. Меняйте его, только если он занят. Ниже, как только трансивер подключён, появляется адрес, который нужно вписать в других программах (127.0.0.1 и этот порт). Если порт совпадает с сетевым трансивером, выбранным в [[cat.port]], Aurora подключилась бы сама к себе и предупреждает Вас.",
  "t.2ghkg0va80f": "[[seq2.stop]] · [[seq2.strictCq]] (по умолчанию выключено): на направленный CQ (CQ NA, CQ DX…) отвечает, только если Вы находитесь в запрошенном районе, в том числе для нужных станций и новых DXCC. Включите, если не хотите тратить периоды на CQ, предназначенные не Вам.",
  "t.2gjaf1kdpe2": "Окна приёма и передачи",
  "t.2gjnoug3iq7": "Скорость передачи: в WPM, от 5 до 60 (по умолчанию 20). Она задаётся ползунком в окне «[[digi.ms.title]]» (щёлкните по значению WPM в строке состояния), макросами <WPM:20> (в том числе относительными, <WPM:+2>) или заводскими макросами F10, F11, F12 (15, 20, 25 WPM). Кнопка «TX = RX» в строке состояния устанавливает скорость передачи равной той, которая только что была понята при приёме.",
  "t.2gjpglrpg06": "PSK · RTTY · CW, SSTV, телефон и агент",
  "t.2gk7gxgoigs": "Чтобы менять диапазон через равные промежутки каждые две минуты, используйте вместо этого Band Hopping ([[sw.sub.ft8]] › [[tab.sequence]] › [[gen2.bandHop]]); расписание предназначено для точного времени (например, 80 м утром, 20 м в полдень).",
  "t.2gkg1n1xusj": "[[fil.decode]] · [[dec.ftolJt65]] и [[dec.ftolJt9]]: два выпадающих списка с допуском по частоте вокруг Rx, от 1 до 1000 Hz (1, 2, 5, 10, 20, 50, 100, 150… до 1000); заводское значение 50 Hz для обоих. В JT65 его используют также одиночное декодирование и усреднение; в JT9 это окно, пробуемое первым. Расширьте, если сигнал далеко от линии Rx, сузьте, чтобы декодировать только то, что рядом с Вами.",
  "t.2gmsl3urntd": "Дважды щёлкните строку или нажмите «[[exp.edit.btn]]» в конце строки: откроется окно «[[exp.edit.title]]». На панели [[panel.log]] станции двойной щелчок по строке делает то же самое.",
  "t.2gnc3l71j9q": "Левый щелчок по значку открывает Aurora (если она уже открыта, выводит её окно поверх всех остальных).",
  "t.2hkea6ltxf": "Шесть кнопок под «[[int.title]]» ([[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]) добавляют получателя с правильными начальными значениями, которые затем можно менять. Ниже для каждой: значения и что она получает.",
  "t.2idhbbjbgn": "QSO не дошло до моей программы ведения журнала: как его восстановить?",
  "t.2iu9fgbao6": "[[nav.sat]]: страница спутников (см. «Спутники: страница, панель за панелью»).",
  "t.2jghd66u7p": "Клавиша Pause и автоматический CQ с двойным Esc относятся только к странице текстовых режимов: в SSTV их нет.",
  "t.2kixb0xakx": "В [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]] Вы настраиваете, как рисуются водопад и спектр. Это первая часть: предпросмотр, разрешение и цвета. Каждое изменение применяется сразу и сохраняется после перезапуска; сохранять не нужно.",
  "t.2lfgjgyaau": "[[digi.mi.threshold]]: открывает окно «[[digi.ms.title]]» с порогом шумоподавителя (и другими пунктами режима).",
  "t.2lsaofxz1r": "Выбор в меню [[digi.menu.view]], ширина журнала, а также высота водопада и панели сигналов сохраняются на этом компьютере (в браузере Aurora). Настройки режимов (частоты, AFC, шумоподавитель, макросы, память) хранятся, напротив, в движке. Если вверху появляется «[[set.loadError]]», Aurora не отвечает: проверьте, что движок включён.",
  "t.2ltd527tjr": "Справа от вкладки «[[sstv.view.rx]]»: служит для записи в журнал QSO, проведённого в SSTV. Позывной приходит сам из FSK ID после изображения (если поле пусто или было заполнено Aurora), и как только появляется позывной, Aurora ищет станцию с помощью уже настроенного поиска (QRZ.com или HamQTH) и заполняет оставшиеся пустыми имя, QTH и локатор. То, что Вы написали вручную, не затрагивается.",
  "t.2m9euithze": "[[cat.profile.save]]: сохраняет настройки трансивера в их нынешнем виде под именем, записанным в «[[cat.profile.name]]»; если профиль с таким именем уже существует, заменяет его. Профиль становится используемым. Нажмите её после тонкой настройки трансивера, чтобы не делать всё заново.",
  "t.2o2eol4qd4": "Маркер Tx можно двигать и во время передачи: тон меняется сразу. Выберите на водопаде свободное место для передачи.",
  "t.2qlm47od2w": "[[ens.g.log]] · [[ens.k.ClearCallGrid]] (по умолчанию выключено): после занесения QSO очищает позывной и локатор станции DX, готовя поля к следующей. Поскольку по окончании QSO Aurora в любом случае очищает станцию DX, при автоматическом занесении флажок мало что значит; оставьте его включённым, если хотите всегда начинать с пустых полей.",
  "t.2rv0bqpda6": "[[sw.close]]: закрывает настройки; если есть несохранённые изменения, сначала спрашивает, отбросить ли их. [[sw.save]]: сохраняет и применяет изменения параметров движка (таких как позывной и локатор). Параметры трансивера, звука, ротора и часов сохраняются сами и не ждут «[[sw.save]]».",
  "t.2ta08in5ls": "«Save ADIF…» открывает окно Windows для выбора папки и имени: в файл попадут только выбранные QSO. С телефона кнопка скачивает файл.",
  "t.2whbpjc26w": "«[[sat.all.title]]»: единый список предстоящих пролётов всех отмеченных спутников, первый — вверху. С помощью «[[sat.pass.hours]]» Вы выбираете окно — 24 или 48 часов; пролёты ниже «[[sat.pass.minEl]]» не показываются. Столбцы: «[[sat.all.sat]]», «[[sat.pass.date]]», «[[sat.pass.aos]]», «[[sat.pass.los]]», «[[sat.pass.dur]]», «[[sat.pass.max]]» и «[[sat.pass.az]]»; эта таблица тоже является перемещаемой сеткой (перетаскивайте заголовки, границу между заголовками — чтобы расширить, двойной щелчок по заголовку — чтобы восстановить). Щелчок по строке выбирает этот спутник; текущий пролёт выделен.",
  "t.2xpl7ymgkj": "[[tab.online]]",
  "t.30ylqi459n": "[[lay.settings]] · [[clock.interval]]: сколько минут между проверками часов Aurora, от 1 до 1440 (сутки); заводское 15. Одной проверки каждые 15 минут достаточно, и она не нагружает серверы; если время вне допуска, Aurora сама перепроверяет каждую минуту.",
  "t.313r9vsirv": "Антивирус удаляет файлы Aurora: что делать",
  "t.34r3o4v678": "Возраст сообщений: откройте [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] и в блоке «[[fil.grp.both]]» отметьте «[[gen.showAge]]». Первая колонка показывает, как давно пришло сообщение (45 s, 3 min), и обновляется сама; наведите курсор на число, чтобы увидеть время UTC.",
  "t.358v0jrx55": "«[[ens.g.lotw]]» · «[[ens.k.LoTWSend]]» (по умолчанию выключено): подписывает и выгружает каждую QSO с помощью TQSL — программы ARRL для LoTW; Aurora сама не подписывает, поэтому TQSL должна быть установлена и настроена с Вашим сертификатом (без пароля, иначе она остановится). «[[ens.k.LoTWTqsl]]»: где находится tqsl.exe; пусто = Aurora ищет его в папках Program Files; впишите путь, только если он в другом месте. «[[ens.k.LoTWLocation]]»: название местоположения станции, созданного в TQSL («Station Locations»), написанное так же: оно сообщает TQSL, с каким позывным и локатором подписывать. Ожидающие QSO уходят вместе одной выгрузкой; дубликаты и QSO вне дат сертификата пропускаются. «[[ens.test]]» проверяет TQSL и местоположение, ничего не выгружая. LoTW — единственный сервис, который отображается и без защиты секретов Windows.",
  "t.35qrp9y5cq": "Какие панели показывать и где они сейчас: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] («[[win.where]]», «[[win.shown]]», «[[win.reset]]»).",
  "t.39fxve0ba0": "расстояние в км от вашего локатора до локатора другой станции (? если нет)",
  "t.39j8oqw3rh": "Начало работы",
  "t.39llsn4rxy": "В меню «Режим» страницы [[nav.textModes]] выберите CW: передача идёт тоном со сглаженными фронтами на заданной скорости, а приём сам следует за скоростью станции (от половины до удвоенной заданной).",
  "t.3a36ojyj4j": "«FT8»: группа режимов КВ. Её меню режимов (см. «Режим, подрежим и частота») предлагает FT8, FT4, JT9, JT65, FST4, FST4W и WSPR. Один щелчок возвращает на страницу [[nav.station]] и восстанавливает последний режим, использованный в этой группе (по умолчанию FT8). Если радио настроено не на частоту этого режима, Aurora переводит его на первый диапазон, где этот режим есть.",
  "t.3aa43gimsc": "Щелчок по строке открывает карточку экспедиции: статус (в эфире, скоро, завершена), сколько осталось, слышите ли Вы её, последний спот, даты, заметки NG3K, расстояние и направление от Вас, карта страны и кнопка «Настроиться на … kHz», переводящая радио на последний спот. Двойной щелчок по услышанной экспедиции вызывает её, не открывая карточку. «[[dxd.close]]» или Esc закрывает карточку.",
  "t.3b0w7beqje": "[[sstv.set.grpRx]] · [[sstv.set.rxOffset]]: от -200 до 200 Hz с шагом 5 (заводское 0). Сдвигает настройку приёма на столько Hz, для трансиверов или станций, немного ушедших с частоты: если изображения получаются с неверными цветами или перекошенными, а сигнал сильный, попробуйте здесь несколько десятков Hz.",
  "t.3ct5fe7gpk": "Откройте страницу [[nav.rotator]] кнопкой «[[rot.set.openPage]]» (в том же месте) или включите «[[rot.set.home.ft8]]», чтобы карточка отображалась на странице «Станция»: сплошная стрелка — это антенна, пунктирная — цель; зелёная отметка — станция DX (короткий путь), оранжевая — длинный путь.",
  "t.3elxiv4637": "Откройте [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]] и включите сервис.",
  "t.3fbpxdggi4": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiMacros]]. Это макросы (готовые тексты) четырёх рядов панели для режима, выбранного на странице PSK · RTTY · CW; строка вверху сообщает, какой режим используется. Страница открывается также из меню [[digi.menu.configure]] рабочей страницы. Макросы разделены на четыре группы, которые открываются и закрываются щелчком: «[[sw.macros.row1]]» (единственная с клавишами F1…F12) и ряды 2, 3 и 4, используемые только щелчком. Сначала открыт только ряд 1; Aurora запоминает, какие группы Вы оставили открытыми.",
  "t.3fmkv8huoc": "Какие диапазоны появляются в выпадающем списке, выбирается в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (используемый диапазон показывается всегда); сами частоты меняются в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].",
  "t.3lrmt8u63e": "[[not2.grpAlerts]] · [[alert.button]]: главный выключатель звуков (это также значок громкоговорителя внизу справа, с ползунком громкости). Когда выключено, Aurora сама ничего не воспроизводит; по умолчанию выключено, потому что звук, которого никто не просил, — помеха в радиокомнате. Включите, если хотите слышать оповещения.",
  "t.3lsi3kgdcp": "[[clock.state]] · [[clock.check]]: сразу опрашивает серверы и показывает смещение. Ничего не меняет на ПК: служит для просмотра. Используйте, когда появляется жёлтое предупреждение о часах или перед контестом.",
  "t.3mc6xxdy9h": "знаки < и > в тексте",
  "t.3mgos8huk2": "[[acc.home]] · [[acc.open]]: флажок, по умолчанию включён. Когда включён, любой в домашней сети управляет Aurora без кода, включая передачу, если она открыта; из интернета, через туннели или прокси код нужен всегда. После перезапуска остаётся как есть. Когда выключить: если домашняя сеть не только Ваша (гости, многоквартирный дом, общий Wi-Fi) или после Ваших испытаний; когда выключено, каждый телефон или планшет нужно связывать с помощью кода.",
  "t.3n412xlbtn": "В FT8 время ПК должно быть верным с точностью до доли секунды. Если всё в порядке, Вы ничего не видите; иначе вверху появляется жёлтое предупреждение.",
  "t.3ol1640qhy": "Помимо диагностических оповещений (см. «Диагностические оповещения внизу справа»), Aurora показывает ещё несколько уведомлений, почти всегда только один раз.",
  "t.3qh4n3xejg": "Контест: вкладка «Гонка», панель за панелью",
  "t.3ruu8z7n7g": "На ПК кнопки «CQ» нет: CQ — шестое сообщение панели [[panel.tx]]. На телефоне кнопка «[[phone.cq]]» делает всё одним касанием.",
  "t.3sqldfrl09": "выделенное слово становится принятым рапортом",
  "t.3tn40cwkq9": "«[[panel.cluster]]»: первые 5 спотов с частотой в MHz, флагом, позывным, страной, режимом, тем, кто сообщил, и временем UTC. Касание спота переводит радио на эту станцию; без CAT появляется уведомление. С фильтрами, выбранными в Aurora, Вы видите подходящие; если их меньше 5, список дополняется остальными. По заголовку можно коснуться, чтобы закрыть или открыть панель (пока страница остаётся открытой; в следующий раз она открывается сама). Её нет, если Вы выключили DX Cluster в Aurora.",
  "t.3tuxn5astp": "В CW каждый из них — один знак, без промежутков между буквами. В RTTY и PSK они передаются обычными буквами (AR, BT, KN, SK).",
  "t.3u5u42vnm7": "[[aud.output]] · [[aud.vol.out]]: ползунок TX Lvl, то есть уровень звука на трансивер (по умолчанию он уменьшает сигнал, не трогая громкость Windows). См. раздел о ползунках Rx, TX Lvl и AUTO. [[aud.outch]]: «[[aud.ch.mono]]» (заводская) посылает звук на все каналы устройства; «[[aud.ch.left]]» или «[[aud.ch.right]]» только с этой стороны (другая молчит); «[[aud.ch.both]]» — одна и та же волна на два канала. Левый, Правый и Оба требуют стереовыхода.",
  "t.3xcyd59sjx": "Радио было выключено или USB-кабель отключён при запуске Aurora? Перезапуск не нужен: включите радио (или снова подключите кабель), и передача восстановится сама на той же звуковой карте.",
  "t.40rsy6vow4": "Добавление второго трансивера: 1) в [[sw.pg.radio]] настройте первый трансивер, в [[sw.pg.profiles]] впишите имя и нажмите «[[cat.profile.save]]»; 2) впишите имя второго и нажмите «[[cat.profile.new]]»; 3) в [[sw.pg.radio]] настройте второй трансивер и снова нажмите «[[cat.profile.save]]». Смена трансивера: выберите профиль, «[[cat.profile.load]]», затем [[cat.connect]]. Не забудьте сменить вход и выход также в [[sw.tab.audio]]: профили их не затрагивают.",
  "t.41aaxkfknq": "Колёсико мыши или маленькие кнопки + и − — масштаб; нажмите и перетащите, чтобы сдвинуть карту.",
  "t.41vdc321co": "«[[qmap.center]]» (в kHz): частота в центре участка, если источник её не сообщает (TCI передаёт её сам; для файлов она читается из имени, например …_144100kHz.wav). Без центра щелчок «[[qmap.qso]]» не может знать, куда переходить.",
  "t.4352oj8t2": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]: выберите модель, затем нажмите «[[cat.preset.apply]]» и [[cat.connect]].",
  "t.43lgi9fivi": "Не находите страницу? Введите слово в поиск вверху дерева: останутся только страницы, где оно упоминается, а щелчок приведёт по нужному пути. Поиск находит и отдельные настройки.",
  "t.458ql4slxw": "[[ap.board]]: флажок «[[ap.boardEdit]]». Когда включён, окна страницы FT8 разблокируются: перетаскивайте заголовок, чтобы переместить их, а правый нижний угол — чтобы удлинить или расширить. Выключите, чтобы снова их заблокировать. «[[ap.boardResetBtn]]» (строка «[[ap.boardReset]]») просит подтверждения и возвращает все окна всех страниц (FT8, VHF, PSK, «Спутники», контесты, столбцы таблиц, отдельные окна) в исходную раскладку, ту, что сразу после первой установки; затем страница перезагружается. Тема, язык, имя и фильтры остаются. Удобно на маленьких экранах.",
  "t.45gnuryeym": "Проверка сети для телефона",
  "t.46gzysibvy": "В строке «[[ctl.skip_tx1]]», когда она активна, Tx1 зачёркнуто; в Hound Tx6 (CQ) выключено. Под сообщениями может появиться короткое уведомление, если команда не удалась.",
  "t.46p77ysual": "Один щелчок по «[[stop.button]] (Esc)» немедленно останавливает передачу, и значок возвращается к RX. Клавиша Esc тоже останавливает её и выключает [[ctl.enable_tx]], если в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] включено «[[gen.escStop]]».",
  "t.46razahyii": "Внизу — строка состояния: RX/TX, Sq, AFC, Lock, Snap, звуковая частота, данные режима и измерения сигнала.",
  "t.477hfm7jl2": "Карта: в настройках “[[sat.map.pick]]” позволяет выбрать между “[[sat.map.terra]]” (снимок NASA с рельефом и дном морей: днём как есть, ночью под тёмной вуалью с огнями городов, с плавным переходом в сумерках; это карта по умолчанию), “[[sat.map.terraRelief]]” (снимок NASA с рельефом), “[[sat.map.terraBase]]” (снимок NASA, только цвета), “[[sat.map.builtin]]” (суша и границы, нарисованные Aurora) и вашими собственными изображениями. На картах Земли “[[sat.map.borders]]” (по умолчанию выключено) рисует тонкие границы стран поверх снимка. Вверху слева на карте список “[[sat.map.country]]” показывает все страны на языке интерфейса (введите название для поиска; если ваша станция находится в какой-либо стране, первой в списке будет ваша страна) и плавным движением показывает выбранную страну; как и любой жест на карте, он приостанавливает автоматическое масштабирование до следующего AOS, а “[[sat.map.zoomFit]]” возвращает ко всему миру. Карты Земли взяты из NASA Earth Observatory (Blue Marble Next Generation и Black Marble), их можно свободно использовать со ссылкой на источник.",
  "t.47ltj8m9w8": "В Настройки › Станция › Радио в блоке «Система управления» выберите «Нет (без CAT, настройка вручную)».",
  "t.4apjb8pkys": "«[[contest.settings]]» открывает настройки контеста с выпадающим списком сообщений (активность), словом CQ, фиксированным обменом, первым серийным номером, режимом, мощностью, бонусными очками, Hold Tx Freq и RRR, а также данными Cabrillo (позывной контеста, локатор, антенна, клуб, имя, электронная почта, адрес, soapbox, категория по времени и дополнительная категория). Значения — те, что Aurora подготовила для контеста; они сохраняются кнопкой «[[contest.set.save]]». Те же пункты находятся в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].",
  "t.4dwq6n0ocv": "Отметки в строке: красная полоса на правом краю (маркер) и подсвеченный фон = эта станция вызывает Вас; полоса (и позывной) становится фиолетовой = она ответила Вам; зачёркнутая строка = станция уже проведена на этом диапазоне и в этом режиме (как её отмечать — зачёркиванием, подчёркиванием, цветом, скрытием — выбирается в [[sw.tab.colors]]); станция, которую Вы вызываете, подсвечена и остаётся закреплённой вверху, а цвет меняется при каждом её ответе (рапорт, R+рапорт, завершение); фиолетовая строка фильтра = позывной, префикс или страна, выбранные в «[[fil.highlight]]»; особый фон = станция из Вашего списка желаемых; синяя точка с номером = в очереди.",
  "t.4f4wvxrufg": "При включённом контесте панель показывает: фазу («Начало через …», время до окончания, «[[contest.phase.finito]]» или «[[contest.phase.sempre]]»), «[[contest.qso]]», «[[contest.mult]]», «[[contest.score]]», «[[contest.rate10]]» и «[[contest.rate60]]» (QSO в час), «[[contest.forecast]]» (результат, если сохранить этот темп), «[[contest.sent]]», плитку категории (щелчок: выбор категории, операторов, мощности, помощи или передатчиков Field Day) и «[[contest.hours]]». Если диапазон или режим не разрешены, появляется красное предупреждение.",
  "t.4f9gqij7sj": "Настройки: журнал, кластер и сервисы",
  "t.4fconwndvm": "[[sw.sec.sstv]]: три страницы, [[sw.pg.rx]], [[sw.pg.tx]] и [[sw.pg.images]]. У них общий черновик: изменения проходят кнопкой «[[sw.save]]» внизу окна, а параметр, который изменён, но ещё не сохранён, отмечен жёлтым значком. Исключение — «[[sstv.rx.smooth]]», который применяется сразу.",
  "t.4ftp1elns5": "[[auto.b3]] · [[auto.window]], [[auto.windowFrom]], [[auto.windowTo]] (один флажок и два поля времени, по умолчанию выключено, затем 08:00 и 22:00): при включённом флажке Aurora отвечает и вызывает CQ только внутри окна, по местному времени ПК; вне его она остаётся включённой, но бездействует, а журнал сообщает, когда она выходит и когда возвращается. Окно может переходить через полночь (например, 22:00–06:00). Два поля времени можно редактировать только при включённом флажке.",
  "t.4gw8f3x40x": "[[sup.privacy]]",
  "t.4h0fnwsgiq": "[[phone.cq]]: запрашивает CQ (появляется «[[tx.cqAsked]]»). Серая, если передача не разрешена.",
  "t.4hso343o5x": "[[cat.detect]] (только Hamlib): считывает то, что система уже знает (имена портов, USB-идентификатор, звуковые карты), и предлагает найденные трансиверы в «[[cat.detected]]», каждый с процентом уверенности и причиной. Она не открывает портов и не посылает трансиверу никаких команд. «[[cat.detected.use]]» подставляет модель, порт и скорость в поля (затем они применяются сами); там, где появляется «[[cat.detected.manual]]», модель выбираете Вы. Используйте её, когда Вы не знаете порт и скорость.",
  "t.4kvu64cw1s": "QTH в последнем записанном QSO",
  "t.4lxg5dg113": "На узком экране страница «Станция» превращается в компактный пульт.",
  "t.4m7cw41z8w": "[[fil.grp.rx]] · [[list.bottom]]: как флажок [[panel.all]], но для окна [[rxw.title]]; по умолчанию выключен. Если включён, новые сообщения окна находятся внизу.",
  "t.4ni331k4ay": "С SDR, у которого есть TCI (SunSDR с ExpertSDR, ANAN с Thetis), достаточно одной связи: команды и звук идут по TCI, без виртуальных аудиокабелей.",
  "t.4og0qlfga5": "Один и тот же журнал должен получать QSO только одним путём: поток WSJT-X с QSO Logged, Logged ADIF, ADIF по UDP, N1MM XML или TCP. Если они приходят двумя путями, QSO появляются дважды.",
  "t.4p6twbl9hj": "Пока включён автоматический CQ, клавиша, которая им управляет (по умолчанию F1), меняет вид, так что сразу видно, что он повторяется.",
  "t.4pnpzkutem": "Вкладка «[[contest.training]]»: симулятор (см. «Контест: календарь, тренировка и анализ»). Вкладка «[[contest.analysis]]»: разбор после контеста.",
  "t.4pufx04rpi": "Кнопка TUNE под дисплеем управляет тюнером трансивера одним щелчком: см. пункт «Кнопка TUNE под дисплеем».",
  "t.4reeptdrpb": "Телефон: страница «[[pair.title]]»",
  "t.4ry3petuai": "Только для Hamlib и последовательного порта: [[cat.databits]] и [[cat.stopbits]] (обычно «[[cat.default]]»: меняйте их, только если руководство трансивера говорит иначе; многие Yaesu, например FT-2000, требуют 8 бит и 2 стоп-бита), [[cat.handshake]] («[[cat.handshake.none]]», «[[cat.handshake.xonxoff]]» или «[[cat.handshake.hardware]]»: многие Yaesu требуют аппаратное), [[cat.dtr]] и [[cat.rts]] («[[cat.line.auto]]» удерживает линию в низком состоянии при открытии, потому что во многих интерфейсах эта линия соединена с PTT; «[[cat.line.high]]» или «[[cat.line.low]]» — только для особых интерфейсов).",
  "t.4slj7qmi37": "По UDP QSO, отправленное в закрытый журнал, теряется: подтверждения нет. С «[[int.resend]]» Aurora проверяет, открыт ли журнал на этом ПК; если он закрыт, она откладывает QSO и сама отправляет его, когда журнал снова откроется. Это работает для каждого журнала, который получает «[[int.adif]]» или «[[int.n1mm]]»: Log4OM, HRD Logbook, WaveLogGate и остальных.",
  "t.4tf523r1oa": "В панели кластера нет спотов.",
  "t.4tr0ifeslh": "Меню [[digi.menu.mode]]",
  "t.4ukipd4mig": "Окно исправления или удаления QSO",
  "t.4vj39tx6rx": "[[lay.notes]]: блок с общим пояснением. Изменения на этой странице сохраняются сами после короткой паузы и при выходе со страницы, ничего нажимать не нужно. Индикатор часов вверху ([[clock.pill]]) и жёлтое предупреждение объяснены в пункте Справки «Часы».",
  "t.4vsfmv4swt": "Одна кнопка собирает журналы, отчёты о сбоях и настройки в zip-файл на рабочем столе, без паролей.",
  "t.4wx8wewjw9": "[[ap.text]] · [[ap.size]]: увеличивает (или уменьшает) весь интерфейс — текст, кнопки, списки и водопад вместе. Меню идёт от 90% до 140% с шагом 5; по умолчанию 100%; на узких экранах (например, 1280 × 800 и 1366 × 768) выбор автоматический, от 65% до 100% в зависимости от ширины. На любой странице Ctrl + и Ctrl − (в том числе на цифровой клавиатуре) переключают значения 60, 70, 80, 90, 100, 110, 125, 140, 160%; Ctrl 0 возвращает 100%. Действует только на этом устройстве: у телефона свой размер.",
  "t.4xrwituegp": "В [[tab.sequence]], блок [[gen2.wsjtx3]]: со спутниковой радиостанцией полного дуплекса включите [[gen2.fullDuplex]]: Вы будете видеть и собственный downlink. При выключенном периоде, в котором Вы передаёте, не декодируется.",
  "t.4yx14xyg01": "[[not2.grpAlerts]] · [[not2.popPos]]: где появляется карточка: сверху или снизу, слева, по центру или справа (шесть положений: четыре угла, а также сверху по центру и снизу по центру; по умолчанию вверху справа). Измените, если карточка закрывает то, что Вам нужно.",
  "t.51oo6i6q6c": "В Windows, пока Aurora закрыта для установки, небольшое окно поверх остальных показывает, как идёт процесс («Закрытие Aurora…», «Установка новой версии…», «Повторное открытие Aurora…», «Запуск Aurora…»), и остаётся, пока окно Aurora не начнёт отвечать; когда она снова открывается, уведомление Windows подтверждает новую версию.",
  "t.51pxldzaet": "[[lay.settings]] · [[upd.enabled]]: флажок, по умолчанию включён. Aurora сама проверяет, вышла ли новая версия, и предлагает её; ничего не устанавливает, пока Вы не попросите. Когда выключить: если ПК не должен выходить в сеть для этого или если Вы хотите сами решать, когда проверять (кнопка «[[upd.check]]» остаётся).",
  "t.53aupnmtnd": "Перед контестом или если никто Вас не декодирует: нажмите «[[clock.check]]». Если смещение больше полусекунды, исправьте часы (Windows: «[[clock.correct]]» от имени администратора или синхронизируйте из настроек Windows).",
  "t.53hpka5dpm": "Все звуки сразу: выключите «[[alert.button]]», первый флажок [[sw.pg.alerts]] (это также значок громкоговорителя внизу справа, рядом с часами UTC, с громкостью). Когда выключено, Aurora сама ничего не воспроизводит; кнопка проверки ▶ работает всегда. По умолчанию выключено.",
  "t.55v9dyyguu": "Файл ищется в папке текстов макросов Aurora; если его нет, команда ничего не пишет.",
  "t.566chr7ra3": "На странице [[nav.sat]] (заголовок «[[sat.title]]») вверху расположена карта, а ниже — блоки. Как её настроить, описано в разделе «Спутники: пролёты, доплер и ротор». Без Вашего локатора страница сообщает «[[sat.noObserver]]».",
  "t.56i4ptld28": "[[sw.tab.audio]]",
  "t.56v2d7rakm": "[[phone.stop]] (во время передачи становится «[[stop.button]]»): сразу останавливает передачу и выключает автоматику, всегда активна и без подтверждения. Два касания подряд (в течение 0,7 секунды) также освобождают вызываемую станцию, как двойной Esc на ПК.",
  "t.57bnm5iwg8": "Выберите станцию в выпадающем списке «[[wefax.freq.label]]»: частоты отсортированы по диапазонам, а затем по частоте. Радио настраивается на несущую, на 1,9 кГц ниже назначенной частоты, в USB. Список — это список Национальной метеорологической службы США (март 2025) плюс Немецкая метеослужба, с ВЧ-частотами от 2 до 22 МГц; расписания карт есть на сайтах служб. Выбранная частота запоминается: когда вы возвращаетесь на страницу, радио возвращается на неё, а когда уходите, радио возвращается на диапазон, на котором было раньше. Список открывается на последней установленной частоте, выделенной и по центру; стрелки «[[wefax.freq.up]]» и «[[wefax.freq.down]]» рядом со списком переходят к следующей более высокой или более низкой частоте.",
  "t.5844d68gu": "[[tab.dxcc]]",
  "t.59s1oakaaf": "Нажмите «Start UDP»: по умолчанию сервер слушает 127.0.0.1, порт 50001.",
  "t.5bjbtfy6hk": "Добавьте тексты и фигуры («[[sstv.add.text]]») или шаблон из «[[sstv.tpl.title]]»: {MYCALL}, {CALL}, {RST}, {GRID}, {DATE} подставляются сами. Каждый слой перемещается, масштабируется и поворачивается за свои маркеры.",
  "t.5cnnt85ka3": "«[[ens.g.logIn]]» · «[[ens.k.LogInEnabled]]» (по умолчанию выключено), «[[ens.k.LogInPort]]» (12062) и «[[ens.k.LogInLan]]» (выключено): Aurora принимает связи, записанные в другом журнале (Log4OM, OpsLog, N1MM+, HRD Logbook), и добавляет их в свой журнал. В другой программе настройте исходящую отправку связей (запись ADIF, XML N1MM или сообщения JT/WSJT-X) на 127.0.0.1 и тот же порт. Связь, уже имеющаяся в журнале (тот же позывной, диапазон и вид работы в пределах 5 минут), второй раз не добавляется; принятые связи не пересылаются в другие журналы и в LoTW, QRZ или ClubLog. Под «[[int.title]]» видны порт и счётчики.",
  "t.5daziufif6": "Вкладка «Map» панели журнала всегда следует за используемым диапазоном и имеет один ряд элементов управления: Lines, Who calls whom, Only who hears me, Callsigns. Всё остальное настраивается на странице DX Map. Когда QSO записывается, панель сама переключается на Log (или Internal log), показывает новую строку и возвращается к Map.",
  "t.5gcz3cqurm": "[[digi.mi.modeSettings]]: открывает Настройки на странице «[[sw.pg.digiRxTx]]» (как в [[digi.menu.configure]]).",
  "t.5h1hm9np26": "Она никому не отвечает: проверьте, что она включена ([[auto.turnOn]]), что режим [[auto.modeLive]] (в [[auto.modeDry]] она никогда не передаёт), что [[ctl.enable_tx]] не выключен вручную, что [[auto.outWindow]] не появляется и что в [[auto.log]] нет красной блокировки.",
  "t.5hvm15e3ho": "Последний сегмент, «[[autoSwitch.off]]», включает или выключает Автоматизацию без открытия настроек. Зелёный: Автоматизация в рабочем режиме (отвечает сама и включается Enable Tx). Оранжевый: пробный режим (решает и пишет в журнал, но не передаёт). Серый: выключена. Когда выключена, если передача разрешена, щелчок спрашивает, перейти ли в рабочий режим (Да = рабочий, Нет = пробный); после подтверждения последующие щелчки включают и выключают её без вопросов. Правила находятся в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (см. «Автоматические ответы»).",
  "t.5i15q5m1c0": "Передача сама останавливается через несколько минут: это [[gen2.watchdog]]; увеличьте число минут или задайте 0.",
  "t.5i79ui7nsx": "[[sw.sec.log]]",
  "t.5isz5yv3zr": "[[not2.grpTable]] · [[not2.colKind]]: одна строка на новинку: «[[not2.n.cqz]]», «[[not2.n.itu]]», «[[not2.n.dxcc]]», «[[not2.n.grid]]», «[[not2.n.px]]», «[[not2.n.call]]», а в конце «[[not2.n.worked]]». У названия есть знак «?», объясняющий новинку.",
  "t.5jynxokwi": "Блок [[bands.title]] страницы «Станция» показывает, какие диапазоны открыты и кто Вас слышит. Ему нужны онлайн-сервисы: когда они выключены, блок сообщает об этом, а кнопка «[[prop.settings]]» ведёт в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], где включаются прохождение и PSK Reporter.",
  "t.5m3sdjc0r": "Q65-30A выбирается в переключателе режимов: периоды по 30 s (чётные и нечётные), сообщения как в FT8 (включая RR73), 65 тонов в полосе около 217 Hz. Он чувствительнее FT8 и подходит для 6 м и 2 м: частоты 50,275 и 144,180 MHz, частоты EME находятся в списке частот.",
  "t.5peakirobp": "[[rep.title]] · [[rep.auto]]: флажок, по умолчанию включён. При каждой серьёзной ошибке сам отправляется краткий анонимный отчёт (одинаковые ошибки не чаще раза в час, и есть суточный предел). Если выключить, ничего не отправляется, а очередь очищается. Под флажком строка сообщает, сколько отчётов ожидает отправки и сколько уже отправлено сегодня (только при включённом флажке).",
  "t.5ra1w2l7h2": "текст, выделенный в окне RX, становится именем",
  "t.5s7xymi4qb": "[[sw.p.operator]] · [[sw.p.surname]] и [[sw.p.email]] (необязательно): они хранятся здесь, на этом ПК, и не передаются. Заполняйте их, только если Вам это удобно.",
  "t.5uce2jo0ci": "Обе станции должны использовать один и тот же режим, те же тоны и ту же полосу: с разными значениями ничего не читается. Если вы не знаете, что использует другая станция, попробуйте сначала 8/250 в Olivia и 16/500 в Contestia.",
  "t.5vw53tjgnw": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] Вы выбираете, какие новинки Aurora подсвечивает в списках («Активность диапазона», окно RX) и какими цветами. Это первая часть: таблица новинок и «уже отработано». Флажки таблицы относятся к движку: они применяются кнопкой «[[sw.save]]» внизу; остальные на этой странице применяются сразу. С внешним движком (JTDX) страница показывает вместо этого одну таблицу с цветом, подсветкой и звуком для каждого типа.",
  "t.5vxf2cs3po": "[[sw.tab.autocq]]",
  "t.5xjoj8hpia": "возврат на приём, когда передача доходит до этого места; текст после него остаётся в окне неотправленным",
  "t.5y21s74qhh": "[[digi.ms.receive]] · [[digi.freq.rx]]: звуковая частота, которую слушает приёмник, от 200 до 3500 Hz (заводское значение 1000). Введите число и покиньте поле; если оно вне диапазона, возвращается прежнее значение. Меняйте, когда хотите слушать другой сигнал.",
  "t.5zif2xo3cx": "Панель макросов удлиняется или укорачивается перетаскиванием её правого края (тонкая линия рядом с ней); двойной щелчок по линии восстанавливает исходный размер.",
  "t.5zj325q98c": "Настройки: оформление и оповещения",
  "t.61olh4f8ap": "Кнопка «RX» на вкладках панели «Журнал» (рядом с «[[log.tab.log]]» и «[[log.tab.map]]») включает и выключает окно RX: когда оно выключено, панель «Журнал» занимает всё место. Ваш выбор сохраняется.",
  "t.61wrjax8vy": "Нужны Ваш позывной и локатор ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]) и частота радиостанции, считанная по CAT. Индикатор в блоке показывает, как прошла последняя отправка; если WSPRnet не отвечает, повторные попытки идут не более одного часа. Страница также показывает, сколько загрузок ещё ожидает, включая ту, что выполняется.",
  "t.63ih2szxre": "первый текст, если есть позывной, второй, если нет",
  "t.64k0z9tvzw": "Жёлтая метка «DX» с позывным, локатором, флагом и страной — это станция, которую Вы вызываете; если станции нет, стоит прочерк.",
  "t.64yjq7sg1i": "PTT только по RTS или DTR, без CAT: выберите модель Hamlib «Dummy» и укажите порт в [[cat.port]]; затем в блоке [[cat.grp.ptt]] выберите RTS или DTR.",
  "t.658fqstg8w": "Чтобы вернуться назад или на другом ПК: «[[bak.restore]]», выберите zip, затем закройте Aurora из области уведомлений и откройте снова.",
  "t.65hgio7l3w": "Как в WSJT-X 3.3: RR73 от DX, адресованный вам, возобновляет QSO; Wait and Call срабатывает на любой CQ от DX (в том числе CQ EU или CQ TEST) и больше не вызывает DX снова после адресованного вам 73/RR73; позывной узнаётся и с /P. STOP, другой DX, выбранный вручную, или смена диапазона обнуляют лимит Wait and Call; выключение Wait features снимает Wait and Pounce с боевого взвода; при включённом Tune передача не начинается, а Wait не реагирует.",
  "t.6839g5vffi": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] → «[[int.title]]»: добавьте или откройте получателя журнала с адресом 127.0.0.1 и портом, который слушает журнал.",
  "t.68o80n33zg": "Строки Band activity и окна RX имеют одинаковые отметки. Почти у каждого цвета есть подсказка: наведите курсор на строку.",
  "t.6abev1wl8q": "Панель [[ssbc.statsTitle]] всегда видна в режиме SSB и относится к активному контесту: таблица по диапазонам (QSO, дубли, очки, множители), отработанные множители из общего числа, темп, прошедшее и оставшееся время и число QSO в час.",
  "t.6actz0owru": "«и» на языке другой станции",
  "t.6eh9mk1rf1": "При включённом «[[not2.unconfirmed]]» (или «[[not2.unconfirmedGrid]]») в списке Band activity строки, которые новые только из-за отсутствия подтверждения, используют тот же цвет, что и новые, но светлее и с полосами; по-настоящему новые остаются сплошными. Предпросмотр в [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] показывает разницу.",
  "t.6g8k1mp32h": "Окно «[[cop.title]]»",
  "t.6gou60wrvz": "Она не работает во время передачи, только с ПК, на котором запущена Aurora, и не работает с OmniRig. Наведите курсор на кнопку, чтобы увидеть, что делает щелчок.",
  "t.6ic5d7r7k2": "Очистка только одного окна: в заголовке Band activity и окна RX нажмите «[[list.clear]]». Очищается только это окно, новые сообщения появляются снова.",
  "t.6m74ymojqa": "Контест: панель и вкладки",
  "t.6mg9gb24dv": "[[tab.bands]] · [[bands.all]]: возвращает список к исходному — диапазоны от 160 м до 2 м (несмотря на название, редкие диапазоны он не включает: они включаются по одному).",
  "t.6nxdm6ad20": "передаёт в SSTV картинку из папки картинок для отправки (%C: с позывным другой станции)",
  "t.6ozcdlxpxt": "Aurora отправляет каждое QSO в программы журналов и в онлайн-сервисы только один раз, в момент занесения. Если журнал был закрыт или не было сети, QSO может не дойти. Кнопки «отправить повторно» для QSO, уже находящихся в журнале, нет; вот что можно сделать.",
  "t.6p3tat9qbw": "[[ca.station]]: «[[ca.station.ok]]», если заданы позывной и локатор; «[[ca.station.bad]]», если одного не хватает. Ссылка «[[diag.fix]]» ведёт на страницу личных данных.",
  "t.6qno0ail04": "[[fil.decode]] · [[dec.depth]]: выпадающий список с [[dec.depth1]], [[dec.depth2]] и [[dec.depth3]] (заводское значение). Применяется к FT8, FT4, JT65, JT9 и MSK144; Q65 всегда использует глубокий поиск. Чем глубже, тем больше слабых сообщений Вы находите, но тем сильнее нагружается процессор: перейдите на [[dec.depth1]], если ПК медленный или декодирование не успевает завершиться вовремя.",
  "t.6tqy24ukgf": "DX Map: диапазон, линии и позывные",
  "t.6u9cfb32rf": "Aurora показывает две громкости звуковой системы ПК и меняет их, только когда вы двигаете ползунок: громкость записи входа (ползунок Rx) и громкость выхода к трансиверу (ползунок TX Lvl). При запуске Aurora их только читает и ничего не пишет, так что WSJT-X и другие программы находят звуковую карту такой, какой её оставили; уровень записи меняется только ползунком Rx или с AUTO (по умолчанию выкл.), уровень передачи — только после того, как вы сами подвигали ползунок TX Lvl. Одни и те же ползунки есть в двух местах: в [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]], рядом с выбранным устройством, и на странице Station (индикатор Rx и панель передачи). Если двигать один, второй движется тоже. По умолчанию выходной ползунок (TX Lvl) не трогает громкость Windows: он уменьшает генерируемый сигнал. Он управляет громкостью Windows только с опцией «[[out.mode]]», рядом с ползунком в [[sw.tab.audio]].",
  "t.6uih8tcruq": "Как QSO заносятся в журнал",
  "t.6xol75gi2": "Порт Logger32 должен совпадать с портом Aurora. Щёлкните правой кнопкой по «UDP» в Logger32 › «Change WSJT/JTDX port #»: по умолчанию 2237, как и порт Aurora («[[ens.k.UDPServerPort]]»).",
  "t.6yip7mrxjd": "«[[sstv.rx.stop]]» выключает приём SSTV (FT8 не затрагивается) и становится «[[sstv.rx.start]]»; выключенный приём остаётся выключенным, пока Вы не включите его снова.",
  "t.70756ntvu4": "Страница «Станция», индикатор «[[rxl.title]]»: шкала слева показывает уровень звука, приходящего от трансивера, а ползунок рядом — это «[[rxl.volume]]». Под шкалой надпись сообщает, как идут дела: [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] или [[rxl.state.overdrive]]. Цель — «[[rxl.state.good]]». Если уровень низкий, поднимите ползунок; если он насыщен, опустите его (или снизьте уровень звука на трансивере). Индикатор появляется только пока звуковой вход принимает.",
  "t.70i9kzit68": "Aurora сообщает, что нет rigctld (программы Hamlib)? Обычно его удалил антивирус. В Windows: 1) откройте [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]; 2) нажмите «[[cat.restore]]»: Aurora заново скачает его из официального релиза Hamlib и проверит контрольную сумму; 3) нажмите [[cat.connect]]. Если он исчезнет снова, добавьте папку Aurora в исключения антивируса.",
  "t.72gmjxqrcu": "позывной другой станции без /P, /M и префиксов",
  "t.73ml4ra8oq": "подрежим: BPSK31, PSK63, RTTY, CW, OLIVIA, CONTESTIA меняют режим (OLIVIA-8-250 также тоны и полосу; 8/250 меняет тоны и полосу в Olivia и Contestia); те, которых в Aurora нет (Hell, MFSK), пропускаются",
  "t.74jvtmcft1": "Панель «[[digi.band.title]]»",
  "t.75rxy2xre8": "Изображения в SSTV",
  "t.76gilufj9f": "Выбор: при открытии страницы ни один QSO не выбран (чтобы экспортировать всё, используйте «[[exp.all]]»; так безопаснее: удалить журнал по ошибке нельзя). У каждой строки есть свой флажок; флажок вверху выбирает или снимает все показанные строки («[[exp.selectShown]]»). Кнопки «[[exp.all]]» и «[[exp.none]]» делают то же самое только для QSO, которые показывают фильтры. Строка сообщает, сколько QSO выбрано, сколько показано и сколько всего в журнале; выбранные QSO, скрытые фильтром, всё равно сохраняются.",
  "t.77g5az7xo0": "Под водопадом узкая линейка имеет отметку каждые 100 Hz (число каждые 500), две скобки для Tx (оранжевая) и Rx (зелёная) и знак для каждого сообщения последнего периода.",
  "t.77lakfdx0x": "Что отправляется: версия Aurora и Windows, движок, модель радио, PTT, бэкенд CAT, название звуковой карты, область проблемы, очищенное сообщение об ошибке и число её повторений; после сбоя также очищенный журнал и текстовые отчёты о сбое.",
  "t.77tjno1seh": "[[aud.mode]] · [[aud.dir]]: папка, куда попадают звуковые файлы (имена вида yymmdd_hhmmss.wav). Пусто (заводское) = папка «save» в данных Aurora, показанная серым в поле. Впишите её, только если хотите, чтобы файлы лежали на другом диске; папка вне данных Aurora, оставшаяся от других программ, не учитывается и не показывается.",
  "t.78hhffaman": "текст файла из папки текстов макросов; <FILE> без имени позволяет выбрать файл для поля передачи",
  "t.78hj5bkf0t": "«[[dxs.preview]]»: карточка с примерными данными (позывной IU3ABC), которая сразу меняется при каждом выборе ниже, так что Вы видите результат, не возвращаясь к журналу.",
  "t.78x1ik4zg6": "DX Cluster пуст",
  "t.79bed8k0db": "ослабление звукового выхода в дБ (без числа открывает настройки звука)",
  "t.79v58u75ag": "Если вверху появляется «[[set.loadError]]», Aurora не отвечает: проверьте, что движок включён.",
  "t.7ak4ukn88c": "Какой звук для какого события (вызов мне, новый DXCC, QSO записано…), голос и Ваши собственные файлы WAV или MP3, тишина во время передачи: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (см. «Звуки» и «Голос и собственные файлы для оповещений»). Всплывающие оповещения описаны в «Всплывающие сообщения».",
  "t.7e2o1tktn8": "Передача, режим и приёмник: заблокировать режим или приём, параметры режима с SET, значения сигнала с GET, PTT, фильтры. Пример: <SET BW:250><SNAPNOW> сужает фильтр CW и захватывает сигнал; UR S/N <GET SN> DB записывает измеренный рапорт.",
  "t.7eymh5jsmn": "как <GA>, длинная фраза",
  "t.7f2wnwlpcn": "Особые случаи: то, что [Score] выразить не может, помещается в конец файла, в раздел [Script], небольшую программу с функциями punti(qso) (очки), moltiplicatori(qso) (множители), ammesso(qso) (допустимо) и punteggio(totali) (счёт); пишите только те, которые нужны. Пример: «fn punti(qso) { if qso.cont == \"EU\" { 1 } else { 3 } }». В соревновании RAEM, поставляемом с Aurora, есть полный сценарий, который можно скопировать. Сценарий не может открывать файлы, использовать сеть или запускать программы и сам останавливается, если работает слишком долго; если он завершается с ошибкой, [[ctest.stats]] показывает её, а счёт возвращается к счёту по [Score].",
  "t.7glesm887j": "[[digi.mi.seekLeft]] и [[digi.mi.seekRight]]: переводят приём на следующий сигнал слева или справа, в пределах от 300 до 3300 Hz. Если ничего не найдено, появляется «[[digi.run.seekNone]]»; при выключенном приёме — «[[digi.run.noSpectrum]]».",
  "t.7ho93sgz3d": "Наиболее используемые подстановки: <MYCALL> — Ваш позывной, <CALL>, <NAME>, <QTH> и <WWLOC> — другой станции, <RSTS> и <RSTR>, <DATE>, <TIME>, <BAND>, <MODE>. Полезные команды: <AUTOCQ>, <SAVEQSO> (ставится перед командами очистки), <CLEARQSO>, <FQ:14070.5> (перестраивает радио так, чтобы сигнал попал на эту частоту), <AUDIOFQ:1500>, <WPM:20> и <BAUDRATE:45.45>. <TUNE>, <BOOKMARK> и <MACROS:file> есть в списке, но сегодня отвечают лишь «Command not available yet». Для соревнований: <QSONR> — порядковый номер (001, 002…: он растёт с каждым сохранённым QSO; его исправляют или сбрасывают в панели внизу журнала, «[[digi.log.serial]]»), <NRS> — обмен для отправки (пусто = порядковый номер), а <NRR> — принятый, введённый в поле NRR или взятый правым щелчком по слову («[[digi.word.nrr]]»). При сохранении QSO оба обмена попадают в поля «отправленный обмен» и «принятый обмен» QSO, а поля очищаются. В соревновании <QSONR> начинается заново с 001 с последнего номера соревнования + 1.",
  "t.7husjuoul4": "Icom: 115200, PTT CAT, CI-V 0; в радиостанции CI-V USB Port «Unlink from [REMOTE]», Echo Back OFF, DATA MOD USB. Yaesu: 38400, CAT RTS OFF. Kenwood: 115200, DATA VOX OFF.",
  "t.7k4bb02na5": "«[[lay.settings]]» · «[[cluster.enabled]]» (по умолчанию включено): если включено, Aurora подключается к выбранным серверам, как только появляется позывной станции; если выключено, не подключается ни к одному, и панель DX Cluster остаётся пустой.",
  "t.7kkymswem": "поворачивает ротор на станцию из QSO по короткому пути",
  "t.7ngayo1dqi": "«[[wefax.file.open]]» под элементами приёма декодирует запись: выберите файл WAV (несжатый, PCM 16 бит или float, моно или стерео, с частотой дискретизации от 6000 до 96000 Гц, до 200 МБ), и Aurora подаст его приёмнику так, как будто он пришёл со звуковой карты, как можно быстрее, но блоками, не загружая весь процессор. Появляется ход в процентах и «[[wefax.file.stop]]»; готовые карты попадают в историю, даже если автосохранение выключено. Во время декодирования приём в реальном времени приостановлен и продолжится в конце; запомненная ошибка часов звуковой карты не меняется. Файл, который не является читаемым WAV, вызывает сообщение об ошибке.",
  "t.7noy6nyclb": "Установка Aurora",
  "t.7ojn5qkjfw": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]]. Карточка DXCC (под журналом, на странице [[nav.station]]) сообщает для станции, которую Вы вызываете, новая ли её страна и на каких диапазонах и видах связи Вы с ней уже работали. Здесь Вы выбираете, что она показывает и какими цветами. Выбор применяется сразу, сохраняется на этом устройстве между перезапусками и не проходит через «[[sw.save]]». Данные берутся из внутреннего журнала Aurora и из подключённых программ ведения журнала (например, Log4OM). Порядок на экране: «[[dxs.guide.title]]», «[[dxs.preview]]», «[[dxs.look]]», «[[dxs.rows]]», «[[dxs.bands]]», «[[dxs.colors]]».",
  "t.7p3j6ggm3k": "Передача SSTV длится от получаса до почти пяти минут: держите TX Lvl низким и остановите автоматику FT8 перед передачей. Если она не запускается, причина записывается: «[[sstv.tx.busy]]», «[[sstv.tx.disabled]]» или «[[sstv.tx.notReady]]».",
  "t.7pvf2cbm20": "У карты, открытой крупно, есть инструменты для удобного просмотра: «[[wefax.view.zoomIn]]» и «[[wefax.view.zoomOut]]» (или Ctrl с колесом), «[[wefax.view.fit]]», чтобы видеть её целиком в окне, «[[wefax.view.actual]]» для реальных пикселей, двойной щелчок для переключения между ними и «[[wefax.big.fullscreen]]» для полного экрана. Она открывается уже вписанной; если она больше окна, её двигают, перетаскивая мышью или пальцем. Клавиши: + и − масштаб, 0 вписать, 1 реальные пиксели, F во весь экран, R и L поворот. Если у карты есть записанное аудио, появляется «[[wefax.big.audio]]».",
  "t.7q1u47oqs4": "Позвольте Aurora управлять радио: частотой, режимом и передачей.",
  "t.7qnhr3i66n": "Отделённая панель больше не видна в главном окне; там остаётся уведомление («[[win.elsewhere]]»), где это нужно, а соседние панели сами расширяются, заполняя место. Когда Вы возвращаете их все, возвращается обычная страница.",
  "t.7qw8hdnyii": "«[[pair.name]]»: имя, по которому устройство можно узнать в списке сопряжённых устройств (от 1 до 64 символов). Затем «[[pair.button]]».",
  "t.7t4yfoafpu": "Контест: календарь, тренировка и анализ",
  "t.7t8f9gxw4m": "[[cat.profile.new]]: создаёт НОВЫЙ профиль с базовыми настройками (сохраняется только выбранная система управления: всё остальное, включая порт и модель, начинается с нуля) и делает его используемым; трансивер отключается. Если поле имени пусто или профиль с таким именем уже существует, Aurora предлагает свободное. После этого настройте новый трансивер на странице [[sw.pg.radio]].",
  "t.7uufo25jfm": "использует макросы режима (PSK31, PSK63, RTTY, CW) без смены режима; пусто: макросы текущего режима",
  "t.7wh43tryrj": "Цвета строк: диапазон, на котором Вы находитесь, подсвечен; другой фон у станций из списка желаемых и у DX-экспедиций в эфире по данным NG3K (цвет выбирается в [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).",
  "t.7wiig5s96s": "[[ctest.list]] открывает окно со столбцами [[ctest.colActive]] (стрелка отмечает активное), [[ctest.colName]] и [[ctest.colNotes]]. Первая строка — [[ctest.none]]. Кнопки: [[ctest.edit]], [[ctest.delete]] (запрашивает подтверждение), [[ctest.add]], [[ctest.select]] (двойной щелчок делает то же самое) и [[ctest.close]]. Над таблицей вкладки [[ctest.tab.all]], [[ctest.tab.ssb]], [[ctest.tab.cw]], [[ctest.tab.rtty]], [[ctest.tab.psk]], [[ctest.tab.digi]] и [[ctest.tab.other]] показывают контесты по режимам (контест с двумя режимами есть в обеих вкладках, число рядом с названием), а поиск работает внутри выбранной вкладки.",
  "t.7z0nrroj8y": "открывает этот макрос для редактирования",
  "t.7zbip0uwcg": "[[sdr.radios]]: текстовое поле с подходящими трансиверами (TCI: SunSDR2, ColibriNANO с ExpertSDR2/3, ANAN и Hermes-Lite 2 с Thetis; для QMAP также нужен поток I/Q от TCI или файл WAV I/Q) и две кнопки, [[sdr.guideTci]] и [[sdr.guideQmap]], которые открывают пункты Справки о TCI и QMAP (если настройки находятся в отдельном окне, Справка открывается в главном окне и появляется «[[sdr.opened]]»).",
  "t.81rjwcggbr": "QMAP: все команды",
  "t.82rtrixm2i": "Кнопка RX/TX (или клавиша Pause) открывает передачу и удерживает её включённой: без текста RTTY передаёт сигнал паузы. Всё, что Вы печатаете в окне передачи, уходит по мере набора; нажмите RX/TX или Pause ещё раз, и передача вернётся на приём, как только уже набранный текст будет отправлен. Esc останавливает немедленно.",
  "t.83xmrihth": "Карточка не появилась: для тех, кто выбрал «Off» или «Icon only», это нормально; во время режима «Не беспокоить» не появляется ни одна. Карточки появляются только при закрытой Aurora: при открытой Aurora уведомления показывает сама Aurora внутри своего окна. Агент ведёт небольшой журнал в %TEMP%\\aurora-agente.log, полезный тому, кто Вам помогает.",
  "t.85uquf1jej": "В конце панели есть одна шестерёнка: она сразу открывает [[nav.settings]], без меню, уже на странице настроек, соответствующей тому, где вы находитесь (страница и используемый режим). [[nav.wiki]] и [[nav.news]] больше не в панели: они внутри «Настроек», внизу дерева слева, [[nav.wiki]] зелёным и [[nav.news]] золотым, рядом с «[[sw.tab.info]]» фиолетовым. На телефоне выпадающее меню остаётся, с [[nav.wiki]] и [[nav.news]]; менять настройки можно только с ПК.",
  "t.864ykzvw51": "Страница [[nav.propagation]] (заголовок «[[prop.title]]») содержит слева условия на солнце и диапазонах, справа — карту и список тех, кто Вас принял. Ей нужны онлайн-сервисы; когда они выключены, страница сообщает об этом и показывает кнопку «[[prop.settings]]» (они включаются в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). Вверху кнопка «[[prop.refresh]]» сразу запрашивает новые данные, не ожидая 10 секунд.",
  "t.893l0gpyf5": "В блоке «[[fil.highlight]]» впишите позывные, префиксы или страны: их строки станут фиолетовыми. «[[fil.bypass]]» на время показывает всё, не теряя фильтров.",
  "t.89j2ekcpth": "Полная статья: подробное объяснение — «Выключение или изменение оповещений: выделенные карточки, звуки, цвета, сообщения»; о цветах — «[[sw.tab.colors]]».",
  "t.8hsl3gdylv": "У панели «Журнал» три вкладки в строке заголовка: «[[log.tab.log]]» (или «[[log.tab.internal]]», если внешнего журнала нет), «[[log.tab.map]]» и «RX» (окно RX). В строке справа общее число QSO («n QSO»).",
  "t.8iair2nbfn": "[[panel.cq]] и DX-экспедиции",
  "t.8jcjdi8zod": "время начала QSO",
  "t.8ky5022i6j": "[[cat.civ]]: появляется только при Hamlib, последовательном порте и трансивере Icom (или когда значение не равно 0). Его нужно вводить в ДЕСЯТИЧНОМ виде и обычно оставлять 0 (= заводской адрес модели). Как его преобразовать и какие ошибки самые частые, описано в отдельном разделе.",
  "t.8l8nb6e2zc": "Верхняя панель: режимы",
  "t.8lc8xmywjv": "[[auto.b1]] · флажки новизны: [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_zone]], [[kind.new_call]], [[kind.new_call_band]]. Aurora отвечает только на CQ, приносящие одну из отмеченных новизн; обычных CQ никогда не достаточно. По умолчанию включены: [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]] и [[kind.new_grid]] (новая страна, DXCC на новом диапазоне или режиме, зона CQ, новый квадрат); отметьте и остальные, если Вам интересны новые станции.",
  "t.8mtvlqjksv": "Если у радиостанции нет сплита по CAT (например, IC-820H): в [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.doppler]] выберите «[[sat.mode.rx]]» и «[[sat.mode.tx]]» (с «[[sat.mode.auto]]» на инвертирующем транспондере Вы принимаете в USB и передаёте в LSB) и попробуйте флажок «[[sat.uplink.on]]». Это экспериментальная функция, не проверенная на реальных радиостанциях и по умолчанию выключенная; она сама отключается, если радиостанция отклоняет команду. Парковка и ротор с реальным ротором тоже не проверялись.",
  "t.8nx29ewr2p": "«[[rep.sendBundle]]» загружает пакет без личных данных и показывает код: сообщите его тому, кто Вам помогает, чтобы он смог его найти.",
  "t.8ojezq0kub": "После обновления заново подключите программы, использующие трансивер через Aurora. Что изменилось, описано в [[nav.news]]. Та же новая версия показывается и в заголовке (см. «Полоса в заголовке и афиша»).",
  "t.8rykxs8cxp": "[[ctl.stop_rx]]: останавливает приём и текущее декодирование (не передачу). [[ctl.decode]]: сразу декодирует последний записанный период.",
  "t.8s37mh88k": "дата последней QSO с этим позывным в журнале (пусто, если нет)",
  "t.8xb25moa08": "Во время передачи кнопки «FT8» и «VHF» не переключают группу: наведите на них курсор и прочтёте «[[mode.locked]]». Дождитесь конца периода или остановите передачу кнопкой STOP TX.",
  "t.8xgzbqt59i": "Метеокарты в WEFAX",
  "t.8xs9yiu4ax": "«[[contest.map]]»: для диапазона, выбранного на вкладках, уже проведённые множители, новые, которые Вы слышите сейчас (оранжевые), и услышанные, но уже взятые (по декодированиям последних 15 минут). Щелчок по ячейке или по позывному вызывает станцию. Если в контесте нет множителей, написано «[[contest.noMult]]».",
  "t.8zenfk21dm": "Индикатор каждого сервиса (кружок перед названием): показывает «[[ens.led.off]]», «[[ens.led.untested]]», «[[ens.led.ok]]» или «[[ens.led.err]]»; наведите курсор, чтобы увидеть причину. Знак «?» рядом с названием объясняет сервис. Переключатель сервиса называется «[[ens.svc.on]]»; знак «?» рядом с ним объясняет, что он делает.",
  "t.90xgkxizz2": "Настройте радиостанцию на частоту PSK31 (например, 14,070 MHz USB) или RTTY (14,080 MHz) и откройте [[nav.textModes]]: прослушивание начинается само при входе на страницу и прекращается при выходе, если только в Настройках не включено «[[digi.autoReceive]]». Через [[digi.menu.options]] › [[digi.mi.listen]] Вы останавливаете и снова запускаете его. Выберите режим в меню [[digi.menu.mode]] и наведите настройку на сигнал щелчком по водопаду: текст появится в окне приёма.",
  "t.913rpxepdv": "Когда другая станция подтверждает строку, отметьте QSL (или [[qtc.allOk]], если она подтверждает всё), затем [[qtc.saveSent]]: только подтверждённые строки отмечаются как отправленные и больше не предлагаются.",
  "t.917qkm25ir": "«[[lay.lists]]» · «[[wish.calls]]» и «[[wish.prefixes]]» (четыре текстовых поля, одна запись в строке, не более 200 в списке): в «[[wish.calls]]» позывные, например 3Y0J (допустимы и с суффиксом, K1ABC/P, или префиксом, F/K1ABC); в «[[wish.prefixes]]» начало позывного, например VP8, ZL9 или 3Y, полезно для экспедиций. Только буквы, цифры и косая черта, без пробелов.",
  "t.92sck5hajn": "На ПК кнопки «CQ» нет: в панели [[panel.tx]] щёлкните по шестой строке («[[tx.step.6]]») и включите [[ctl.enable_tx]]; на телефоне достаточно кнопки «[[phone.cq]]». Тот, кто ответит, обрабатывается автоматически (см. «Вызов CQ со страницы «Станция»»).",
  "t.937b96y30u": "[[digi.edit.title]] · [[digi.edit.subset]]: выпадающий список фильтрует список команд по группам ([[digi.edit.group.all]], [[digi.edit.group.text]], [[digi.edit.group.program]], [[digi.edit.group.frequency]], [[digi.edit.group.autocq]], [[digi.edit.group.macros]], [[digi.edit.group.mode]], [[digi.edit.group.rotor]], [[digi.edit.group.rtty]], [[digi.edit.group.sstv]], [[digi.edit.group.cw]], [[digi.edit.group.hell]]). Ниже список: один щелчок выбирает команду и показывает её объяснение, двойной щелчок вставляет её; команды с «[[digi.edit.soon]]» запланированы, но пока не активны.",
  "t.93o8nisihm": "BBLogger: QSO из ADIF-файла Aurora",
  "t.93swe6ydkk": "Включите «[[rot.set.enabled]]»: состояние станет «[[rot.state.connected]]», и Aurora будет подключаться и при следующих запусках.",
  "t.93uty182p7": "«[[sstv.rx.mode]]» (выпадающий список) и «[[sstv.rx.force]]»: чтобы принудительно задать режим, не дожидаясь VIS ([[sstv.rx.forceHint]]). Выпадающий список начинается с режима, выбранного в «[[sstv.rx.lock]]» в Настройках SSTV (или с предложенного для передачи).",
  "t.94qchg6es7": "Все Ваши QSO с поиском по позывному, датам, диапазону и режиму: выберите нужные и сохраните их в файл ADIF командой «Save ADIF…».",
  "t.957ettm5zf": "Полная статья: «Отчёты об ошибках»; «Отчёты об ошибках: что отправляется и как это выключить»; «Отправка журнала тому, кто вам помогает».",
  "t.95v4sifku3": "Только отчёты об ошибках без личных данных и только если флажки отмечены (по умолчанию они отмечены). Выключите их в [[nav.settings]] › [[sw.sec.access]] › [[tab.support]].",
  "t.96w8hg93nm": "Двойной щелчок по строке внутреннего журнала: открывается окно для исправления или удаления QSO (см. «Исправление или удаление QSO»). В журнале Log4OM2 Вы читаете «[[log.readonly4om]]».",
  "t.96xzk0is4d": "Бессмысленный текст в RTTY: проверьте [[digi.rtty.shift]] и [[digi.rtty.baud]] (они должны быть такими же, как у станции) и попробуйте [[digi.rtty.reverse]].",
  "t.97umn1xrzs": "[[gen2.logFilter]] · [[gen2.fromDate]] (текстовое поле, по умолчанию пусто): учитывает только QSO, проведённые начиная с этой даты и времени, в формате YYYYMMDDHHMMSS (например, 20260101, чтобы начать заново с 1 января; недостающие цифры считаются нулями). Пусто = учитывается весь журнал. Полезно, чтобы начать с нуля для диплома или нового места, не удаляя журнал.",
  "t.98zyavxb98": "[[nav.settings]] › [[sw.tab.info]]. Это страница-презентация Aurora, внизу дерева настроек и вне семейств. На ней нет ни флажков, ни полей для настройки: Вы читаете её, и есть ссылки.",
  "t.999zccnqgw": "Откройте [[nav.log]] в верхнем меню и найдите QSO: введите позывной в поле поиска или отфильтруйте по датам, диапазону и режиму.",
  "t.9aem6g1d7c": "«[[rep.active]]»: [[rep.activeTip]]",
  "t.9c02ucdo2": "На страницах режимов в [[nav.settings]] › [[sw.fam.modes]] ([[sw.sub.ft8]] › [[fil.decode]], [[sw.sub.jt]], [[sw.sub.vhf]]) находятся параметры декодера WSJT-X с его заводскими значениями: глубина (Fast, Normal, Deep), одиночное декодирование вокруг Rx, усреднение периодов и автоматическая очистка среднего для Q65, априорный анализ, глубокий поиск и агрессивный уровень для JT65, F Tol для JT65, JT9, MSK144 и Q65. Самые используемые вынесены и кнопками рядом с режимом: «Avg» и «Auto ⟲» в Q65, «AP» и «Deep» в JT65. Они применяются со следующего периода.",
  "t.9c4mamtdlg": "[[rep.title]] · [[rep.id]] и [[rep.newId]]: случайный номер, который идентифицирует эту установку в отчётах, не сообщая, кто Вы. «[[rep.newId]]» создаёт новый: прежние отчёты больше нельзя связать с этой установкой. Когда: если хотите «начать с нуля».",
  "t.9f73n1nfny": "[[snd.title]] · банк звуков: внизу блока есть выпадающий список «Банк звуков» со всеми звуками по категориям; щелчок по названию воспроизводит его (при выбранной громкости), никуда его не назначая. Он нужен, чтобы спокойно выбирать, прежде чем пользоваться меню события.",
  "t.9fv2msrwwb": "«[[digi.band.validation]]»: насколько строго проверять позывные ([[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]], [[digi.band.valMaximum]]; по умолчанию «Normal»). Aurora подсчитывает, как выглядят позывные каждой страны (по журналу, по спотам DX Cluster и по MASTER.SCP, если Вы положите его в папку данных), и позывной редкой формы должен быть услышан несколько раз, прежде чем он считается проверенным. Выше = меньше выдуманных позывных, но они появляются медленнее. Изменение сохраняется, и несколько секунд кнопка показывает выбор.",
  "t.9g4dn70ez6": "Проверьте на эквивалент антенны: вызовите CQ и следите за радиостанцией.",
  "t.9h6d0x3qgn": "Остерегайтесь дубликатов: один и тот же журнал должен получать QSO только одним путём (поток WSJT-X с QSO Logged, Logged ADIF, ADIF по UDP или N1MM XML). Если значение помечено красным, исправьте его: пока оно не станет верным, список не сохраняется.",
  "t.9hpqo3h9r0": "[[sstv.set.grpTx]] · [[sstv.set.defaultMode]]: режим, уже выбранный в композиторе при открытии передачи (заводской Martin 1). Выберите тот, которым Вы обычно пользуетесь; для каждого изображения его всё равно можно изменить.",
  "t.9kg79qblm9": "Aurora работает и когда радио не подключено по CAT: она всё равно декодирует и передаёт, но частоту радио вы меняете сами.",
  "t.9ltfuelr27": "Над окном расположена панель макросов: 4 ряда по 12 клавиш. Щелчок запускает макрос, а клавиши клавиатуры F1-F12 запускают макросы первого ряда; правый щелчок редактирует его (или «[[digi.mi.macrosMode]]» в меню [[digi.menu.configure]]): клавиша, метка, цвет, текст, команды между < >, для всех режимов или только для используемого (см. «Панель макросов» и «Редактирование макроса»). Данные другой станции, которые используют команды <CALL>, <NAME> и <QTH>, находятся в синей строке текущего QSO, на вкладке «[[digi.log.title]]» справа: впишите их туда или они заполнятся двойным щелчком по позывному в окне приёма (см. «Правая колонка: вкладка «[[digi.log.title]]» и текущий QSO»).",
  "t.9nj12hlsc5": "контест: время UTC более ранней QSO с этим позывным (пусто, если нет)",
  "t.9noy5epnzd": "Либо: тип JT_MESSAGE на порту основного сервера, если Вы хотите получать в Log4OM и состояние (частота, текущий DX). Только один из двух, не оба.",
  "t.9pbtgwzcrg": "Обычно трогать [[ctl.hound]] не нужно: при включённом [[gen2.houndAuto]] (по умолчанию), как только Вы выбираете Fox и слышите его передачу в Fox/Hound (строки с меткой FOX), Aurora включает Hound, переносит Tx выше 1000 Hz и включает [[ctl.split]]; она сама выключает его, если станция отвечает обычными сообщениями или Вы выбираете другой DX. Кнопка [[ctl.hound]] нужна только для принудительного включения вручную.",
  "t.9qxdctd8wa": "Режимы FST4 и FST4W (маяк)",
  "t.9qzmjcgx19": "[[ctl.enable_tx]] и STOP всегда под рукой.",
  "t.9slq1myfof": "Журнал ADIF: повреждённое поле больше не теряет остальное",
  "t.9slrf1olb7": "поворачивает ротор на этот азимут (0-359)",
  "t.9uzm17xubq": "Проверка сети при связывании",
  "t.9vxhh0g76u": "когда этот текст приходит в приёме (* = что угодно), запускает макрос; <OnRX:> удаляет все такие правила",
  "t.9wdjvqt2ao": "случайная строка файла",
  "t.9wobeehnhq": "Отсутствует Ваш позывной: без него Aurora не знает, какие сообщения адресованы Вам. «[[diag.fix]]» открывает [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].",
  "t.9ylyeswjgx": "Сообщение уходит с обрезанным началом: увеличьте [[gen2.txDelay]] (0,3 или 0,4).",
  "t.a0gif2icbs": "[[nav.qmap]]: появляется только в группе «VHF» и только если в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]] включено «QMAP page in the menu». Требуется SDR-приёмник (см. «QMAP: все команды»).",
  "t.a1nh4ms5ti": "[[cop.choose]] · [[cop.double]] и [[cop.single]]: выберите, нужен ли для перехода трансивера на станцию спота двойной щелчок (заводской, исключает случайные щелчки) или достаточно одного (быстрее).",
  "t.a2n5tqidvq": "Оранжевая полоса в заголовке: на ПК, как только найдена новая версия, Aurora загружает её в фоне, и вместо значка Вы видите номер версии со стрелкой вниз, индикатор выполнения с процентами и оставшимися секундами, затем «[[upd.strip.verifying]]» (проверка подписи). Когда загрузка заканчивается, она становится «[[upd.strip.ready]]» с кнопкой «[[upd.strip.install]]» (установка и перезапуск одним щелчком). Если загрузка не удалась, появляется «[[upd.strip.failed]]» с «[[upd.strip.retry]]». Щелчок по версии открывает небольшую панель выше.",
  "t.a3krvubt7f": "В Linux Aurora использует PulseAudio или PipeWire и показывает те же устройства, что WSJT-X и JS8Call: для приёма выберите вход («alsa_input…»), для передачи — выход («alsa_output…»). Имя, которое вы используете в WSJT-X, можно также ввести вручную.",
  "t.a5nxzlbdoc": "немедленно прекращает передачу",
  "t.a76c6sw8s3": "Строки с кодом скрыты; чтобы увидеть их, включите [[gen2.showOtp]] в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].",
  "t.a7g7gtp06d": "«＋ [[exp.add]]» открывает форму для QSO, проведённого вне Aurora: [[exp.f.call]], [[exp.f.date]] и [[exp.f.time]] (UTC), [[exp.f.band]] или [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] и [[exp.f.comment]]. «[[exp.addSave]]» заносит его как обычное QSO (журнал, ADIF-файл и подключённые программы); «[[exp.addCancel]]» закрывает форму.",
  "t.aau531gtyu": "Я не нахожу настройку: где искать?",
  "t.ab5g7yj0ve": "Маяк передаёт только при включённом [[ctl.enable_tx]] и между 1400 и 1600 Hz. Отправка в WSPRnet по умолчанию выключена, как «Upload spots» в WSJT-X. Страница относится и к WSPR, и к FST4W.",
  "t.abp15bzhz6": "Когда сильная станция начинает или прекращает передачу, АРУ радиостанции меняет громкость, и слабые сигналы в этот момент теряются. [[ctl.agc]] возвращает эти участки к нужному уровню. Держите её включённой.",
  "t.aezq1kfiql": "Olivia и Contestia — текстовые режимы MFSK для очень слабых и зашумлённых сигналов, типичных для 40-20 м. Их выбирают в селекторе режимов на странице текстовых режимов (в том числе из SSTV и WEFAX) и в меню «Режим», как PSK31, RTTY и CW, с подменю «Тоны» и «Полоса»; внизу два выпадающих списка и S/N синхронизации. В настройках (в том числе в «Настройки › По режимам») задаются тоны, полоса, запас и интегрирование синхронизации и порог шумоподавителя. Макросы <SET TONES>, <SET BW> и <SET SUBMODE> меняют параметры на лету. В селекторе диапазонов есть частоты из диапазонного плана IARU Регион 1 (внутри узкополосных участков цифровых режимов), и при входе в режим радио переходит на этот диапазон. Если тоны и полоса не помещаются в звуковую полосу, появляется предупреждение. В ADIF режим записывается как OLIVIA с подрежимом (например, OLIVIA 8/250); Contestia записывается как CONTESTI. Движок написан на Rust на основе библиотеки Павла Ялохи (её использует и fldigi) и проверен с fldigi в качестве эталона; его ещё нужно настроить на настоящем радио (пороги шумоподавителя). Тоны и полоса должны быть одинаковыми у обеих станций.",
  "t.affhv0akh1": "После слишком многих попыток Вам больше не нравится внешний вид: «[[ap.reset]]» внизу страницы возвращает всё, как в начале (кроме языка).",
  "t.afgw5x3e1m": "Автоматический CQ — это правило блока [[auto.b5]] в [[nav.automation]]: его нет на странице [[sw.tab.autocq]], которая лишь меняет диапазон в заданное время.",
  "t.agtfixf7c1": "клавиши Ctrl для внешнего TNC: в Aurora они ничего не пишут",
  "t.aias45wioh": "Выбор стиля индикатора радиостанции.",
  "t.aieq7eevnp": "Верхний край водопада (тонкую линию) можно перетаскивать, чтобы изменить высоту.",
  "t.an8b8danny": "переносит приём на частоту передачи",
  "t.ancesr0xh0": "Страница «[[hist.title]]» перечисляет все принятые Вами сообщения, с поиском. Это не журнал QSO: здесь услышанные станции, а не проведённые связи. В меню у неё нет пункта: она открывается по адресу «#/storico» (например, в браузере, после адреса Aurora). Aurora запоминает её как последнюю открытую страницу.",
  "t.anpoqqly5o": "частота трансивера в кГц (<KHZ:n> для n знаков после запятой)",
  "t.aoaohszh2x": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]: «[[bak.make]]» кладёт файл Aurora-impostazioni-….zip на рабочий стол.",
  "t.aowv3uhoj0": "Антивирус: в отчётах также указывается, какой антивирус установлен. Если после обновления или при запуске некоторые файлы Aurora отсутствуют (удалены антивирусом), отправляется отчёт: он помогает понять, какие антивирусы блокируют Aurora. Отключается теми же флажками.",
  "t.aq5rhdvhac": "«[[int.port]]»: порт, который слушает программа (от 1 до 65535). Обычные значения: 2237 для потока WSJT-X, 2333 для многих журналов, принимающих ADIF, 12060 для XML от N1MM. Он должен совпадать с указанным в принимающей программе; две программы не могут слушать один и тот же unicast-порт на одном ПК (используйте разные порты или multicast).",
  "t.auxh30u8dj": "При активном соревновании метки DUPE в Aurora BIGScan учитывают только QSO журнала в окне дат соревнования (даты повторяются каждый год), следуя [[ctest.f.noBand]] и [[ctest.f.noMode]] и только для допустимых категорий (CW, телефон, цифровые). Строка состояния показывает «Contest: name»: щелчок снова открывает список.",
  "t.aw03ud6q49": "Откройте [[nav.settings]]: слева находится дерево настроек, разделённое на цветные семейства: «[[sw.sec.station]]», «[[sw.fam.modes]]», «[[sw.fam.log]]», «[[sw.sec.look]]» и «[[sw.sec.access]]». При открытии всё свёрнуто: щелчок по семейству раскрывает его, а внутри «[[sw.fam.modes]]» у каждого режима своя ветка со страницами.",
  "t.ayneulhr64": "[[wfs.colors]] · [[wfs.gain]] и [[wfs.zero]] (от −50 до 50, по умолчанию 0): если повысить усиление, сигналы становятся ярче (и шире), если понизить — тоньше и темнее; ноль сдвигает всю цветовую шкалу: при повышении фон тоже светлеет, при понижении фон темнеет и остаются только сильные сигналы. Измените их, если водопад слишком яркий или тусклый.",
  "t.azanypqxaj": "переключается на передачу и отправляет текст макроса (одна: текст из поля)",
  "t.b1cmu6sai6": "Какие уведомления отправляет агент и когда",
  "t.b4iufcpm78": "Заводские макросы, первый ряд: F1 AutoCQ (включает автоматический CQ), F2 CQ, F3 Call 3, F4 Call, F5 Info, F6 Brag, F7 Bye (завершает, сохраняет QSO и наводит порядок), F8 Clear (очищает окна и QSO), F9 TX, F10 RX, F11 «<<» и F12 «>>» (поиск сигнала слева или справа). Ряд Ctrl: MyCall, MyName, MyQTH, а также Call, Name, QTH, которые записывают данные QSO в поле; Ctrl-F12 «BM» — закладка, которая пока не активна.",
  "t.b50c7d04mf": "При наведении курсора показываются [[hl.cpu]], [[hl.mem]], последнее декодирование (например, «0,9 с из 15,0 с»), [[hl.threads]] и состояние [[hl.audio]], [[hl.cat]] и [[hl.clock]].",
  "t.b55uy1dhoo": "Спутники: слежение ротором и передача без сплита",
  "t.b5lrj6ntbq": "«[[cluster.callsign]]» доступен только для чтения и берётся из [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]: укажите там свой настоящий позывной, потому что многие серверы требуют его для входа.",
  "t.b69qeopzkh": "«[[ens.g.pskspot]]» · «[[ens.k.PSKReporter]]» (по умолчанию включено): отправляет в PSK Reporter станции, которые Вы принимаете, чтобы передающие видели, где их слышно; так Вы вносите вклад в карту прохождения. Выключите, если не хотите, чтобы Ваш позывной и позывные принятых станций попадали в интернет. «[[ens.test]]» проверяет, доступен ли PSK Reporter, не отправляя спотов.",
  "t.b6az7cq712": "[[nav.sat]] › [[sat.set.catMap]]",
  "t.b6c8fnkwlt": "[[rd.title]]: дисплей в шапке (частота, режим, приём или передача, S-метр, мощность, КСВ). Каждый стиль — это карточка с предпросмотром на примерных данных: щёлкните понравившуюся. Стили: [[rd.style.fluorescent]], [[rd.style.analog]], [[rd.style.color]], [[rd.style.amber]], [[rd.style.led]], панели [[rd.style.ft2000]] и [[rd.style.ic7610]] (они сами занимают всё место справа вверху). Приборы, которых трансивер не выдаёт, остаются выключенными. На узких экранах (например, 1280 × 800 и 1366 × 768) дисплей всегда компактный (частота, мощность, КСВ и TUNE), и другие стили выбрать нельзя: они возвращаются на более широком экране.",
  "t.b79qyyov1m": "В Windows «[[aud.keepVol.on]]» не трогает громкости Windows: Aurora их не меняет, а уровень приёма настраивается только на радио или в программе.",
  "t.b7vrihwz6k": "Введите свой позывной и локатор (6 символов, например FN42ab).",
  "t.ba4952fi8e": "[[nav.textModes]]: PSK31, PSK63, RTTY, CW и SSTV находятся на одной странице; режим выбирается в меню «Mode» страницы. Когда Вы заходите с другой страницы, Aurora переводит радио на диапазон из бэнд-плана IARU для этого режима (а если на текущем диапазоне его нет — на первый подходящий). Во время передачи этого не происходит.",
  "t.bamdf3nx3h": "Щелчок всегда запускает автоматическую настройку, и кнопка остаётся подсвеченной (жёлтой), пока Вы не выключите её вручную ещё одним щелчком.",
  "t.baxob1wmt3": "Позывной и локатор: первое, что нужно ввести.",
  "t.bbge03zs16": "В настройках контеста, группа [[ctest.g.suggest]]: пока Вы вводите позывной, под ним появляется зона CQ (или ITU) из базы префиксов; щелчок подставляет её в принятый обмен. В группе [[ctest.g.grab]] выберите, что подставлять: [[ctest.gt.cq]], [[ctest.gt.itu]], [[ctest.gt.serial]] или [[ctest.gt.none]].",
  "t.bbpzoqugz": "На ПК откройте [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] и нажмите «[[acc.pair]]».",
  "t.bd8gd5j7r2": "Чтобы отправлять QSO в другую программу ведения журнала или онлайн-сервис, а также повторно отправлять пропущенные, пока журнал был закрыт (параметр «[[ens.k.UDP2Resend]]»), перейдите в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]: это настройки журнала, а не часть этой страницы.",
  "t.bdhj3erxrm": "Карточки: [[ssbc.enter]], [[ctw.card.log]], [[ctw.card.cluster]], [[ctw.card.rate]], [[ssbc.statsTitle]] и по одной карточке на каждый тип множителя (например, «[[ctest.mt.dom]]» и «[[ctest.mt.dxcc]]»); в CW, RTTY и PSK также [[ctw.card.rx]], [[ctw.card.tx]], [[ctw.card.wf]], а в CW и RTTY ещё [[radar.title]].",
  "t.bdm0ifml2s": "Мигающая карточка вверху справа показывает флаг, позывной, страну и время UTC последнего приёма («[[newdx.last]]», с сигналом в dB) станции, которая является новой страной («[[newdx.dxcc]]») или новой на диапазоне («[[newdx.band]]»). Время обновляется при каждой её передаче; карточка исчезает через 10 минут после последнего момента, когда Вы её слышали. Показывается не более 4 карточек.",
  "t.be9g4p5mmd": "Откройте [[nav.log]] в верхнем меню и дважды щёлкните строку: откроется окно «[[exp.edit.title]]» с кнопками «[[exp.edit.save]]» и «[[exp.edit.delete]]». Изменение применяется только к журналу Aurora, не к внешним журналам.",
  "t.bepsbr6ojv": "Olivia и Contestia: два новых режима для самых слабых сигналов",
  "t.bfl67i7yhl": "[[ctl.spot]]: открывает окно «[[digi.spot.title]]», чтобы сообщить о станции в DXSummit (см. «Отправка спота»).",
  "t.bg561tqmnp": "[[bfl.title]] · [[bfl.bands]]: по одному флажку на каждый диапазон, выбранный в [[sw.pg.bands]]. Ничего не отмечено = все диапазоны. Когда Вы отметите некоторые, [[panel.all]] остаётся пустым на остальных диапазонах: используйте, если следите за одним диапазоном, пока трансивер переключается между несколькими.",
  "t.bgxfn1t9w1": "Какой нужен компьютер",
  "t.bitc47h817": "[[ctw.card.log]]: в той же строке находятся общее число QSO ([[ssbc.logTotal]]), «[[ssbc.logAll]]», поиск и карандаш. Карандаш выбирает столбцы журнала контеста (выбор отдельный от обычного журнала). Диапазоны выбираются из контеста и в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]]; в контестах с несколькими режимами кнопки режимов (CW, SSB) стоят рядом с диапазонами. В журнале контеста также есть столбцы «[[digi.log.exs]]» и «[[digi.log.exr]]» (серийный номер, штат или секция), включённые по умолчанию; у QSO, внесённых до этой версии, их нет.",
  "t.bjkckxfzzp": "Сделайте панель выше, перетащив небольшую линию на её верхней кромке (от трёх строк до половины колонки; высота запоминается). «[[digi.band.clear]]» очищает список, историю и позывные на водопаде: сигналы, всё ещё находящиеся в эфире, вернутся сами. На водопаде позывной исчезает, если его не слышали 75 секунд; «[[digi.band.wfCalls]]» в меню [[digi.menu.view]] отключает их все.",
  "t.bm77xne3td": "Столбец [[freq.preferred]] (флажок): строка, на которую Aurora переходит, когда Вы выбираете диапазон в этом режиме. Если у диапазона и режима несколько строк, побеждает отмеченная; остальные — альтернативы, которые Вы выбираете из списка частот рядом с кнопками диапазонов. Если отмеченной строки нет, побеждает самая низкая частота.",
  "t.bqdobcl2dx": "Список сообщений",
  "t.bqie0bvg5f": "«[[sstv.sel.start]]» (серое, если лента пуста): выберите несколько миниатюр щелчком по каждой; «[[sstv.sel.all]]» выбирает все, кнопка «Delete» с числом удаляет их после подтверждения (это нельзя отменить), а «[[sstv.sel.done]]» выходит из выбора.",
  "t.brtyg0hb81": "[[sw.contest.title]] · [[sw.contest.which]]: выпадающий список с контестами, допускающими MSK144 или Q65; активный контест отмечен словом «[[sw.contest.active]]». Пока Вы не выберете один, там написано «[[sw.contest.choose]]» с примечанием [[sw.contest.note]]. Без собственного движка он показывает «[[contest.unavailable]]».",
  "t.bt13cugmym": "Шестерёнка ⚙ на странице каждого режима (FT8, PSK · RTTY · CW, SSTV, Спутники, Контест…) открывает настройки сразу на ветке этого режима.",
  "t.bwz039ctai": "RTTY: движок сам передаёт переключение на буквы там, где нужно, команда ничего не добавляет",
  "t.c1brvz8d3h": "При первом запуске пошаговый мастер спрашивает язык, позывной и локатор, звуковую карту и радио; любой шаг можно пропустить, а всё остальное изменить позже в [[nav.settings]].",
  "t.c2fbj6pqch": "следующий текст не передаётся до <SHOWTEXT> (это были команды для внешнего TNC)",
  "t.c2ymqxc0sf": "Журнал на том же ПК: 127.0.0.1. Журнал на другом компьютере: его IP-адрес.",
  "t.c58v68c4e": "[[rxl.auto]] (кнопка рядом с ползунком Rx, по умолчанию выключена): сама регулирует громкость записи. Она сразу снижается, если сигнал насыщается, и медленно растёт, если он остаётся слабым; приостанавливается во время передачи и сама выключается, если Вы подвигали ползунок вручную. Включите её, если сигналы сильно меняются или Вы не хотите об этом думать; выключите и настройте вручную, если предпочитаете фиксированный уровень.",
  "t.c6unc4ejpk": "Кнопка с названием режима и стрелкой ▾ открывает меню режимов группы, выбранной вверху («FT8» или «VHF»). Выберите режим, и Aurora его установит; во время передачи кнопка не реагирует («[[mode.locked]]»). Она серая только в том случае, если ни радио (CAT), ни собственный движок Aurora не могут сменить режим: подсказка объясняет, как это исправить ([[band.noRig]]).",
  "t.cbde8ixl4c": "«[[wft.palette]]»: цвета (30 палитр плюс Ваша собственная). «[[wft.gain]]» и «[[wft.zero]]»: два ползунка от -50 до 50 (по умолчанию 0); Gain делает сигналы ярче, Zero осветляет или затемняет также фон.",
  "t.cbdu6ywnot": "Счёт следует реальным правилам соревнования, записанным в разделе [Score] файла: очки за ту же страну, тот же континент или другой континент, диапазоны, которые считаются вдвойне, множители (страны DXCC, зоны, районы позывных, префиксы WPX, континенты, штаты, провинции или области из обмена) на каждом диапазоне или один раз, веса диапазонов, бонусы и QTC. У CQ WW RTTY, CQ WPX RTTY, WAE RTTY, BARTG HF, ARRL RTTY Roundup, RAEM, SARTG, Russian WW Digital и Ukrainian DX DIGI они уже есть. [[ctest.stats]] показывает также темп, недопустимые QSO (диапазон или страна вне соревнования), новые множители и сетку диапазон по множителю с недостающими. Счёт по-прежнему оценочный: официальный подсчитывает организатор по Cabrillo.",
  "t.cbjtca26gd": "Сама по себе включает или выключает Auto CQ: повторяет макрос AutoCqText (или F2) с паузой между вызовами (<ACQDELAY>). Если после <AUTOCQ> указан текст, он становится повторяемым вызовом (его команды подставляются в каждом цикле). Двойное нажатие Esc выключает Auto CQ.",
  "t.cfq9xk9ew7": "[[lotw.grp]] · [[lotw.enable]]: ставит цветную полосу под позывным того, кто недавно выгрузил журнал в LoTW, в «Активности диапазона» и в окне RX (по умолчанию включено). Aurora ежедневно загружает общедоступный список ARRL; наведите курсор на позывной, чтобы прочитать дату последней выгрузки.",
  "t.cif26b4j8h": "Log4OM: Settings → Program Configuration → Software Integration → Connections. (название приблизительное, проверьте версию своей программы)",
  "t.ciosirf7nt": "[[sw.digi.perMode]] · CW, «[[digi.cw.som]]» (по умолчанию выключено): вместо таблицы выбирает символ, ближайший по длительностям точек и тире; помогает при неровной работе на ручном ключе.",
  "t.ckxeik4yiq": "язык фраз INT (как <FORCELANGUAGE:xx>)",
  "t.cmckknb386": "SDR с TCI (ExpertSDR, Thetis)",
  "t.con3u3l5we": "[[digi.edit.label]]: текст на кнопке (не более 60 символов). Если он пуст и текста нет, клавиша остаётся пустой.",
  "t.cpe4b3831t": "Радио: LogHX и Aurora не могут открыть один и тот же COM-порт. Если LogHX должен читать частоту, используйте OmniRig в обеих программах (в Aurora: [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] › OmniRig) или отключите CAT в LogHX.",
  "t.cqhp25ac1n": "[[bak.title]] · [[bak.restore]]: открывает окно выбора файла; выберите zip, созданный через «[[bak.make]]». Aurora запрашивает подтверждение («[[bak.confirm]]»); если Вы соглашаетесь, копия подготавливается и применяется при следующем запуске: закройте Aurora из области уведомлений (правый щелчок › Выход) и откройте снова. Если файл не является копией Aurora, она сообщает об этом. После восстановления Вы заново вводите пароли и ключи сервисов. Осторожно: текущие настройки и журнал заменяются.",
  "t.cra1tccxuh": "В первый раз поле читает страницы и занимает полторы секунды; потом поиск мгновенный. Названия страниц тоже ищутся.",
  "t.ctzb98fvg6": "F1: передаёт изображение (как «[[sstv.tx.send]]»), даже пока Вы печатаете в текстовом поле. Не запускается, если Вы уже передаёте или передача не готова.",
  "t.cucqd1jmqp": "[[digi.spot.call]]: позывной станции, уже взятый из текущего QSO (его можно изменить; не более 20 символов, заглавными буквами).",
  "t.cwz5zkuxn2": "Экспедиции Fox время от времени передают код (например, K8R.920749). Aurora проверяет его и сообщает, настоящий ли это Fox.",
  "t.cx84d3g626": "Селектор диапазона и частот SSTV (план IARU, например 14.230 MHz USB): такой же, как на странице текстовых режимов; заблокирован, пока Вы передаёте.",
  "t.d3l1uux8jy": "[[lay.lists]] · [[fil.always]]: текстовое поле; эти позывные или префиксы показываются всегда, даже когда континент, страна или другой фильтр скрыл бы их. Впишите сюда друзей и станции, которые не хотите пропустить.",
  "t.d3z42ldd9g": "Панель [[panel.all]] перечисляет все сообщения, декодированные на диапазоне, самые свежие сверху. В строке заголовка три маленькие кнопки, затем кнопка ⧉ для отделения панели (см. «Отдельные окна и раскладка»).",
  "t.d4jxky1ak1": "Каждое декодированное сообщение появляется со своей частотой; «QSO» переводит радиостанцию на этот сигнал в Q65 с нужным периодом и подрежимом. Для EME строка Луны показывает азимут, элевацию и доплер, а колонка Sked — частоту для использования.",
  "t.d52mu41k9g": "Вкладка «[[sstv.layers]]», под списком, при выбранной фигуре (прямоугольник, эллипс, рамка, полосы): [[sstv.p.filled]], [[sstv.p.stroke]] ([[sstv.p.width]], [[sstv.p.color]]), [[sstv.p.width]] и [[sstv.p.height]] фигуры, [[sstv.p.opacity]] и [[sstv.p.rotation]]. Щелчок по пустому месту предпросмотра или по названию выбранного слоя снимает выбор.",
  "t.d5jtu28zv2": "[[acc.pair]] · [[acc.ttl]]: числовое поле в минутах, от 1 до 60 (по умолчанию 10). Задаёт, как долго код остаётся действительным; код остаётся одноразовым и блокируется после слишком многих неверных попыток. Сохраняется само, если значение в пределах (появляется «[[acc.ttlSaved]]»); вне пределов не сохраняется. Когда: увеличьте, если нужно больше времени, чтобы отсканировать QR-код; безопаснее сократить.",
  "t.d5vgf3ekfu": "Глубина декодирования ([[dec.depth]]) и одиночное декодирование ([[dec.singleDecode]]) тоже применяются к JT65 и JT9, но находятся на странице [[sw.sub.ft8]] › [[fil.decode]]. Кнопка [[ctl.jt_both]] рядом с режимом декодирует также другой режим JT.",
  "t.d61pm7e56g": "Блокировка из другой программы: при включённом «Accept UDP requests» подключённая программа может на ограниченное время заблокировать передачу; панель Tx показывает, кто её блокирует.",
  "t.d63oxmazzi": "[[rot.set.range]]: на сколько градусов может поворачиваться ротор. Варианты: 0° … 360° (заводской, один оборот), 0° … 450°, −180° … 180° (центр на юге), −90° … 450°, 0° … 540°; «[[rot.set.rangeCustom]]» показывает [[rot.set.rangeFrom]] и [[rot.set.rangeTo]], чтобы ввести значения вручную. С роторами на 450° (перекрытие за севером) Aurora выбирает ближайший угол и показывает зону перекрытия.",
  "t.d72vbvtpo6": "«[[int.enabled]]» (при создании включено): если выключено, получатель остаётся в списке со своими настройками, но ничего не получает. Удобно, чтобы приостановить программу, не настраивая её заново.",
  "t.d8g5lzsf9j": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] выберите звук для каждого события.",
  "t.d8klr0d1h8": "[[sw.mem.title]] · «[[sw.mem.load]]»: возвращает настройки этой ячейки (режим, частоты, RTTY, AFC, Snap, шумоподавитель) в движок и подтверждает уведомлением. Недоступна для пустых ячеек или если настройки ещё не поступили. «[[sw.mem.clear]]» очищает ячейку (недоступна, если она уже пуста).",
  "t.dahelw4e2x": "Только при активном соревновании WAE. В окне предлагаются QSO соревнования, которые ещё можно передать станции из QSO (не собственные, не отправленные ранее, не более 10 на станцию), с номером серии; кнопки отправляют заголовок «QTC n/m», все строки или одну (в том числе для повтора). Подтверждённые строки сохраняются как отправленные. Имя <STATS:SendQTC> из импортированных файлов тоже работает.",
  "t.de1wk6mv7y": "[[lay.settings]] · [[clock.auto]] (по умолчанию включено; если Вы его выключили, один раз Вы найдёте его включённым): когда смещение превышает порог, Aurora сама меняет время Windows и, если сети нет, повторяет попытку, когда она вернётся. Нужна Aurora, запущенная от имени администратора. Если Вам это не нужно, выключите и исправляйте вручную через «[[clock.correct]]» или в настройках Windows.",
  "t.dg3ew10dev": "[[cqp.title]] · [[set.reset]]: кнопка; возвращает выбор [[panel.cq]] (категории, списки, строки) к заводским значениям. Затрагивает только этот блок: активность диапазона остаётся как есть.",
  "t.dg9hfpm8v0": "Нажмите «[[rot.short]]», чтобы повернуть на DX-станцию, «[[rot.long]]» — по длинному пути, шаги −10°/−2°/+2°/+10° для точной подстройки, или щёлкните по розе ветров либо введите градусы и нажмите «[[rot.go]]». «[[rot.stop]]» немедленно останавливает ротор.",
  "t.dgf4tcr03o": "рапорт, принятый в последнем записанном QSO",
  "t.dgygycjm1e": "[[auto.b4]]: станции, страны, выбранные из списка DXCC, и, при желании, только некоторые континенты. Фильтры [[panel.all]] (Настройки › Режимы › FT8 · FT4 › Сообщения и фильтры) тоже учитываются: тем, кого они скрывают, автоматический ответ не посылается никогда, в том числе в пробном режиме, и журнал сообщает об этом.",
  "t.djk50fqikz": "Вверху заголовок «[[lp.title.lead]] ПОЗЫВНОЙ?» и метки с диапазоном, режимом, частотой и временем UTC QSO. Если ожидают другие QSO, об этом сообщается («n QSO ожидают»).",
  "t.djnnij0ykf": "Нажмите [[wfs.preview.show]] вверху страницы: настоящие водопад и спектр остаются на виду, пока Вы меняете параметры, и каждое изменение видно сразу. Предпросмотр выключается, когда Вы покидаете страницу.",
  "t.dk3az8ro74": "Общий выключатель звука: «[[alert.button]]» в [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]]. Один звук на событие: та же страница, блок звуков. Цвета и выделения: [[sw.tab.colors]] (та же ветка).",
  "t.dnalzjih55": "Передача останавливается с предупреждением о КСВ: проверьте антенну и кабель; только если уверены, что показание неверно, увеличьте [[gen2.swr]] или задайте 0.",
  "t.dokxt6ihvx": "Маяк передаёт на частоте Tx, если она между 1400 и 1600 Hz, иначе на 1500 Hz. С составным позывным или с 6-значным локатором при выключенном [[mode.wsprType1]] он чередует передачу с «<CALL> LOCATOR6» (в FST4W без мощности). При прослушивании FST4W декодирует в поддиапазоне 1400-1600 Hz, как WSJT-X. При сплите «[[cat.split.rig]]» или «[[cat.split.emulate]]» (WSPR, FST4W, FST4) тон следует за сдвигом радиостанции и не оказывается вне частоты.",
  "t.dp4y67n7qx": "Скорость: [[cat.baud]] должна совпадать с заданной в меню CAT радио (в меню радио, см. руководство: пункт CAT RATE или CI-V…). Если они различаются, радио не отвечает.",
  "t.drhl3kv764": "Макросы внутри макроса: имя другого макроса между < > запускает его на месте (до 10 уровней); ? запрашивает пустые значения или открывает макрос. Пример: <CALL?> <F2> запрашивает позывной, если его нет, и затем запускает F2.",
  "t.drq3umslai": "[[win.open]]: список открытых отдельных окон с их элементами. Для каждого «[[win.show]]» выводит его на передний план (полезно, если оно оказалось под другими или на экране, который Вы не видите), а «[[win.attach]]» возвращает его в главное окно. Если отдельных окон нет, Вы видите «[[win.none]]». «[[win.attachAll]]» возвращает их все вместе (неактивна, если их нет).",
  "t.dseh7um64v": "Телефонные соревнования проводятся выбором SSB в меню «Режим»: QSO засчитываются как телефонные (очки, статистика и Cabrillo с режимом PH).",
  "t.dt3r4z33up": "полужирный текст окна RX (OFF — обычный)",
  "t.du2h29fjqm": "Четыре небольших меню страницы [[nav.textModes]], в каждом по несколько пунктов.",
  "t.du7mf6xmb7": "[[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]: включите «[[cluster.enabled]]» и выберите сервер.",
  "t.duprjv57c": "[[bfl.title]] · [[list.bottom]]: флажок, по умолчанию выключен (новые сообщения приходят сверху, и список прокручивается вниз). Если включён, новые находятся внизу, а последняя строка — всегда последнее сообщение. Применяется к [[panel.all]]; флажок для окна [[rxw.title]] находится ниже.",
  "t.dw2fq6eg5o": "Ваш позывной без /P, /M...",
  "t.dwb9dcp9oa": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › [[sw.pg.vhfModes]] находятся параметры декодирования Q65 (усреднение периодов, для EME и сигналов ниже шума) и MSK144 (метеорная связь) с заводскими значениями WSJT-X. Страница существует только с собственным движком; параметры применяются со следующего периода, после [[sw.save]].",
  "t.dy9zp0tf4g": "Внизу страницы. Каждый блок — кнопка или поле; правой кнопкой по любому из них открывается небольшое меню. Если она не нужна, выключите «[[digi.mi.statusBar]]» в меню [[digi.menu.view]].",
  "t.dz1p461ttd": "В Arch Linux и производных группа последовательного порта называется не dialout, а uucp: команда становится sudo usermod -aG uucp $USER, затем выйдите из системы и войдите снова.",
  "t.dzbjn87a0i": "[[sw.contest.title]] · [[contest.set.exchange]] и [[contest.set.serial]]: первое — фиксированный обмен (Field Day: класс и секция, вне США и Канады «1D DX»; Roundup: штат или # для серийного номера); второе — первый серийный номер для передачи, от 1 до 9999 (заводское значение 1). Следующий номер — всегда число QSO в журнале контеста + 1. Меняйте [[contest.set.serial]], только если возобновляете контест, уже начатый в другом месте.",
  "t.e0690gb2u8": "[[sw.tab.phone]]",
  "t.e3hmq7adpo": "В поле «Modo UDP» введите IP 127.0.0.1 и порт 2237 в строках «Msg ID 5» и «Msg ID 12» (строка «Msg ID ADIF» не нужна), затем нажмите «Chiudi» (Закрыть).",
  "t.e5jh2e4gby": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] Aurora может сама отвечать на CQ, которые приносят Вам что-то новое, и, если хотите, вызывать CQ. Вверху шапка (состояние, режим, сегодняшние числа); ниже пять блоков правил, у каждого свой «?»; внизу списки того, что она сделает и что сделала. Она запускается выключенной и в пробном режиме: настоящую передачу можно включить только с ПК. Правила сохраняются кнопкой [[sw.save]].",
  "t.e6oetsquo3": "[[sw.contest.title]] · [[contest.set.name]], [[contest.set.email]], [[contest.set.address]], [[contest.set.location]], [[contest.set.assisted]]: данные Cabrillo. Имя, email и адрес записываются один раз и действуют для всех контестов; [[contest.set.location]] — секция ARRL/RAC или «DX»; пустое [[contest.set.assisted]] принимает значение категории.",
  "t.e7qa2lhu51": "«[[rep.id]]» и «[[rep.newId]]»: случайный номер, который идентифицирует эту установку в отчётах. «[[rep.newId]]» создаёт новый: прежние отчёты больше нельзя связать с этой установкой. Используйте, если хотите начать с чистого листа.",
  "t.e860cpeg0a": "возврат каретки (CR)",
  "t.e8zxbkyy34": "Вверху окна находятся таблетки групп режимов («FT8», «VHF», [[nav.textModes]], [[nav.sat]]) и страницы. Режим (FT8, FT4…) выбирается в меню кнопки режима вверху слева на странице [[nav.station]]; диапазон меняется кнопкой частоты рядом с ней (кнопок диапазонов нет). См. «Режим, подрежим и частота» и «Верхняя панель: режимы».",
  "t.ea58klys71": "Служебные сигналы записываются <AR>, <BT>, <KN>, <SK> и уходят как единый знак; в других режимах они превращаются в буквы.",
  "t.ecx9x8bei5": "Откройте [[nav.fox]] в верхнем меню и нажмите «[[fox.off]]»: Вы передаёте в чётные периоды, ниже 1000 Hz.",
  "t.ef0htc65o7": "«[[cluster.dxpedColor]]»: цвет, которым в DX Cluster подсвечиваются споты DX-экспедиций в эфире по календарю NG3K (нужно включить «[[onl.dxped]]»). Палитра флуоресцентных цветов («[[cluster.dxpedFluo]]») и два мягких, выбор «[[cluster.dxpedCustom]]» для любого цвета и «[[set.reset]]», чтобы вернуть исходный флуоресцентный жёлтый. Текст сам становится тёмным или светлым, чтобы оставаться читаемым. Хранится на этом устройстве.",
  "t.eiapucegxa": "Band activity показывает весь диапазон (кнопкой «Filter» Вы выбираете только некоторые виды вызовов); окно RX показывает Вашу частоту приёма (±50 Hz) и адресованные Вам сообщения. Оба можно настроить.",
  "t.emmy5zrur5": "Страница «Сопряжение этого устройства»",
  "t.eqbos729iz": "[[nav.sat]] › [[sw.pg.doppler]]",
  "t.eqe7n3gqq": "контест: обмен, отправленный в последней записанной QSO (чтобы повторить его, когда спросят снова)",
  "t.er9xqwxw7i": "При нажатии макроса показывается «Command not available yet: …»: названная команда пока не выполняется Aurora; удалите её из текста.",
  "t.etrcfd0162": "[[tab.support]]",
  "t.evvwlsv3s4": "«[[contest.export]]»: выберите «[[contest.exp.format]]» (Cabrillo 3.0, EDI или ADIF в соответствии с правилами); список «[[contest.exp.problems]]» сообщает, что исправить перед отправкой (или «[[contest.exp.ok]]»); «[[contest.exp.save]]» сохраняет файл, а «[[contest.exp.send]]» открывает страницу организатора. Aurora сама ничего не отправляет.",
  "t.exauphqtlq": "Кнопка «[[ctl.spot]]» находится на вкладке DX Cluster страницы «Станция» (FT8 и другие режимы): она открывает окно спота с DX текущего QSO, частотой радиостанции и режимом. Отправленный Вами спот сразу появляется в списке под Вашим позывным.",
  "t.ey2z02kur": "«[[sstv.img.save]]»: сохраняет на диск тот файл, который Вы видите (если выбрано Cleaned — очищенный). «[[sstv.img.delete]]»: удаляет изображение после вопроса «[[sstv.img.deleteConfirm]]».",
  "t.ey73gwvooc": "Радио не передаёт",
  "t.eya2a8upm": "используемый режим",
  "t.f069ydugd": "«[[newlog.button]]» (на странице «Журнал и сервисы»): чтобы начать заново с пустым журналом (например, в начале года или с новым позывным). Предупреждение показывает число QSO в текущем журнале, кнопку «[[newlog.exportFirst]]» и два варианта; по умолчанию выбрана «Отмена», и ни Enter, ни Esc ничего не запускают. «[[newlog.keep]]» копирует журнал в файл рядом с текущим, с датой и временем в названии (logbook-archivio-YYYYMMDD-HHMMSS.db), проверяет, что в копии есть все QSO, и только потом открывает новый журнал: ни одна QSO не теряется. «[[newlog.replace]]» действительно удаляет QSO: запрашивается второе, красное подтверждение, в котором нужно ввести слово «[[newlog.word]]». Файл aurora_log.adi тоже откладывается с датой и временем. Это нельзя сделать во время передачи или при включённом Enable Tx. Отработанные станции, карточка DXCC, статистика и карта сразу начинаются заново с нового журнала, без перезапуска. Чтобы вернуть QSO архивного журнала: экспортируйте их в ADIF перед созданием нового и снова импортируйте через «[[logio.import]]» либо, при закрытой Aurora, положите файл архива на место logbook.db (отложив текущий).",
  "t.f0voywy549": "[[digi.mi.listen]]: отмечено = Aurora слушает. Щелчок останавливает или возобновляет приём. При входе на страницу приём включается сам.",
  "t.f51z6cwcrq": "[[digi.edit.title]] · [[digi.edit.label]] и [[digi.edit.color]]: подпись (до 60 символов) — это текст на клавише рабочей страницы; цвет — фон клавиши, чтобы узнавать группы с первого взгляда (CQ, ответ, 73).",
  "t.f5l3jf3u6p": "[[ctl.hold_tx]] фиксирует Ваш Tx: при ответе меняется только Rx.",
  "t.f79kv9xouv": "«+ [[int.p.adif]]»: название Log4OM, 127.0.0.1, порт 2333, включены «[[int.adif]]» и «[[int.resend]]». Для каждой QSO получает полную запись ADIF простым текстом, одна датаграмма на QSO, без потока и без состояния. Для Log4OM 2 (входящее соединение типа ADIF_MESSAGE) и WaveLogGate. Порт должен совпадать с указанным в журнале: если журнал слушает 2237, измените порт здесь. С «[[int.resend]]» QSO, проведённые при закрытом журнале, приходят, когда Вы снова его откроете.",
  "t.f9iaul69kt": "Общее число QSO указано в строке панели; чтобы увидеть весь журнал и экспортировать его в ADIF, используйте [[nav.log]] в верхнем меню.",
  "t.f9my60cnmt": "«Проведено ранее» по журналу Log4OM: в [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]], блок «[[l4.title]]», нажмите «[[l4.choose]]» и выберите базу данных SQLite Log4OM (или введите путь и нажмите «[[l4.use]]»; иногда Aurora находит её сама). Aurora только читает её, а панель [[panel.log]] показывает QSO из Log4OM. Переменная AURORA_LOG4OM_DB — лишь ещё один возможный источник, для тех, кто её уже использует.",
  "t.fc5unsp08w": "Шаги в Aurora, от частоты до записанного в журнал QSO.",
  "t.fci05adtwr": "В Cat4OM создайте группу со своим радио и проверьте, что оно подключено. Log4OM и Aurora будут использовать эту группу вместе.",
  "t.fd24ivyy7i": "Число вверху слева — общее количество проведённых стран; внизу — сколько стран Вы провели из скольких существует и число QSO в журнале.",
  "t.fdq1mmltjt": "Правый щелчок по кнопке (даже пустой) открывает окно «[[digi.edit.title]]» для этой клавиши: см. «Редактирование макроса». При наведении мыши на кнопку показываются клавиша и текст макроса.",
  "t.feipt5eqk5": "Если Fox не отвечает, Aurora продолжает вызывать. После первого R+рапорта без RR73 последующие попытки смещаются на 300 Hz от частоты Fox.",
  "t.fgpbk0yf78": "«[[rep.active]]» (включено): при запуске, а затем примерно каждые 40 минут, пока Aurora открыта, отправляется анонимный подсчёт: уровень использования (простаивает, принимает, передаёт), случайный код установки (или полученный из позывного, который никогда не отправляется), версия Aurora, операционная система, название установленного антивируса, страна и тип компьютера (процессор, ядра и память). Он нужен, чтобы считать, кто пользуется Aurora, и понимать, на каких компьютерах ей тяжело. Выключите, если не хотите даже этого.",
  "t.fh4awhy5md": "[[digi.mi.scan]] › [[digi.mi.scanStart]]: каждые «dwell» (по умолчанию 10 секунд, от 2 до 600) приём переходит на следующий сигнал справа, а в конце диапазона начинает сначала; [[digi.mi.scanStop]] останавливает его; [[digi.mi.scanProps]] открывает Настройки на странице «[[sw.pg.digiScan]]», где выбирают время задержки, останавливаться ли на первом сигнале и записывать ли время и частоту в текст.",
  "t.fidyd6c1ag": "[[gen2.operation]] · [[gen2.swr]] (карточка «Трансивер», числовое поле, от 1,0 до 4,0 с шагом 0,1, по умолчанию 2,0): защита антенны. Если во время передачи трансивер показывает КСВ выше этого значения, Aurora сразу прекращает передачу и предупреждает Вас. Нужна связь CAT, считывающая КСВ с трансивера; если трансивер его не выдаёт, проверка ничего не делает.",
  "t.fjhs4b1fkc": "Чтобы вернуть всё в главное окно: кнопка ⤓ («[[win.attachAll]]»), которая появляется вверху справа, только если есть хотя бы одно отдельное окно. У каждого отдельного окна есть также своя кнопка «[[win.attach]]».",
  "t.fjlw80s2iq": "Над водопадом находится панель команд с теми же опциями, что в [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: менять здесь или там — одно и то же, и изменение видно сразу. У каждого пункта есть подсказка (наведите курсор).",
  "t.fjxan632xo": "открывает порог шумоподавителя",
  "t.fk0qxa4ljv": "[[ctl.jt_both]]: появляется только в JT65 или JT9; когда включён, он также декодирует второй из двух режимов в ту же минуту. [[ctl.agc]]: компенсирует изменения АРУ радио (см. «[[ctl.agc]]: слабые сигналы рядом с мощными станциями»).",
  "t.fki0flzr4y": "На странице Контеста: F1 запускает Auto CQ (контестный CQ в каждом периоде), F2 — обмен, F3 — R + обмен, F4 — завершение; Esc немедленно останавливает передачу, двойной Esc очищает и текущее QSO. Над декодированными сообщениями: частота (только контестные диапазоны) и блок RX/TX (щёлкните TX, чтобы остановить, RX — чтобы очистить QSO). «How it works» кратко излагает правила и что отправляется. В журнал контеста попадают только QSO, начатые с этой страницы во время соревнования.",
  "t.fkoa83vd4y": "[[digi.mi.memory]] › [[digi.mi.memWrite]] / [[digi.mi.memRead]]: двадцать ячеек памяти. Ячейка сохраняет режим, частоты приёма и передачи, Lock, сдвиг и скорость RTTY, Rev, AFC, Snap, шумоподавитель и три порога. Память хранится на этом компьютере; её можно также вызвать или очистить в «[[sw.mem.title]]» в Настройках. Пустая ячейка отвечает уведомлением.",
  "t.fktogaxvj1": "[[digi.edit.title]] · [[digi.edit.macro]]: выпадающий список клавиш (4 ряда панели; только F1…F12 первого имеют клавишу на клавиатуре) и макросов событий, срабатывающих сами (OnStart, OnEnd, OnTX, OnCR, OnClickAny, OnAlarm, OnSP0, OnSP1, Gray+, Hello, AutoCqText). Выберите клавишу, на которую нужно назначить текст.",
  "t.fmck1971q4": "Роза: сплошная стрелка — антенна, пунктирная — цель; зелёная отметка — станция DX (короткий путь), оранжевая — длинный путь. Если у ротора диапазон шире 360°, жёлтая полоса на компасе отмечает перекрытие, куда можно прийти с двух углов (выбирается ближайший). Щёлкните или перетащите по розе, чтобы направить антенну в эту сторону («[[rot.clickHint]]»).",
  "t.fo9dfqfwrn": "«[[sat.list.title]]»: поле «[[sat.list.search]]» ищет по названию. Флажок определяет, какие спутники Вы видите: щелчок по названию выбирает спутник и отмечает его (он появляется в «[[sat.data.title]]» и на карте); снятие отметки с выбранного спутника переносит выбор на следующий отмеченный; установка флажка, когда ничего не выбрано, делает этот спутник выбранным. «[[sat.list.clear]]» снимает все отметки: если ни один не отмечен, на карте показана только Земля. В начале списка идут отмеченные («[[sat.list.ticked]]»), затем остальные («[[sat.list.all]]»). Спутники без данных орбит помечены «[[sat.list.noTle]]».",
  "t.folw8r9el2": "Проверьте, что [[ctl.monitor]] включён.",
  "t.fr5hkkschj": "В [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]] кнопка «[[sdr.useAll]]» задаёт CAT и звук сразу. S-метр, мощность и КСВ поступают от SDR; кнопки PWR − / + на дисплее меняют мощность SDR, а TUNE включает и выключает несущую настройки. Каждая команда ждёт подтверждения от SDR: если его нет, Aurora сообщает об этом. «Power on» и «Power off» включают и выключают SDR по TCI.",
  "t.ft3y4nqdh4": "Где находятся настройки и как они сохраняются.",
  "t.fuspnf34v3": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] есть параметр «[[dec.slowPc]]» с тремя пунктами: «[[dec.slowPc.auto]]» (по умолчанию), «[[dec.slowPc.always]]» и «[[dec.slowPc.never]]». В автоматическом режиме он включается сам после 3 периодов из 10, превысивших 70 % времени, после потери 3 звуковых блоков за 10 минут или при 2 процессорах и меньше, и выключается после 20 спокойных периодов. Пока он включён, во время декодирования Aurora откладывает DX Cluster, DX-экспедиции, PSK Reporter, поиск позывных, список LoTW, данные спутников и проверку обновлений, которые работают сразу после окончания декодирования (не позднее чем через 30 секунд). Кроме того, есть проверка, которая измеряет, сколько времени занимает декодирование каждого периода, и, если не менее 4 из последних 10 периодов превышают 70 % длины периода (для FT8 около 11 секунд из 15), показывает жёлтую карточку внизу справа: эта карточка никогда ничего не меняет сама.",
  "t.fuvx0fyeh9": "слово, выделенное в окне RX, становится позывным QSO",
  "t.fv35udoag6": "Передача SSTV длится от получаса до почти пяти минут: держите TX Lvl низким и остановите автоматику FT8 перед передачей. Настройки находятся в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]], а также под колесом ⚙ на странице.",
  "t.fvamc8r6t8": "[[digi.mi.hairlines]] (выкл.): рисует тонкую вертикальную линию вдоль частоты приёма (и частоты передачи, при Lock), чтобы лучше центрировать сигнал.",
  "t.fxt2hq4odp": "Esc один раз: сразу останавливает передачу. В Aurora Esc имеет и общее действие, которое работает на всех страницах и включено по умолчанию: он выключает «[[ctl.enable_tx]]» (отключается пунктом «[[gen.escStop]]» в Настройках).",
  "t.fy02sxwno0": "Ниже: активность диапазона, DX Cluster диапазона, последние QSO, шесть сообщений Tx, водопад и CQ.",
  "t.fyozk8etkn": "«[[exp.save]]» (на ПК открывает окно Windows для выбора папки и имени ADIF-файла) или «[[exp.download]]» (с телефона или другого компьютера: скачивает файл в папку загрузок): они сохраняют только выбранные QSO. «[[exp.saveCbr]]» сохраняет те же QSO в Cabrillo 3.0 (для контеста со своими правилами используйте страницу [[nav.contest]]). Если ни одно QSO не выбрано, кнопки серые.",
  "t.g09cbf3nv7": "Вверху — цифры журнала (QSO, страны, зоны); ниже — QSO по диапазонам и карточка DXCC станции, с которой Вы работаете. Недостающие страны открываются щелчком; блок «[[logio.title]]» уже открыт, с [[logio.export]] и [[logio.import]].",
  "t.g0yx2wnzf7": "Никакое исправление или удаление не передаётся во внешние журналы (программы, подключённые по UDP, Wavelog, ClubLog, QRZ, LoTW): там QSO исправляют вручную.",
  "t.g1d92z0iow": "Станции, работающие CW с жёсткой манипуляцией, оставляют на водопаде горизонтальную линию на каждом фронте (щелчки). «[[digi.mi.anticlick]]» в меню [[digi.menu.view]], включённое по умолчанию, убирает их, пока страница слушает: широкополосная энергия короче 10 ms приглушается до отрисовки строки, сигналы остаются. Пока эта страница слушает, это действует и на водопад других страниц.",
  "t.g2y3p4gu3s": "[[acc.devices]] · список и «[[acc.revoke]]»: у каждого связанного телефона или планшета есть имя и кнопка «[[acc.revoke]]», которая сразу отзывает его доступ (ему придётся связываться заново). Если их нет, Вы читаете «[[acc.noDevices]]». Когда: телефон потерян, продан или одолжен.",
  "t.g4wl2jzhvs": "Ползунки Rx, TX Lvl и AUTO (громкость устройства)",
  "t.g5biuv451j": "[[sw.pg.bands]]",
  "t.g6tjw6vnn0": "блокирует частоту приёма: щелчки и макросы её не двигают (<UNLOCKRX>, <LOCKRXTOGGLE>)",
  "t.g6z5e46cpn": "Постановка в очередь станций, которые вызывают Вас во время QSO.",
  "t.g7ocqb0ygi": "В FT991Link выберите порт радио и нажмите «COM Port», чтобы открыть его.",
  "t.g9l15etnfs": "Очередь и [[ctl.answer_all]]",
  "t.ga36xt3kfr": "«[[qmap.source]]»: [[qmap.source.off]], [[qmap.source.tci]] (с «[[qmap.tci]]», например 127.0.0.1:40001, и «[[qmap.rate]]») или [[qmap.source.file]] (с «[[qmap.file]]» и кнопкой «[[qmap.decodeFile]]»). Источник можно менять только с ПК, на котором работает Aurora.",
  "t.gaevr1vxz2": "[[fil.decode]] · [[gen2.decStart]]: выпадающий список, задающий, на каком моменте периода начинается декодирование FT8. [[gen2.decStartEarly]] оставляет больше времени на ответ до следующего периода; [[gen2.decStartLate]] ловит также сигналы, приходящие с опозданием; заводское значение [[gen2.decStartNormal]]. Меняйте, только если Вам не хватает времени на ответ или Вы пропускаете поздние сигналы.",
  "t.gcdejo2n4n": "[[ens.g.log]] · [[ens.k.AutoQSOLogging]] и [[ens.k.ClearCallGridExit]]: эти два параметра в Aurora не появляются, потому что действуют всегда. QSO заносится в журнал само (если только [[ens.k.PromptToLog]] не требует подтверждения), по окончании QSO передача прекращается, и станция DX очищается; чтобы продолжить, снова вызовите CQ или выберите другой DX. При запуске Aurora всегда начинает без станции DX.",
  "t.gfiwgibl0p": "Задержка Tx: в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], блок [[gen2.operation]], [[gen2.txDelay]] — время между включением PTT и началом звука, от 0 до 0,5 s (по умолчанию 0,2 s, как «Tx delay» в WSJT-X). Увеличьте её, если радио или CAT медленные и начало сообщения теряется.",
  "t.gh252g4655": "Окно «Занести QSO с…»",
  "t.ghey2037ce": "[[cqp.title]] · категории: по одному флажку для каждой из [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]]; по умолчанию все включены. Они определяют, что перечисляет окно [[panel.cq]]: снимите те, которые Вам не нужны.",
  "t.ghge5q25g0": "[[sstv.set.grpClock]] · «[[sstv.cal.button]]»: измеряет ошибку тактовой частоты звуковой карты в ppm (причина наклонных картинок) по последней хорошо принятой SSTV-картинке (полной, с хорошей синхронизацией). Значение верно только если у передающей станции точные часы: у обычной станции в измерение вошла бы и собственная ошибка передатчика. Для большинства звуковых карт 0 вполне подходит, потому что наклон исправляется сам на каждой картинке: калибровка нужна только для карт, сильно уходящих по частоте.",
  "t.glmednso3e": "Строка DX: «[[phone.cqCall]]», если Вы вызываете CQ (или ещё не выбрали станцию); иначе «[[phone.dx]]» (или «[[phone.calling]]», пока Вы передаёте), позывной, флаг и строка со страной, локатором, расстоянием в км и S/N.",
  "t.glth09yywf": "Щелчок по результату (или Enter для первого) открывает нужную страницу и выводит параметр в поле зрения, ненадолго подсвечивая его.",
  "t.gmohqdglg8": "во время набора передача идёт целыми словами (OFF: по буквам)",
  "t.gohjwy47rk": "[[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]]: вход (от трансивера) и выход (к трансиверу). На главной странице полоса Rx должна показывать «Правый»; мощность задаётся ползунком TX Lvl, а не ручкой микрофона.",
  "t.gpqngvvfwy": "[[rep.title]] · [[rep.show]] и [[rep.showAuto]]: две кнопки, открывающие окно «[[rep.previewTitle]]» с точным текстом того, что было бы отправлено: первая — пакет (список открываемых файлов с размерами), вторая — автоматический отчёт (находящийся в очереди или пример). Они ничего не отправляют; закрываются кнопкой «[[rep.close]]» или Esc.",
  "t.gq2l6yrsos": "Шестерёнка рядом: открывает «[[cop.title]]» (см. ниже). Подсказка кнопки — «[[cop.tip]]».",
  "t.gqrxbaq943": "[[bfl.title]] · [[bfl.minKm]] и [[bfl.maxKm]]: два числовых поля от 0 до 25000 км. При ограничении показываются только станции, чей локатор известен. Пусто = без ограничения. Используйте, чтобы искать только далёкие DX (минимальное расстояние) или только ближние станции (максимальное расстояние).",
  "t.gs2zqhpdnm": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] Вы выбираете, какие диапазоны появляются в полосе диапазонов станции. Выбор применяется сразу и сохраняется.",
  "t.gsf69m2sgs": "Широкий режим для DX-экспедиций, совместимый с WSJT-X SuperFox. На стадии тестирования.",
  "t.gtb7onmmp0": "Не удаётся создать пакет или резервную копию? Откройте эту страницу с ПК, на котором работает Aurora, а не с телефона или другого компьютера.",
  "t.gtslv4tqfn": "Только с Hamlib, если у вас уже запущен собственный rigctld (тот же, что у oplog, WSJT-X или других): нажмите «[[cat.external]]». Aurora выбирает модель «NET rigctl», записывает 127.0.0.1:4532 в порт (если там ещё нет сетевого адреса) и отключает «Делиться с другими программами»; она не открывает COM-порт радио, а работает с вашим rigctld. Затем нажмите «Применить» и [[cat.connect]].",
  "t.gzcnj3gzey": "[[tab.macros]] · список: каждая строка — это макрос с кнопкой [[set.remove]], чтобы его убрать. По умолчанию их пять: «@ TNX 73», «TU ^ 73», «@ &», «@ #», «@ R#». Если список пуст, появляется «[[macro.empty]]».",
  "t.h0z8ifrqb1": "сохраняет настройки в память n (<MEMR:n> считывает их обратно)",
  "t.h111i6llgy": "Настройка радиостанции",
  "t.h125id6qdt": "отправляет радиостанции команду CAT",
  "t.h1swcc1tcd": "Значок в заголовке (рядом с языком): появляется, когда вышла новая версия; щелчок открывает небольшую панель с «[[upd.install]]» (если можно установить), «[[upd.open]]» и «[[upd.later]]», которая скрывает его до следующей версии. Закрывается клавишей Esc или щелчком снаружи.",
  "t.h4oilo7ebj": "Интеграции: что получает каждая программа",
  "t.h5yxy436i7": "как <IGNOREBEFORE:date>",
  "t.hc1rnmojb1": "Каждая миниатюра показывает позывной (или режим) и время UTC; метка «[[sstv.img.partial]]» говорит, что изображение пришло лишь частично. При наведении мыши показываются режим и время.",
  "t.hdy6ozn1j9": "[[sw.digi.perMode]] · CW, ползунок скорости передачи (от 5 до 60 слов в минуту, заводское 20): это скорость автоматического ключа Aurora; меняйте, когда Вы передаёте быстрее или медленнее другой станции.",
  "t.hg8je5qhsk": "FT-991/FT-991A с FT-991(A) Link",
  "t.hi886iwg83": "[[fil.grp.rx]] · [[bfl.hideOwnTx]]: флажок; скрывает Ваши собственные переданные сообщения в окне [[rxw.title]]. Это тот же выбор, что и «[[gen2.showTx]]» в блоке [[gen.screen]], только с обратной стороны: включение одного выключает другой.",
  "t.hky2qb26ee": "Путь: [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]], под QR-кодом, пока Вы связываете телефон. Это строки, с помощью которых Aurora сообщает, что ей известно о сети ПК, чтобы тот, у кого не получается подключиться, сразу понял, почему. Обновляются сами каждые 15 секунд, пока Вы ждёте телефон.",
  "t.hkyeifxcpt": "«[[int.loggedAdif]]»: после каждой QSO отправляет запись ADIF в двоичном сообщении номер 12 (его читают MacLoggerDX, GridTracker, BBLogger, LogHX и другие). Можно включить и отдельно, без потока. Включите, если QSO не попадает в журнал, хотя состояние доходит.",
  "t.hm4ab36uew": "В RTTY: [[digi.rtty.reverse]], [[digi.rtty.uos]], «[[digi.rtty.receiver]]» ([[digi.rtty.receiverAuto]], [[digi.rtty.receiverFilters]], [[digi.rtty.receiverDisc]]) и ползунок порога шумоподавителя (S/N от 0 до 40 dB, по умолчанию 0).",
  "t.hm5hfjrtpq": "Блок сообщений Tx: заголовок «[[phone.txMessages]]» с частотой Tx (краснеет «[[phone.transmitting]]», пока Вы передаёте), строка DX («[[phone.dx]]» или «[[phone.calling]]» с флагом и расстоянием) и кнопка «[[ctl.split]]», затем шесть сообщений с их типом ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): касание выбирает следующее для передачи. Ниже — водопад.",
  "t.hmzyk9q8wy": "[[sstv.set.grpSave]] · [[sstv.set.autoSave]] (по умолчанию включено): каждое полностью принятое изображение само сохраняется в папку изображений. Выключите, если хотите сами выбирать, что хранить (со страницы SSTV изображения по-прежнему можно сохранять вручную).",
  "t.hnws1pedtz": "Откройте [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]], блок [[fil.decode]].",
  "t.hp6708prb4": "Под «[[fox.callers]]» находится водопад («[[fox.waterfall]]»): щелчок = частота Rx, щелчок правой кнопкой или Shift + щелчок = частота Tx; высота меняется перетаскиванием ручки. Справа «[[fox.received]]» перечисляет последние декодированные сообщения, причём адресованные Вам подсвечены. Строка «Попыток … ожидание … циклов …» суммирует параметры.",
  "t.hvxn9j9d0d": "Правый столбец: вкладка «[[digi.tab.cluster]]»",
  "t.hy4p38bf71": "Номер для отправки (<QSONR>, <NRS>): при [[ctest.f.autoInc]] выбор соревнования начинает порядковый номер заново с записанного номера (001, если пусто), и он растёт с каждым сохранённым QSO; без этого <NRS> всегда отправляет фиксированный обмен (зона, провинция).",
  "t.hz4a6rogoo": "Если Ваш внешний журнал уже выгружает QSO на сервис (например, ClubLog или QRZ.com), не включайте его и здесь: QSO придёт дважды.",
  "t.i2f1r39jrg": "Последние QSO одним взглядом и экспорт ADIF.",
  "t.i2yuljslky": "При выключенном контесте панель пишет «[[contest.none]]», а кнопка «[[contest.calendar]]» открывает список контестов ближайших месяцев с кнопкой «[[contest.cal.prepare]]», чтобы активировать один на лету (даты с пометкой «[[contest.cal.check]]» нужно сверить с правилами).",
  "t.i3qxwpppr9": "Чтобы переместить карточку, перетащите её за строку заголовка; чтобы изменить размер, потяните за правый нижний угол или за маркер на правом краю, если нужно изменить только ширину (двойной щелчок: исходная ширина).",
  "t.i46qbtc2t5": "«[[l4.title]]» (вверху; появляется, только если Aurora может прочитать его состояние): Aurora читает (только чтение) файл SQLite программы Log4OM 2, чтобы знать, с кем Вы уже работали, и отмечать «новая DXCC», «новый диапазон»… Под заголовком видны путь (или «[[l4.none]]») и способ, которым файл найден: «[[l4.srcAuto]]», «[[l4.srcChosen]]» или «[[l4.srcEnv]]»; «[[l4.missing]]», если файла больше нет. Это нужно, только если Вы пользуетесь Log4OM, а файл не найден сам или их несколько.",
  "t.i6a22fg6dk": "USB-драйвер: откройте «Диспетчер устройств» Windows и посмотрите в разделе «Порты (COM и LPT)»: порт радио должен быть там при включённом радио и подключённом кабеле. Если его нет или рядом жёлтый восклицательный знак, нет USB-драйвера: установите драйвер производителя (для многих радио Yaesu это драйвер Silicon Labs CP210x).",
  "t.i79tsd3b8m": "Поле «[[dxcc.tryCall]]» (только если включено в настройках): введите позывной, чтобы узнать, какая это страна и проводили ли Вы с ней связь, не вызывая её. На странице [[nav.stats]] кнопки «[[dxcc.view.station]]» и «[[dxcc.view.totals]]» переключают отображение со страны станции на итоги.",
  "t.i8mhlawjed": "Если сигнал выходит за звуковой диапазон 200-2700 Hz, многие радиостанции срезают там мощность.",
  "t.i9ie1wm6mb": "удаляет строки отметок из окна RX",
  "t.i9zjg59x66": "как <DIST>, в милях",
  "t.idef94aflm": "[[sup.title]] · [[sup.openFolder]]: появляется только после создания пакета; снова открывает Проводник с уже выделенным zip (чтобы перетащить его в сообщение).",
  "t.idjk6lpt3y": "«QSL, спасибо» на языке другой станции",
  "t.ihl64zzw7z": "Шестерёнка ⚙ («[[dxmap.more]]») открывает прочие настройки: «[[dxmap.spotMax]]» (от 5 минут до 6 часов: насколько давними могут быть показываемые споты PSK Reporter), «[[dxmap.background]]» (цвет), «[[dxmap.autoNight]]» со стилем ночи и «[[dxmap.nightDark]]» (насколько тёмный), «[[dxmap.twilight]]», «[[dxmap.moon]]», «[[dxmap.animated]]» (анимированные линии), для прохождения «[[dxmap.spotPaths]]» с его цветом и «[[dxmap.dots]]», для «Кто кого вызывает» цвет, «[[dxmap.linkMeColor]]», толщина и скорость, а также «[[dxmap.decay]]» (от 2 до 60 минут: через сколько станция выцветает и исчезает).",
  "t.ihlpswr36n": "Всплывающие сообщения",
  "t.ihyk5hjoql": "[[sw.contest.title]] · [[contest.set.freqs]]: ряд кнопок с диапазоном, режимом и kHz; появляется, только если в правилах перечислены частоты. Один щелчок переводит трансивер на частоту, предложенную для этого диапазона и режима (нужен CAT).",
  "t.ii6zt926fg": "«[[sat.ctl.title]]»: выпадающий список «[[sat.ctl.transponder]]», «[[sat.ctl.downlink]]» (ползунок), «[[sat.ctl.txOffset]]», «[[sat.ctl.minEl]]» (0–60°), «[[sat.ctl.doppler]]» (с состоянием радио и скорректированными частотами приёма и передачи), «[[sat.ctl.rotor]]» и «[[sat.ctl.prepoint]]». Под каждым переключателем строка сообщает, подключены ли радио или ротор («[[sat.ctl.radioReady]]», «[[sat.ctl.rotorReady]]», иначе «[[sat.ctl.radioNot]]», «[[sat.ctl.rotorNot]]»).",
  "t.ij4d5h0owr": "[[digi.mi.wideWaterfall]] (вкл.): водопад показывает 0-5 kHz; при выключении — 0-3,5 kHz (крупнее, но то, что выше 3,5 kHz, не видно).",
  "t.ijgxpkih5w": "Пока Вы передаёте, рядом с панелью макросов появляется красная метка TX; она мигает, если в меню [[digi.menu.view]] включено [[digi.mi.flashTx]].",
  "t.il6pe9mko5": "В фильтре Band activity кнопки «[[kind.new_state]]» и «[[kind.new_state_band]]» показывают станции США из штата, с которым связь никогда не проводилась или не проводилась на этом диапазоне. Штат берётся с QRZ.com или HamQTH (при включённом поиске позывных), проведённые штаты — из журнала Log4OM. Те же два варианта есть и в Автоматизации: Auto отвечает на CQ из нового штата.",
  "t.ile1q0414k": "Столбец «[[ctl.grp.tx]]»: [[ctl.enable_tx]] (в следующем периоде Aurora передаёт); [[ctl.auto_tx]] (автоматическая передача: её включение также включает [[ctl.enable_tx]]; когда QSO заканчивается, CQ начинается снова сам); [[ctl.wait_call]] (ждёт, пока DX освободится, и затем вызывает его); [[ctl.pounce]] (при выключенном Enable Tx сама отвечает на выбранный CQ). Когда включены, эти четыре переключателя становятся красными: это означает, что Aurora может передавать сама.",
  "t.imvizmlblk": "Aurora заносит QSO в журнал сама: Вы лишь выбираете, хотите ли сначала проверить данные. Параметры находятся в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.pg.qso]].",
  "t.in13dvnyo5": "отправляет станции сообщение TALK через подключённый DX Cluster",
  "t.io3xsh4zpc": "[[ap.text]] · [[ap.fontLog]]: шрифт таблицы журнала для режимов PSK, RTTY и CW. «[[ap.fontLogData]]» (по умолчанию) использует шрифт данных; варианты: JetBrains Mono, Cascadia Mono, Consolas, Lucida Console, Courier New, IBM Plex Sans.",
  "t.iqdlb04fz0": "Включите «[[cat.auto]]», чтобы не делать это при каждом запуске, и «[[cat.extras]]» для частоты VFO B и кнопки TUNE. Эти два флажка сохраняются сразу, сами, как «[[cat.powerOn]]» и «[[cat.powerOff]]» (они включают и выключают радио при запуске и выходе: есть с Hamlib, TCI и FT-991(A) Link, с Cat4OM только второй). Остальные пункты применяются сами после паузы около 1,5 секунды (радио переподключается один раз) или сразу через [[cat.apply]].",
  "t.iquy6jdlvo": "Текст на языке Aurora. О том, что изменилось после обновления, см. также «Обновления».",
  "t.ismrbzchgx": "Aurora хранит макросы в своих настройках: чтобы загрузить файл, используйте «Импорт макросов»; команда напоминает об этом",
  "t.iuuvg0xxt0": "Меню [[digi.menu.options]]",
  "t.ivlwl6go0j": "Только для Hamlib и последовательного порта: [[cat.baud]] (варианты от 1200 до 115200; «[[cat.default]]» использует стандартную для модели). Она должна совпадать с указанной в меню CAT трансивера: если они различаются, трансивер не отвечает. Icom с PTT по CAT требуют 115200 (Aurora предупреждает, если иначе), современные Yaesu обычно 38400. Не показывается, если порт — сетевой адрес.",
  "t.ivuuedi3n3": "Шумоподавитель Olivia и Contestia смотрит на отношение сигнал/шум синхронизации, которое строка состояния показывает как «С/Ш синхр.»: ниже порога ничего не выводится. На одном шуме синхронизация доходит примерно до 10 дБ, слабый, но читаемый сигнал — выше 17 дБ; порог по умолчанию 12 дБ, он настраивается в окне «[[digi.ms.title]]». При выключенном шумоподавителе действует порог по умолчанию, потому что без порога шум выводил бы случайные символы.",
  "t.iw2zdrzz5u": "Если DX-экспедиция не сообщает, что использует Fox/Hound, вызывайте её как обычную станцию, без [[ctl.hound]].",
  "t.ix2lj2j36a": "Остальные фильтры этой панели (минимальный сигнал, минимальное и максимальное расстояние, скрыть сообщения мне, скрыть мои передачи, только определённые диапазоны) находятся в блоке «[[bfl.title]]» в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; там же Вы записываете позывные, которые нужно всегда или никогда не показывать, и обход, на мгновение показывающий всё (см. «Фильтры по позывному, префиксу и уже проведённым связям»).",
  "t.ix83n1ftf8": "Контест: клавиатура и команды",
  "t.iy5vlgl22s": "Карта мира выбирается в настройках: [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]], категория «[[sat.set.catMap]]». Там «[[sat.map.pick]]» выбирает карту, а «[[sat.map.add]]» добавляет Вашу собственную (равнопромежуточное изображение 360° × 180°, jpg, png, bmp или webp).",
  "t.iyhnvsq502": "Столбец [[freq.region]] (выпадающий список): [[gen2.regionAll]], [[gen2.region1]], [[gen2.region2]] или [[gen2.region3]]. Он говорит, к какому региону относится эта частота. Строка региона, отличного от выбранного Вами, остаётся в таблице, но становится серой и не используется (при наведении показывается «[[freq.hidden]]»).",
  "t.iz5pfbc3oq": "[[nav.settings]] › [[sw.sec.station]] › [[tab.clock]]. В FT8 и FT4 часы ПК должны быть точными: при ошибке свыше полусекунды сообщения теряются, а другие станции Вас не декодируют. Aurora опрашивает серверы NTP, показывает смещение и может исправить часы Windows. В Linux исправления нет: время синхронизирует система.",
  "t.j2gurugkas": "SSTV: отправить картинку из папки картинок, из буфера обмена или последнюю принятую. Пример: <SSTVMODE:Martin 1><PIC:foto.jpg %C>.",
  "t.j2ivm9tewh": "Внизу страницы мелким шрифтом находится «[[sstv.credits]]»: это благодарности авторам алгоритмов SSTV и используемых шрифтов. Настраивать здесь нечего.",
  "t.j3fb4ocirw": "Сопряжённые телефоны и планшеты показывают единственную страницу — Station — в виде пульта дистанционного управления. В узком окне (менее 768 точек) это компактный пульт; у планшета в альбомной ориентации (от 768 до 1366 точек, на пульте или сенсорном устройстве) два столбца. Настройки, другие страницы и отдельные окна используются только с ПК.",
  "t.j4prr3dmlw": "Только что занесённое QSO мигает вверху с меткой «[[log.loggedBadge]]». Если открыта вкладка «[[log.tab.map]]», при каждом занесённом QSO панель на мгновение переключается на журнал, показывает новую строку, а затем возвращается к карте.",
  "t.j5fi51ynwf": "Ctrl+щелчок по водопаду ставит в этой точке режекторный фильтр шириной 30 Hz; он подавляет эту зону не менее чем на 60 dB и не затрагивает то, что лежит сразу за ней. Можно добавить столько, сколько нужно.",
  "t.j6pvv3dir9": "[[sw.pg.alerts]]",
  "t.jalszt5fa9": "[[sstv.set.grpSave]] · [[sstv.set.saveTx]] (по умолчанию включено): передаваемые Вами изображения тоже сохраняются в папку изображений, чтобы можно было найти то, что Вы отправили. Выключите, чтобы не заполнять диск.",
  "t.jba2d6esut": "Как заставить Aurora вызывать CQ самой",
  "t.jc9nm85873": "приветствие по местному времени (GM, GA, GE или GN); если у вас есть макросы gm, ga, ge или gn, используются они",
  "t.jdeso5yggy": "Где находится файл: в папке соревнований в данных Aurora (%APPDATA%\\Aurora\\contest в Windows), по одному файлу <name>.contest на соревнование, макросы в macros\\<name>.mc, а списки провинций или штатов в dom\\<name>.dom. Название, даты, обмен и макросы меняются через «[[ctest.edit]]» в «[[ctest.listTitle]]»; разделы [Score] и [Script] пишутся при открытии файла в текстовом редакторе (например, в Блокноте).",
  "t.jemzl1h1ce": "Когда Вы снова открываете Aurora, всё как было: та же страница (FT8, VHF, PSK·RTTY·CW, SSTV, спутники...), тот же текстовый режим с его настройками и, как только радио отвечает по CAT, та же частота и тот же режим радио (USB, LSB, данные). Если радио уже настроено так, команда ему не отправляется. Частота запоминается, когда остаётся неизменной около десяти секунд; режим радио восстанавливается только через Hamlib (OmniRig его не сообщает).",
  "t.jenf62f5dg": "Щелчок по водопаду переводит приём в эту точку; при перетаскивании мыши курсор следует за ней (в движок это доходит не чаще десяти раз в секунду). При включённом [[digi.mi.snap]] курсор захватывает пик сигнала (в RTTY — пару двух тонов, в PSK — середину сигнала). Предел — от 200 до 3500 Hz.",
  "t.jfubj1ok0m": "Если рядом с частотой Rx нет сообщений, в окне написано «[[rxw.empty]]».",
  "t.jhu37iz55u": "Не трогая радио: ползунок «[[sstv.tune.label]]» сдвигает метки шагами по 6,25 Hz, до ±200 Hz; совместите их с сигналом. Изображение перерисовывается сразу, включая уже принятые строки и последнее завершённое изображение. Колесо мыши: по одному шагу; двойной щелчок: возврат к 0 («[[sstv.tune.auto]]»).",
  "t.jk7n9n7d9z": "АПЧ корректирует настройку шагами не более 25 Гц и никогда не выходит за «[[wefax.set.afcRange]]» от последней выбранной вручную поднесущей; он придаёт больший вес тону начала и фазированию и осторожнее внутри изображения.",
  "t.jl8kri6815": "Страницы на верхней панели",
  "t.jlzjxdm1u3": "Оставаясь в «Fast QSO», в меню под «Auto-Save» выберите «UDP 12» (оно передаёт все данные QSO) и отметьте «Auto-Save», если хотите, чтобы QSO записывалось само по окончании.",
  "t.jm6lo2sihu": "[[auto.b1]] · [[auto.direction]] (по умолчанию включено): «CQ NA» вызывает только Северную Америку, а «CQ DX» — только тех, кто вне континента вызывающего; при включённом флажке Aurora не отвечает, если CQ предназначен не Вам. Нужен Ваш позывной, заданный в [[sw.pg.personal]].",
  "t.jmp1hikdw4": "[[digi.menu.help]] › [[digi.mi.macroGuide]]: все команды макросов по категориям, с объяснением и примером, а также событийные макросы; фильтр вверху находит команду или слово. Открывается также из окна редактирования макроса.",
  "t.jn63pyd2e4": "Окно RX находится над панелью «Журнал» (по умолчанию включено) и показывает только то, что относится к Вашей частоте приёма: станции, передающие там, где стоит зелёный маркер Rx (±50 Hz; ±100 Hz в MSK144), сообщения, адресованные Вам, и Ваши собственные передачи. Это окно «Rx Frequency» из WSJT-X. Чтобы следить только за DX, поставьте маркер Rx на него.",
  "t.jnbws1wb1i": "Параметры декодера WSJT-X",
  "t.jodwtkys2y": "Стандартное расположение в SSB: [[ctw.card.log]] слева; затем [[ssbc.enter]] над «[[ctest.mt.dxcc]]» (страны DXCC), [[ctw.card.cluster]] над [[ssbc.statsTitle]] и [[ctw.card.rate]] справа, а карточки множителей обмена внизу. В CW, RTTY и PSK: журнал, [[ctw.card.rx]] над [[ctw.card.tx]], затем [[ssbc.enter]], «[[ctest.mt.dxcc]]», [[ssbc.statsTitle]] и [[ctw.card.rate]]; в CW и RTTY [[radar.title]] над [[ctw.card.cluster]]; [[ctw.card.wf]] и множители внизу.",
  "t.jqgnx0ut2y": "Справка: как искать",
  "t.js771xsd16": "Две программы, управляющие радиостанцией одновременно, мешают друг другу. Лучше, чтобы с радиостанцией общалась только Aurora, а остальные обращались к Aurora.",
  "t.jtku7j7w4c": "Правый щелчок по любому блоку: [[digi.mi.squelch]], [[digi.mi.afc]], Lock, [[digi.mi.snap]], «[[digi.st.threshold]]», часы UTC (они появляются в строке) и [[digi.mi.flashTx]].",
  "t.ju2c8e2uky": "Чтобы Logger32 следовал за частотой и режимом Aurora: «Allow WSJT/JTDX to set frequency/mode» при закрытом CAT в Logger32. С Aurora это пока не проверено: если работает плохо, оставьте управление трансивером только за Aurora.",
  "t.jv8j62bx7p": "«[[panel.all]]»: список принятых сообщений, с Вашими строками Tx между ними. Касание сообщения отвечает этой станции (двойной щелчок не нужен); повторное касание того же сообщения в течение 2 секунд игнорируется. Флаги стран показываются всегда.",
  "t.jwzd5j6sbj": "Сменить тему: на нижней панели справа значок темы (луна = тёмная, солнце = светлая, наполовину закрашенный круг = автоматическая). Каждый щелчок переключает на следующую в порядке: тёмная, светлая, автоматическая; «автоматическая» следует теме Windows и меняется вместе с ней. По умолчанию тёмная. Тот же выбор находится в [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (пункт «[[ap.theme]]»), где Вы также найдёте «[[ap.contrast]]» и размеры текста. На телефоне тема находится вверху справа, в панели удалённого управления.",
  "t.jx4madgi9f": "включает Auto CQ; следующий за командой текст становится вызовом",
  "t.jxmllm0xs2": "Выделенный текст: выделите слово в окне RX и нажмите макрос: <SELCALL> помещает его в позывной, <SELNAME> — в имя, <SELRXTEXT> отправляет его. Пример: <SELCALL><TX><CALL> DE <MYCALL> KN<RX>.",
  "t.jykexm1ajm": "Другие метки: «Queue» с номером (станция в очереди, номер — её место) и «Fox» (DX-экспедиция в режиме Fox/Hound).",
  "t.jz1muqdbh4": "«[[acc.open]]»: без кода для всех в домашней сети. Включено по умолчанию, поэтому дома код не нужен; из интернета код нужен всегда. Менять можно только с ПК. Страница другого сайта, открытая в браузере на том же ПК, не может прочитать состояние (позывной, локатор, журнал) и не может заставить радио передавать.",
  "t.k027ipmga7": "Выберите [[fox.slots]] (до 5 станций в одной передаче) и кому адресован CQ.",
  "t.k30khast1h": "Перед передачей: на странице Station полоса Rx должна показывать «[[rxl.state.good]]». Если PTT включается, но мощности нет, проблема почти всегда здесь (не тот выход или громкость TX Lvl); если трансивер не переходит на передачу, дело в CAT.",
  "t.k3v40fpncz": "[[bak.title]] · [[bak.make]]: создаёт на рабочем столе zip-файл Aurora-impostazioni-….zip со всеми настройками (станция, трансивер, звук, оповещения, цвета, панели) и журналом QSO и сообщает имя и число файлов. Пароли и ключи сервисов (QRZ, LoTW, ClubLog…) не включаются. Когда: перед переустановкой Windows, сменой ПК или рискованными испытаниями.",
  "t.k42gvylxxy": "Журнал Aurora и журнал подключённых программ ведутся в другом месте ([[nav.log]] и [[nav.settings]] › [[sw.fam.log]]): здесь Вы видите и сохраняете только QSO Aurora.",
  "t.k6elgig8og": "Нажмите «[[sstv.cal.button]]»: кнопка становится активной только после хорошо принятого изображения. Под кнопкой строка показывает измеренные ppm (или сообщает, что подходящего изображения пока нет), и значение попадает в поле выше.",
  "t.k6p28xt2zh": "[[sw.p.operator]] · [[sw.p.name]] и [[sw.p.qth]]: Ваше имя и Ваш город. Это те же поля, что «[[digi.f.myname]]» и «[[digi.f.myqth]]» на странице PSK·RTTY·CW, и они подставляются вместо слов <MYNAME> и <MYQTH> в макросах. Сохраняются сразу.",
  "t.kbiuvbcx2e": "Каждая строка — это декодированное сообщение: время, рапорт, текст, страна с флагом и расстояние. Метки справа показывают, чем оно особенное.",
  "t.kc7bsc3hxe": "Во время пролёта: «[[sat.trk.minEl]]» задаёт, с какой элевации спутник считается видимым, «[[sat.trk.startEl]]» — с какой элевации ротор начинает его сопровождать, «[[sat.trk.interval]]» — как часто, самое большее, отправляется новая позиция, а «[[sat.trk.tol]]» — на сколько градусов должна измениться позиция, чтобы ротор сдвинулся.",
  "t.kdcexiomd2": "«[[cta.log.section]]» · «[[logio.export]]» и «[[logio.import]]»: экспорт внутреннего журнала в ADIF и импорт Вашей истории, как в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.files]].",
  "t.kezkywakhh": "В [[gen2.bandHopList]] впишите элементы через запятую: «FT8 20m», «FT4 40m» или частоту в kHz, например «14090».",
  "t.khppj990m4": "местное время",
  "t.khtearoamd": "Радио, общее с Log4OM через Cat4OM",
  "t.kj0vm43jhh": "Индикатор, «[[ens.test]]» и результат: в блоках спотов и поиска они работают как в [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]]; в «[[onl.grpSolar]]» и «[[onl.grpDxped]]» индикатор показывает, включён ли сервис, а «[[ens.test]]» делает один запрос помимо периодических. Спот на WSPRnet («[[ens.g.wsprnet]]», «[[ens.k.WSPRnetUpload]]», по умолчанию выключено) находится в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.wspr]].",
  "t.kjki0dxvs4": "Красная метка: эта станция вызывает Вас.",
  "t.kkki5xoaqo": "отправляет радиостанции команду CAT, записанную в hex (Icom и другие двоичные радиостанции)",
  "t.kkxhny9u39": "Открывается из [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] › [[ca.title]] кнопкой «[[ca.run]]». Проверяет пять вещей и для каждой показывает отметку: ✓ всё хорошо, ! посмотреть, × исправить, … ещё измеряется. Вверху итоговая строка: «[[ca.allOk]]» или «[[ca.someBad]]». Никаких настроек не меняет.",
  "t.klukfbk9vr": "Ваше имя",
  "t.kmxlgvb2wl": "[[nav.stats]]",
  "t.knqavm0mr8": "Панель показывает споты для используемого диапазона: на тихом диапазоне она может оставаться пустой. Попробуйте другой сервер.",
  "t.komauxu99x": "Типичная ошибка: в руководстве указано 88h, а Вы пишете 88. Но 88 в десятичном виде — это 58h, другой трансивер, и Icom не отвечает. Aurora это замечает: под полем появляется небольшая заметка с числом в шестнадцатеричном виде и тем, которое нужно ввести, и кнопка «Use», которая впишет его за Вас. Нажмите её, если введённое Вами число взято из руководства.",
  "t.kq89c29o3a": "Отправка журнала тому, кто Вам помогает",
  "t.kqsb0dhg8a": "Страница пуста: Aurora работает не с собственным движком или не может прочитать его настройки. Перезапустите Aurora и снова откройте страницу.",
  "t.krpytbulzk": "Команды макросов по семействам",
  "t.ksjmqligyg": "передаёт файл .wav из папки текстов макросов",
  "t.kt37qqjvzd": "Aurora BIGScan (CW и RTTY)",
  "t.ktd4qpq0wc": "Верхняя панель: значок RX (зелёный) или TX (красный); выпадающий список диапазонов и выпадающий список режимов (серые, если радио не управляется; если Вы передаёте, Aurora запрашивает подтверждение перед их изменением); кнопка с ваттами (реальная мощность, которую отдаёт радио): касание открывает − и +, которые повышают или понижают мощность радио на 5%; секунды периода; кнопка ⟳, перезагружающая страницу с ПК («[[phone.refresh]]»); значок темы. Ниже полоса показывает ход периода.",
  "t.ku7gfu5kxq": "[[bak.note]]",
  "t.kut2fdg4rz": "Режим JT4",
  "t.kuu2fh3c7n": "«[[rbn.title]]» (по умолчанию выключено): «[[rbn.enabled]]» подключает Aurora к telnet.reversebeacon.net с позывным станции; «[[rbn.cwRtty]]» и «[[rbn.digital]]» выбирают порты. Диапазоны, режимы и континент приёмника фильтруют споты (если ничего не выбрано, показываются все). Споты не попадают в панель DX Cluster: Aurora группирует их по станциям (сколько приёмников, лучшее ОСШ, последние 10 минут) и показывает на странице CW и RTTY, на водопаде с пунктирной меткой «RBN» и в списке «[[rbn.listTitle]]» под Aurora BIGScan, только для станций, которые Aurora не декодировала. Щелчок переносит частоту приёма туда; «[[rbn.show]]» в меню «Вид» скрывает их.",
  "t.kvszyri4pd": "[[sw.pg.digiMacros]] · «[[sw.macros.new]]»: открывает редактор на первой ещё свободной клавише, действительной для всех режимов; клавишу можно изменить в редакторе. «[[sw.macros.edit]]» открывает макрос этой строки.",
  "t.ky57cmhior": "При «UP N» в комментарии (например «UP 5») спот — это DX-экспедиция со сплитом: передача смещается на N kHz выше приёма, до 3,5 kHz звуковой частоты; сверх этого появляется уведомление, а передача остаётся на месте. Настоящий DX Split, с радио в сплите, выполняется из DX Cluster в Настройках.",
  "t.l04og0i7fm": "Дважды щёлкните по строке CQ: ответ начинается сразу, затем включается [[ctl.enable_tx]], и уведомление сообщает «Answering …». Aurora передаёт в нужном периоде. Если Вы уже передаёте, а новую станцию нужно вызвать в том же периоде, передача не прерывается: сообщение переключается на лету.",
  "t.l1mrlctk30": "Предупреждение о роторе: в блоке «[[sat.alert.title]]» установите «[[sat.alert.rotorLead]]» от 0 до 30 минут (по умолчанию 5; 0 = без предупреждения). При включённом роторе за это время до пролёта воспроизводится звук, выбранный для «[[sat.alert.ev.rotor]]», а карточка «Доплер и ротор» показывает «ротор поворачивается на N°», так что у Вас есть время освободить антенну. Ротор запускается сам примерно за 150 секунд до пролёта и после окончания пролёта не возвращается в положение парковки. Когда Вы выбираете звук, Вы сразу его слышите.",
  "t.l1o8ofw5m5": "«[[lay.settings]]» · «[[cluster.max]]» (по умолчанию 500, от 50 до 2000): сколько спотов хранить в памяти; самые старые отбрасываются первыми. «[[cluster.age]]» (по умолчанию 60, от 5 до 1440 минут): через какое время спот отбрасывается; старый спот редко ещё полезен, 60 минут — хорошее значение. Значение вне пределов показывает красное предупреждение и не сохраняется.",
  "t.l2bm1ohmkn": "Поиск параметра в Настройках",
  "t.l2zedm0yme": "Предпросмотр: щелчок по слою выбирает его; перетаскивание перемещает его; маркер справа внизу меняет размер, а маркер сверху поворачивает (с шагом 15 градусов). Щелчок по пустому месту снимает выбор. Правый щелчок или два пальца перетаскивают фоновое фото, чтобы скадрировать его; колесо меняет масштаб. Когда предпросмотр пуст, в нём написано «[[sstv.bg.drop]]». Когда Вы перетаскиваете или вставляете фото, панель переключается на вкладку «[[sstv.tab.photo]]»; когда щёлкаете по слою — на вкладку «[[sstv.layers]]».",
  "t.l347ug8vj8": "Посвящение автора («[[about.dedica]]») и четыре блока только для чтения: «[[about.author]]», «[[about.license]]» (GPL-3.0: свободное программное обеспечение, без гарантий), «[[about.derived]]» (программы, от которых происходят части Aurora) и «[[about.thanks]]» (проекты, на которые опирается Aurora).",
  "t.l37l2iejae": "Блок «Открытые диапазоны»",
  "t.l3efzmn0dg": "Быстрее: щелчок по пику синхро в гистограмме ставит туда короткую метку.",
  "t.l5a66cqtcd": "Станция из списка загружала журналы, но это не значит, что она подтвердит Ваше QSO: полоса — лишь подсказка.",
  "t.l61o9lspas": "[[toast.grp]] · [[toast.show.ok]] и [[toast.show.info]]: какие типы сообщений показывать (оба по умолчанию включены). Снимите [[toast.show.ok]], чтобы не видеть подтверждений успеха, [[toast.show.info]] — информационных. «[[toast.show.error]]» включён всегда и не меняется: ошибку нужно видеть.",
  "t.l6a5njy109": "«[[cop.spots]]» · [[cop.expire]]: споты старше 5, 10, 15, 20, 30, 60 или 120 минут исчезают; «[[cop.never]]» (по умолчанию) хранит их, пока их хранит кластер.",
  "t.l7n1vo4azh": "Журнал на другом ПК: брандмауэр Windows на том ПК должен пропускать UDP на выбранный порт.",
  "t.l87e21wi4x": "[[tab.bands]]: кнопка с флажком для каждого диапазона, от 2200 м до 1,25 см (всего 25); щелчок включает или выключает его в полосе. По умолчанию включены диапазоны от 160 м до 2 м (160, 80, 60, 40, 30, 20, 17, 15, 12, 10, 6 и 2 м); 2200 м, 630 м, 8 м, 4 м, УКВ (UHF) и СВЧ включаются здесь. Хотя бы один всегда остаётся включённым, а диапазон, на котором находится трансивер, показывается всегда, даже если Вы его выключили.",
  "t.la4o0nopgh": "Всегда сначала открывайте Aurora, затем остальные программы.",
  "t.lbkhtx7nap": "На страницах SSTV клавиши другие: F1 передаёт изображение, Esc останавливает его. Pause и двойного Esc, как здесь, в SSTV нет.",
  "t.lckkvnlcyv": "Символ, который не даёт звука сразу, отмечается как отправленный вместе со следующим звуком. В CW и RTTY раньше отметка опережала то, что было слышно.",
  "t.lfdi5hk4iu": "Строка адреса: сообщает, какой адрес ПК помещён в QR-код (виртуальные адаптеры WSL, Hyper-V, VirtualBox и VPN исключаются). Если вместо этого она красная, «[[net.noAddress]]»: у ПК нет адреса в домашней сети, проверьте кабель или Wi-Fi ПК.",
  "t.lh2siurj75": "В [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], в блоке «[[cat.share]]», включите «[[cat.share.on]]» (только с Hamlib; порт указан в «[[cat.share.port]]», по умолчанию 4532): примерно через 1,5 секунды Aurora применит настройку сама и один раз переподключит радиостанцию, или сразу по кнопке [[cat.apply]]. Адрес для использования появится там же после подключения радиостанции.",
  "t.lhlcu1lnyx": "Внизу слева легенда: QSO (квадрат, проведённый по журналу), QSL (подтверждён), QSX (трафик в эфире, не с Вами), CQ, CQDX и QRZ (кто вызывает Вас). Во время передачи красная линия идёт к станции, которую Вы вызываете.",
  "t.ljgxl1otvw": "[[tab.waterfall]]",
  "t.ljp664ufso": "Список частот",
  "t.ljvyi8gwq2": "«[[digi.cw.som]]»: для приёма неровной ручной манипуляции выбирает символ, ближайший к длительностям точек и тире. По умолчанию выключено; включайте только для станций, которые манипулируют неровно.",
  "t.llqr8x2afi": "Откройте [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › «[[dec.slowPc]]».",
  "t.lm0kqndiaf": "[[auto.b1]] · [[auto.minSnr]] (числовое поле, от −30 до 20, по умолчанию −18): не отвечает на сигналы слабее этого значения. Увеличьте, если Вы тратите время на сигналы, с которыми QSO не завершается.",
  "t.lma1pzkqzp": "Пароли и ключи: введите их в поле и нажмите Enter (или выйдите из поля); поле покажет «[[ens.pw.saving]]» и останется ожидающим, пока вы не нажмёте «[[sw.save]]» внизу. После сохранения оно показывает «[[ens.pw.savedShort]] ••••» с «[[ens.pw.change]]» и «[[ens.pw.remove]]», и только тогда «[[ens.test]]» блока запускается сам. Поиск QRZ.com и HamQTH находится в «[[sw.fam.log]] › [[tab.online]]»: если навести курсор на позывной DE в DX Cluster, будут показаны флаг, страна и, если включено, имя и город.",
  "t.lnzas6uggy": "Фиолетовая метка: эта станция ответила на Ваш вызов.",
  "t.lofyx0j9l8": "MSK144 предназначен для связей через метеорные следы на 6 м и 2 м: периоды T/R по 5, 10, 15 или 30 s (по умолчанию 15 s), сообщения как в FT8, кадр 72 ms повторяется весь период, поэтому для приёма достаточно одного метеорного всплеска. Aurora всегда передаёт на 1500 Hz (тоны 1000 и 2000 Hz). Частоты зависят от региона: 50,260 MHz (регионы 2 и 3) или 50,380 MHz (регион 1), 144,150 или 144,360 MHz.",
  "t.lt1g4snzrv": "Проверка: нажмите «[[sw.testCat]]»: должно появиться сообщение, что CAT подключён. Затем «[[sw.testPtt]]»: радио передаёт одну секунду, поэтому используйте эквивалент антенны или подходящую антенну.",
  "t.ltkadlq7k3": "открывает окно отправки QTC (соревнование WAE) станции из QSO",
  "t.ltr731tee7": "Водопад, курсор и настройка",
  "t.luj63ut15z": "ставит курсор в поле передачи",
  "t.lvtylqagd": "Журнал: при открытии ни один QSO не выбран",
  "t.lwx664rkmh": "Панель команд: «[[fox.off]]» / «[[fox.on]]» (переключатель режима Fox: когда включён, вызывает CQ в чётные периоды, ниже 1000 Hz; заблокирован, если контест запрещает Fox/Hound), «[[fox.enableTx]]» (без него Fox слушает, но ничего не передаёт), кнопка «[[stop.button]]», органы управления приёмом (как в «Строка управления приёмом») и «[[ctl.split]]». Блок под панелью предупреждает, если частота защищена (Fox не передаёт в пределах 3 kHz от стандартных частот FT8) или если не включён Enable Tx («[[fox.needTx]]»).",
  "t.lz8o4djfla": "Если корреспондент после изображения передаёт позывной в FSK (FSK ID, как это делает MMSSTV), Aurora считывает его, показывает поверх изображения, записывает в историю и в поле «[[sstv.log.call]]» блока «[[sstv.log.title]]». Если позывной попал в журнал, Aurora сразу ищет станцию через уже настроенный поиск (QRZ.com или HamQTH) и заполняет пустые поля имени, QTH и локатора; страна берётся из cty.dat. Ваши передачи заканчиваются Вашим позывным в FSK: отключить это можно в [[sw.sec.sstv]] › «[[sstv.set.fskId]]».",
  "t.m02jrcuo2y": "Пакет и сеть: в Aurora нет packet: <TALK:call,text> отправляет сообщение через DX-кластер. Пример: <TALK:IU3ABC,QSY 14085>.",
  "t.m2g71pdfzc": "[[gen.screen]] · [[gen.showDt]] и [[gen.showAge]]: два флажка. [[gen.showDt]], по умолчанию включён, показывает столбец DT (смещение времени сигнала): выключите, чтобы выиграть место. [[gen.showAge]], по умолчанию выключен, — тот же флажок, что в блоке фильтров: возраст сообщения вместо времени.",
  "t.m4pf4no6od": "[[sw.tab.freq]]",
  "t.m6993g2prk": "Update: новая версия Aurora (сравнивается с последним выпуском на GitHub). Появляется всегда, даже в режиме «Не беспокоить»; одна карточка на версию, с первыми новостями на Вашем языке (на английском, если их нет). Отключить нельзя.",
  "t.m6idsn0x5e": "Читаются не более последних 500 QSO, а показываются 300 (при поиске — среди последних 500). Если журнал пуст, появляется «[[digi.log.empty]]».",
  "t.m6kmcc5gc2": "[[sstv.set.grpView]] · [[sstv.rx.smooth]]: увеличенное изображение в просмотрщике показывается сглаженным, а не с чёткими пикселями. Применяется сразу, даже на странице SSTV, уже открытой в главном окне, без «[[sw.save]]».",
  "t.m7jeynxmkm": "«[[sstv.undo]]», «[[sstv.redo]]» и «[[sstv.clear]]»: отменить и повторить (до 60 шагов) и начать с нуля (удаляет и фото).",
  "t.m7vaj82uxc": "Позывной, имя, QTH и локатор также заполняются двойным щелчком по позывному в окне приёма, из панели сигналов («[[digi.band.toQso]]») или щелчком по споту. Имя, QTH и локатор заполняются сами по запросу QRZ.com или HamQTH, если он настроен в [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]: текст, введённый Вами вручную, никогда не перезаписывается.",
  "t.m8grk4plxr": "[[gen.screen]] · [[gen2.blank]]: флажок, по умолчанию выключен. Вставляет пустую строку между одним периодом декодирования и следующим, чтобы разделять группы сообщений.",
  "t.maf11lah0w": "LogHX (бесплатный журнал от RX4HX, rx4hx.qrz.ru, версия 3.1) получает данные Aurora так же, как от WSJT-X, JTDX и MSHV: QSO записываются сами, а окно «Active calls for FT8» показывает декодированные станции. Нужны получатель в Aurora и настройка цифровой программы в LogHX с тем же портом.",
  "t.mc68o27nij": "Меню [[ctest.menu]]: список соревнований",
  "t.md469p3nwa": "Подключённые программы и журналы",
  "t.mjs7qkmw16": "«[[agent.kind.prop]]»: геомагнитная буря (индекс K от 5: КВ-диапазоны возмущены) и дневное открытие 12 и 10 метров («good» условия). Не более одного раза в день для каждого; данные поступают с hamqsl.com. По умолчанию «Icon only».",
  "t.mlg298riw3": "Когда в станции что-то не так, внизу справа появляются небольшие карточки: от самой серьёзной (красной) до самой мягкой (голубой, только информация). Они исчезают сами, когда проблема уходит. В первые 20 секунд после открытия ничего не показывается: радио и звук ещё запускаются. У каждой карточки есть × для закрытия (она остаётся закрытой, пока проблема не изменится) и, где нужно, кнопка «[[diag.fix]]», открывающая нужную страницу настроек.",
  "t.mmhe3h3f3f": "[[sw.wspr.beacon]] · [[mode.wsprType1]]: кнопка вкл/выкл, по умолчанию включена. Если включена, маяк посылает сообщения типа 1 (позывной, четырёхсимвольный локатор, мощность). Если выключена и локатор шестисимвольный, чередуются типы 2 и 3; составные позывные всегда их чередуют. Выключайте, только если хотите передавать шестисимвольный локатор.",
  "t.moeyfo6a1t": "открывает настройки режима",
  "t.mpl8zhta2f": "Отключение или изменение оповещений: подсвеченные карточки, звуки, цвета, сообщения",
  "t.mqly8on7zt": "скорость: 31,25 или 62,5 для PSK, 45,45, 50, 75... для RTTY",
  "t.ms98humib0": "Проверьте часы: если время неверное, вверху появляется жёлтое предупреждение.",
  "t.mu6kilv7ft": "[[ens.g.alltxt]] · [[ens.k.WriteDecodedDebugALLTXT]] (по умолчанию выключено): как предыдущий, плюс диагностические строки декодера. Нужен только для поиска проблемы, и файл быстро растёт. Два флажка исключают друг друга: отметив один, Вы снимаете другой.",
  "t.mumakf3c5g": "[[clock.state]] · [[ens.test]] (кнопка внизу блока, со светодиодом рядом с заголовком): выполняет измерение смещения, как «[[clock.check]]», без исправления, и записывает результат («[[ens.test.ok]]» или «[[ens.test.err]]»). Светодиод горит, только если периодическая проверка включена, а проверка выполняется сама при открытии страницы.",
  "t.muwnf0h8uk": "Страница журнала открывается без выбранных QSO, и после удаления тоже ничего не остаётся выбранным: так нельзя случайно стереть всё. Чтобы экспортировать весь журнал, используйте «Выбрать все». По просьбе Luc, ON7KEC.",
  "t.mwa1bssphr": "Полная статья: «[[sw.tab.appearance]]»; «Язык, тема и громкость на панели».",
  "t.mwp5gnujxp": "[[auto.b4]] · [[auto.countries]] (выпадающий список «[[auto.addCountry]]» и ряд меток): выберите из списка DXCC страны, которым никогда не отвечать; каждая показывается как метка с «×» для удаления. Если списка нет, появляется «[[auto.noCty]]»: нужен файл префиксов cty.dat.",
  "t.mwsxzvzz2w": "Вверху окна слева находятся кнопки режимов, справа — страницы (см. «Страницы на верхней панели»). Логотип «AURORA» слева всегда возвращает на страницу [[nav.station]]. Подсвеченная кнопка показывает, где Вы сейчас.",
  "t.mxutp0qmdu": "Клавиши и кнопки, включающие и выключающие передачу на странице [[nav.textModes]].",
  "t.mxvjl8i1xz": "После группы «[[bfl.except]]» идут четыре кнопки, которые сужают оставшееся: «[[bfl.cqOnly]]» (только сообщения станций, вызывающих CQ), «[[bfl.rr73AsCq]]» (станция, отправляющая RR73, тоже считается вызывающей CQ), «[[bfl.hasGrid]]» (только станции, приславшие свой локатор) и «[[bfl.notMyCont]]» (скрывает станции Вашего континента). Во втором ряду после «[[bfl.hide]]» идут континенты (EU, AS, AF, NA, SA, OC, AN): один щелчок скрывает их (красная зачёркнутая кнопка), другой возвращает; рядом два поля для стран и позывных, которые нужно скрыть, через запятую (JA* = все JA). Это те же фильтры, что в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], и они также действуют для опции Автоматизации, игнорирующей скрытые станции.",
  "t.mydz7a6b1f": "Проверки, когда водопад показывает сигналы, а список остаётся пустым.",
  "t.mzuhm4rlgb": "«[[wft.spec]]»: выпадающий список для спектра под водопадом: «[[wfs.specOff]]» скрывает его, «[[wfs.current]]» показывает последний спектр, «[[wfs.cumulative]]» — среднее за весь период. Высота меняется перетаскиванием мышью разделителя между водопадом и спектром, он стал выше и с более крупной ручкой («[[wf.specHeight]]»).",
  "t.mzw20jxh0r": "[[bak.title]]",
  "t.n0te1iliz3": "RTTY: приёмник, шумоподавитель и настройки RTTY",
  "t.n1ddyvx0eu": "[[aud.input]] · [[aud.inch]]: «[[aud.ch.mono]]» (заводской) суммирует два канала; «[[aud.ch.left]]» или «[[aud.ch.right]]» используют один канал (нужно, если трансивер выдаёт звук только на одну сторону). Левый и правый требуют стереовхода; при моновходе список их отключает.",
  "t.n2i5d715xd": "Если «Band activity» кажется пустой, сразу проверьте кнопку «[[bfl.button]]»: если рядом с ней стоит число, фильтр активен. Сообщение «[[bfl.empty]]» это подтверждает.",
  "t.n362wxiqb": "«[[ens.g.udp]]» · «[[ens.test]]»: проверяет адрес и порт и отправляет Heartbeat подключённой программе. Сам при открытии страницы не запускается. Индикатор этого блока следует не за переключателем (сервер всегда принимает), а за последней проверкой. Пункты «[[ens.k.udpWindowToFront]]», «[[ens.k.udpWindowRestore]]» и «[[ens.k.ApplyFiltersToUDPmessages]]» есть в программе, но ещё не подключены: на странице они не отображаются.",
  "t.n40svdpzm1": "[[gen.screen]] · [[gen.confirmList]]: флажок, по умолчанию выключен. Двойной щелчок по строкам списков декодирования (Активность в диапазоне, окно RX) вызывает станцию сразу, без вопроса «Вы хотите вызвать…?»; вопрос остаётся для «CQ и новости» и для DX-экспедиций. Когда включено, вопрос появляется и при двойном щелчке в списках. Не путайте с двумя соседними флажками: [[gen.confirmUnseen]] убирает окно подтверждения, [[gen.dblReply]] отключает сам ответ по двойному щелчку.",
  "t.n442lclnlg": "[[sup.title]] · [[sup.email]]: текстовое поле (по умолчанию пустое) для адреса электронной почты того, кто Вам помогает. Сохраняется само в этой программе и используется только кнопкой «[[sup.sendMail]]»: никуда не отправляется.",
  "t.n7ix4l0ynj": "[[digi.menu.file]] › [[digi.mi.macrosReset]]: восстанавливает заводские макросы Aurora (базовые, для отдельных режимов и выбор объединения) и подтверждает сообщением «[[digi.mi.macrosRestored]]». Стираются все Ваши изменения макросов: используйте это, только если хотите начать с нуля. Работает только с ПК, на котором запущена Aurora.",
  "t.n8e7s7xaij": "[[rep.title]] · [[rep.active]]: флажок, по умолчанию включён. При запуске, а затем примерно каждые 40 минут, пока Aurora открыта, отправляет уровень использования (простаивает, принимает, передаёт), случайный код установки (или, если Вы задали позывной, код, полученный из него: сам позывной никогда не отправляется), версию Aurora, операционную систему, название установленного антивируса, страну и тип компьютера (процессор, число ядер и память). Нужен, чтобы считать, кто пользуется Aurora, и узнавать, на каких компьютерах ей тяжело. Выключите, если не хотите даже этого.",
  "t.n8y9xbw3hv": "Водопад: левая кнопка = частота Rx, правая кнопка или Shift + щелчок = частота Tx; Tab для перехода на маркер и стрелки влево/вправо для его перемещения (10 Hz; Shift = 50 Hz).",
  "t.ndtnjju5b1": "Панель «Команды»: каждое поле и кнопка",
  "t.neixb7ufpt": "При слишком большом числе сигналов Aurora оставляет самые сильные, чтобы не использовать более четверти ядра.",
  "t.neot2ye04o": "«[[sstv.img.reply]]» (у принятых): переносит изображение в редактор как фон и ставит позывной станции как другую станцию. «[[sstv.img.useBg]]» (у переданных): использует Ваше изображение как фон повторно.",
  "t.nev1yvtq4u": "Столбцы: [[digi.band.colFreq]] (реальная частота в kHz, если радио подключено, иначе нота в Hz), WPM (только CW), S/N в dB, [[digi.band.colCall]] (с флагом и CQ или DE; курсивом до проверки, со страной и состоянием проверки в подсказке) и [[digi.band.colText]] (последние 44 символа, неуверенные — серым).",
  "t.nez33b5fp1": "режим SSTV для <PIC> и <FROMCLIP> (без имени: тот, что в настройках SSTV)",
  "t.nf4vt4d9bj": "CW: скорость, тон и манипуляция",
  "t.nha4xj6b1q": "Если передача не начинается, сначала посмотрите на [[ctl.enable_tx]]: это единственный переключатель, который обязательно должен быть включён для отправки сообщения; остальные определяют, как продолжается QSO.",
  "t.ni3j4te482": "[[diag.crashFolder]] · [[diag.openCrashFolder]]: кнопка блока, которая появляется только если у ПК есть папка сбоев (%APPDATA%\\Aurora\\crash). Открывает папку, в которой Aurora сама записывает каждый сбой: читаемый файл .txt и, для зависаний и ошибок, минидамп .dmp. Когда: чтобы приложить к отчёту файлы с даты проблемы вместе с журналом работы. Хранятся последние 10 дампов и 50 текстов.",
  "t.niq3ak0vdy": "[[auto.b3]]: попытки и пауза для каждой станции, не более заданного числа QSO в час (0 = без ограничения) и, при желании, временное окно по местному времени: вне него автоматизация ждёт.",
  "t.njebvowq6y": "Вторая вкладка показывает QSO, которое Вы проводите (голубая строка вверху), а под ним QSO журнала Aurora, самые свежие сверху. Голубая строка заполняется прямо на месте.",
  "t.nqnhn7ihgv": "PSK, RTTY и CW: открытая передача и набор «вживую»",
  "t.nqqoolfn1p": "Заголовок: сколько всего сигналов, сколько из них вызывают CQ (их строки выделены) и примечание о том, что серые символы неуверенные. Кнопка «[[digi.band.clear]]» очищает список, историю и позывные на водопаде; сигналы, которые ещё присутствуют, появляются снова сами.",
  "t.nrksjzpye3": "передаёт в SSTV картинку из буфера обмена",
  "t.ntactuqu62": "Только для Cat4OM: [[cat.cat4om.management]] (заводское 127.0.0.1:17300: отсюда Aurora сама находит группу и её порт; с другого ПК впишите адрес того ПК), [[cat.cat4om.group]] и [[cat.cat4om.address]] (оставьте их пустыми: в серой подсказке показано «[[cat.cat4om.auto]]» или найденное значение; впишите Control, например 127.0.0.1:5001, только если управление не отвечает или запрашивает пароль), [[cat.cat4om.key]] (пароль группы, только если нужен) и [[cat.cat4om.radio]] (имя трансивера в Cat4OM, например kenwood/ts-990; пусто = «[[cat.cat4om.firstRadio]]»).",
  "t.ntoh82q3sb": "Частота — это частота сигнала: Aurora перестраивает радиостанцию так, чтобы сигнал оказался на текущей звуковой частоте приёма.",
  "t.nu0hnq7k1r": "строки картинки выбираются на странице SSTV: команда открывает её",
  "t.nvlesdka3p": "Для тех, кто работает на DX-экспедиции: классический режим Fox, на стадии тестирования. Без SuperFox.",
  "t.ny812tiou9": "Порог шумоподавителя: S/N от -30 до +20 dB (по умолчанию -15), измеряется в 3 kHz, как в WSJT-X. Задаётся в окне «[[digi.ms.title]]»; ниже примерно -16 dB ничего не печатается, даже при выключенном шумоподавителе.",
  "t.nzoufjxdsj": "водопад: 1 — обычная ширина, 2 и более — широкий водопад",
  "t.o1phiwm6hd": "Панель WEFAX в одну строку и ALC в компактном дисплее",
  "t.o2wnagggwo": "Двойной щелчок по сообщению: Вы отвечаете (нужна «[[gen.dblReply]]»). Щелчок правой кнопкой по сообщению: в очередь. Щелчок правой кнопкой по позывному: меню «Открыть на QRZ.com». Двойной щелчок по «RX» в панели передачи: освобождает DX. Двойной щелчок по QSO в панели «Журнал»: исправить или удалить.",
  "t.o6jgv7ztqw": "PSK и RTTY: страница и параметры «View»",
  "t.o7la0shcta": "Более чувствительное декодирование FT8",
  "t.o7u6dgxoz1": "Aurora читает комментарий: «UP 5», «UP5», «5 UP», «5UP», «10up», «DN 2» или «DOWN 2» (ниже), «QSX 14.030» или «QSX 030» (где слушают). Просто «UP» означает 1 kHz; «UP 1-3» означает середину, 2 kHz. Числа в kHz, в верхнем или нижнем регистре. В строке спота показывается метка «UP 5»: наведя на неё курсор, Вы увидите, куда пойдёт передача. «UP 14.0305», «QSX 21.2» и диапазоны частот читаются правильно, а локатор вроде «DN31» не принимается за «DN».",
  "t.ob26wcoizj": "[[sw.digi.perMode]] · CW, «[[digi.band.mi]]» (по умолчанию включено): декодирует каждый сигнал CW в звуковой полосе собственным приёмником в отдельном потоке, используя не более четверти одного ядра (при слишком большом числе сигналов оставляет самые сильные). Питает список сигналов рабочей страницы.",
  "t.obv8pioqff": "Опции: «[[fox.slots]]» от 1 до 5 (сколько станций Вы обслуживаете в одном периоде: больше слотов = быстрее, но мощность делится); «[[fox.cq]]» (CQ всем или только одному континенту или DX); переключатели «UltraFOX» (один широкий сигнал от 750 до 2260 Hz с числом станций до 9), «[[fox.moreCqs]]» (отправляет CQ также в периоды с занятыми слотами) и «[[fox.autoQueue]]» (ставит вызывающих в очередь сам, начиная с лучшего сигнала); «[[fox.reset]]» очищает вызывающих, очередь и текущие QSO и обнуляет счётчики.",
  "t.odtp2vjrtu": "передаёт запись (из папки записей или текстов макросов); <STOPPLAY> останавливает",
  "t.oep2e6vqpp": "«[[cluster.servers]]» (справа от заголовка число, например 3/8): список серверов, не более 8. По умолчанию: IU3WJQ-7 (cluster.iu3wjq.com, порт 8000), HamQTH (hamqth.com, порт 7300), Hamcloud (dx.hamnet.network, порт 7300) и VE7CC (ve7cc.net, порт 23); споты по умолчанию идут с IU3WJQ-7, а если он не отвечает — со следующего. В каждой строке: индикатор (зелёный = доступен, с миллисекундами; красный = недоступен, с причиной; серый = проверка), название и адрес:порт, флажок «[[cluster.server.on]]» (использовать этот сервер; снимите отметку, чтобы оставить его в списке без подключения) и «[[cluster.server.remove]]». При нескольких серверах одинаковые споты показываются только один раз.",
  "t.ofqqiq0io6": "В левом верхнем углу страницы [[nav.station]], над водопадом, находятся выбор режима и выбор частоты. Они работают, если радио управляется по CAT; без CAT Вы меняете режим на радио (или на странице), и Aurora всё равно декодирует.",
  "t.ogq8ylljk0": "QMAP: все Q65 в участке диапазона",
  "t.ogxbunrapx": "Aurora каждый день загружает публичный список пользователей LoTW от ARRL (если не удаётся, сохраняет старый). Наведите курсор на позывной: появится «Uses LoTW: last upload» с датой. В карточке позывного «LoTW» появляется только если станция им пользуется, зелёным и без даты; если не пользуется, ничего не появляется. Это справедливо и для станций DX Cluster, проверяемых по публичному списку ARRL.",
  "t.ogxtgzei1c": "Дважды щёлкните карточку: Вы ответите этой станции. Значок × закрывает её (она не возвращается, пока Aurora остаётся открытой); каждая станция появляется только один раз, со своим звуком.",
  "t.ohvawip0le": "«[[wft.bins]]» (по умолчанию 5): сколько каналов спектра складывается в один пиксель; меньше каналов = больше деталей и больше шума. «[[wft.start]]»: звуковая частота, с которой начинается левый край (0-4900 Hz, по умолчанию 0); увеличение отрезает нижнюю часть и увеличивает остальное.",
  "t.oi90z4hrah": "[[sup.title]] · [[sup.prepare]]: создаёт на рабочем столе zip-файл Aurora-assistenza-….zip с журналами работы, отчётами о сбоях, настройками (без паролей) и сводкой по станции, затем показывает его в Проводнике. Пока она работает, на кнопке написано «[[sup.working]]». Когда: если что-то не так и Вам кто-то помогает.",
  "t.oisv1ruymb": "снова отправляет позывной после того, как вы его исправили",
  "t.ojrewyq0k9": "Рядом восемь счётчиков: «[[fox.logged]]» (QSO, занесённые в этом сеансе), «[[fox.inProgress]]», «[[fox.callers]]», «[[fox.queue]]», «[[fox.stat.rate]]» (QSO в час за последние 10), «[[fox.stat.hour]]» (QSO за каждые 5 минут последнего часа), «[[fox.periods]]» и «[[fox.continents]]» (QSO по континентам). Наведите курсор для пояснения.",
  "t.ol26sybozj": "WinKeyer и ротор: текст и байты для WinKeyer, ручка скорости и команды ротора в стиле GS-232. Пример: <WKTEXT:CQ TEST> или <ROTORCMD:M180>, чтобы повернуть на юг.",
  "t.olfavqsm36": "фиксирует передачу на месте (<UNLOCKTX> освобождает её)",
  "t.omdusp9xh0": "[[digi.edit.clear]]: очищает название, текст и цвет (клавиша становится пустой после OK).",
  "t.oqqgfoo3er": "«[[prop.bands]]»: таблица со сгруппированными диапазонами (80-40 m, 30-20 m, 17-15 m, 12-10 m) и двумя столбцами: день (солнце) и ночь (луна). В каждой ячейке три маленькие полоски (одна = плохо, две = удовлетворительно, три = хорошо) и слово «[[prop.cond.Good]]», «[[prop.cond.Fair]]» или «[[prop.cond.Poor]]». Столбец, в котором Вы находитесь сейчас, помечен «[[prop.here]]»; строка группы диапазонов, на которую настроено радио, подсвечена и помечена «[[prop.tuned]]». Те же данные находятся в блоке «[[bands.title]]» страницы «Станция».",
  "t.or5m153g6w": "очищает окна приёма и передачи",
  "t.oscpgb57ty": "«[[ens.test]]» выдаёт ошибку: проверьте имя пользователя, пароль или ключ и, для Wavelog, адрес и номер станции; затем сохраните кнопкой «[[sw.save]]» и попробуйте снова. Индикатор остаётся красным, пока последняя проверка или выгрузка завершалась ошибкой.",
  "t.p03crnx9k8": "Кнопка «[[radar.title]]» в верхней панели (рядом с выбором частоты) включает и выключает его отдельно для CW и RTTY; выбор запоминается. Выключено: нет списка и нет лишней нагрузки, декодируется только та станция, которую Вы слушаете. Тот же переключатель есть в меню «Параметры» («[[radar.mi]]»).",
  "t.p3571i1a4k": "команда ротора в стиле GS-232: M или W с градусами — поворот, S или A — остановка; выполняется через ротор Aurora",
  "t.p466xtix6e": "Ручку на верхнем краю панели перетаскивают, чтобы изменить высоту списка; высота запоминается. Параметр «[[digi.band.wfCalls]]» включается из меню «Параметры» и «Вид».",
  "t.p4a5hf33v1": "[[lay.options]] · [[fil.ownContinent]]: флажок, по умолчанию выключен. Скрывает станции Вашего континента: полезно, чтобы видеть только далёкие DX.",
  "t.p4alaj4tiq": "«[[ens.g.udp]]» · «[[ens.k.UDPServer]]» и «[[ens.k.UDPServerPort]]» (по умолчанию 127.0.0.1 и 2237): куда Aurora отправляет поток WSJT-X (декодирования и состояние) — протокол, который читают GridTracker, JTAlert, QLog, Log4OM и подобные программы. 127.0.0.1 означает этот же ПК; для другого компьютера впишите его IP-адрес или адрес группы multicast. Порт должен совпадать с указанным в принимающей программе. Меняйте их, только если 2237 занят или программа слушает в другом месте.",
  "t.p5y2bjbpy0": "[[sw.testCat]]: подключает трансивер с настройками [[sw.pg.radio]] и ждёт результата до 15 секунд. Сообщает «[[sw.catOk]]», если трансивер отвечает, иначе «[[sw.catFail]]» с причиной (порт, скорость, трансивер выключен…). Это то же самое, что [[cat.connect]] и просмотр состояния.",
  "t.p864fbidug": "Панель [[panel.cluster]] показывает споты с серверов, к которым Вы подключены. Если она пуста, см. также «DX Cluster пуст». Если кластер выключен, панель сообщает об этом и показывает кнопку «[[cluster.settings]]»; то же самое происходит, если в данных станции нет Вашего позывного.",
  "t.p8o7qkfaxa": "Страница SSTV: как она устроена",
  "t.pa3hh2p21r": "[[lay.settings]] · [[clock.warn]]: порог тревоги в миллисекундах, от 10 до 5000; заводское 500. При смещении сверх этого значения часы помечаются жёлтым и, при включённом автоматическом исправлении, исправляются. Для FT8 200 — хорошее значение, если Вы хотите быть строже; увеличьте его, если предупреждение срабатывает слишком часто.",
  "t.pa9qp7j4vo": "При включённом [[ctl.filter]] две тёмные области по бокам от маркера Rx показывают часть диапазона, которую Aurora игнорирует.",
  "t.peetesnrqs": "Только для RTTY: выпадающий список сдвига (Hz), выпадающий список скорости (bd) и кнопка «Rev» (mark и space поменяны местами; при радио в LSB появляется «Rev (LSB)», потому что Aurora уже сама их инвертирует). По названию «RTTY» в конце можно щёлкнуть, чтобы открыть «[[digi.rtty.title]]».",
  "t.pfvdroh0z0": "Каждая плитка CQ показывает флаг, позывной и страну; сообщение, рапорт и время появляются при наведении курсора. Двойной щелчок — ответить, правый щелчок — поставить в очередь. Станция, не слышимая 15 минут, исчезает сама.",
  "t.pgnostb2v2": "[[lay.settings]] · [[clock.atStart]] (по умолчанию включено): сразу при запуске Aurora проверяет время по серверам NTP и, если оно вне допуска, исправляет его (повторяет попытки около десяти минут, пока серверы не ответят). Чтобы менять время, Aurora должна быть запущена от имени администратора, иначе она только сообщает.",
  "t.pgszkmlci1": "Настройте радиостанцию на частоту, объявленную экспедицией, в FT8.",
  "t.ph9ke9sgx2": "F1…F12 запускают макросы первого ряда; открытое окно «[[digi.edit.title]]», «[[digi.ms.title]]» или «[[digi.rtty.title]]» блокирует все эти клавиши, пока Вы его не закроете.",
  "t.phrzdgdz8e": "После сбоя (при включённом «[[rep.ask]]»): при перезапуске появляется окно «[[rep.crashTitle]]» с кнопками «[[rep.crashSend]]», «[[rep.show]]» (прочитать, что было бы отправлено) и «[[rep.no]]» (ничего не отправляет и больше не спрашивает об этом сбое). После отправки оно показывает код и «[[rep.close]]».",
  "t.phu7uxc5zx": "[[sw.pg.digiMacros]] · внутри каждой группы по одной строке на каждый из 12 слотов: клавиша (F1… в ряду 1, номер слота в остальных) цветом макроса, подпись, сокращённый текст (наведите курсор, чтобы увидеть его целиком), к чему он относится («[[digi.edit.scopeAll]]» или название используемого режима) и кнопка «[[sw.macros.edit]]». Пустые слоты затемнены и имеют «[[sw.macros.add]]». Макросы событий, если они есть, находятся ниже, под «[[sw.macros.events]]».",
  "t.pk321posrh": "Блок «[[prop.solar]]»: три показателя — «[[prop.sfi]]» (солнечный поток на 10,7 см: выше 100 открываются высокие диапазоны, ниже 70 они закрыты), «[[prop.a]]» (ниже = спокойнее прохождение) и «[[prop.k]]» (от 5 и выше — геомагнитная буря) — с цветом оценки; затем «[[prop.xray]]», «[[prop.spots]]», «[[prop.wind]]», «[[prop.geomag]]», «[[prop.noise]]» и, если есть, «[[prop.aurora]]». Внизу время последнего обновления и источник данных (N0NBH, hamqsl.com).",
  "t.pnnpzp5se1": "Вкладка «[[sstv.tab.photo]]»: «[[sstv.bg.load]]», либо перетащите файл на предпросмотр или вставьте с помощью Ctrl+V; «[[sstv.bg.fromFolder]]» с миниатюрами папки фото для передачи (щелчок использует фото; с «[[sstv.sel.start]]» Вы выбираете те, которые нужно удалить с диска); «[[sstv.bg.cover]]» или «[[sstv.bg.contain]]» и «[[sstv.bg.fitAll]]» (когда есть фото); всегда «[[sstv.bg.color]]» (виден там, куда фото не доходит).",
  "t.pp1w3rp27s": "Столбец [[freq.mhz]] (числовое поле): частота настройки в MHz с тремя десятичными знаками (14,074 = 14 074 000 Hz). Она должна попадать в выбранный диапазон, и одна и та же частота не может встречаться дважды для диапазона и режима, иначе таблица не сохраняется.",
  "t.ppry2pp0z0": "[[cat.catmode]]: для FT8 выберите USB data (DATA-USB). Звук идёт через USB-звуковую карту радио, как обычно.",
  "t.prgis0ojek": "Постоянный красный баннер «PTT не выключился»: радио может передавать. Aurora сама повторяет попытки выключить PTT с нарастающими интервалами другими способами (вторая команда, повторное открытие CAT, линии RTS и DTR); пока выключение не подтверждено, передача остаётся заблокированной, а звук повторяется каждые несколько секунд. «[[tx.pttStuck.retry]]» запрашивает новую попытку сразу; «[[tx.pttStuck.ignore]]» скрывает баннер и звук до следующей неисправности (блокировка передачи остаётся). Если Вы меняете радио или профиль при включённом PTT, Aurora не отправляет команду не тому радио: появляется уведомление «PTT предыдущего радио не подтверждён как выключенный», которое закрывается кнопкой «[[diag.close]]». Проверьте радио вручную.",
  "t.psz1ghp9ed": "Поле Tx панели управления становится красным, когда частота Tx вне 200-2700 Hz.",
  "t.pyo1mnp5pp": "ищет сигнал справа",
  "t.pyzt6h99tq": "Последний столбец, кнопка «✕» ([[set.remove]]): удаляет строку из таблицы. Сохраняется сама, как и другие изменения; чтобы вернуть удалённые строки, используйте [[freq.reset]].",
  "t.q2ma1xpn9y": "как <ROTOR:SP>, но по длинному пути",
  "t.q2mdekugmo": "В [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] Вы меняете внешний вид Aurora: язык, светлую или тёмную тему, шрифты и размер текста. Каждый выбор применяется сразу и сохраняется на этом компьютере; сохранять ничего не нужно.",
  "t.q3f2onu0fh": "Раскрывающийся список «[[digi.band.validation]]» в панели задаёт строгость проверки позывных: Aurora подсчитывает, как устроены позывные каждой страны (по журналу, спотам DX Cluster и MASTER.SCP, если Вы поместили его в папку данных Aurora), и позывной с редкой формой должен быть услышан несколько раз, прежде чем будет засчитан.",
  "t.q4c8m17uz1": "Частота приёма и передачи — это центр сигнала: щелчок по водопаду ставит туда центр (Snap не цепляется за тон, потому что сигнал широк, как вся полоса). Тоны и полоса должны помещаться в звуковую полосу: при широкой полосе у краёв (например, 32/2000 на 3500 Гц) Aurora предупреждает красным сообщением и не передаёт и не принимает, пока вы не сдвинете частоту к центру (1500 Гц) или не выберете меньше тонов или более узкую полосу.",
  "t.q5rhjega5b": "в Aurora нет packet: уведомление (также для YAPPRECV и PACKET)",
  "t.q65igl199t": "Кнопка [[ctl.jt_both]] появляется только когда режим JT65 или JT9: при включении она декодирует в ту же минуту и другой режим JT. Вы передаёте в выбранном режиме.",
  "t.q8deoiaaiy": "Контест на перемещаемых карточках",
  "t.q8nlqs5kai": "В FT8 мощность остаётся постоянной на всём протяжении передачи: это нормально.",
  "t.q8yimdbdjy": "[[ctl.agc]]: слабые сигналы рядом с сильными станциями",
  "t.q9ba3kic5a": "Панель над водопадом",
  "t.q9xpjxexiy": "В SSTV F1 запускает передачу, а Esc останавливает. В PSK · RTTY · CW кнопка RX/TX или клавиша Pause открывает и удерживает передачу, Esc останавливает её, а двойное нажатие Esc прерывает сразу.",
  "t.qdbeun6jt3": "[[wfs.specPct]] (по умолчанию 30) показывает спектр под водопадом; в [[wfs.specMode]] выберите [[wfs.current]] или [[wfs.cumulative]] (среднее за период).",
  "t.qe282dzi7r": "После изменения флажков таблицы нажмите «[[sw.save]]» внизу: пока Вы не сохраните, списки не меняются.",
  "t.qeuatmdqtg": "«[[digi.band.clear]]»: очищает список, историю и позывные на водопаде; сигналы, которые ещё присутствуют, появляются снова сами. Полезно после смены диапазона или чтобы начать с чистого листа.",
  "t.qg4sta2opv": "Esc дважды подряд (в пределах полусекунды): помимо остановки передачи он выключает автоматический CQ; клавиша автоматического CQ (по умолчанию F1) выключается, и появляется «[[digi.run.autoCqPaused]]». Чтобы возобновить, нажмите клавишу снова. При включённом «[[gen.escStop]]» два Esc также освобождают, как в FT8, станцию, выбранную для вызова.",
  "t.qgjzz2emsw": "При работе в RTTY щёлкните по названию режима в нижней строке состояния (выбор RTTY в меню «Режим» её не открывает): «[[digi.rtty.title]]» объединяет Rev, AFC, Snap, Squelch, UOS, порог, частоты, приёмник, сдвиг, скорость и [[digi.rtty.charset]] (в том числе кириллицу и скандинавские), в четырёх профилях Set 1-4, выбираемых точками.",
  "t.qgrmd082oq": "обмен для передачи (контест; пусто = порядковый номер)",
  "t.qi4j72p575": "Справа две вкладки, «[[digi.tab.cluster]]» и «[[digi.log.title]]», с текущим QSO; её левый край можно перетаскивать, чтобы расширить столбец. Появляется также вкладка ротора (включена по умолчанию; отключается пунктом [[digi.mi.rotor]] в меню [[digi.menu.view]]).",
  "t.qjlcw3e78s": "задаёт звуковую частоту (относительно — с + или -)",
  "t.ql6986y0kg": "В строке заголовка панели справа: «[[ctl.spot]]» открывает окно для отправки спота на DXSummit с текущим DX и частотой радио (см. «Панель «Команды»»); колесо открывает «[[cop.title]]», такое же, как на странице PSK · RTTY · CW, и действующее здесь тоже: «[[cop.choose]]» (двойной щелчок, по умолчанию, или одиночный; ротор поворачивается в сторону станции), «[[cop.spots]]» (через сколько минут спот исчезает) и «[[cop.columns]]». На телефоне и в отдельном окне две кнопки расположены над панелью. Справа на панели фильтров Вы читаете, к скольким серверам подключены («Подключено к n из m») или «[[cluster.nobody]]» (ни один сервер не подключён).",
  "t.qlxm1w7be7": "[[rot.set.state]]: только для чтения, как идут дела со связью ([[rot.state.off]], [[rot.state.connecting]], [[rot.state.connected]], [[rot.state.moving]], [[rot.state.error]]). Если связь прерывается, Aurora сама повторяет попытку через несколько секунд. При «[[rot.state.error]]» ниже красным появляется причина: обычно неверный порт (не трансивера ли он?), порт уже открыт в другой программе или нет разрешения в Linux.",
  "t.qngj247kdf": "[[wfs.barsOn]] показывает полосы Rx и Tx; [[wfs.freqOn]] — частоту в точке, на которую наведена мышь. [[set.reset]] возвращает заводские значения.",
  "t.qnolql7xtv": "Панель списка желаемых станций (звезда ★): полоса вверху страницы с «разыскиваемый позывной (причина)» [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] или [[wish.reason.grid]], источником ([[wish.source.decode]] или [[wish.source.cluster]]), сообщением, диапазоном и сигналом. При споте из кластера есть также «[[wish.tune]]», который переводит радио на частоту спота; «[[wish.close]]» закрывает панель. Она исчезает сама через 90 секунд и воспроизводит звук, если звуковые оповещения включены (и, если браузер разрешает, отправляет уведомление).",
  "t.qq1anzxpdp": "Мой ПК медленный: есть ли облегчённый режим?",
  "t.qq3gs7icww": "[[sw.contest.title]] · [[sw.contest.open]]: кнопка; открывает страницу [[nav.contest]] в главном окне, где Вы активируете контест, вызываете и экспортируете журнал.",
  "t.qq9jami0dz": "С PSTRotator: в «[[rot.set.connection]]» выберите «[[rot.set.pst]]», затем впишите «[[rot.set.pstHost]]» (127.0.0.1, если он работает на этом компьютере) и «[[rot.set.pstPort]]» (по умолчанию 12000, на нём PSTRotator принимает команды). Aurora только посылает команды (азимут, угол места, стоп): положение ротора не считывается и не показывается.",
  "t.qqg4qcfz6z": "Чтобы поменять местами два соседних окна одинаковой высоты, перетащите заголовок влево или вправо: окно следует за мышью, а другое сдвигается на его место.",
  "t.qqi780mxcy": "В панели [[panel.tx]], под шестью сообщениями, блок «[[ctl.sec.qso]]» содержит два столбца кнопок. Наведите курсор на каждую, чтобы прочитать объяснение; включено = зелёный со светодиодом. Выключать можно всегда; включение тех, что заставляют Вас передавать, требует, чтобы передача была открыта на ПК.",
  "t.qrso5kwsbf": "блокирует режим: <MODE:...> его больше не меняет (<UNLOCKMODE> освобождает)",
  "t.qu3l1hbnwq": "Заголовок страницы: время UTC, кнопка «[[sat.alert.title]]» (оповещения, см. ниже), кнопка обновления «[[sat.tle.refresh]]» (загружает данные орбит; во всплывающей подсказке видно, как давно Вы их загрузили; если данных нет — «[[sat.tle.none]]»), «[[sat.dash.lock]]» / «[[sat.dash.unlock]]» и «[[sat.dash.reset]]» (см. шаг о перемещаемых карточках) и кнопка «[[sat.set.title]]», открывающая настройки спутников ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: сервер данных орбит, автоматическое обновление, карта, доплер и ротор).",
  "t.qzbls7dalr": "Нажмите [[cat.connect]]: состояние должно стать «Подключено» с указанием группы, радио и роли (например, group-1/kenwood/ts-990 — slave). Log4OM сохраняет управление радио; Aurora записывает (частоту, режим, PTT, сплит) только при необходимости и следует за QSY, сделанными Log4OM, например щелчком по споту.",
  "t.qzmgvyyluo": "Телефон не открывает страницу: телефон и ПК должны быть в одной сети Wi-Fi; если QR не открывается, используйте альтернативные QR ПК (Wi-Fi, кабель, постоянное имя) или введите адрес вручную в Chrome или Safari. Внутри Messenger или WhatsApp страница часто не открывается.",
  "t.qzrfwwycxc": "Проверка, интервал, тестовые версии и репозиторий задаются в [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].",
  "t.r377i7cy3a": "Сплит выключается кнопкой «[[cluster.splitDx.off]]», при смене диапазона или частоты, при щелчке по споту без UP и при возврате в FT8 или FT4. Если выключить его не удалось, Aurora не сообщает, что он выключен, пока радиостанция всё ещё в сплите; «[[cluster.splitDx.off]]» не работает во время передачи.",
  "t.r3oewrahj7": "[[ca.radio]]: «[[ca.radio.ok]]» при подключённом трансивере; «[[ca.radio.warn]]», если он не подключён (или OmniRig не отвечает); «[[ca.radio.bad]]», если соединение даёт ошибку. «[[diag.fix]]» ведёт на страницу трансивера.",
  "t.r60q72dfp6": "Чтобы отвечать на скорости корреспондента, используйте «TX at received speed» в меню [[digi.menu.mode]] (она задаёт скорость один раз) или переключатель «[[digi.st.txAtRx]]» в нижней строке: когда он включён (окрашен, как Sq, AFC и Snap), Ваша скорость непрерывно следует за измеренной на принимаемой станции, округлённой до целого WPM и в пределах от 5 до 60; если измерения нет, остаётся последняя. Когда выключен, действует скорость, заданная клавишами − и +; нажатие − или + выключает его. С WinKeyer скорость тоже следует. Нужны включённое прослушивание и сигнал.",
  "t.r88m2b3rga": "ручка WinKeyer задаёт скорость (<WKNOPOT>: задаёт Aurora)",
  "t.r8cbzncnfy": "«[[phone.log]]»: последние три QSO со временем UTC, флагом, позывным, страной, диапазоном и режимом и обменянными рапортами. Заголовок открывает и закрывает панель. Если журнал не отвечает, появляется «[[log.unavailable]]», если он пуст — «[[log.empty]]».",
  "t.ra32xq0h78": "Wait and Reply: если Вы вызвали DX и выключили [[ctl.enable_tx]], когда DX вызовет Вас, QSO возобновится само.",
  "t.ra468wnajp": "[[digi.mi.defaultRst]] (вкл.): после каждого QSO (сохранённого или очищенного) отправленный и принятый рапорты возвращаются к 599. Когда выключено, остаются те, что Вы записали.",
  "t.rad6fz68vs": "Подключение программ ведения журнала (UDP)",
  "t.rbb9a93sj5": "Правый щелчок в окне приёма открывает меню: на слове «[[digi.word.call]]», «[[digi.word.name]]», «[[digi.word.qth]]», «[[digi.word.grid]]» и «[[digi.word.rst]]» помещают слово в нужное поле строки QSO (рапорт попадает в «rcvd.»); всегда присутствуют «[[digi.word.copy]]» (копирует выделенный текст или слово) и «[[digi.mi.clearRx]]».",
  "t.rbyx53gsup": "Введите UDP-порт 2237 (адрес 127.0.0.1) и оставьте multicast выключенным. Не позволяйте LogHX запускать JTDX или WSJT-X: цифровая программа — это Aurora.",
  "t.req3rs8tby": "[[not2.grpDisplay]] · [[not2.diffBg]] с выбором [[not2.cyan]] / [[not2.yellow]]: строки, содержащие Ваш позывной, получают другой фон — голубой или жёлтый, чтобы Вы сразу их замечали. Выбор цвета разблокируется только при включённом флажке. По умолчанию выключено.",
  "t.rg32monv8v": "FlexRadio, SunSDR, ExpertSDR: COM-порта нет, используйте TCI ([[cat.backend]] → «[[cat.backend.tci]]»); для FlexRadio работает также SmartSDR CAT.",
  "t.rgf9sdzhyq": "Полная статья: «Вижу сигналы, но ничего не декодируется»; «Часы».",
  "t.ri0qvz6m2r": "Статус: «[[rot.state.connected]]», «[[rot.state.moving]]», «[[rot.state.off]]» или «[[rot.state.error]]». Точка рядом с заголовком красная, когда ротор выключен или не подключён, и зелёная, когда включён; наведите курсор, чтобы прочитать причину. При выключенном роторе роза не реагирует: настройка находится в [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]].",
  "t.ripejls4px": "Главная страница из блоков",
  "t.rjbsteciih": "Поля, все редактируемые: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] и [[lp.f.comment]]. Если значение неверно, появляется «Проверьте поле …», и QSO не сохраняется.",
  "t.rjklfgkwz1": "[[gen.screen]] · [[gen.escStop]]: флажок, по умолчанию включён. Клавиша Esc сразу прекращает передачу и выключает [[ctl.enable_tx]]; при двукратном нажатии подряд она также освобождает станцию для вызова. Работает на каждой странице; выключите, если иногда нажимаете Esc по ошибке.",
  "t.rjydkrp3wi": "[[sw.tab.colors]]",
  "t.rkde317uuf": "Маленькая кнопка рядом с шестерёнкой выносит страницу в отдельное окно, чтобы разместить его на втором экране; в отдельном окне этой кнопки нет, на телефоне тоже.",
  "t.rkvp7qwege": "[[digi.menu.edit]] › [[digi.mi.copyRx]]: копирует весь принятый текст в буфер обмена.",
  "t.rn94wdf0dy": "[[digi.tx.title]] · [[digi.mi.lock]]: если выключено (заводское), Вы передаёте на той же частоте, на которой принимаете; если включено, у передачи своя частота, и поле «[[digi.freq.tx]]» разблокируется. Используйте, чтобы отвечать немного в стороне от сигнала, который Вы слушаете (сплит). На рабочей странице при включённом Lock щелчок по водопаду перемещает передачу, а Ctrl+щелчок — приём.",
  "t.ro39od0c11": "Если сузить окно Aurora на ПК, заголовок страницы «Станция», панель водопада и заголовки блоков переносятся на несколько строк, а не обрезаются справа: расширьте окно, чтобы снова увидеть их в одну строку. На телефоне ничего не меняется.",
  "t.rs0asi1hut": "Цветная метка справа: «[[tag.new_dxcc]]», «[[tag.new_dxcc_band]]», «[[tag.new_zone]]», «[[tag.new_zone_band]]», «[[tag.new_itu]]», «[[tag.new_itu_band]]», «[[tag.new_grid]]», «[[tag.new_grid_band]]», «[[tag.new_px]]», «[[tag.new_px_band]]», «[[tag.new_call]]», «[[tag.new_call_band]]», «[[tag.worked_call]]» и «[[tag.auto]]». Они сообщают, чем эта станция особенная для Вашего журнала; цветная полоса слева в строке имеет тот же цвет. Цвет каждого типа меняется в [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Более светлый полосатый цвет означает «связь проведена, но не подтверждена» (если Вы включили эту опцию).",
  "t.rs67r0i0zb": "имя другого оператора",
  "t.rsti6ivck3": "Полная статья: «Исправление или удаление QSO»; «Окно исправления или удаления QSO».",
  "t.rv1mchckle": "По UDP QSO, отправленная в закрытый журнал, теряется, потому что подтверждения нет. Aurora может отложить её и отправить повторно, когда журнал снова откроется. У функции два поля: одно для вторичного UDP-сервера и по одному для каждого получателя в «[[int.title]]». Полное объяснение с шагами — в пункте «Журнал закрыт: QSO приходят позже».",
  "t.rvvu61wi6f": "Большая кнопка рядом с диапазоном, MHz и ▾ — это выпадающий список частот ([[band.freqs]]): щёлкните её, чтобы открыть. Для каждого диапазона он показывает частоты используемого режима: основную (цветная точка, обозначение «[[band.main]]») и дополнительные, более бледные; некоторые действуют только в одном регионе IARU (сокращение в верхнем индексе). Щелчок по частоте переводит радио на неё. Щелчок по названию диапазона переводит на его основную частоту. Строка диапазона, на котором Вы находитесь, подсвечена.",
  "t.rxpdygzsht": "Почти всегда дело в CAT или PTT: попробуйте «[[sw.testCat]]» и «[[sw.testPtt]]» внизу настроек. Если радио переходит на TX, но мощности нет, значит, нет звука на радио.",
  "t.ry0hr60z9r": "[[aud.input]] · [[aud.vol.in]] (в [[sw.tab.audio]]): тот же ползунок Rx, от 0 до 100 %, то есть громкость «Запись» выбранного устройства, такая же, как в звуковых настройках системы. Отправляется, когда Вы его отпускаете. Справа значение в процентах и, если AUTO включена, слово AUTO. В Linux это громкость записи системного микшера (PulseAudio или PipeWire).",
  "t.s0kfl562hk": "Станция вызывает Вас, пока Вы заняты: щёлкните правой кнопкой по её строке, и она встанет в очередь. В списке появится синяя точка с её номером.",
  "t.s1pvhn78w3": "по клавише + цифровой клавиатуры",
  "t.s2h1ztk9d1": "[[gen.screen]] · [[gen.showCountry]] и [[gen.showFlag]]: два флажка, по умолчанию включены. Первый пишет название страны DXCC рядом с каждым сообщением, второй добавляет маленький флаг. Выключите, чтобы дать тексту больше места.",
  "t.s6svkm86zw": "[[gen2.operation]] · [[gen2.txDelay]] (числовое поле, от 0 до 0,5 секунды, по умолчанию 0,2): минимальное время между включением PTT и началом звука. Увеличьте его (0,3 или 0,4), если трансивер или CAT медленно переходят на передачу и начало сообщений теряется; уменьшайте, только если уверены, что трансивер готов сразу.",
  "t.s7qa8b02if": "[[sw.sub.ft8]] · [[sw.sub.contest]]",
  "t.s86lig4osg": "Ваш локатор",
  "t.s8z214vch2": "[[snd.title]] · [[snd.voiceLang]]: голос может произносить оповещение и позывной (по фонетическому алфавиту) на языке Aurora («[[snd.voiceLang.ui]]», по умолчанию) или всегда по-английски («[[snd.voiceLang.en]]»). Относится к меню, где Вы выбираете «Голос».",
  "t.sdovh9xuek": "[[auto.b3]] · [[auto.attempts]] (числовое поле, от 1 до 10, по умолчанию 2) и [[auto.cooldown]] (от 0 до 120 минут, по умолчанию 15): после стольких попыток без QSO Aurora перестаёт вызывать эту станцию и ждёт время паузы, прежде чем вызвать её снова (на загруженном диапазоне станция, не ответившая сегодня, может ответить позже). 0 = без паузы.",
  "t.sdwvpcluri": "Поиск позывных (QRZ.com, HamQTH): [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.selrqzrho2": "Шкала над водопадом: если частота радио известна, она показывает реальные частоты в kHz (радио плюс звуковая нота, в USB), метку каждые 100 Hz и число каждый kHz; иначе — ноты в Hz, число каждые 500.",
  "t.shae7n3ti7": "Мощность в ваттах (как её реально отдаёт радио, например «50 W»): появляется, только если радио сообщает мощность; касание открывает − и +, которые меняют мощность сразу на 5%. Если радио не позволяет её менять, она остаётся только для чтения.",
  "t.si10133zlo": "Wait and Pounce: при выключенном [[ctl.enable_tx]] выберите в [[gen2.pounce]] ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]), на какой CQ отвечать, и включите [[ctl.pounce]]. В конце периода Aurora сама отвечает на выбранный CQ, пропуская станции, с которыми связь уже проведена.",
  "t.sjlgyygvcn": "Ползунок TX Lvl",
  "t.slnwecbqnd": "Внизу: сколько сообщений Вы видите из скольких имеется, кнопка «[[hist.more]]» для загрузки дополнительных строк и общее число сообщений и станций с датой первого из них.",
  "t.sojh71i9r5": "[[sdr.tci]] · [[cat.backend]] и [[sw.tab.audio]]: две строки только для чтения. Первая сообщает, что сейчас использует CAT; если это TCI, она показывает светодиод, состояние ([[cat.state.connected]]…) и частоту, считанную с SDR. Вторая показывает используемые звуковой вход и выход. Они позволяют с первого взгляда увидеть, всё ли работает через TCI.",
  "t.solo8q4ob2": "В [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] Вы выбираете, когда начинается декодирование FT8 и насколько глубоко декодеры ищут. Страница существует только с собственным движком Aurora. Параметры применяются со следующего периода, после [[sw.save]].",
  "t.soythi7erd": "QMAP · [[pref.showQmap]] (по умолчанию выключено): включает пункт QMAP в верхнем меню. QMAP прослушивает участок диапазона шириной до 90 kHz и декодирует все сигналы Q65 вместе: он нужен только при SDR, передающем поток I/Q (TCI), или с файлом WAV I/Q; с обычным трансивером оставьте выключенным. Рядом строка сообщает, какой источник I/Q выбран в QMAP.",
  "t.sqsn231a48": "[[fil.grp.rx]] · [[rxw.exclusive]]: флажок, по умолчанию выключен. Если включён, при открытом окне [[rxw.title]] сообщения, адресованные Вам, и сообщения станции QSO появляются только там, а не также в [[panel.all]]. Если выключен, они показываются в обоих списках.",
  "t.sr4g1qgw2r": "Вкладка «[[contest.training]]»: выберите контест, «[[contest.sim.pileup]]» ([[contest.sim.light]], [[contest.sim.medium]] или [[contest.sim.heavy]]) и «[[contest.sim.duration]]», затем «[[contest.sim.start]]»; «[[contest.sim.stop]]» останавливает. Ненастоящие позывные появляются как декодирования в контесте: двойной щелчок для ответа, RR73 для завершения. Радио не используется и в журнал ничего не пишется; в итогах показаны темп, дубли, неверные обмены и «[[contest.sim.nil]]», которых удалось избежать повторной отправкой RR73. Метка «[[contest.sim.badge]]» напоминает, что это тренировка.",
  "t.ssmqk2zyp1": "[[digi.mi.afc]]: приём следует за станцией, если она уходит по частоте. Включено по умолчанию; на одном шуме остаётся на месте.",
  "t.st1vwkk4g6": "Текст в PSK31, PSK63 и RTTY",
  "t.svf98j0j0w": "настраивает радиостанцию так, чтобы сигнал оказался на этой частоте в кГц",
  "t.sxepdxiwbv": "Работа в эфире",
  "t.sxg9a1vqhq": "[[wfs.digi.title]]: на этой вкладке есть и цвета водопада на страницах текстовых режимов (CW, PSK, RTTY...): [[wfs.palette]], [[wfs.gain]] и [[wfs.zero]]; они действуют только для этого водопада и не затрагивают водопад FT8. «[[wfs.digi.classic]]» с усилением и нулём 0 — как раньше. Если в CW сигнал не выделяется на фоне, попробуйте поднять усиление или выбрать другую палитру; «[[wfs.digi.reset]]» возвращает всё как было.",
  "t.sxxz15anfr": "Первый запуск: появляется полоса с «[[rep.notice]]», ссылкой «[[rep.notice.open]]» (ведёт на страницу «Поддержка») и кнопкой «[[rep.notice.ok]]», которая закрывает её навсегда. Не появляется, если Вы уже отключили и «[[rep.ask]]», и «[[rep.auto]]».",
  "t.syeo94yu6p": "Строка адреса: сообщает адрес и сетевую карту, использованные в QR-коде (виртуальные адаптеры, такие как WSL, Hyper-V, VirtualBox и VPN, исключаются); если у ПК нет адреса в домашней сети, Вы видите «[[net.noAddress]]»: проверьте кабель или Wi-Fi ПК. Внизу «[[net.tips]]»: если телефон не открывает страницу, выключите мобильные данные и VPN, избегайте «гостевой» сети или повторителей с «изоляцией клиентов», а на Android, если aurora.local не работает, используйте адрес с цифрами.",
  "t.szo7jtk9k4": "Ещё не отправленная часть остаётся доступной для правки: щёлкните внутри и исправляйте, удаляйте или добавляйте; уже отправленную часть изменить нельзя. Макрос, запущенный во время передачи, ставится в очередь.",
  "t.t0hqszd6n3": "Сердце UltraFOX — AQP-127 (Aurora Q-ary Polar), полярный код Aurora, реализация Тициано Кассоне IU3WJQ: 50 символов по 7 бит (47 сообщения и 3 контрольных) превращаются в 127 тонов. На приёме декодер взвешивает вероятности 128 тонов каждого символа и исправляет испорченные шумом и замираниями: он декодирует примерно до −16 dB в 2500 Hz, при этом в одном сигнале может быть до 9 станций.",
  "t.t14d56yhl0": "меняет режим (PSK31, PSK63, RTTY)",
  "t.t1hctlptxy": "[[digi.ms.receive]] · [[digi.mi.afc]] (по умолчанию включено): приёмник следует за сигналом, если его частота медленно дрейфует. Выключайте, только если он следует за чужим сигналом рядом с Вашим.",
  "t.t2149hi05u": "Объединение макросов режима с базовыми («[[digi.mi.macrosMerge]]») и возврат к макросам Aurora («[[digi.mi.macrosReset]]») выполняются из меню [[digi.menu.file]] страницы PSK · RTTY · CW, а не отсюда.",
  "t.t3gob4alw4": "Флажки: «[[dxmap.greyline]]» (линия дня и ночи), «[[dxmap.arcs]]» (линия от Вашей станции к каждой станции в эфире), «[[dxmap.heat]]» (тепловая карта тех, кто Вас принял, по данным PSK Reporter), «[[dxmap.links]]» (линия между двумя станциями, когда одна вызывает другую, золотая, если вызывают Вас), «[[dxmap.onlyHeardMe]]» (только линии к тем, кто Вас принял), «[[dxmap.callLabels]]» (позывные всегда подписаны; когда выключено, показываются при наведении), «[[dxmap.squares]]» (проведённые квадраты: жёлтый = проведена связь, зелёный = подтверждено).",
  "t.t3j5fcymtu": "«Update now»: если Aurora закрыта, он открывает её и ждёт (до минуты), пока она ответит; затем Aurora устанавливает новую версию (загружая её, если она ещё не загружена). Карточка остаётся открытой и показывает ход: полосу с процентами, MB, скоростью и оставшимся временем, а также шаги «Download › Check › Install › Restart». В конце Aurora закрывается и сама открывается снова.",
  "t.t3yynge1xt": "[[list.clear]] очищает окно сообщений.",
  "t.t3zex0hfwq": "Более быстрый FT8 и более устойчивая повторная передача",
  "t.t5azc63m68": "Для ротора, в «[[sat.ctl.title]]» при включённом «[[sat.ctl.rotor]]»: «[[sat.ctl.rotMinMove]]» (по умолчанию 2) — минимальная разница азимута или угла места, ниже которой ротор не получает новой команды, чтобы было меньше рывков и износа; «[[sat.ctl.rotOffset]]» (от −180 до 180) прибавляется к азимуту, отправляемому на ротор, чтобы скомпенсировать неточную установку ротора или севера.",
  "t.t5rtgudhia": "Часы ПК отклоняются на столько-то миллисекунд: жёлтое при превышении 4% периода (600 ms в FT8), красное при превышении 8%. «[[diag.fix]]» открывает [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].",
  "t.t630ybzkk5": "Сохраняет текущее QSO в журнал с данными на этот момент. Ставьте перед <CLEARQSO>: команды выполняются в том порядке, в каком вы их записали.",
  "t.t6tgl6g3es": "На некоторых страницах настроек есть ссылка на соответствующую статью; адрес «#/guida/название-статьи» открывает Справку сразу на этой статье.",
  "t.ta1s9otowr": "Карточка DXCC",
  "t.tcinq12ddr": "Используйте режим Fox, только если Вы действительно экспедиция и объявляете об этом: на обычном диапазоне он создаёт помехи.",
  "t.tdt8zms2dg": "[[sw.pg.radio]]: [[cat.grp.link]]",
  "t.thwpwnu8ge": "Для IC-820H есть также флажок «[[sat.uplink.civ]]» (выключен по умолчанию, вместо «[[sat.uplink.on]]»): сначала он сам выполняет проверку без записи частот, переключаясь на другой диапазон и обратно с контрольными чтениями; если проверка не удалась, он никогда ничего не записывает, и Доплер отслеживает только приём. Результат с прочитанными частотами показывается на странице [[nav.sat]] и в пакете поддержки.",
  "t.tijxj7nv9c": "«[[dxs.colors]]» · «[[dxs.resetColors]]» (кнопка вверху справа, неактивна, пока Вы не изменили цвет): удаляет все выбранные цвета и возвращает карточке цвета светлой или тёмной темы; диапазоны, строки и оформление остаются.",
  "t.tjjcon5pbl": "диапазон последней QSO с этим позывным",
  "t.tk3kme0bef": "В конце нажмите «[[contest.export]]»: Cabrillo 3.0, EDI или ADIF, как требуют правила, с проверкой перед отправкой и ссылкой на страницу организатора. Затем «[[contest.end]]» возвращает прежние настройки.",
  "t.tl0lo3apg0": "[[sstv.set.grpTx]] · [[sstv.set.fskId]] (по умолчанию включено): после каждого изображения посылает позывной станции в FSK (около 2 секунд), так что тот, кто принимает программой SSTV, которая его читает, видит его рядом с изображением. Выключите, если не хотите удлинять передачу.",
  "t.tl2gkbtvrm": "Появляется под QR-кодом в [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] › [[acc.pair]], только пока QR-код открыт, и обновляется сама каждые 15 секунд. Сообщает, что ПК знает о своей сети, чтобы тот, у кого не получается подключиться, сразу видел почему. Строки только для чтения; единственная кнопка — «[[net.allow]]».",
  "t.tl3j6nutkg": "«[[dxs.rows]]» · FT8, FT4, DIG: строки (режимы) сетки. FT8 и FT4 — разные режимы, и они включены; DIG объединяет остальные цифровые режимы (JT65, JT9, RTTY, PSK…) и выключен. Хотя бы одна строка должна остаться включённой: последнюю выключить нельзя.",
  "t.tmggavdxxu": "Нажмите «[[exp.edit.save]]»: строка обновится, файл aurora_log.adi будет исправлен, а «работал ранее» (метки декодирования, карточка DXCC, карта) пересчитается. Если какое-то значение неверно, окно укажет, какое, и не сохранит. «[[exp.edit.cancel]]» или Esc закрывают окно без изменений.",
  "t.to46xwcz90": "Почти все проблемы с подключением вызваны несколькими причинами. Проверьте их по порядку, прежде чем искать в другом месте.",
  "t.to8aiafaju": "громкость звукового входа в процентах (без числа открывает настройки звука)",
  "t.tomzpso2ew": "[[digi.ms.receive]] · [[digi.mi.squelch]] (по умолчанию выключено): включите, чтобы декодер молчал, когда сигнал ниже порога, и на шуме не появлялись случайные символы. Порог каждого режима задаётся в блоке «[[sw.digi.perMode]]».",
  "t.tp0fvwawlw": "Кнопка «Auto» в верхней панели включает и выключает автоматизацию, не открывая меню. В первый раз, если она в пробном режиме, спрашивается, перейти ли в боевой режим: при ответе «Да» она сразу стартует в боевом режиме, а затем один щелчок включает и выключает её.",
  "t.tqlhorkmi7": "Станция, которая так и не присылает финальный 73: Aurora повторяет RR73 не более того числа раз, которое задано в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], затем останавливается.",
  "t.tqzfvfjvyt": "При включённом [[ctl.enable_tx]] или во время передачи радиостанция не переключается: она остаётся там, где Вы работаете.",
  "t.tr4777movl": "Настройки: Режимы",
  "t.ts4pswtt1z": "Споты в участках цифровых видов связи плана диапазонов IARU Регион 1 без других признаков теперь показывают «DIGI» (и фильтр «Digi» их находит). Раньше режим оставался пустым. Комментарий и известные рабочие частоты (FT8, FT4, WSPR…) по-прежнему главнее.",
  "t.tsieh1ipmc": "Радио и звук",
  "t.tt94z7c9g2": "Внизу, в поле «Modo ADIF», введите в «Descrizione» (описание) Aurora, а в «Percorso file ADIF» (путь к ADIF-файлу) C:\\Users\\<your user>\\AppData\\Roaming\\Aurora\\aurora_log.adi (или найдите файл через лупу), затем нажмите зелёный +.",
  "t.tv84vqu0gj": "Расстояние и азимут показываются и у сообщений без локатора, если эта станция передавала его раньше.",
  "t.twxpwv4pau": "Если ПК медленно декодирует",
  "t.tx073tffry": "У окон фиксированные размеры; меняются только порядок и ширина соседних окон.",
  "t.txgacev1w4": "[[nav.log]]: страница со всеми Вашими QSO, поиском, экспортом и исправлением (см. «Журнал: поиск, выбор и экспорт»).",
  "t.txudczar9o": "ALC при передаче, по желанию",
  "t.ty0dtyxfkp": "[[rot.set.grp.link]] · [[rot.set.enabled]] (по умолчанию выключено): с галочкой Aurora подключается к ротору и остаётся подключённой и при следующих запусках; без неё подключения нет. Сохраняется сразу вместе с другими уже введёнными параметрами. Включайте только после выбора модели, порта и скорости.",
  "t.tyz9d8ka7k": "Немедленная остановка передачи.",
  "t.tzc30vqhc0": "Разделитель между двумя окнами можно перетаскивать вверх или вниз: соотношение (от 10% до 90%) запоминается.",
  "t.tzq6ug4abb": "Позывной, взятый из приёма: <GRABCALL> берёт последний принятый в окне RX позывной и помещает его в QSO, так что <CALL> того же макроса сразу его использует. Если Вы принимаете «IU3ABC DE K1ABC», макрос <GRABCALL><TX><CALL> TU 599 <NRS><RX> отправляет «K1ABC TU 599 001».",
  "t.u118ppvuwa": "«Удалить выбранные (n)» (с числом выбранных QSO) удаляет выбранные QSO из журнала Aurora и ADIF-файла после подтверждения; «[[exp.clearLog]]» удаляет все QSO, чтобы начать с пустого журнала (прежний ADIF-файл откладывается с датой), после подтверждения. Восстановить из программы нельзя.",
  "t.u21xzjelyo": "При включённом доплере можно настроиться на станцию, покрутив ручку радио (например, RS-44 в SSB): Aurora считывает новую частоту, принимает её как выбранную частоту приёма, а частота передачи следует за ней с тем же смещением. Aurora замечает это через пару секунд, когда ручка остановилась. Большие скачки (более 80 кГц, например смена диапазона) не отслеживаются. Флажок «[[sat.knob.on]]» включён по умолчанию, его можно снять.",
  "t.u276jdcbxj": "В контестах, где после номера требуется третий элемент (клуб или секция, штат или провинция), в строке ввода после «[[ssbc.serialRcvd]]» появляется отдельное поле со своим названием («[[ssbc.exLabel.generic]]»; для UBA «Club (UBA section)», для ARRL «State / province»). Оно показывается только тогда, когда это требуют правила контеста и введённый позывной должен его давать (в UBA — только бельгийские станции; DX-станции передают лишь RST и номер). Впишите его заглавными буквами и переходите дальше клавишей Tab или Enter: QSO сохраняется как номер, за которым следует секция, например «003 ACC». Если и Вашей станции нужно его передавать, впишите его в настройках контеста, в поле «[[ctest.f.mySect]]»: оно передаётся после Вашего номера (например, «001 ACC»).",
  "t.u2p37w0a5m": "«de» на языке другой станции (по префиксу)",
  "t.u54zk4t2ck": "Чтобы отключить всё: снимите «[[rep.ask]]», «[[rep.auto]]» и «[[rep.active]]» (и, если хотите, «[[upd.enabled]]»). С этого момента ничего не покидает ПК, кроме того, что Вы отправляете вручную.",
  "t.u5hzt9kzv3": "подаёт звуковой сигнал",
  "t.u5sfadmpw5": "[[lay.status]] · [[upd.lastCheck]]: дата и время последней проверки или «[[upd.never]]». Только чтение.",
  "t.u7c103azlj": "при закрытии страницы (переход на другую страницу или закрытие Aurora)",
  "t.u8ebunc1lm": "В правом нижнем углу каждой кнопки мелко показана её клавиша: «F1», «F2»… в первом ряду, «C-F1» (Ctrl), «S-F1» (Shift) и «CS-F1» (Ctrl+Shift) в остальных. Если Вы нажимаете макрос, пока другой (или тот же) передаёт, предыдущий останавливается, а новый начинается заново с начала, без сброса PTT: уже отправленный текст остаётся, ещё не отправленный отбрасывается. Это действует при каждом нажатии: побеждает всегда последнее, и только его команды «<RX>» и «<RXANDCLEAR>» решают, когда вернуться на приём и очистить окно. Esc останавливает всё.",
  "t.u93mri8s1a": "«[[wefax.set.autoIoc]]» (по умолчанию включено) читает тон начала: 300 Гц означает IOC 576, 675 Гц — IOC 288. Если это не выбранный IOC, Aurora переключает его до фазировки, не меняя настройку, а число в «[[wefax.ro.ioc]]» это показывает.",
  "t.u99idmjpn0": "Исправление остаётся в Aurora: во внешние журналы ничего не отправляется повторно (программы, подключённые по UDP, Wavelog, ClubLog, QRZ, LoTW), там QSO нужно исправить или удалить вручную. Если панель [[panel.log]] показывает журнал Log4OM2, эти QSO доступны только для чтения и исправляются в Log4OM2. Работает только с ПК или из домашней сети.",
  "t.uahjb4fsdh": "[[snd.title]]",
  "t.uaqkc1zzm0": "Как убрать звуки или изменить цвета оповещений?",
  "t.ub3g29st9p": "Станции, которые Вы ищете: добавьте их в [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]].",
  "t.ufxay0d5rb": "Вы готовите изображение, как в небольшой графической программе: фоновое фото, а поверх него тексты и фигуры («слои»), затем передаёте. Слева — предпросмотр с тем же разрешением, которое получит другая станция; справа — панель с вкладками ([[sstv.tab.photo]], [[sstv.tab.adjust]], [[sstv.layers]], [[sstv.tpl.title]]), по одной за раз, высотой с предпросмотр. Выбранная вкладка запоминается.",
  "t.ug1x8iopdf": "Журнал: поиск, выбор и экспорт",
  "t.uio7mjrzv4": "[[cat.powerOn]] и [[cat.powerOff]] (по умолчанию выключены; появляются при Hamlib, TCI и FT-991(A) Link; при Cat4OM есть только «[[cat.powerOff]]»): первый посылает трансиверу команду CAT включения питания при подключении Aurora (не все трансиверы её принимают: некоторые не слушают CAT в выключенном состоянии, например Yaesu FT-2000); второй выключает трансивер при закрытии Aurora, после выключения PTT (не при смене трансивера). У SDR по TCI они включают и выключают SDR.",
  "t.ujctmdn3xo": "S-метр и мощность на индикаторе",
  "t.uk7mnotwwu": "Затем звук и радио: пункты «Звуковая карта» и «Подключение радио (CAT)» в группе «Радио и звук».",
  "t.ukyslnubwz": "[[digi.edit.title]] · [[digi.edit.text]]: сценарий макроса, свободный текст с командами в угловых скобках. Вводите его вручную или вставляйте команды из списка справа.",
  "t.um2oor49sk": "Нажмите [[sw.save]], затем в шапке страницы [[auto.turnOn]]. CQ уходит только в [[auto.modeLive]], только когда передача свободна и внутри окна времени, если оно задано. В [[auto.modeDry]] журнал записывает, когда она сделала бы это, без передачи.",
  "t.unet35nmp7": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]: [[cat.backend]] TCI, адрес 127.0.0.1:40001, затем [[cat.connect]].",
  "t.uo8tm38is9": "[[auto.b3]] · строка-примечание о пределах, заданных на ПК (ответы подряд без QSO, ответы в сутки, выключение без подключённых устройств): её нельзя изменить ни отсюда, ни с телефона, это последняя страховочная сетка, и она действует всегда, даже в пробном режиме.",
  "t.uobd3v7dl6": "последние две буквы позывного последнего QSO",
  "t.uoyx6m6h4f": "Работает с Hamlib, OmniRig, TCI и Cat4OM (если радиостанция заявляет сплит); не работает с FT-991(A) Link, который управляет только VFO A. Без CAT спот только настраивает частоту. Если сплит невозможен, радиостанция всё равно переходит на спот. После переподключения Hamlib DX-сплит устанавливается снова сам; с Cat4OM он выключается при закрытии, даже если Cat4OM был перезапущен.",
  "t.upzy42ggio": "У водопада и спектра есть собственные настройки с заводскими значениями. Изменения видны сразу и сохраняются после перезапуска.",
  "t.uqengvwhnm": "Как работают настройки",
  "t.urhdtygxyy": "[[sup.title]] · примечания под блоком: «[[sup.privacy]]» и, красным, причина, если пакет не создан. Пакет остаётся на Вашем ПК, пока Вы сами его не отправите.",
  "t.ux5ci7a0j3": "При ширине менее 768 px (телефон) страница Station превращается в компактный пульт дистанционного управления; на планшете в альбомной ориентации у неё два столбца. Он работает одинаково на сопряжённом телефоне и в узком окне на ПК. Как выполнить сопряжение, описано в разделе «Сопряжение телефона или планшета».",
  "t.uylg1zjyvb": "В BBLogger откройте «Configurazione interfaccia Wsjtx» (значок шестерёнки в «Fast QSO» или «Nuovo QSO»).",
  "t.v2cpuo4ip1": "SSTV: вкладка «[[sstv.view.tx]]» (редактор)",
  "t.v4ooe4ha9m": "Важно, куда Вы её поставите: в начале она очищает окно, и затем текст макроса попадает в чистое; после текста она его стирает. После <RX> очищает при возврате на приём.",
  "t.v61u3aw7y": "[[tab.wishlist]]",
  "t.v68amzrc7k": "Ваш позывной",
  "t.v739g46sn9": "[[fil.decode]] · [[dec.correlation]]: флажок, по умолчанию выключен. В JT65 сравнивает недекодированные сигналы со списком вероятных сообщений (QSO с DX и позывные, услышанные на диапазоне): находит более слабые сигналы, но может давать несколько ложных. Рядом с режимом есть кнопка «Deep».",
  "t.v7960hihgf": "При «[[rot.set.remote]]»: [[rot.set.host]] (заводское 127.0.0.1: компьютер, на котором работает rotctld, или его сетевой адрес, если это другой компьютер) и [[rot.set.tcpPort]] (заводское 4533, порт, на котором слушает rotctld).",
  "t.v7dkfamoxp": "Аудиовход перегружен (красный), молчит (жёлтый) или слабый (голубой): исправьте громкость записи Windows, кабель или выбранное устройство; рядом с ползунком «Rx» есть также «[[rxl.auto]]», который регулирует её сам (см. «Уровни Rx и TX Lvl»).",
  "t.v7rdvq58p": "[[seq2.switches]] · [[seq2.answerB4]]: отвечает также станциям, с которыми связь уже была (Answer B4); если выключено, станции, уже находящиеся в журнале, пропускаются. Тот же переключатель, что и на панели QSO («[[ctl.answer_b4]]»).",
  "t.v8jtcyid9a": "Свободный текст сообщений FT8 и FT4 — это всего 13 символов, в верхнем регистре, из букв, цифр и нескольких знаков: более длинный макрос обрезается до 13.",
  "t.vc90to0r5k": "Aurora работает в Windows; установите её один раз, дальше она обновляется сама.",
  "t.vgea1q9fkz": "Сканирование и память",
  "t.vgrgqymn0x": "Звук только одного события: выберите «[[snd.none]]» в его меню. Меню находятся в блоке «[[snd.title]]» (события вроде «[[snd.ev.alert_my_call]]» или «[[snd.ev.qso_logged]]») и, для типов сообщений, на странице «[[sw.tab.colors]]». «[[snd.clear]]» убирает звук у всех событий; «[[snd.stop]]» останавливает воспроизводимый сейчас.",
  "t.vhp7ouj18c": "[[sat.ctl.title]] · [[sat.ctl.rotor]] (по умолчанию выключено): поворотное устройство следует за азимутом и углом места выбранного спутника. Включайте, только если поворотное устройство настроено и подключено.",
  "t.vhsikb8wxe": "[[cat.profile.load]]: подставляет выбранный профиль в настройки трансивера, ОТКЛЮЧАЕТ трансивер и НЕ подключает его снова: Вы нажимаете [[cat.connect]] на странице [[sw.pg.radio]] (или «[[sw.testCat]]»). Остаётся недоступной, пока Вы не выберете профиль.",
  "t.vjt2eh9zq0": "[[agent.popup]] · [[agent.quiet]] с «[[agent.quietFrom]]» и «[[agent.quietTo]]»: флажок (по умолчанию выключен) и два времени (по умолчанию 22:00 и 07:00; введите или выберите). Два времени становятся активными, только когда флажок включён. В этом интервале всплывающие карточки не появляются; обновления появляются в любом случае. Во время передачи всплывающие карточки не появляются никогда, с этим флажком или без него. Когда: включите на ночь.",
  "t.vm1qzmw6qb": "Вверху справа, прямо перед шестерёнкой (на телефоне в заголовке), есть точка: индикатор состояния. Зелёный означает, что всё хорошо. Он становится янтарным, если загрузка процессора Aurora остаётся выше 50 % не менее 10 секунд или декодирование занимает более 70 % периода; красным — при загрузке процессора выше 80 % в течение 10 секунд или когда декодирование не укладывается вовремя. Он также учитывает предупреждения о звуке, CAT и часах. Когда он становится янтарным или красным, он плавно мигает несколько секунд.",
  "t.vm3igq4gqs": "Если карты приходят сдвинутыми вбок, «[[wefax.start.button]]» выравнивает их: щёлкните по настоящему левому краю карты, и начало строки фиксируется для принимаемой карты и следующих; для сохранённой карты создаётся сдвинутая копия. Aurora это запоминает.",
  "t.vnnczzmgj1": "[[sstv.set.grpFolders]] · [[sstv.set.txFolder]]: необязательно (по умолчанию пусто). Если Вы её укажете, в композиторе фотографии для передачи выбираются из этой папки. Изменить её можно только с ПК Aurora.",
  "t.vqs7ecwxal": "Открывается двойным щелчком по QSO (на странице [[nav.log]] и в панели [[panel.log]] Станции) или кнопкой «[[exp.edit.btn]]». Меняет только внутренний журнал Aurora и его ADIF-файл; признаки «уже проведено» пересчитываются. См. также «Исправление или удаление QSO».",
  "t.vrtbro4z4o": "Панель WEFAX растягивается на всю ширину окна и умещается в одну строку; меню станции имеет более крупный шрифт и выровнено по правому краю, рядом с кнопками ▲ ▼. Компактный дисплей радио теперь показывает и ALC (прочерк, если радио его не передаёт).",
  "t.vruk7679rv": "Звуковую частоту можно ввести вручную в поле «Hz» строки состояния или изменить командами [[digi.mi.seekLeft]] и [[digi.mi.seekRight]] и сканированием; панель сигналов и споты DX Cluster перемещают её за Вас.",
  "t.vt4q6pb3pm": "[[not2.grpTable]] · [[not2.colHighlight]]: флажок включает подсветку этого типа (цветные строки в списках). По умолчанию включено: новая страна, новый квадрат, новый позывной; выключено: зона CQ, зона ITU, префикс. Выключите новинки, которые Вам не важны, чтобы списки были менее пёстрыми.",
  "t.vu8wux1b1t": "Экспедиция объявляет об этом на своём сайте: частота (обычно в стороне от обычных частот FT8) и используется ли классический Fox/Hound или SuperFox.",
  "t.vulxq9zyqk": "Правила: под [Contest] добавьте раздел [Score], по одному правилу в строке. Пример для соревнования вроде CQ WW: «bands=80,40,20,15,10» (разрешённые диапазоны), «points=same_dxcc=1; same_cont=2; other_cont=3» (1 очко за ту же страну, 2 за тот же континент, 3 за остальных), «mult=cq/band; dxcc/band» (зоны CQ и страны, считаемые на каждом диапазоне). Есть также бонусы, веса диапазонов, районы позывных, префиксы WPX и принятый обмен: полный список находится в docs/contest-file.md. При сохранении неверное правило отклоняется с указанием причины.",
  "t.vw15nqasdm": "Защиты передачи",
  "t.vw1s1ntl59": "Esc: сразу останавливает передачу SSTV (как «[[sstv.tx.stop]]»), даже пока Вы печатаете в поле. Во всей Aurora при включённом «[[gen.escStop]]» (по умолчанию) Esc останавливает и другую передачу и выключает «[[ctl.enable_tx]]».",
  "t.vxxsljkzfh": "«[[digi.mi.scanProps]]» в меню [[digi.menu.options]] открывает эту страницу напрямую.",
  "t.vyaep5884v": "[[digi.edit.title]] · «[[digi.edit.insert]]»: вставляет выбранную команду в текст, в позицию курсора (или вместо выделенного текста). Активна только после выбора команды в списке.",
  "t.vyh6jjbfmr": "показывает (HIDE скрывает, TOGGLE переключает) часть Aurora: CONTROLBAR, LOGBAR, STATUSBAR, TUNINGBAR (водопад), CONTESTSTATS, QSOSTATISTIC, ROTOR, DXCLUSTER, WORLDMAP (карта), BEACONS, CALLBOOK, KIWISDR (веб-приёмник: уведомление)",
  "t.vzq2tkm2dj": "«[[cluster.add.heading]]» · «[[cluster.add.custom]]»: для собственного сервера или сервера, которого нет в списке: «[[cluster.add.name]]» (если оставить пустым, используется адрес), «[[cluster.add.host]]» (имя сервера или IP) и «[[cluster.add.port]]» (по умолчанию 7300, от 1 до 65535), затем «[[cluster.add.button]]» (неактивна, пока адрес и порт не станут верными). Если сервер уже есть, Вы видите «[[cluster.add.exists]]»; сверх восьми — «[[cluster.add.full]]». После добавления запускается проверка соединения.",
  "t.w1mhy18q7n": "[[sat.set.servers]] · добавленные Вами серверы: они появляются под списком с полным адресом и включённым флажком; снимите флажок, чтобы убрать их из списка. Поле «[[sat.set.addPlaceholder]]» и кнопка «[[sat.set.add]]» добавляют сервер: нужен адрес, начинающийся с http:// или https://, который выдаёт список TLE из трёх строк; кнопка остаётся неактивной, если адрес недействителен или уже есть. Не более 10 серверов.",
  "t.w2zzg97glq": "[[lay.status]] · [[upd.current]]: версия Aurora, работающая прямо сейчас. Только чтение.",
  "t.w3wmtr6jwf": "«[[int.resend]]»: «повторная отправка потерянных QSO» для этого получателя; включается только при активных «[[int.adif]]» или «[[int.n1mm]]» и относится к журналу на этом ПК (127.0.0.1). См. пункт «QSO, потерянные, пока журнал закрыт: где это включить».",
  "t.w49xjmoold": "[[sstv.set.grpRx]] · [[sstv.set.autoSync]] (по умолчанию включено): если VIS потерян (прослушивание включено, когда изображение уже началось, помехи), режим распознаётся по ритму строк синхронизации. После захвата режим сохраняется до конца изображения. Выключайте, только если он распознаёт неверные режимы.",
  "t.w4p8vnm5sc": "[[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]]: «[[gen.language]]» в первом блоке, «[[ap.size]]» в блоке «[[ap.text]]». Язык можно изменить и в нижней панели.",
  "t.w6a2nk0arv": "«повторите, пожалуйста, ваш позывной» на языке другой станции",
  "t.w9vm9t2xyg": "Пути записываются через «›», например [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]. eQSL, Wavelog, ClubLog, QRZ.com и LoTW находятся в «[[sw.fam.log]] › [[sw.sec.log]]»; GridTracker, Log4OM и N1MM — в «[[sw.fam.log]] › [[sw.pg.reporting]]»; споты PSK Reporter и DXSummit — в «[[sw.fam.log]] › [[tab.online]]».",
  "t.wa0bq75tx0": "[[cat.poll]] (только Hamlib): как часто Aurora считывает частоту и режим с трансивера, от 1 до 99 (заводское 2). На последовательном порту ниже 2 секунд значение не опускается, а во время передачи чтения становятся реже. Увеличьте его, если трансивер медленный или порт занят чтениями.",
  "t.wab9kudml1": "[[nav.settings]] › [[sw.sec.access]] › [[agent.tab]]. Агент — это небольшая программа рядом с часами Windows (в области уведомлений): она остаётся там даже при закрытой Aurora, открывает Aurora по щелчку и показывает уведомления в виде всплывающих карточек. Здесь Вы выбираете, какие уведомления хотите и как. Выбор сохраняется сразу (кнопки «Сохранить» нет), и агент перечитывает его каждую минуту. Уведомления об обновлениях Aurora появляются всегда, что бы Вы ни выбрали.",
  "t.wavjdfmn1y": "Контекстное меню браузера по правому щелчку больше не появляется: правый щелчок предназначен для очереди (копирование и вставка в текстовых полях по-прежнему работают).",
  "t.wb0ngjqn90": "RTTY: меняет местами mark и space (<INVON>, <INVOFF>)",
  "t.wbvl1kwrqa": "«[[acc.home]]» (aurora.local) остаётся прежним, даже если роутер меняет IP-адрес ПК: добавьте его в закладки на телефоне.",
  "t.wbvov5naym": "Это ложная тревога: Aurora — свободная программа, её код открыт на GitHub. Добавляйте исключения только для папок Aurora, а не для всего диска.",
  "t.wd3md5j3gw": "«[[ens.g.udp]]»: [[ens.k.UDPServer]] 127.0.0.1, [[ens.k.UDPServerPort]] 2237. Отправляет поток WSJT-X (Heartbeat, Status, Decode, QSO Logged); с «[[ens.k.EnableUDP1adifSending]]» также Logged ADIF. Предназначен для журналов, слушающих «WSJT-X/JTDX».",
  "t.wewllajgwo": "[[nav.dxmap]]",
  "t.wfm8m1m1sk": "«[[wft.navg]]»: сколько строк усредняется перед отрисовкой одной (от 1 до 50, по умолчанию 1): больше = медленнее и менее зашумлённый водопад.",
  "t.wg11pfp4lf": "В «[[wefax.hist.title]]», в рамке справа вверху, принятые карты остаются целой миниатюрой: щелчок открывает их крупно, «[[wefax.hist.download]]» сохраняет PNG, «[[wefax.hist.delete]]» удаляет их; элементы управления — под рамкой.",
  "t.wggr4cht8z": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › «[[int.title]]» › в получателе: «[[int.resend]]» (по умолчанию выключено; кнопка «+ [[int.p.adif]]» создаёт его уже включённым): та же функция для этого получателя. Она остаётся серой, пока Вы не включите «[[int.adif]]» или «[[int.n1mm]]», потому что относится только к этим двум форматам.",
  "t.wh5zgtsbsp": "Во время передачи (в том числе макроса) символы, уже ушедшие в эфир, становятся красными, с небольшой чертой в достигнутой точке, и, только если в меню [[digi.menu.view]] включено «[[digi.mi.echoRx]]» (по умолчанию выключено), в окне приёма эхо появляется в темпе передачи.",
  "t.whipkxgnni": "время UTC в заданном формате: %H %M %S часы минуты секунды, %d %m %Y %y день месяц год, %j день года, %b месяц (также для DATE, LOCALTIME, CTIME)",
  "t.wiad91ajw9": "Щёлкните ⧉: откроется небольшое меню с пунктами «[[win.new]]» (новое окно только с этой панелью), «[[win.dash]]» (панель из блоков, где собраны несколько панелей) и, если отдельное окно уже есть, «Рядом с: …», чтобы поместить панель рядом с панелями этого окна.",
  "t.wiajdi7uae": "Путь: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]. Здесь Вы выбираете, куда направляются QSO и состояние Aurora: журналы, утилиты вроде GridTracker, JTAlert или QLog, программы ведения журнала. Сверху вниз: три блока («[[ens.g.udp]]», «[[ens.g.adif]]», «[[ens.g.tcp]]»), «[[int.title]]» и, наконец, «[[ens.info]]». В каждом блоке есть индикатор, знак «?», «[[ens.test]]» и результат последней выгрузки, как в [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]]. Изменения сохраняются кнопкой «[[sw.save]]», действуют сразу (без перезапуска) и вносятся только с домашнего ПК.",
  "t.wiu4ijft3s": "В RTTY набор символов по умолчанию ([[digi.rtty.cs.ita2]]) содержит только заглавные буквы: включите [[digi.mi.capsOnly]], чтобы сразу видеть, как уйдёт текст.",
  "t.wjjjx0hcd0": "начинает сохранять принятый текст; <RXLOG STOP> записывает его в файл .txt",
  "t.wlxcvt5ij8": "[[seq2.switches]] · [[seq2.skipTx1]]: при ответе на CQ начинает с Tx2 вместо Tx1 (пропускает сообщение с двумя позывными и без рапорта). Тот же переключатель, что и на панели QSO («[[ctl.skip_tx1]]»).",
  "t.wm8s2fob95": "Строка сети: с зелёной галочкой сообщает, к какой сети Wi-Fi подключён ПК (телефон должен быть в той же, не в «гостевой»); со знаком «i» сообщает, что ПК подключён кабелем и телефон должен использовать Wi-Fi того же маршрутизатора.",
  "t.wmpuyibhzb": "Чтобы рапорт в dB или расстояние тоже попали в журнал: отметьте «[[ens.k.dBtoComments]]» и «[[ens.k.distanceToComments]]»; они окажутся в комментарии к QSO.",
  "t.wotqsh389v": "[[not2.grpTable]] · строка [[not2.n.worked]], флажок «[[not2.worked]]»: даёт позывным, уже имеющимся в Вашем журнале, собственный цвет (по умолчанию выключено: они только зачёркиваются). Существует, только если включена хотя бы одна подсветка «нового»: станция, с которой не работали, никогда не бывает «уже отработанной». Как они отображаются, решает блок «[[not2.grpWorked]]».",
  "t.wpz4mhb6f6": "Что Вы видите на странице и как рисуются текст и водопад. Каждый пункт — это отметка и меняется сразу; значения по умолчанию указаны в скобках. Выбор сохраняется на этом компьютере.",
  "t.wqa80zckq1": "показывает, была ли уже связь с этим позывным и когда",
  "t.wtknyg9z8d": "Aurora отправляет QSO и состояние в журналы по UDP. Всё находится в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]].",
  "t.wufx184hm5": "Автоматические ответы",
  "t.wurfvc76w8": "Если передача закрыта (Aurora запущена с AURORA_ALLOW_TX=0), четыре переключателя, заставляющие передавать, серые, и строка сообщает об этом: открыть её можно только с ПК, при запуске. [[ctl.pounce]] взводится только при выключенном [[ctl.enable_tx]].",
  "t.wyzm9kahxf": "Если карточка не показывает «новая DXCC», как Вы ожидаете, проверьте, что Ваша история есть в журнале: импортируйте её в [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.files]] или укажите базу данных Log4OM в [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]].",
  "t.wzcp6inqen": "Настройки открываются только с ПК, на котором работает Aurora (в окне программы или с localhost), а не с другого устройства, подключённого по IP-адресу: на телефоне, планшете или в браузере другого компьютера пункт «[[nav.settings]]» в меню не появляется, и настройки не открываются.",
  "t.x0aw95149m": "Встроенные контесты: даты проведения, рабочие часы, начальный номер, автоувеличение и макросы можно изменить и сохранить и для встроенного контеста; [[ctest.ro.reset]] возвращает значения из папки контеста. Правила подсчёта очков остаются только для чтения (чтобы их изменить, скопируйте контест в свою папку). Клавиши макросов стали выше на 6 пунктов.",
  "t.x0priuos7h": "Щелчок по миниатюре (вне режима выбора) открывает большое изображение. Стрелками клавиатуры ← и → или кнопками по бокам ([[sstv.img.prev]] и [[sstv.img.next]]) Вы переходите к предыдущему и следующему из той же ленты; Esc или «[[sstv.img.close]]» закрывают.",
  "t.x0r293xyni": "Если Вы изменили адрес в меню трансивера (пункт CI-V Address), впишите здесь то же число, переведённое в десятичный вид: цифра шестнадцатков × 16 + последняя цифра. Примеры: 94h = 9×16 + 4 = 148; 88h (IC-7100) = 8×16 + 8 = 136; A4h = 10×16 + 4 = 164 (A = 10, B = 11, C = 12, D = 13, E = 14, F = 15).",
  "t.x2u3fbtt5y": "[[acc.home]] · [[acc.home]]: постоянное имя, которое Aurora объявляет в домашней сети (например, aurora.local). Введите его в браузере телефона: оно остаётся тем же, даже если маршрутизатор меняет IP ПК, так что добавьте его в закладки. Если вместо этого Вы читаете «[[acc.noHome]]», Aurora слушает только на этом ПК или сеть не позволяет объявление: используйте цифровой адрес, показанный с QR-кодом. Редактировать нельзя.",
  "t.x59ea9j2s5": "[[cat.apply]] (и сообщение рядом с ней): сохраняет настройки и, если трансивер подключён, переподключает его с новыми значениями. Обычно она не нужна: если значения допустимы, они применяются сами через мгновение и при выходе со страницы; она остаётся недоступной, пока какое-то значение неверно («[[cat.invalid]]»). «[[cat.dirty]]» означает, что есть изменение, ещё не применённое.",
  "t.x78j22hkr7": "символ табуляции",
  "t.x7cf6oray9": "Вкладки WEFAX, SSTV, Распространение и Статистика: одно окно",
  "t.x80rhae3xv": "«[[dec.slowPc.auto]]» (по умолчанию): включается само после 3 периодов из 10 с загрузкой свыше 70% времени, 3 потерянных звуковых блоков за 10 минут или при 2 процессорах и менее; выключается после 20 спокойных периодов.",
  "t.xa6p96oohb": "Icom: та же скорость, что в радио (рекомендуется 115200), и в радио для CI-V USB Port выберите «Unlink from [REMOTE]».",
  "t.xa9tmntagg": "Откройте [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]].",
  "t.xayicrb3pe": "Сигнал SSTV читается правильно, только если его частоты попадают туда, где их ожидает Aurora: синхро на 1200 Hz, чёрный на 1500, белый на 2300. Если радио немного сбито, изображение получается с неверными цветами либо слишком светлым или тёмным. Панель настройки под спектром служит для того, чтобы это увидеть и исправить.",
  "t.xcz3p79zjx": "Aurora сама проверяет новые версии и предлагает их. Установщик закрывает Aurora и снова открывает её. На Mac Aurora сама заменяет Aurora.app и перезапускается: она должна находиться в «Программах» (или в вашей папке), а не запускаться из .dmg; при первом запуске после обновления macOS может запросить подтверждение, потому что Aurora не подписана Apple. После обновления заново подключите программы, которые используют радио через Aurora. Что изменилось, смотрите в [[nav.news]].",
  "t.xdjs7ci9eu": "Цвета: зелёный — в эфире, синий — предстоит, серый — закончилась, оранжевый — если Вы слышите её сейчас. Сколько дней хранить закончившиеся: «[[onl.dxpedDays]]».",
  "t.xdp0koaobn": "[[rd.title]] · [[rd.layout]]: как дисплей располагается вверху справа. «[[rd.layout.single]]» — одна панель с крупным VFO A и VFO B рядом; «[[rd.layout.pair]]» — два равных блока рядом. С панелями FT-2000 и IC-7610 выбор недоступен (панель сама занимает всё): выберите другой стиль, чтобы выбрать его.",
  "t.xf6hx1lvkr": "[[digi.mi.underlineSent]] (вкл.): подчёркивает переданные строки в окне приёма; видно только при включённом [[digi.mi.echoRx]].",
  "t.xgwzlec8t": "Загрузка на WSPRnet: в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.wspr]], блок [[ens.g.wsprnet]], включите [[ens.k.WSPRnetUpload]] и нажмите [[sw.save]]. После каждого периода WSPR или FST4W Aurora отправляет на wsprnet.org принятые сигналы (или, если их нет, состояние Вашей станции) в течение 20 s после декодирования.",
  "t.xifaddr6rq": "«[[digi.ms.title]]» · [[digi.tx.title]]: [[digi.mi.lock]] (выкл., передача следует за приёмом), «[[digi.freq.tx]]» (серое, пока Lock выключен), в CW ползунок скорости (от 5 до 60 WPM, по умолчанию 20), в RTTY сдвиг и скорость, и [[digi.autoReceive]] (по умолчанию выключено: при включённой отметке приём начинается при открытии Aurora).",
  "t.xke4x53y7u": "[[phone.band]] и [[phone.mode]]: два выпадающих списка для смены диапазона и режима. Они серые, если радио не управляется по CAT (режим FT8/FT4 можно менять и без радио). Если Вы передаёте, Aurora запрашивает подтверждение («You are transmitting: change band…?» или «…switch to…?», с выбранным диапазоном или режимом).",
  "t.xkjjp5vnbr": "Какие сочетания клавиш в текстовых режимах и SSTV?",
  "t.xl3gjj29bl": "«[[contest.decodes]]» (или «[[contest.decodes.time]]»): декодирования последних периодов. Столбцы: «[[contest.col.utc]]», «[[contest.col.msg]]», «[[contest.col.country]]», «[[contest.col.new]]» (что засчитывается Вам) и «[[contest.col.value]]»; заголовки можно перемещать и расширять перетаскиванием. Двойной щелчок по строке: Вы вызываете эту станцию (если это дубль, Aurora сначала запрашивает подтверждение); звезда ★ — рекомендуемая станция. Строки: зачёркнута = дубль, жёлтая = «[[contest.nonContest]]», «[[contest.outOfRules]]» = вне правил.",
  "t.xne2nmith2": "«[[ens.g.udp]]» · «[[ens.k.EnableUDP1adifSending]]» (по умолчанию включено): для каждой записанной QSO дополнительно отправляет запись ADIF на этот сервер (сообщение «Logged ADIF»), чтобы внешний журнал сохранял её сам; выключите, если тот же журнал получает QSO другим способом (дубликаты). «[[ens.k.preventFalseUDPspots]]» (по умолчанию включено): не отправляет программам сообщения, подозреваемые в ложности; в FT8 и FT4 ничего не меняет (касается только маркера «?» в JT65 и JT9).",
  "t.xoq3nhycgu": "Телефон (или планшет) видит её при первом открытии адреса Aurora, пока не выполнено сопряжение. В домашней сети при включённом «[[acc.open]]» (по умолчанию) телефон входит сам: страница появляется, только если нужен код. Пока сопряжения нет, телефон проверяет снова каждые 3 секунды, а если Вы включите с ПК доступ без кода, он входит сам, ничего не нажимая.",
  "t.xq1acl8kg4": "[[digi.spot.de]]: Ваша станция, только для чтения (берётся из Вашего позывного в Настройках).",
  "t.xqfzypdtxt": "Каждая QSO отправляется только один раз: сразу, если журнал открыт, из очереди, если он был закрыт, и никогда дважды. Очередь сохраняется при закрытии Aurora, а QSO, пробывшая в очереди больше семи дней, отбрасывается. Если указан адрес другого ПК, узнать, открыт ли журнал, невозможно: QSO уходят сразу, как и раньше.",
  "t.xqudqe5t4t": "открывает окно приёма серии QTC (соревнование WAE) от станции из QSO",
  "t.xrm1jff9je": "В Автоматизации включите «[[auto.filterCallers]]»: даже при CQ, вызванном вручную, Aurora не отвечает станциям, скрытым фильтрами Band activity (например, «не мой континент») или исключённым в Автоматизации. «[[auto.contExcludeShort]]» рядом с континентами исключает их, а не оставляет только их.",
  "t.xs0n62xsr8": "[[nav.automation]]",
  "t.xvo6u7o0wm": "записывает принимаемый звук в файл WAV в папке записей (без имени: дата и время)",
  "t.xw2mdgu6r5": "[[gen2.operation]] · [[gen2.qsy]] (по умолчанию включено): позволяет менять частоту передачи во время передачи (трансивер и сообщение сразу следуют за ней). Если выключено, новое значение частоты передачи не принимается, пока идёт передача.",
  "t.xyyv82wl3p": "Звуковая частота: нота в Hz, на которой Вы слушаете (нулевые биения радио). Её можно ввести вручную, от 200 до 3500; Enter подтверждает, Esc отменяет. Это частота приёма (не радио).",
  "t.y0rcc8vh4w": "[[ca.clock]]: «[[ca.clock.ok]]», если время верное; при смещении около 4 % периода или больше появляются «!» и значение в миллисекундах, при смещении свыше примерно 8 % — «×» (декодирование сильно ухудшается). Если время ещё не измерено, сообщается «[[ca.clock.none]]». «[[diag.fix]]» ведёт на страницу часов.",
  "t.y17z1sapht": "[[not2.markers]] · [[not2.mark7373]]: отмечает 73 и RR73 между другими станциями, то есть тех, кто только что закончил QSO и свободен для вызова. Параметр движка, по умолчанию включён: применяется кнопкой «[[sw.save]]».",
  "t.y1gprkyrn9": "выравнивает частоту приёма по кратному этих Гц значению",
  "t.y2bkj4htoj": "Она закрывается сама по истечении времени, выбранного в «[[agent.seconds]]» (по умолчанию 10 секунд; от 3 до 60); тонкая полоса внизу показывает, сколько осталось. Если мышь над карточкой, она не закрывается. Крестик × вверху справа и кнопка «Close» закрывают её сразу.",
  "t.y4etzu7vvz": "[[sw.pg.digiRxTx]]",
  "t.y6wz3s9a56": "Звук для каждого события.",
  "t.y7hccjnbtj": "Введите пользователя, пароль или ключ и подтвердите клавишей Enter (или покиньте поле): они остаются в ожидании, пока Вы не нажмёте «[[sw.save]]» внизу; только после сохранения проверка этого блока запускается сама (или нажмите «[[ens.test]]»).",
  "t.y8wehmelmj": "[[cqp.title]] · [[cqp.only]] и [[cqp.hide]]: два текстовых поля с позывными или префиксами через запятую (JA* = все JA). Первое, если не пусто, перечисляет ТОЛЬКО эти станции (чтобы следить за активностью или экспедицией); второе никогда не перечисляет эти станции (те, что вызывают всё время и Вам не интересны). По умолчанию пусто.",
  "t.y97lypgbu0": "Настройте радио вручную на ту же частоту (ту, что показывает Aurora, например 7.074 MHz в FT8) в USB.",
  "t.yb7rqcogwb": "Как выбрать звуковую карту и правильный уровень?",
  "t.ybwmky91r1": "Данные берутся из внутреннего журнала Aurora (и из Log4OM2, если подключён) и из файла префиксов cty.dat; обновляются сами при каждом занесённом QSO. Если одного из двух не хватает, карточка сообщает «[[dxcc.unavailable]]».",
  "t.ye6nspusiu": "время UTC (ЧЧММ) последнего записанного QSO",
  "t.yebn9ov1hw": "[[set.add]] · кнопка [[set.reset]]: возвращает пять исходных макросов и отбрасывает те, что Вы добавили или удалили. Используйте, если список пришёл в беспорядок.",
  "t.yhuaxyp3sl": "Правила для станций: появляются только передающие станции (после CQ, DE или TU либо перед TEST и QRZ), а не те, что только упомянуты. На одной частоте побеждает последняя передающая станция: предыдущая теряет метку через 10 секунд и покидает список через 60; станция, которая больше не слышна, покидает список через 3 минуты. Смена диапазона или большой скачок радио очищает список сам; при небольших сдвигах (примерно до 3,5 kHz) он остаётся, и станции отслеживаются; кнопка «[[radar.clear]]» очищает его вручную.",
  "t.yienm0mp54": "[[not2.grpAlerts]] · [[not2.muteTx]]: во время передачи оповещения молчат (кроме звука Вашего собственного передаваемого сообщения). По умолчанию включено; в основном полезно, если звук ПК попадает и в трансивер. Выключайте, только если звуки идут на отдельную колонку.",
  "t.yiyykltm2m": "ждёт указанное число миллисекунд перед следующей командой CAT",
  "t.ymgea2bovd": "Сообщения появляются под кнопкой: «[[pair.short]]», «[[pair.badCode]]», «[[pair.expired]]», «[[pair.badName]]» или «Too many attempts» с оставшимися секундами (в это время повторить нельзя).",
  "t.yn0v7wunz8": "[[snd.title]] · меню «[[snd.pick]]» (одинаковое в каждой строке этой страницы и в цветах): «[[snd.none]]», голос, группа «[[snd.myFiles]]» с Вашими файлами и пункт «[[snd.addFile]]», затем звуки Aurora по категориям. Ваш собственный файл WAV, MP3 или OGG может быть не более 5 МБ (иначе появляется «[[snd.fileFail]]») и остаётся в списке для каждого оповещения. Кнопка ▶ («[[snd.try]]») воспроизводит Ваш выбор; × рядом с ней, показываемый только для Вашего файла, убирает его из звуков. Выбор звука также включает оповещение этой функции.",
  "t.yniuia5lyx": "служебные сигналы: один знак в CW, буквы в других режимах",
  "t.ynkrevlin0": "Отправка спота: окно «[[digi.spot.title]]»",
  "t.yoo5eazqd6": "BPF в строке состояния (рядом с AFC, также в меню [[digi.menu.options]]) включает полосовой фильтр вокруг частоты приёма: PSK31 около 94 Hz, PSK63 около 188 Hz, RTTY — сдвиг плюс удвоенная скорость в baud, CW 80 Hz. Он следует за выбранной Вами частотой и убирает близкие станции только для декодера.",
  "t.ypdch92rlq": "«[[int.host]]»: IP-адрес программы: 127.0.0.1 (или localhost), если она работает на этом ПК, IP другого компьютера, если он в сети, адрес от 224.0.0.0 до 239.255.255.255, если это группа multicast (тогда включите и «[[int.multicast]]»). Адрес multicast при выключенном поле — ошибка, и наоборот.",
  "t.ypksqhuio7": "Автоматическое масштабирование карты: в панели “[[sat.alert.title]]” параметр “[[sat.alert.zoom]]” определяет, что делает карта, когда спутник входит в вашу зону (AOS): “[[sat.alert.zoom.off]]” не трогает карту; “[[sat.alert.zoom.area]]” показывает зелёный круг, из которого виден спутник; “[[sat.alert.zoom.both]]” (по умолчанию) показывает вашу станцию и спутник вместе; “[[sat.alert.zoom.follow]]” центрирует карту на спутнике и следует за ним. На LOS карта плавно возвращается ко всему миру. Если вы масштабируете или сдвигаете карту вручную, автоматическое масштабирование приостанавливается до следующего AOS. Автоматическое масштабирование доходит максимум до 3x. Вручную: колесо мыши (или щипок двумя пальцами) на карте, кнопки “+” и “−” и “[[sat.map.zoomFit]]” вверху справа; перетаскивание увеличенной карты сдвигает её и по вертикали; двойной щелчок возвращает всю карту.",
  "t.yprahqpj9o": "Как обновить Aurora и можно ли отложить обновление?",
  "t.yqo9brue7r": "[[auto.b1]] · [[auto.newMode]], [[kind.new_state]], [[kind.new_state_band]] и [[tab.wishlist]] (ещё четыре флажка, по умолчанию выключены): [[auto.newMode]] отвечает стране, с которой никогда не было связи в используемом режиме (вычисляется по Вашему журналу); [[kind.new_state]] и [[kind.new_state_band]] отвечают американским станциям штата, с которым никогда не было связи или не было на этом диапазоне (штат берётся из поиска на QRZ.com/HamQTH и из журналов); [[tab.wishlist]] отвечает станциям, префиксам, странам и квадратам из Вашего списка желаемого. Действуют все ограничения: минимальный сигнал, попытки, пределы, исключения.",
  "t.ysaoklqcur": "Включите «[[clock.atStart]]»: при каждом запуске Aurora исправляет время сама. Чтобы менять время ПК, Aurora должна быть запущена от имени администратора.",
  "t.yskrwfct7f": "Чаще всего это происходит с Windows Defender и Avast: они ошибочно считают опасными программы Hamlib (rigctld, rotctld и библиотеку libhamlib) и малоиспользуемые программы и помещают их в карантин или удаляют. Симптомы: радио не подключается и сообщает, что нет rigctld, окно Aurora остаётся белым, нет списка стран (cty.dat) и сущности DXCC не распознаются. Aurora замечает это при запуске и показывает вверху полосу с названием антивируса и списком отсутствующих файлов, с кнопками «[[files.missing.guide]]» и «[[files.missing.dismiss]]» (и «[[cat.restore]]», если нет Hamlib).",
  "t.ysn586xpkp": "Ваш QTH",
  "t.ysu5hbxtd5": "[[digi.edit.color]]: цвет кнопки.",
  "t.ysyrvvknyu": "Под позывным строка «[[dxp.onAir]]» сообщает, что кластер только что отметил её спотом, с частотой, режимом и тем, сколько минут назад; дважды щёлкните частоту, чтобы перевести радио туда. «[[dxp.heardByMe]]» = Вы декодировали её сами: частота, режим, сигнал и время.",
  "t.yt8ik8qcp": "Для доплера подключите радиостанцию через Hamlib ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]), выберите «[[sat.ctl.transponder]]» и включите «[[sat.ctl.doppler]]»: выше минимальной элевации Aurora ставит приём на основной VFO, а передачу на VFO сплита, с коррекцией каждую секунду. С линейным транспондером перемещайте «[[sat.ctl.downlink]]»: линия вверх следует сама, даже если транспондер инвертирующий, как RS-44.",
  "t.yuclonwjzw": "[[lay.options]] · [[set.reset]]: кнопка; возвращает к заводским значениям только фильтры этой страницы (но не другие настройки). Нажмите её, если Вы перестали понимать, почему сообщение не появляется.",
  "t.yuwksen2ui": "[[sw.digi.perMode]] · CW, ползунок порога шумоподавителя (S/N от -30 до 20 dB, заводское -15): измеряет отношение сигнал/шум вокруг тона. На одном шуме оно держится около -25 dB; ниже -16 dB ничего не печатается, даже при выключенном шумоподавителе. Увеличьте, если на шуме появляются символы. Учитывается только при включённом «[[digi.mi.squelch]]».",
  "t.yvmtsq2ndm": "В «[[fil.calls]]» впишите позывные для скрытия; в «[[fil.showOnly]]» — единственные, которые нужно видеть. JA* соответствует всем позывным, начинающимся с JA.",
  "t.ywerzvmg0g": "Те же настройки контеста (активность, обмен, категория, данные Cabrillo) находятся и в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]], с раскрывающимся списком для выбора контеста; для контестов, допускающих MSK144 или Q65, они находятся в [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › [[sw.pg.contest]]. Шестерёнка ⚙ на странице [[nav.contest]] открывает ветку используемого режима.",
  "t.yyxty6ahta": "На карте видны отмеченные спутники с их трассой и зоной радиовидимости, день и ночь, а также Ваша станция — красная звезда с Вашим позывным (если позывной не задан — «[[sat.station]]»). Легенда для «[[sat.sun]]» и «[[sat.moon]]» находится внутри карты. Если ни один спутник не отмечен, на карте показана только Земля. Рядом расположен радар неба, показывающий, где находится выбранный спутник и куда направлен ротор (светло-голубое кольцо).",
  "t.yztc96psoa": "Как выключить (самый частый вопрос): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], блок «[[not2.grpAlerts]]». «[[not2.popNew]]» включает и выключает карточку для новой страны, «[[not2.popNewBand]]» — для новой страны на диапазоне: снимите обе отметки, и карточка больше не появится. «[[not2.popPos]]» выбирает угол или край экрана, где она появляется; её звук выбирается в «[[not2.popSound]]».",
  "t.z177sfkc9z": "Полная статья: «SSTV: клавиши быстрого доступа»; «RX/TX, Pause, Esc, двойной Esc и автоматический CQ»; «Сочетания клавиш и жесты».",
  "t.z1s4owb3z5": "Только для CW: выпадающий список полосы фильтра («[[digi.cw.bandwidth]]») и кнопка «TX = RX», которая устанавливает скорость передачи равной принимаемой (серая при отсутствии сигнала).",
  "t.z4627jxyco": "QSO короткое: Вы передаёте позывной и локатор, Fox даёт Вам рапорт, Вы отвечаете R+рапорт, Fox завершает RR73. Финального 73 от Вас не требуется.",
  "t.z4ayw025rp": "IMD принимаемого сигнала PSK: Aurora показывает его в строке состояния, но команда ничего не пишет",
  "t.z4lw7dq1lr": "Регион, действующий для всей таблицы, выбирается в [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]], блок [[sw.station]], выпадающий список [[gen2.region]] (по умолчанию [[gen2.regionAll]]: строки всех регионов видны). Его смена не удаляет ни одной строки.",
  "t.z4pigoj7zn": "«[[rep.ask]]» (включено): после сбоя при перезапуске Aurora спрашивает, отправлять ли отчёт. Если выключено, она ничего не спрашивает и сама ничего не отправляет.",
  "t.z86af14ogm": "Цифровая подпись (код OTP) поддерживается: как экспедиция введите seed на странице Fox, и код уйдёт в сигнале; как Hound Aurora проверяет Fox, и строка получает отметку «verified» или «invalid».",
  "t.z8kqe79vg4": "Проверка: проведите QSO (даже на эквивалент антенны) и убедитесь, что строка появилась в журнале.",
  "t.z9fcxzedlh": "«[[cluster.state]]»: по одной строке на каждый используемый сервер, с индикатором и состоянием: подключение, подключён (с числом полученных спотов) или не подключён (с причиной). Если ни один сервер не подключён, Вы видите «[[cluster.state.none]]». Это помогает понять, почему панель пуста.",
  "t.zdx78kent9": "Последовательные порты: Windows и Linux (группа dialout)",
  "t.zezvqjr2t5": "Число повторов в четырёх сценариях и приоритеты вступают в силу сразу после [[sw.save]], без перезапуска. Предохранители ([[gen2.watchdog]], [[gen2.swr]], [[auto.b3]] в автоматизациях) независимы: каждый останавливает передачу по-своему.",
  "t.zf9han8r1t": "«[[rep.auto]]» (включено): при каждой серьёзной ошибке уходит краткий отчёт: версия, система, антивирус, движок, модель трансивера, PTT, CAT, звуковая карта, область и очищенное сообщение. Одинаковые ошибки не чаще раза в час и не более определённого числа в день (указано ниже). Если включено, ниже Вы также видите, сколько отчётов ожидает отправки и сколько отправлено сегодня.",
  "t.zjhlztvxfn": "Ниже — панель настройки: гистограмма уровней (она следует за сигналом в реальном времени), три красные метки (синхро 1200 Hz, чёрный 1500, белый 2300), ползунок «[[sstv.tune.label]]» и строка, сообщающая, правильна ли настройка. Как ими пользоваться, см. «Как настроиться на сигнал SSTV».",
  "t.zjrik99jkt": "фильтр приёма: PASS — узкая полоса пропускания, NONE — выкл (режекторные тоже); NOTCH и NOISE включают полосу пропускания",
  "t.zkqdpjsksl": "Маяк FST4W: рядом с режимом выберите мощность (реальную, на антенне) и [[mode.wsprPct]], затем включите [[ctl.enable_tx]]. В начале периодов, выбранных процентом, Aurora передаёт «CALL LOCATOR dBm»: как WSJT-X, она решает случайным выбором для каждого периода и при значении ниже 40% никогда не передаёт два периода подряд.",
  "t.zlun6yzl82": "[[sw.contest.title]] · [[contest.set.callContest]], [[contest.set.grid6]], [[contest.set.antenna]], [[contest.set.operators]], [[contest.set.club]]: текстовые поля для заголовка журнала. Позывной контеста записывается, только если он отличается от позывного станции (пусто = позывной станции); шестисимвольный локатор нужен для EU VHF и журнала EDI; антенна (например, «Yagi 9 el») попадает в EDI контестов УКВ; операторы и клуб — только если этого требуют правила.",
  "t.zmwckzhbxv": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › «[[ens.g.adif]]» · «[[ens.k.UDP2Resend]]» (по умолчанию включено): относится ко вторичному UDP-серверу (по умолчанию 127.0.0.1, порт 2237). Если журнал на этом ПК (например, Log4OM) закрыт, когда Вы проводите QSO, Aurora откладывает её и сама отправляет примерно через 15 секунд после того, как Вы его снова откроете, в том порядке, в котором Вы их провели.",
  "t.zo5nx6bs0r": "[[cat.txPower]] и [[cat.txSwr]] (по умолчанию включены, сохраняются сразу): во время передачи Aurora запрашивает у трансивера мощность и КСВ. На некоторых трансиверах (например, Kenwood TS-850) каждое чтение другого измерителя заставляет трансивер переключать селектор измерителя с «щелчком» реле во время передачи. Если Вы его слышите, выключите один из двух флажков: читается только одна величина, и щелчок пропадает. КСВ используется также защитой, которая останавливает передачу при слишком высоком значении: если выключить [[cat.txSwr]], защита не действует, поэтому обычно лучше выключить мощность.",
  "t.zo8b1llifb": "Телефон и планшет: пульт дистанционного управления, верхняя панель",
  "t.zols3w9gwe": "Агент проверяет через 20 секунд после запуска, а затем каждый час. Уведомления появляются только при закрытой Aurora (при открытой Aurora их показывает сама Aurora), и каждое — только один раз. Исключение — «Check for updates» из меню, которое отвечает всегда.",
  "t.zoz9462k0u": "[[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sat.set.catMap]]. Выбирает карту мира под треками спутников на странице «Спутники». Каждое изменение сохраняется сразу.",
  "t.zsd9ka16of": "[[gen2.logFilter]] · [[gen2.useCall]] и [[gen2.useGrid]] (два флажка, по умолчанию выключены): Aurora считает «уже проведёнными» (цвета новых объектов, новый DXCC, автоматические ответы) только QSO журнала, проведённые с Вашим позывным, а с флажком локатора — также только с Вашим локатором (первые четыре символа). Используйте их, если в Вашем журнале есть QSO с другого позывного или из другого места. Журналы, не записывающие, какой позывной Вы использовали (собственный журнал Aurora, Log4OM), по этим двум причинам не отбрасываются.",
  "t.ztdinm290o": "Индикатор радиостанции",
  "t.zv5hw7m6xj": "QSO отсутствует во внешнем журнале",
  "t.zwxo4ij1xt": "Кнопки ниже: «[[contest.autoseq]]» (сообщения сменяются сами), «[[contest.enableTx]]», «[[contest.autoCq]]» (F1: контестный CQ в каждом периоде, пока кто-нибудь не ответит), «[[contest.rr73]]» (повторно отправляет завершение, если другая станция повторяет обмен), «[[stop.button]]». «[[contest.next]]» сообщает, кого вызывать следующим, в порядке ценности.",
  "t.zxz5isp8kv": "[[gen2.bandHop]] · [[gen2.bandHopOn]] (по умолчанию выключено): каждые две минуты трансивер переходит на следующий диапазон или частоту из списка, по кругу. Переходов нет при включённом [[ctl.enable_tx]] или во время передачи (запись пропускается и повторяется в следующем круге). Его можно включить также из [[nav.automation]].",
};
